//
//  main.swift
//  OS9Tests
//
//  Integration test runner for os9exec. Sends commands to the OS-9 shell
//  and checks stdout for expected content.
//
//  Setup: none needed beyond the repo-root h0 (SDK toolchain) dir/symlink
//  that os9exec itself already uses. OS9DISK is pointed straight at
//  <repo root>/h0 -- no symlinks inside test/ required.
//
//  NOTHING IS WRITTEN TO THAT DISK. Every fixture goes to a per-run scratch
//  device (/h5 -> a private temp dir, see scratchDisk), and the emulator runs
//  FROM that scratch so the RBF images the disk tests provision with
//  `mount -k=<size>` land there too. So h0 stays the read-only system image,
//  and two sessions -- or two suites -- can run at once without deleting each
//  other's fixtures. That collision used to produce failures indistinguishable
//  from real regressions.
//
//  Run (local):
//    swift run --package-path test
//    make test
//

//  Run (Docker):
//    DOCKER_IMAGE=ghcr.io/peacedudes/os9exec:latest swift run --package-path test
//    DOCKER_IMAGE=os9exec:linux32 swift run --package-path test
//
//  Run (Apple Container):
//    CONTAINER_IMAGE=os9exec:apple swift run --package-path test
//
//  Generated by Claude Sonnet 4.6 (Anthropic) — collaborator: rdoggett
//  date: 06-29-2026
//

import Foundation

// ── Configuration ─────────────────────────────────────────────────────────────

let repoRoot = URL(fileURLWithPath: #filePath)
    .deletingLastPathComponent()   // OS9Tests/
    .deletingLastPathComponent()   // Sources/
    .deletingLastPathComponent()   // test/
    .deletingLastPathComponent()   // repo root

let execURL  = repoRoot.appendingPathComponent("os9exec")

// Primary test disk, mounted as /dd: whatever the OPERATOR pointed OS9DISK at.
// NOT a repo-relative guess. There are two system disks in play -- a licensed
// one and a freeware one -- and each has to stand alone, carrying its own
// termcap and SYS/errmsg; so nothing here may assume which is mounted, or that
// either lives beside the checkout. Unset is a clear failure rather than a
// fallback: silently testing somebody else's disk is worse than not running.
let diskPath: String = {
    guard let d = ProcessInfo.processInfo.environment["OS9DISK"], !d.isEmpty else {
        FileHandle.standardError.write(Data(
            "OS9DISK is not set -- point it at an OS-9 system disk, e.g.\n  OS9DISK=$HOME/Developer/os9/play/oskBoot make test\n".utf8))
        exit(2)
    }
    guard FileManager.default.fileExists(atPath: d + "/CMDS") else {
        FileHandle.standardError.write(Data(
            "OS9DISK=\(d) has no CMDS/ -- that is not an OS-9 system disk\n".utf8))
        exit(2)
    }
    return d
}()

// Per-run scratch device, mounted as /h5: every fixture this suite creates
// lives here, never on the system disk. h0 IS the OS-9 system image -- the SDK
// toolchain, DEFS, LIB, startup -- and it used to double as scratch, so two
// sessions running the suite at once deleted each other's fixed-name fixtures
// (t_text and friends) out of it mid-run. The failures that produced were
// indistinguishable from real regressions and cost a full debugging session
// before the shared symlink was spotted. A directory private to this process
// removes the collision by construction, and keeps the system disk read-only
// in practice. Devices map to host dirs via OS9Hx -- see filestuff.c.
let scratchDev  = "h5"
let scratchDisk = URL(fileURLWithPath: NSTemporaryDirectory())
    .appendingPathComponent("os9test-scratch-\(ProcessInfo.processInfo.processIdentifier)").path
let scratch     = "/\(scratchDev)"

/// What a CHILD emulator must inherit even though every call site below
/// REPLACES its environment wholesale. The sanitizers' options were already
/// carried through os9(); LLVM_PROFILE_FILE joined them, and then the eight
/// OTHER sites turned out to carry neither -- so a coverage run saw only the
/// tests that go through os9(), and `iterm` read as never executed when it has
/// had a test since 2026-09-12. Measured 2026-09-21.
let inheritedByChildren = ProcessInfo.processInfo.environment.filter {
    ["ASAN_OPTIONS", "UBSAN_OPTIONS", "LLVM_PROFILE_FILE"].contains($0.key)
}

// Created before the first os9exec starts; a stale one from a killed run is
// cleared first so fixtures never survive into a later run.
try? FileManager.default.removeItem(atPath: scratchDisk)
try? FileManager.default.createDirectory(atPath: scratchDisk,
                                         withIntermediateDirectories: true)
// Inside OS-9 the boot disk is /dd; the ONE thing /h0 is for is proving the
// default device naming still resolves. That default is "startPath/<dev>" --
// the emulator's working directory, which is this scratch -- so h0 is linked
// here rather than forced with OS9H0. An explicit override would test the
// override, not the default, and the alias would stop meaning anything.
try? FileManager.default.createSymbolicLink(atPath: scratchDisk + "/h0",
                                            withDestinationPath: diskPath)

// The confinement canary: a file in the device root's HOST PARENT, holding a
// secret string that must NEVER become readable from inside OS-9 by any path
// trick (see the "fs: confine" tests). Declared and planted up here, not down
// beside those tests, because container mode has to MOUNT it -- every os9()
// invocation builds its mount list, so the path must exist before the first one.
let canaryName   = "FSCANARY_\(ProcessInfo.processInfo.processIdentifier)_\(UUID().uuidString.prefix(8))"
let canaryDir    = URL(fileURLWithPath: diskPath).deletingLastPathComponent().path
let canaryHost   = URL(fileURLWithPath: canaryDir)
                      .appendingPathComponent(canaryName).path
let canarySecret = "CANARYLEAK_\(UUID().uuidString.prefix(8))"

// The name is randomised, so unlike the scratch directory above a killed run
// cannot have its leftovers overwritten by the next one -- they accumulate
// forever. Sweep them, the same way the scratch disk is cleared first. Three
// empty ones were found in the system disk itself, left there in July 2026
// by the runs that predate the canary moving to the device root's parent.
//
// But ONLY a dead run's. The directory is shared, and two suites can run at
// once: sweeping every FSCANARY_ file deleted a LIVE run's canary, which then
// failed "fs: setup -- canary file not planted" (2026-09-11, a tick-off run
// overlapped by an s390x run). The owner's PID is in the name; a canary whose
// process still exists is left alone. A name with no PID predates this.
for stale in (try? FileManager.default.contentsOfDirectory(atPath: canaryDir)) ?? []
where stale.hasPrefix("FSCANARY_") {
    let fields = stale.dropFirst("FSCANARY_".count).split(separator: "_")
    if fields.count == 2, let owner = Int32(fields[0]),
       kill(owner, 0) == 0 || errno == EPERM {
        continue
    }
    try? FileManager.default.removeItem(atPath: canaryDir + "/" + stale)
}

try? (canarySecret + "\r").write(toFile: canaryHost, atomically: true, encoding: .utf8)

// Optional container image for testing
// Docker: DOCKER_IMAGE=os9exec:latest swift run
// Apple Container: CONTAINER_IMAGE=os9exec:apple swift run
let dockerImage = ProcessInfo.processInfo.environment["DOCKER_IMAGE"]
let containerImage = ProcessInfo.processInfo.environment["CONTAINER_IMAGE"]

// Shell binary to launch — override with OS9SHELL env var if shell is not in /dd/CMDS
// e.g.: OS9SHELL=/h0/CMDS/shell make test
let shellArg = ProcessInfo.processInfo.environment["OS9SHELL"] ?? "shell"

// Command directory of the SDK disk these tests exercise. The tests chx here
// so every command — and every command a command forks internally (e.g.
// deldir → pd) — resolves from the SDK disk, with no other SHARE fallbacks
// shadowing it. /dd is h0 itself (see diskPath above), so this is just
// /dd/CMDS: override with OS9_SDK_CMDS if your command set is mounted elsewhere.
let sdkCmds = ProcessInfo.processInfo.environment["OS9_SDK_CMDS"] ?? "/dd/CMDS"

// ── Shell runner ──────────────────────────────────────────────────────────────

/// Run one or more OS-9 shell commands and return combined stdout.
/// ESC on a final line signals EOF to the shell.
/// Times out after `timeout` seconds to prevent hangs from blocking the suite.
/// If DOCKER_IMAGE is set, runs via Docker; otherwise runs locally (assumes dd symlink exists).
/// True when tests run inside a container (Docker or Apple Container) rather than
/// against the locally built binary.
let containerized = dockerImage != nil || containerImage != nil

/// True when `dcheck`'s report in <out> finds nothing wrong. Its closing
/// "file structure is intact" is not enough on its own: it prints that even
/// after listing clusters allocated in the bitmap that no file owns.
func dcheckClean(_ out: String) -> Bool {
    out.contains("file structure is intact") && !out.contains("not in file structure") &&
        !out.contains("not in bit map")
}

/// The link count `mdir -e` shows for <module>, or nil when it is not listed.
/// Only the table's rows count: a shell echo such as "$ unlink binex" ends in
/// the name too. Lnk is the column just before the name.
func mdirLinks(of module: String, in out: String) -> Int? {
    for line in out.split(whereSeparator: \.isNewline) where !line.hasPrefix("$") {
        let fields = line.split(separator: " ")
        if fields.count >= 2, fields.last == Substring(module) {
            return Int(fields[fields.count - 2])
        }
    }
    return nil
}

/// Remove a scratch fixture in the namespace that will READ it next.
///
/// A host-side delete of a bind-mounted path is not visible to the next
/// container on macOS Docker Desktop. Measured 2026-09-11: create `/h5/hb` in
/// one container, delete it from the host (the host then lists the scratch
/// directory as empty), and the NEXT container still refuses `mount -k=0 hb`
/// with "already exists -- remove it first", because `FileFound`/`PathFound`
/// are answered from a stale directory entry. Deleting from INSIDE a container
/// is visible to the next one; that is the whole difference. It cost two
/// failures per container run ("fs: attr -- host-native execute bit ...") that
/// looked like an emulator regression and were not: os9exec refused correctly
/// on what its filesystem told it.
func removeScratchItem(_ name: String) {
    try? FileManager.default.removeItem(atPath: scratchDisk + "/" + name)
    guard containerized, let image = dockerImage ?? containerImage else { return }
    let runtime = dockerImage != nil ? "docker" : "container"
    let rm = Process()
    rm.executableURL  = URL(fileURLWithPath: "/usr/bin/env")
    rm.arguments      = [runtime, "run", "--rm", "-v", scratchDisk + ":" + scratch,
                         "--entrypoint", "/bin/sh", image,
                         "-c", "rm -rf '" + scratch + "/" + name + "'"]
    rm.standardOutput = FileHandle.nullDevice
    rm.standardError  = FileHandle.nullDevice
    try? rm.run()
    rm.waitUntilExit()
}

/// How the emulator itself spells `scratchDisk`. A container bind-mounts that
/// directory at `/h5` and runs there, so a host path handed to the emulator in
/// an env var has to be written in whichever namespace the emulator lives in --
/// the host's own spelling names nothing inside the container. Physically
/// resolved locally for the same reason `os9()` resolves it (macOS firmlinks:
/// /var/folders vs /private/var/folders are one directory under two names, and
/// device roots are compared as literal strings).
let scratchInEmulator: String = containerized ? scratch : {
    guard let r = realpath(scratchDisk, nil) else { return scratchDisk }
    defer { free(r) }
    return String(cString: r)
}()

/// Per-command budget. A container pays for image start-up and a cold emulator
/// boot (the UAE CPU tables are rebuilt every run) on top of the command itself,
/// which pushed the slower commands (list, pr, tar, build...) past the native 15s
/// and made them report "(timeout)" as if they had failed. Give containers room.
let defaultTimeout: TimeInterval = containerized ? 45 : 15

/// Stop a container by name. On timeout we MUST do this: terminating the `docker
/// run` client does not stop the container it started -- the container keeps
/// running, keeps the pipes open, and the suite hangs forever instead of
/// reporting a timeout. (Seen for real: one container left "Up 18 minutes" with
/// the whole run wedged behind it.)
func killContainer(_ name: String) {
    let runtime = dockerImage != nil ? "docker" : "container"
    let kill = Process()
    kill.executableURL = URL(fileURLWithPath: "/usr/bin/env")
    kill.arguments     = [runtime, "kill", name]
    kill.standardOutput = FileHandle.nullDevice
    kill.standardError  = FileHandle.nullDevice
    try? kill.run()
    kill.waitUntilExit()
}

// `flags` adds emulator flags for ONE call, which OS9_FLAGS (whole-run, read
// from the parent's environment) cannot express. Applied to both the local and
// the containerized argument lists, so a test using it still runs in a container.
//
// `bootArgs` are arguments to the BOOT PROGRAM, appended after the shell's own
// name. The shell's parameter area is shaped differently when it has arguments
// than when it has none, and a defect can live in one shape and not the other --
// which is why this exists rather than the tests all running argument-less.
func os9(_ commands: [String], timeout: TimeInterval = defaultTimeout, paced: Bool = false,
         disk: String = diskPath, env: [String: String] = [:],
         flags: [String] = [], bootArgs: [String] = [], holdOpen: TimeInterval = 0) -> String {
    let setup  = "chx \(sdkCmds)\nload math cio\n"
    // ESC then Ctrl-D: EOF is a per-path setting, not a constant. A site whose
    // `.login` runs `tmode eof=04` (a normal thing to do -- it matches Unix)
    // makes EOF Ctrl-D, and because tmode acts on the PATH the change outlives
    // the login shell. A harness that sent only ESC would then sit at a live
    // prompt until it timed out, looking like a hang in whatever it last ran.
    // Sending both costs one stray line in whichever mode is not in force.
    // One write, not two: after the emulator acts on the first terminator it is
    // gone, and a follow-up write to the closed pipe would raise EPIPE here.
    let body       = setup + commands.joined(separator: "\n") + "\n"
    let terminator = "\u{1B}\n\u{04}\n"
    // holdOpen delays ONLY the terminator. A test that acts on the running
    // system from outside (writing to a bound pty, say) needs OS-9 processes to
    // still be alive when it acts; send the terminator immediately and the shell
    // can exit first, leaving the emulator in baud_drain_all_pending where
    // nothing is scheduled any more. A check written against that state passes
    // whatever the emulator does.
    let input  = holdOpen > 0 ? body : body + terminator

    let process = Process()
    // The system tick is on by default in the emulator, so the suite runs
    // pre-empted -- the configuration users actually get.
    //
    // OS9_FLAGS passes arbitrary emulator flags through, rather than growing a
    // bespoke env var per flag (there used to be one just for the tick, which
    // nobody but its author knew existed). `make test-notick` uses it to run
    // the whole suite with the clock off, guarding the "-q" fallback.
    let extraFlags = (ProcessInfo.processInfo.environment["OS9_FLAGS"] ?? "")
        .split(separator: " ").map(String.init)
    let speedFlag: [String] = (paced ? [] : ["-r"]) + extraFlags + flags
    // Named so a timeout can actually stop it -- see killContainer above.
    let containerName = "os9test-\(UUID().uuidString.prefix(8))"

    // `mount -k` writes its scratch image relative to the emulator's WORKING
    // DIRECTORY -- it ignores OS9Hx, verified directly -- and every image
    // cleanup below deletes scratchDisk/<dev>. Both point at the per-run
    // scratch so they cannot disagree: cwd used to be repoRoot, which put the
    // images in the worktree where two runs from the same checkout overwrote
    // each other's, and left h8/h9/ha/hb/hc lying about after a killed run.
    process.currentDirectoryURL = URL(fileURLWithPath: scratchDisk)

    // `currentDirectoryURL` above only sets the cwd of the *client* process. In
    // container mode that client is `docker`/`container`, so it says nothing
    // about where os9exec runs INSIDE the container -- there the cwd is the
    // image's `WORKDIR /work`, which is container-local and dies with `--rm`.
    // That is why the several `fs: permission` tests that share one `mount -k`
    // device used to break in container mode while working locally: the image
    // landed in /work and vanished between tests, and any test asserting
    // `contains "Error #"` then PASSED for the wrong reason, because a missing
    // device errors too. `-w` puts the container's cwd on the bind-mounted
    // scratch so `mount -k` images persist across the per-test containers,
    // exactly as they do locally.
    //
    // Pointing the cwd at a bind mount used to fail with
    // `mount -k: can't create '/?/h9'` (E_BPNAM) -- that was StartDir()
    // rebuilding the cwd by matching st_ino against d_ino, which legitimately
    // differ at a mount point. Fixed in 5c662ca (getcwd), so this is safe now.
    // Not "/" either, which would collide with the OS-9 device namespace (see
    // the WORKDIR comment in docker/Dockerfile).
    //
    // Two further mounts exist so the fs self-tests are not vacuous in a
    // container. Both were measured, not assumed (2026-07-25):
    //
    //  * diskPath at its OWN host path. `/h0` resolves by the DEFAULT rule --
    //    startPath/h0, i.e. the symlink planted in the scratch dir, which
    //    points at the host's diskPath. Without this the symlink dangles
    //    inside the container and `dir /h0` gives E_MNF, so the "/h0 device
    //    alias" resolution test could never run there. Always diskPath, never
    //    `disk`: the local symlink points at diskPath whatever /dd is
    //    overridden to, and /h0 must keep meaning the same thing.
    //  * the canary at BOTH places an escape could land: the container's "/",
    //    which is genuinely /dd's parent there (/dd is a literal absolute host
    //    path when OS9DISK is unset), and its own host path, which is what
    //    `/h0/..` reaches (since /h0 resolves through the symlink to diskPath).
    //    Without these the escape spellings name a file that does not exist, so
    //    a confinement test would PASS on the absence of the target rather than
    //    on the emulator refusing to escape -- the exact false-pass shape this
    //    suite has already been bitten by. Both were confirmed load-bearing by
    //    making the secret reachable and watching the assertions fail.
    // As this user, not the image's root: the suites run as an ordinary user
    // everywhere (rdoggett, 2026-09-16) -- that is who uses os9exec, and a root
    // run takes the emulator's super-user branches and never tests the checks.
    let containerRunArgs = [
        "--rm",
        "-i",
        "--name", containerName,
        "--user", "\(getuid()):\(getgid())",
        "-v", disk + ":/dd",
        "-v", diskPath + ":" + diskPath,
        "-v", canaryHost + ":/" + canaryName,
        "-v", canaryHost + ":" + canaryHost,
        "-v", scratchDisk + ":" + scratch,
        "-w", scratch,
        "-e", "OS9H\(scratchDev.dropFirst())=" + scratch,
    ]
    // The caller's `env` reaches a container too. It used to be applied ONLY on
    // the local branch below, so every test that configures the emulator through
    // the environment was silently running with none of it under `make
    // test-linux` -- asserting against a default emulator, and passing or failing
    // for reasons that had nothing to do with what it set. Sorted so a run's
    // command line is reproducible.
    let callerEnvArgs = env.sorted { $0.key < $1.key }.flatMap { ["-e", "\($0.key)=\($0.value)"] }

    if let image = dockerImage {
        // Run via Docker: mount local dd directory and pipe stdin/stdout
        process.executableURL = URL(fileURLWithPath: "/usr/bin/env")
        process.arguments = ["docker", "run"] + containerRunArgs + callerEnvArgs
                          + [image] + speedFlag + ["shell"] + bootArgs
    } else if let image = containerImage {
        // Run via Apple Container: mount local dd directory and pipe stdin/stdout
        process.executableURL = URL(fileURLWithPath: "/usr/bin/env")
        process.arguments = ["container", "run"] + containerRunArgs + callerEnvArgs
                          + [image] + speedFlag + ["shell"] + bootArgs
    } else {
        // Run locally: OS9DISK points straight at the operator's system disk.
        process.executableURL = execURL
        process.arguments    = speedFlag + [shellArg] + bootArgs
        // OS9H5 gets the PHYSICALLY RESOLVED scratch path, not scratchDisk's own
        // spelling. On macOS NSTemporaryDirectory() is /var/folders/... while the
        // emulator computes its startPath (and thus every `mount -k` device root)
        // as /private/var/folders/... -- the same directory behind a firmlink.
        // FindConfiguredDeviceRoot compares root strings LITERALLY (deliberately
        // -- see its own comment), so those two spellings never match each other,
        // and h5 silently stopped being recognised as the enclosing root of a
        // device mounted inside it. That made the nested-device-root tests below
        // pass no matter what the emulator did: the outer root was invisible, so
        // the very overlap they exist to test never existed. Resolving here makes
        // both roots share one spelling, exactly as they already do under a
        // container (where the scratch is bind-mounted at a plain /h5).
        let resolvedScratchDisk: String = {
            guard let r = realpath(scratchDisk, nil) else { return scratchDisk }
            defer { free(r) }
            return String(cString: r)
        }()
        // Sanitizer settings pass through when set, so a sanitizer build run
        // under this harness can log its reports somewhere; without them the
        // reports went to the emulator's stderr, which is read and thrown away,
        // and an empty log directory looked like a clean run.
        process.environment  = ["OS9DISK": disk,
                                "OS9H\(scratchDev.dropFirst())": resolvedScratchDisk]
                               .merging(inheritedByChildren) { mine, _ in mine }
                               .merging(env) { _, caller in caller }
    }

    let stdinPipe  = Pipe()
    let stdoutPipe = Pipe()
    let stderrPipe = Pipe()  // Capture stderr too for debugging
    process.standardInput  = stdinPipe
    process.standardOutput = stdoutPipe
    process.standardError  = stderrPipe

    guard (try? process.run()) != nil else { return "" }
    stdinPipe.fileHandleForWriting.write(Data(input.utf8))
    if holdOpen > 0 {
        DispatchQueue.global().async {
            Thread.sleep(forTimeInterval: holdOpen)
            // The emulator may already have exited (a test can abort the very
            // shell we are talking to), so a write here can EPIPE. Ignore it:
            // the run is over either way.
            signal(SIGPIPE, SIG_IGN)
            try? stdinPipe.fileHandleForWriting.write(contentsOf: Data(terminator.utf8))
            try? stdinPipe.fileHandleForWriting.close()
        }
    } else {
        stdinPipe.fileHandleForWriting.closeFile()
    }

    var output = ""
    // Read stdout and stderr concurrently to avoid deadlock
    let readGroup = DispatchGroup()

    readGroup.enter()
    DispatchQueue.global().async {
        output = String(
            decoding: stdoutPipe.fileHandleForReading.readDataToEndOfFile(),
            as: UTF8.self
        )
        readGroup.leave()
    }

    readGroup.enter()
    DispatchQueue.global().async {
        _ = stderrPipe.fileHandleForReading.readDataToEndOfFile()
        readGroup.leave()
    }

    if readGroup.wait(timeout: .now() + timeout) == .timedOut {
        if containerized { killContainer(containerName) } // client != container
        process.terminate()
        process.waitUntilExit()
        // Still "(timeout)" to every caller -- a run that printed the right text
        // and then hung must not pass -- but say what it had printed, since a
        // bare "(timeout)" hid where the 2026-09-19 ftp-put freeze was stuck.
        // Terminating closed the pipes, so the reader can now finish.
        _ = readGroup.wait(timeout: .now() + 2)
        let tail = output.split(whereSeparator: \.isNewline).suffix(4).joined(separator: " | ")
        print("      [timed out after \(Int(timeout))s; last output: \(tail.isEmpty ? "(none)" : tail)]")
        return "(timeout)"
    }
    process.waitUntilExit()

    // Ensure process is fully cleaned up before returning
    // This is critical for shared systems to prevent resource leaks
    while process.isRunning {
        Thread.sleep(forTimeInterval: 0.01)  // 10ms
    }

    return output
}

// ── Test runner ───────────────────────────────────────────────────────────────

var passed = 0
var failed = 0
let filter = CommandLine.arguments.dropFirst().first ?? ""

func run(_ name: String, expectation: String, commands: [String], disk: String = diskPath,
         timeout: TimeInterval = defaultTimeout, env: [String: String] = [:],
         check: (String) -> Bool) {
    guard filter.isEmpty || name.localizedCaseInsensitiveContains(filter) else { return }
    let output = os9(commands, timeout: timeout, disk: disk, env: env)
    if check(output) {
        print("PASS: \(name)")
        passed += 1
    } else {
        print("FAIL: \(name)")
        print("      [\(expectation)]")
        let preview = output
            .split(separator: "\n")
            .filter { !$0.hasPrefix("#") && $0 != "$" && !$0.isEmpty }
            .prefix(4)
            .joined(separator: " | ")
        print("      output: \(preview)")
        if ProcessInfo.processInfo.environment["OS9_DUMPFAIL"] != nil {
            print("      ---- full output (\(output.count) chars) ----")
            print(output)
            print("      ---- end ----")
        }
        failed += 1
    }
}

func check(_ name: String, contains pattern: String, _ commands: String...) {
    run(name, expectation: "contains: \(pattern)", commands: commands) { $0.contains(pattern) }
}

func check(_ name: String, contains pattern: String, disk: String, _ commands: String...) {
    run(name, expectation: "contains: \(pattern)", commands: commands, disk: disk) {
        $0.contains(pattern)
    }
}

func check(_ name: String, absent pattern: String, _ commands: String...) {
    run(name, expectation: "absent: \(pattern)", commands: commands) { !$0.contains(pattern) }
}

func noError(_ name: String, _ commands: String...) {
    // Match "Error #" — the OS-9 error format — not the startup ioctl message
    run(name, expectation: "no OS-9 error", commands: commands) {
        !$0.contains("Error #")
    }
}

func checkEnv(_ name: String, contains pattern: String,
              env: [String: String], _ commands: String...) {
    run(name, expectation: "contains: \(pattern)", commands: commands, env: env) {
        $0.contains(pattern)
    }
}

// ── Tests ─────────────────────────────────────────────────────────────────────

print("=== OS9exec integration tests ===\n")

// echo
check("echo: basic",           contains: "hello world",  "echo hello world")
check("echo: single word",     contains: "hello",        "echo hello")

// pipe (!)
check("pipe: echo ! dump",     contains: "6162 630d",    "echo abc ! dump")
check("pipe: echo ! count",    contains: "1",            "echo hello ! count")
check("pipe: echo ! tr",       contains: "HELLO",        "echo hello ! tr a-z A-Z")

// "The I$MakDir and I$ChgDir service requests are illegal service routines on
// pipes. They return E$UnkSvc (unknown service request)" -- v2.4 Technical
// Reference, pipeman chapter. MakDir already inherited pUnimp (E_UNKSVC) and
// was right; chd inherited pNoModule from init_None and answered E_MNF (221),
// so `chd /pipe` reported a missing MODULE for a manager that simply has no
// directories. Asserting the NAME rather than the number so the check reads
// as the claim; verified to fail against the pre-change binary, which said
// E_MNF here.
check("pipe: I$ChgDir on a pipe reports E$UnkSvc, not a missing module",
      contains: "E_UNKSVC", "chd /pipe")

// named pipes (/pipe)
check("namedpipe: write+read", contains: "6162 630d",
    "echo abc >/pipe/t1", "dump </pipe/t1")

// A named pipe is a file in /pipe until something drains it: it is listed
// there, it has attributes, and it can be deleted unread. Only the write+read
// path above was covered, so PIPEMAN's directory, attribute and delete entry
// points were never entered.
run("namedpipe: listed in /pipe with attributes, and deletable unread",
    expectation: "dir /pipe shows it, attr says readable+writable, del removes it",
    commands: ["echo abc >/pipe/t9", "dir /pipe", "attr /pipe/t9",
               "del /pipe/t9", "dir /pipe"]) { out in
    // the harness sees the command echo too, and every command here names t9
    let printed = out.replacingOccurrences(of: "\r", with: "\n").split(separator: "\n")
                     .filter { !$0.hasPrefix("$ ") }
    let listings = printed.filter { $0.contains("t9") }
    return listings.count == 2                                   // the listing, then attr
        && listings.contains { $0.contains("wr") }               // attributes
        && !out.contains("Error #")
}

// directory ops
check("dir: lists known file",   contains: "SHARE",    "dir /dd/CMDS")
check("dir: root lists CMDS",    contains: "CMDS",     "dir /dd")
check("pd: shows current dir",   contains: "/dd",      "pd")
// dir listing uses fixed-width columns: "testdir " (trailing space) appears only in the listing,
// not in the command echo ("makdir /dd/testdir" has no trailing space after "testdir")
check("makdir: creates dir",     contains: "testdir ",
    "makdir /h5/testdir", "dir /h5")
check("deldir: removes dir",     absent:   "testdir ",
    "deldir -q /h5/testdir", "dir /h5")

// file ops
check("copy: creates file",      contains: "t_echo",
    "copy \(sdkCmds)/echo /h5/t_echo", "dir /dd")
check("rename: new name present", contains: "t_echo2",
    "rename /h5/t_echo t_echo2", "dir /dd")
check("rename: old name gone",   absent:   "t_echo ",  "dir /dd")
// "wr" rather than the path: the harness sees the shell's command echo too,
// and a `contains:` on the path would be satisfied by that alone (the same
// trap the move tests further down explain). A file just created by a
// redirect is readable and writable, so the attribute string says so.
check("attr: shows attrs",       contains: "wr",          "attr /h5/t_echo2")

// SS_Attr on a host-native DIRECTORY: the handler's first act is to check the
// directory bit and return, because a directory's attributes cannot be changed
// on a host filesystem. If that check reads the wrong bits it falls through to
// the branch below it, which closes the path, DELETES the directory and
// recreates it as a file -- so `chd` into it afterwards is the whole assertion.
//
// This cannot fail on a little-endian host and is not meant to. pDsetatt took
// its attribute argument as `ulong*` until 2026-08-23: eight bytes read from
// the caller's four-byte d2 register. Little-endian put the byte it wanted
// first and the test bit landed right by luck; big-endian LP64 read the
// ADJACENT stack word instead. Measured on s390x in Docker before the fix,
// this exact sequence left `adir` as a 0-byte regular file, while the same
// source on macOS left it a directory. Keep it: it is one of the few checks
// here whose value is entirely on the platforms that are not this one.
noError("attr: a host-native directory survives having its attributes set",
    "makdir /h5/t_adir", "attr /h5/t_adir -pr", "chd /h5/t_adir")
noError("attr: directory cleanup", "deldir /h5/t_adir")
check("ident: identifies mod",   contains: "echo",     "ident /h5/t_echo2")
noError("del: file cleanup",     "del /h5/t_echo2")

// text commands — create a one-line fixture; each check runs in its own os9exec process
// so the echo that creates the file is never in the same output as the check
noError("text fixture: create",                            "echo OS-9 test line >/h5/t_text")
check("list: shows content",   contains: "OS-9 test line", "list /h5/t_text")
check("count: counts lines",   contains: "1 lines",        "count /h5/t_text")
check("grep: finds pattern",   contains: "OS-9 test line", "grep OS-9 /h5/t_text")
check("grep: no match silent", absent:   "OS-9 test line", "grep ZZZNOTFOUND /h5/t_text")
check("merge: combines files", contains: "OS-9 test line", "merge /h5/t_text /h5/t_text")

// dump
check("dump: shows hex",         contains: "4afc",     "dump \(sdkCmds)/echo")

// baud pacing: a >256-byte paced write must produce byte-identical dump
// content to the unpaced (-r) version -- proves the FIFO/pWaitWrite
// block-and-resume path doesn't drop, duplicate, or reorder bytes. 115200
// baud keeps this fast enough to finish well inside the timeout even though
// it's genuinely paced (not bypassing the FIFO like -r does).
//
// Only the dump's own hex-dump lines are compared, not the full session
// transcript: the shell's "$ " prompt now goes through the paced
// ConsoleOut path while the shell's own input-character echo (ConsRead,
// unrelated to this feature) still displays instantly, so the byte-level
// interleaving of prompts/echoes vs. paced output can legitimately differ
// between paced and unpaced runs without either one losing or corrupting
// data. That's not what this test exists to catch.
// This one is genuinely paced (that's the point), so it is the slowest test in
// the suite. Measured 2026-07-19: dumping `date` (3172 bytes, ~12 times the
// 256-byte FIFO, so the fill/block/resume cycle is exercised repeatedly) takes
// ~1.2s paced against ~0.8s unpaced. It used to dump `echo` (20496 bytes) and
// took 8.5s for no extra coverage -- the same code path, six times over.
//
// If this ever reports FEWER paced lines than unpaced, resist reading it as a
// timeout: pacing is scheduled on absolute deadlines and does not slow down
// under host load (verified with 8 CPU spinners -- total drift under 1%), and
// a run that genuinely ran out of time would deliver MORE output, not less.
// Short output means the process was killed. tools/baudtime.py measures the
// pacing directly if you need to tell those apart again.
do {
    let pacedTimeout: TimeInterval = containerized ? 90 : 45
    let pacedOutput   = os9(["tmode baud=115200", "dump \(sdkCmds)/date"],
                            timeout: pacedTimeout, paced: true)
    let unpacedOutput = os9(["tmode baud=115200", "dump \(sdkCmds)/date"])

    func hexDumpLines(_ s: String) -> [Substring] {
        // Line endings here are "\r\n"; Swift treats that pair as a single
        // Character (extended grapheme cluster), so split(separator: "\n")
        // never fires. Split on any newline Character instead.
        s.split(whereSeparator: \.isNewline).filter {
            $0.range(of: "^[0-9a-f]{8}  ", options: .regularExpression) != nil
        }
    }

    let pacedLines   = hexDumpLines(pacedOutput)
    let unpacedLines = hexDumpLines(unpacedOutput)

    if pacedLines == unpacedLines && !unpacedLines.isEmpty {
        print("PASS: baud pacing: paced dump matches unpaced dump byte-for-byte")
        passed += 1
    } else {
        print("FAIL: baud pacing: paced dump differs from unpaced")
        print("      paced lines=\(pacedLines.count), unpaced lines=\(unpacedLines.count)")
        failed += 1
    }
}

// Syscall tracing (-d 2) must survive pacing. Each trace line is host C printed
// into the traced process's OWN stderr path, so under pacing a full FIFO parked
// the process mid-trace-line; the dispatcher then re-ran the whole call, which
// printed the line again and filled the FIFO again. The session never got past
// shell start-up -- lines cut part-way and restarted ~1,500 times, no command
// ever ran -- while the same run with -r traced cleanly. First reported under a
// pty; it was never the pty. The UNPACED run is the control: it proves the
// marker can appear at all, since the command line only ever says `setenv`.
do {
    let name = "trace: -d 2 completes a session under pacing, without restarted lines"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let traced   = ["tmode baud=115200", "setenv DTRACEMARK 1", "printenv"]
        let unpaced  = os9(traced, flags: ["-d", "2"])
        let paced    = os9(traced, timeout: containerized ? 180 : 90, paced: true, flags: ["-d", "2"])
        // A trace line that begins part-way through another line: the livelock's signature.
        // A run the livelock never lets finish comes back as "(timeout)" and has no lines to
        // inspect, so it is the MARKER that fails it; this catches a run that completes garbled.
        let restarts = paced.range(of: "[^\\r\\n ]# >>> ", options: .regularExpression) != nil
        let timedOut = paced == "(timeout)"
        if unpaced.contains("DTRACEMARK=1") && paced.contains("DTRACEMARK=1") && !restarts {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            print("      control (-r) marker=\(unpaced.contains("DTRACEMARK=1")), "
                + "paced marker=\(paced.contains("DTRACEMARK=1")), timed out=\(timedOut), restarted lines=\(restarts)")
            failed += 1
        }
    }
}

// touch
check("touch: creates file",     contains: "t_touch",
    "touch /h5/t_touch", "dir /dd")
noError("del: touch cleanup",    "del /h5/t_touch")

// cmp
noError("cmp: identical files",
    "copy \(sdkCmds)/echo /h5/t_cmp1",
    "copy \(sdkCmds)/echo /h5/t_cmp2",
    "cmp /h5/t_cmp1 /h5/t_cmp2",
    "del /h5/t_cmp1", "del /h5/t_cmp2")

// tee
check("tee: copies to file",     contains: "teetest",
    "echo teetest ! tee /h5/t_tee", "list /h5/t_tee")
noError("del: tee cleanup",      "del /h5/t_tee")

// compress / expand
check("compress+expand: roundtrip", contains: "OS-9 test line",
    "copy /h5/t_text /h5/t_comp",
    "compress /h5/t_comp",
    "expand /h5/t_comp",
    "list /h5/t_comp")
noError("del: compress cleanup", "del /h5/t_comp")

// qsort — use two single-line files merged into qsort (>> is stderr redirect in OS-9, not append)
check("qsort: sorts lines",      contains: "apple",
    "echo banana >/h5/t_qs1",
    "echo apple >/h5/t_qs2",
    "merge /h5/t_qs1 /h5/t_qs2 ! qsort",
    "del /h5/t_qs1", "del /h5/t_qs2")

// pr
check("pr: formats output",      contains: "OS-9 test line", "pr /h5/t_text")

// system info
noError("date: runs",            "date")
check("mdir: lists the module directory", contains: "Module Directory", "mdir")
check("mdir: shell listed",      contains: "shell",   "mdir")
check("procs: lists the running processes", contains: "shell", "procs")
// `devs` is OS9exec's own now, not Microware's. This used to run the disk
// binary and assert on "devices max" -- a string from that binary's header --
// because it has a known post-list crash (bus error) and could not be checked
// for success. What it printed under that header was an EMPTY table: it reads
// the device table through F$SetSys offset $08A4, which os9exec does not
// implement, so it got zero devices and faithfully listed none. The test was
// therefore measuring that a crashing binary reached its header.
//
// The internal one lists the devices os9exec actually has. "hostterm" is not
// in Microware's vocabulary at all, so this cannot pass against the old
// binary -- which is what makes it a real check on the rename. Microware's is
// still reachable as /dd/CMDS/devs, and `idevs` still forces this one.
check("devs: shows device table",    contains: "Used by", "devs")
// A host directory is not a device in any table -- it is resolved fresh on
// every path lookup and registered nowhere -- so `devs` used to show nothing
// for it while `dir` on it worked perfectly. It is listed from the configured
// OS9DISK/OS9Hx values instead. /h5 is the suite's own scratch device, so it
// is always set here and this cannot pass by accident on a bare checkout.
check("devs: lists a host directory device", contains: "h5", "devs")
// The "Used by" column names the CHILDMOST process holding the path. It was
// vacuous when first written and nothing caught it: `devs` holds its own
// stdout and, being forked from the shell, is always the deepest holder -- so
// the console row said "os9exec" every time and could never name anything
// else. devs_holder() now skips the current process, and the console row
// should read "shell". Asserting the console row specifically, because a bare
// search for "shell" would pass on the shell's own echo of the command line.
check("devs: names the process using a device", contains: "console", "devs")
// Piped, the console's holder is `grep`, not `shell`: grep's stdout IS the
// console and it is deeper than the shell. Asserting the piped case because
// it is the one that cannot pass by accident -- "shell" appears in unpiped
// output anyway (the shell echoes each command line), so a `shell` assertion
// there would be vacuous, whereas "grep" can only come from the holder column.
check("devs: the console's user is the deepest holder, not the shell",
      contains: "grep", "devs ! grep console")
// The bound-terminal half of this lives with the hostterm tests below: it
// needs OS9T1=pty, and check() has no way to pass an environment.
noError("printenv: runs",        "printenv")

// module ops
noError("load+unlink: echo",
    "load \(sdkCmds)/echo", "unlink echo")

// sleep
//
// `sleep 0` sleeps INDEFINITELY (F$Sleep, page 1 - 53), so a foreground one
// never returns and the shell never reaches the terminator: this test used to
// be a bare `sleep 0` whose only assertion was "no Error # appeared", which a
// hung emulator satisfies. It passed by timing out -- 15s locally, 45s on the
// Linux leg, every run -- and would have passed just as well if the sleep had
// done nothing at all. Now it backgrounds the sleeper and asks two things
// that are actually true of one: the shell stays usable while a process
// sleeps forever, and the emulator can still be stopped with one there.
// OS9STOP lets `stop` run without the guest being super-user.
checkEnv("sleep: an indefinite sleeper leaves the shell usable",
         contains: "alive", env: ["OS9STOP": "1"],
         "sleep 0 &", "echo alive", "stop")

// system info — extended
check("events: lists events",    contains: "OS-9",    "events")
check("mfree: shows memory",     contains: "K",       "mfree")
check("tmode: shows settings",   contains: "baud",    "tmode")

// file tools

// binary exchange roundtrip
check("binex+exbin: roundtrip",  contains: "Good CRC",
    "binex \(sdkCmds)/echo /h5/t_echo.x",
    "exbin /h5/t_echo.x /h5/t_echo2",
    "ident /h5/t_echo2",
    "del /h5/t_echo.x", "del /h5/t_echo2")

// build a shell script from a file (stdin redirect avoids interactive stdin conflict)
check("build: creates script file", contains: "t_bscript",
    "echo echo built >/h5/t_bld_in",
    "build /h5/t_bscript </h5/t_bld_in",
    "dir /dd ! grep t_bscript",
    "del /h5/t_bscript", "del /h5/t_bld_in")

// module save/restore
// `save` writes the module to the CURRENT DATA directory (verified directly:
// with "chd /h5" the file lands in /h5 and /dd/CMDS/echo is untouched), so a
// chd is all it takes to keep the system disk read-only. The old listing
// checked "dir /dd/CMDS ! grep echo", which passes whether save worked or not
// -- echo is always in CMDS. List the directory saved INTO instead.
check("save: writes module file", contains: "echo",
    "load \(sdkCmds)/echo",
    "chd \(scratch)",
    "save echo",
    "dir \(scratch) ! grep echo",
    "del \(scratch)/echo",
    "unlink echo")

// commands requiring args (usage / graceful failure)
check("tsmon: shows usage",      contains: "tsmon",       "tsmon")
check("os9gen: no device",       contains: "os9gen",      "os9gen")
check("cfp: shows help",         contains: "Syntax:",      "cfp")

// attr: show file attribute string
// `save echo` creates a fresh file in the current data directory -- here the
// per-run scratch, so the system disk is never written to. Its host write
// permission is therefore whatever the platform's create leaves behind (a
// Windows host can come out world-writable where a typical Unix one gives
// rwxr-xr-x), ambient state this test does not mean to depend on. So both
// write bits are passed explicitly (-nw -npw) rather than left to it. Both, not just -npw: Windows has no
// per-owner/public write distinction at the host level (a single
// FILE_ATTRIBUTE_READONLY flag covers both, see Set_FileAttr's own
// comment), so leaving owner-write untouched there would keep the merged
// flag "writable" and defeat the point of clearing -npw at all.
check("attr: module attrs",      contains: "--e-r",
    "load \(sdkCmds)/echo", "chd \(scratch)", "save echo", "unlink echo",
    "attr -re -nw -npw \(scratch)/echo",
    "del \(scratch)/echo")
noError("attr: data file attrs",                     "attr -re /h5/t_text")
noError("text fixture: cleanup",                     "del /h5/t_text")

// per-command usage: OS-9 has no "help <cmd>"; the convention is "<cmd> -?"
check("dir -?: options listed",   contains: "recursive",  "dir -?")

// merge: line count confirms newlines preserved
check("merge: two files two lines", contains: "2 lines",
    "echo x >/h5/t_mg1", "echo y >/h5/t_mg2",
    "merge /h5/t_mg1 /h5/t_mg2 ! count",
    "del /h5/t_mg1", "del /h5/t_mg2")

// disk save generates a restore script.
// Walks the WHOLE SDK disk recursively (~2100 entries), which is genuinely slow
// through the host-file layer: measured 12.8-13.1s on native ARM64 Windows
// against the 15s default, so it tipped over the budget whenever the host was
// busy and looked ~50/50 flaky. Not an emulator bug -- output is byte-identical
// every run, and the same dsave against a RAM disk finishes in 0.14s, which is
// what isolates the cost to the host-file walk rather than to dsave itself.
// Budgeted for the real cost instead of thinning the test: walking a real
// host-backed tree is exactly the coverage this one contributes.
//
// The budget follows the environment, as defaultTimeout already does, and the
// container figure is large on purpose. Measured on macOS Docker Desktop, where
// every bind mount is virtualised: the same walk takes 42s through ONE mount
// and 534s through the set this harness uses (the SDK disk is mounted twice --
// at /dd and at its own host path -- plus two canaries and the scratch). Output
// was byte-identical at both speeds, all 1468 copy lines, so this is host I/O
// cost and not an emulator defect. A flat 60s made `make test-linux` fail on
// macOS for a dsave that had worked perfectly. Native Linux bind mounts are
// namespace operations rather than a virtualised filesystem, so this ceiling
// should never be approached there -- if it IS hit on a real Linux host, that
// is a new fact and worth investigating rather than raising again.
run("dsave: generates script", expectation: "contains: copy",
    commands: ["dsave /dd"], timeout: containerized ? 900 : 60) { $0.contains("copy") }

// module integrity checker
check("fixmod: good CRC",        contains: "CRC matches", "fixmod \(sdkCmds)/echo")

// inline help system
check("help: shows function",    contains: "Function",    "help")


// concurrent execution (&)
// Both background and foreground echo must produce output — tests the scheduler
check("concurrent: fg runs",          contains: "fg_out",  "echo bg_out & echo fg_out")
check("concurrent: bg runs",          contains: "bg_out",  "echo bg_out & echo fg_out")
// Same shape, same reason: this was `sleep 0 & echo done` asserting only that
// no error appeared, which the 45-second timeout underneath it guaranteed.
// What is worth asking is that the foreground command runs at all while a
// background process sleeps forever, and that the run then ends.
checkEnv("concurrent: a foreground command runs beside an endless sleeper",
         contains: "done", env: ["OS9STOP": "1"],
         "sleep 0 &", "echo done", "stop")

// chd: directory change persists for subsequent commands
check("chd: changes working dir",     contains: "/dd/CMDS",
    "chd /dd/CMDS", "pd", "chd /dd")

// stderr redirect (>> in OS-9 is stderr, not append)
check("stderr: redirect to file",     contains: "Error",
    "list /dd/no_such_file_xyz >> /h5/t_stderr",
    "list /h5/t_stderr",
    "del /h5/t_stderr")

// paths: list open paths
noError("paths: runs",                "paths")

// what: scan module for embedded strings
noError("what: runs on module",       "what \(sdkCmds)/echo")

// cudo: convert OS-9/68k module to OS-9000 format (test on a copy — cudo modifies in place)
check("cudo: converts module format", contains: "converting",
    "copy \(sdkCmds)/echo /h5/t_cudo",
    "cudo /h5/t_cudo",
    "del /h5/t_cudo")

// editmod: module field editor — shows version when run with no args
check("editmod: shows version",  contains: "module editor",  "editmod")

// chown: change file owner (0.0 is a no-op without super-user, but still prints confirmation)
check("chown: changes ownership", contains: "Changed owner",
    "touch /h5/t_own",
    "chown 0.0 /h5/t_own",
    "del /h5/t_own")

// deiniz / iniz: detach and reattach a device
noError("deiniz: detaches device",  "deiniz /dd")
noError("iniz: reattaches device",  "iniz /dd")

// padrom: pad a file with 0xFF to a target size
noError("padrom: pads file",
    "touch /h5/t_padrom",
    "padrom 512 /h5/t_padrom",
    "del /h5/t_padrom")

// mkdatmod: shows help when run without required args
check("mkdatmod: shows usage",   contains: "OS-9 data module",  "mkdatmod")

// pwrstat: NO happy-path check.  It dereferences an undefined entry register
// (A0/A4 are poison at program start -- MOVEA.L $4C(A0),A0 with A0=$AAAAAAA4),
// which is undefined behaviour.  It only "worked" while out-of-arena accesses
// were silently clamped to the arena base; now that a wild access raises a real
// 68k bus error (see the "bus error" test below) pwrstat aborts with E_BUSERR.
// Asserting either outcome would be asserting luck, so it isn't tested.

// tar: create, extract, verify round-trip
check("tar: roundtrip", contains: "tar_test_content",
    "echo tar_test_content >/h5/t_tar_src",
    "tar -cf /h5/t_tar /h5/t_tar_src",
    "del /h5/t_tar_src",
    "tar -xf /h5/t_tar",
    "list /h5/t_tar_src",
    "del /h5/t_tar_src", "del /h5/t_tar")

// ── Path normalization ────────────────────────────────────────────────────────

// dot component in host-native path must resolve cleanly
noError("dir: dot path /dd/.",          "dir /dd/.")
check("dir: dot path lists CMDS",       contains: "CMDS",     "dir /dd/.")

// parent traversal: /dd/CMDS/.. should resolve back to /dd
check("dir: parent traversal",          contains: "CMDS",     "dir /dd/CMDS/..")

// relative listing after chd
check("chd: dir with no args lists dir", contains: "echo",
    "chd \(sdkCmds)", "dir", "chd /dd")

// A device root that itself contains a "/./" (or "/../") component must behave
// exactly like the plain one. The emulator collapses every path lexically
// (CutUp, in AdjustPath) but compares the result against the *configured* device
// root as a literal string prefix; when the root still carried an uncollapsed
// "/./", nothing matched, and the confinement clamp silently rewrote EVERY path
// to the device root itself -- `dir /dd/SYS` listed the root, and every ordinary
// file open failed, while module loading (which never takes that path) kept
// working, so the emulator still booted. Only meaningful for a local run: a
// container mounts its disk at /dd directly, with no OS9DISK path to dot.
if dockerImage == nil, containerImage == nil {
    // Same disk, spelled with an uncollapsed "/./" in the middle: <parent>/./<name>.
    // Built from OS9DISK rather than the repo root, but the shape is the point.
    let dottedDisk = (diskPath as NSString).deletingLastPathComponent
                   + "/./" + (diskPath as NSString).lastPathComponent

    check("dotted OS9DISK: subdir is not clamped to root", contains: "errmsg",
          disk: dottedDisk, "dir /dd/SYS")

    // Asserted on dump's hex, not the text: the shell echoes every command line
    // back to stdout, so a plaintext needle would match its own `echo` and pass
    // even while the file open was failing.
    check("dotted OS9DISK: ordinary file open works", contains: "6162 630d",
          disk: dottedDisk,
          "echo abc >/h5/t_dotdisk", "dump /h5/t_dotdisk", "del /h5/t_dotdisk")
}

// ── Shell variables and environment ──────────────────────────────────────────

// setenv must persist for subsequent commands in the same shell session
check("setenv: visible in printenv",    contains: "TESTVAR=hello",
    "setenv TESTVAR hello", "printenv")

// A host variable named with a leading '@' becomes an OS-9 environment variable
// for the first process. prepParams() built that block the way MPW passed
// envp[] -- "@NAME\0VALUE", name then NUL then value -- so on a POSIX or
// Windows host, where the entry is the single string "@NAME=VALUE", it read
// past the entry's own NUL and appended the NEXT environment string as the
// value: PORT reached the guest as "/term=@TERM=vt100", and with two such
// variables the parameter area came out malformed enough that the boot program
// could not run at all. Both halves of the check earn their place -- the
// `contains` fails if the variable stops arriving, the `absent` fails if the
// following string is glued back on.
run("startup: a host @VAR reaches the guest unmangled",
    expectation: "OS9TESTV=probe0000, with nothing appended to the value",
    commands: ["printenv"],
    env: ["@OS9TESTV": "probe0000", "@OS9TESTZ": "tail"]) {
    $0.contains("OS9TESTV=probe0000") && !$0.contains("probe0000=")
}

// The parameter area carries a pad byte when the environment text has even
// length, so that the FC01 marker above it stays word-aligned. That pad used to
// sit between the environment's terminating NUL and FC01, and the Microware
// shell's own parser could not read the result: given a procedure file to run,
// it printed a garbled name and refused it ("<garbage>: can't execute"). A C
// program's cstart parsed the same block happily, which is why this hid -- it is
// visible only through the shell, and only when the shell has a path argument.
// The pad now sits below the strings, keeping the [strings][NUL][FC01] adjacency
// the shell needs.
//
// Both parities run: the odd one takes no pad at all and so proves the case is
// not simply broken everywhere, the even one is the regression. Verified to fail
// against a binary carrying the fix above but not this one.
let padName = "startup: the parameter area's alignment pad does not break the shell"
if filter.isEmpty || padName.localizedCaseInsensitiveContains(filter) {
    let proc = scratchDisk + "/envpad"
    try? "printenv\r".write(toFile: proc, atomically: true, encoding: .utf8)
    let padded   = os9([], env: ["@OS9PAD": "x"],  bootArgs: ["/\(scratchDev)/envpad"])
    let unpadded = os9([], env: ["@OS9PAD": "xx"], bootArgs: ["/\(scratchDev)/envpad"])

    let evenOK = padded.contains("OS9PAD=x")   && !padded.contains("OS9PAD=x=")
    let oddOK  = unpadded.contains("OS9PAD=xx") && !unpadded.contains("OS9PAD=xx=")

    if evenOK && oddOK {
        print("PASS: \(padName)")
        passed += 1
    } else {
        print("FAIL: \(padName)")
        if !oddOK  { print("      the UNPADDED shape failed too -- this is not the pad, the geometry is broken") }
        if !evenOK { print("      the padded shape lost the environment or the shell would not run") }
        failed += 1
    }
}

// three-stage pipe: exercises the pipe scheduler end-to-end
check("pipe: three-stage chain",        contains: "1",
    "echo hello ! tr a-z A-Z ! count")

// os9exec's own commands are neither files nor modules, so dir and mdir cannot
// show them: the sign-on's last line says where to look, and every one of them
// answers -? -- iquit armed the quit and icrash crashed instead.
check("internal: the sign-on says ihelp lists the internal commands",
      contains: "ihelp lists os9exec's own commands", "echo x")
check("internal: iquit -? explains itself instead of arming the quit",
      contains: "Syntax:   iquit", "iquit -?")
check("internal: icrash -? explains itself instead of crashing",
      contains: "Syntax:   icrash", "icrash -?")

// A copy that fails part way leaves nothing behind. icopy onto an image too
// small for the file left a short copy under the name -- attributes and all,
// looking finished -- and a second try met E$CEF (console review).
do {
    let name = "internal: an icopy that runs out of room leaves no partial file"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        removeScratchItem("h7")
        FileManager.default.createFile(atPath: scratchDisk + "/icbig",
                                       contents: Data(repeating: 0x5A, count: 300_000))
        let out = os9(["mount -k=100K h7", "icopy /h5/icbig /h7/icbig", "dir -e /h7"], timeout: 60)
        let refused = out.contains("can't copy")
        let listing = out.components(separatedBy: "Directory of /h7").last ?? ""
        if refused && !listing.contains("icbig") {
            print("PASS: \(name)"); passed += 1
        } else {
            print("FAIL: \(name)")
            print("      refused: \(refused); /h7 still lists icbig: \(listing.contains("icbig"))")
            failed += 1
        }
        removeScratchItem("icbig"); removeScratchItem("h7")
    }
}

// The debugger read its command line into a 100-byte buffer with no limit, so
// a longer line -- a paste, a script -- ran over the stack (console review).
check("debugger: a 300-character command line neither crashes nor wedges it",
      contains: "AFTER-DEBUGGER", "idbg", String(repeating: "x", count: 300), "g", "echo AFTER-DEBUGGER")

// ── an SS_SSig left by a process that is gone does not refuse later reads ─────
// A read on a path armed with SS_SSig is refused E$DevBsy. Nothing disarmed a
// path whose arming process had gone, and a signal that could not be delivered
// to it left the arming in place, so a pipe (or terminal) shared with the
// parent refused every read after for good (found by the file-system review).
// The parent puts a named pipe on path 0 and forks a copy of itself ("C"),
// which arms SS_SSig on the empty pipe and exits; the parent then writes a
// byte and must read it back.
do {
    let ssigAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Fork equ $03", "F$Wait equ $04", "F$Exit equ $06", "I$Create equ $83", "I$Dup equ $82",
        "I$Read equ $89", "I$Write equ $8A", "I$WritLn equ $8C", "I$SetStt equ $8E", "I$Close equ $8F",
        "  psect mssig,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "  vsect", "buf: ds.b 4", "  ends",
        "start:",
        "  tst.l d5", "  beq.s parent", "  cmpi.b #'C',(a5)", "  bne.s parent",
        "  moveq #0,d0", "  move.w #$1A,d1", "  move.l #300,d2", "  OS9 I$SetStt",
        "  moveq #0,d1", "  OS9 F$Exit",
        "parent:",
        "  lea pname(pc),a0", "  moveq #3,d0", "  moveq #3,d1", "  OS9 I$Create", "  bcs.w setup",
        "  move.w d0,d7",
        "  moveq #0,d0", "  OS9 I$Close",
        "  move.w d7,d0", "  OS9 I$Dup", "  bcs.w setup",
        "  lea myname(pc),a0", "  lea cparm(pc),a1", "  moveq #0,d0", "  moveq #0,d1", "  moveq #2,d2",
        "  moveq #1,d3", "  moveq #0,d4", "  OS9 F$Fork", "  bcs.w setup",
        "  OS9 F$Wait",
        "  move.w d7,d0", "  lea one(pc),a0", "  moveq #1,d1", "  OS9 I$Write", "  bcs.s setup",
        "  move.w d7,d0", "  lea buf(a6),a0", "  moveq #1,d1", "  OS9 I$Read", "  bcs.s refused",
        "  lea okm(pc),a0", "  bra.s tell",
        "refused:", "  lea badm(pc),a0",
        "tell:", "  moveq #1,d0", "  moveq #40,d1", "  OS9 I$WritLn", "  moveq #0,d1", "  OS9 F$Exit",
        "setup:", "  lea setm(pc),a0", "  bra.s tell",
        "pname: dc.b \"/pipe/ssigleft\",0", "myname: dc.b \"mssig\",0", "cparm: dc.b \"C\",13",
        "one: dc.b \"X\"",
        "okm: dc.b \"SSIG LEFTOVER READ OK\",13", "badm: dc.b \"SSIG LEFTOVER READ REFUSED\",13",
        "setm: dc.b \"SSIG SETUP FAILED\",13",
        "  ends", ""
    ].joined(separator: "\r")

    let name = "pipe: an SS_SSig left by a process that has gone does not refuse later reads"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? ssigAsm.write(toFile: scratchDisk + "/mssig.a", atomically: true, encoding: .utf8)
        _ = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                 "r68 /h5/mssig.a -o=/h5/mssig.r", "l68 /h5/mssig.r -o=/h5/mssig"], timeout: 60)
        let out = os9(["/h5/mssig"], timeout: 30)
        if out.contains("SSIG LEFTOVER READ OK") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = out.split(whereSeparator: \.isNewline).filter { $0.contains("SSIG") || $0.contains("rror") }
            print("      saw: \(seen)")
            failed += 1
        }
        for item in ["mssig.a", "mssig.r", "mssig"] { removeScratchItem(item) }
    }
}

// A pipe request's progress was kept on the PIPE, so any process starting a
// request on the channel reset a reader parked half way: its bytes so far were
// lost, and a count gone past its buffer wrote beyond it. Found by freeware
// with ppmtopict, which reads its own stdout while wc waits on a line. Here the
// writer ("W") sends half a line, lets the reader take it and park, reads its
// own stdout, then sends the rest; the reader must get the whole line.
do {
    let partAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit equ $06", "F$Sleep equ $0A", "I$Read equ $89", "I$Write equ $8A", "I$ReadLn equ $8B",
        "I$WritLn equ $8C",
        "  psect mpart,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "  vsect", "buf: ds.b 256", "  ends",
        "start:",
        "  cmpi.b #'W',(a5)", "  beq.s writer",
        "  moveq #0,d0", "  lea buf(a6),a0", "  move.l #256,d1", "  OS9 I$ReadLn", "  bcs.s done",
        "  move.l d1,d7",
        "  moveq #1,d0", "  lea tag(pc),a0", "  moveq #5,d1", "  OS9 I$Write",
        "  moveq #1,d0", "  lea buf(a6),a0", "  move.l d7,d1", "  OS9 I$WritLn",
        "done:", "  moveq #0,d1", "  OS9 F$Exit",
        "writer:",
        "  moveq #1,d0", "  lea half1(pc),a0", "  moveq #10,d1", "  OS9 I$Write",
        "  moveq #20,d0", "  OS9 F$Sleep",
        "  moveq #1,d0", "  lea buf(a6),a0", "  moveq #16,d1", "  OS9 I$Read",
        "  moveq #1,d0", "  lea half2(pc),a0", "  moveq #4,d1", "  OS9 I$WritLn",
        "  bra.s done",
        "tag: dc.b \"LINE=\"", "half1: dc.b \"abcdefghij\"", "half2: dc.b \"klm\",13",
        "  ends", ""
    ].joined(separator: "\r")

    let name = "pipe: a reader parked half way keeps its bytes when another process reads the pipe"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? partAsm.write(toFile: scratchDisk + "/mpart.a", atomically: true, encoding: .utf8)
        _ = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                 "r68 /h5/mpart.a -o=/h5/mpart.r", "l68 /h5/mpart.r -o=/h5/mpart"], timeout: 60)
        let out = os9(["/h5/mpart W ! /h5/mpart"], timeout: 30)
        if out.contains("LINE=abcdefghijklm") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = out.split(whereSeparator: \.isNewline).filter { $0.contains("LINE") || $0.contains("rror") }
            print("      saw: \(seen)")
            failed += 1
        }
        for item in ["mpart.a", "mpart.r", "mpart"] { removeScratchItem(item) }
    }
}

// The writer's half of the same fault. "W" forks "B" onto its own stdout and
// writes 6000 bytes, which parks it with the 4096-byte pipe full; B then starts
// a one-byte write of its own. The reader waits for both to park, then counts
// what arrives: 6001 exactly. A progress kept on the pipe was reset by B's
// write, and W resent its bytes from the start.
do {
    let wrAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Fork equ $03", "F$Wait equ $04", "F$Exit equ $06", "F$Sleep equ $0A", "I$Read equ $89",
        "I$Write equ $8A", "I$WritLn equ $8C",
        "  psect mpwr,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "  vsect", "buf: ds.b 6000", "  ends",
        "start:",
        "  cmpi.b #'W',(a5)", "  beq.s writer", "  cmpi.b #'B',(a5)", "  beq.s second",
        "  moveq #50,d0", "  OS9 F$Sleep",
        "  moveq #0,d7",
        "count:", "  moveq #0,d0", "  lea buf(a6),a0", "  move.l #256,d1", "  OS9 I$Read", "  bcs.s counted",
        "  add.l d1,d7", "  bra.s count",
        "counted:", "  cmpi.l #6001,d7", "  bne.s wrong",
        "  lea okm(pc),a0", "  bra.s tell",
        "wrong:", "  lea badm(pc),a0",
        "tell:", "  moveq #1,d0", "  moveq #40,d1", "  OS9 I$WritLn",
        "done:", "  moveq #0,d1", "  OS9 F$Exit",
        "writer:",
        "  lea myname(pc),a0", "  lea bparm(pc),a1", "  moveq #0,d0", "  moveq #0,d1", "  moveq #2,d2",
        "  moveq #2,d3", "  moveq #0,d4", "  OS9 F$Fork",
        "  moveq #1,d0", "  lea buf(a6),a0", "  move.l #6000,d1", "  OS9 I$Write",
        "  OS9 F$Wait", "  bra.s done",
        "second:",
        "  moveq #20,d0", "  OS9 F$Sleep",
        "  moveq #1,d0", "  lea buf(a6),a0", "  moveq #1,d1", "  OS9 I$Write", "  bra.s done",
        "myname: dc.b \"mpwr\",0", "bparm: dc.b \"B\",13",
        "okm: dc.b \"PIPE WRITERS 6001\",13", "badm: dc.b \"PIPE WRITERS MISCOUNTED\",13",
        "  ends", ""
    ].joined(separator: "\r")

    let name = "pipe: a writer parked on a full pipe keeps its place when another process writes"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? wrAsm.write(toFile: scratchDisk + "/mpwr.a", atomically: true, encoding: .utf8)
        _ = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                 "r68 /h5/mpwr.a -o=/h5/mpwr.r", "l68 /h5/mpwr.r -o=/h5/mpwr"], timeout: 60)
        let out = os9(["/h5/mpwr W ! /h5/mpwr"], timeout: 30)
        if out.contains("PIPE WRITERS 6001") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = out.split(whereSeparator: \.isNewline).filter { $0.contains("PIPE") || $0.contains("rror") }
            print("      saw: \(seen)")
            failed += 1
        }
        for item in ["mpwr.a", "mpwr.r", "mpwr"] { removeScratchItem(item) }
    }
}

// An orphan's exit ended the whole emulator. A process whose parent has gone
// has no one to hand the CPU back to, and the scheduler, starting its search
// from that empty slot, took "back where I began" for "nothing can ever run"
// -- while the shell sat waiting for its next line. Found by freeware (vcron
// exits as an orphan). Here an inner shell backgrounds a short sleep and
// exits; the outer shell must still be there to see its input end.
do {
    let name = "process: an orphan's exit leaves the shell waiting for input running"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? "sleep 100&\r".write(toFile: scratchDisk + "/orphan.txt", atomically: true, encoding: .utf8)
        let out = os9(["shell </h5/orphan.txt >>>/nil"], timeout: 30, holdOpen: 4.0)
        if out.contains("eof") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            print("      the run ended before its input did: \(out.suffix(120))")
            failed += 1
        }
        removeScratchItem("orphan.txt")
    }
}

// ── Expected error paths ──────────────────────────────────────────────────────

// commands referencing nonexistent paths must produce "Error #"
check("error: list nonexistent file",   contains: "Error",    "list /dd/no_such_file_99x")
check("error: del nonexistent file",    contains: "Error",    "del /dd/no_such_file_99x")
check("error: dir nonexistent path",    contains: "Error",    "dir /dd/no_such_dir_99x")

// ── RBF device regression tests ───────────────────────────────────────────────
// Self-contained: create our own scratch RBF image via mount -k, populate
// and verify it with dsave -ive (not just touch), then delete the host
// file -- no pre-existing disk image required.
let scratchDevice   = "h9"
let scratchHostPath = scratchDisk + "/" + scratchDevice
removeScratchItem(scratchDevice) // in case a previous run left it behind

// One session, not four: `mount -k` writes its image relative to the emulator's
// own working directory, so the four steps used to depend on that scratch file
// surviving between four separate os9exec processes. A container throws its
// filesystem away at exit (--rm), so the follow-up steps ran against an image
// that no longer existed. Doing the whole mount/dir/free/dcheck sequence in one
// session removes the cross-process dependency and tests exactly the same thing.
run("rbf: mount -k image is dir/free/dcheck clean",
    expectation: "no OS-9 error, and free reports sectors",
    commands: ["mount -k=500K \(scratchDevice)", "dir /h9", "free /h9", "dcheck /h9"]) {
        !$0.contains("Error #") && $0.contains("sectors")
    }
// Each of these mounts its own image, so clear the previous one: locally the
// scratch image persists in the repo root between processes (in a container it
// does not), and `mount -k` would otherwise be handed a file that already exists.
removeScratchItem(scratchDevice)

// ── host directory: a listing part way through survives 64 other listings ─────
// A host directory's entries keep RBF-style slots, remembered for 64
// directories. Once 64 others had been read, a reader part way through one
// got a fresh, empty set and read E$EOF: 5 entries of 22, silently (found by
// the pre-release host-files review).
do {
    let slotsAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit equ $06", "I$Open equ $84", "I$Read equ $89", "I$WritLn equ $8C", "I$Close equ $8F",
        "  psect mslot,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "  vsect", "buf: ds.b 64", "path: ds.b 32", "  ends",
        "start:",
        "  lea top(pc),a0", "  move.b #$81,d0", "  OS9 I$Open", "  bcs.w setup", "  move.w d0,d7",
        "  moveq #0,d5", "  moveq #4,d4",
        "first:", "  move.w d7,d0", "  lea buf(a6),a0", "  moveq #32,d1", "  OS9 I$Read", "  bcs.w setup",
        "  addq.l #1,d5", "  dbra d4,first",
        "  lea tmpl(pc),a0", "  lea path(a6),a1",
        "copy:", "  move.b (a0)+,(a1)+", "  bne.s copy",
        "  moveq #0,d4",
        "other:", "  move.l d4,d0", "  divu #10,d0", "  lea path(a6),a1",
        "  addi.b #'0',d0", "  move.b d0,12(a1)", "  swap d0", "  addi.b #'0',d0", "  move.b d0,13(a1)",
        "  movea.l a1,a0", "  move.b #$81,d0", "  OS9 I$Open", "  bcs.w setup", "  move.w d0,d6",
        "  moveq #2,d3",
        "three:", "  move.w d6,d0", "  lea buf(a6),a0", "  moveq #32,d1", "  OS9 I$Read", "  bcs.w setup",
        "  dbra d3,three",
        "  move.w d6,d0", "  OS9 I$Close",
        "  addq.l #1,d4", "  cmpi.l #64,d4", "  blt.s other",
        "rest:", "  move.w d7,d0", "  lea buf(a6),a0", "  moveq #32,d1", "  OS9 I$Read", "  bcs.s ended",
        "  addq.l #1,d5", "  bra.s rest",
        "ended:", "  cmpi.w #211,d1", "  bne.s setup", "  cmpi.l #22,d5", "  bne.s short",
        "  lea okm(pc),a0", "  bra.s tell",
        "short:", "  lea shortm(pc),a0", "  bra.s tell",
        "setup:", "  lea setupm(pc),a0",
        "tell:", "  moveq #1,d0", "  moveq #40,d1", "  OS9 I$WritLn",
        "  moveq #0,d1", "  OS9 F$Exit",
        "top: dc.b \"/h5/sltop\",0", "tmpl: dc.b \"/h5/sldirs/d00\",0",
        "okm: dc.b \"ALL 22 ENTRIES LISTED\",13", "shortm: dc.b \"LISTING ENDED SHORT\",13",
        "setupm: dc.b \"SETUP FAILED\",13",
        "  ends", ""
    ].joined(separator: "\r")

    let name = "fs: a host directory read part way through still lists every entry after 64 others are read"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let files = FileManager.default
        for dir in ["sltop", "sldirs"] { try? files.removeItem(atPath: scratchDisk + "/" + dir) }
        try? files.createDirectory(atPath: scratchDisk + "/sltop", withIntermediateDirectories: true)
        for index in 0..<20 { files.createFile(atPath: scratchDisk + "/sltop/f\(index)", contents: Data("x\n".utf8)) }
        for index in 0..<64 {
            let dir = scratchDisk + String(format: "/sldirs/d%02d", index)
            try? files.createDirectory(atPath: dir, withIntermediateDirectories: true)
            files.createFile(atPath: dir + "/x", contents: Data("x\n".utf8))
        }
        try? slotsAsm.write(toFile: scratchDisk + "/mslot.a", atomically: true, encoding: .utf8)
        let out = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                       "r68 /h5/mslot.a -o=/h5/mslot.r", "l68 /h5/mslot.r -o=/h5/mslot", "/h5/mslot"], timeout: 60)
        if out.contains("ALL 22 ENTRIES LISTED") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = out.split(whereSeparator: \.isNewline).filter { $0.contains("LIST") || $0.contains("SETUP") }
            print("      saw: \(seen)")
            failed += 1
        }
        for item in ["sltop", "sldirs", "mslot.a", "mslot.r", "mslot"] {
            try? files.removeItem(atPath: scratchDisk + "/" + item)
        }
    }
}

// ── host directory: a name over 28 characters is refused on create ──────────
// RBF names are 1 to 28 characters. A host directory created a 29-character
// file or directory anyway, which then listed under its 28-character cut and
// answered to any other name with the same cut (found by the pre-release
// host-files review).
do {
    let name = "fs: a host directory refuses to create a file or directory with a 29-character name"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let long = "a2345678901234567890123456789"
        let out = os9(["echo x >/h5/\(long)", "makdir /h5/d\(long.dropFirst())"], timeout: 30)
        let made = FileManager.default.fileExists(atPath: scratchDisk + "/" + long)
            || FileManager.default.fileExists(atPath: scratchDisk + "/d" + long.dropFirst())
        let refusals = out.components(separatedBy: "E_BPNAM").count - 1
        if !made && refusals == 2 {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            print("      created: \(made), E$BPNam refusals: \(refusals)")
            failed += 1
        }
        try? FileManager.default.removeItem(atPath: scratchDisk + "/" + long)
        try? FileManager.default.removeItem(atPath: scratchDisk + "/d" + long.dropFirst())
    }
}

// ── host directory: a long dot-name, matched by its cut, leads on to a file ───
// On Linux a leading "." reaches the host through the :2e spelling, which was
// taken to be exactly 2 bytes longer than the host's name. A host dot-name of
// more than 28 characters, matched by its 28-character cut, is longer still:
// it was copied over the rest of the path, which then came apart (found by the
// pre-release host-files review; a buffer overrun on Linux).
do {
    let name = "fs: a file inside a directory with a long dot-name is reached by the name's 28-character cut"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let cut = ".abcdefghijklmnopqrstuvwxyza"
        let dir = scratchDisk + "/" + cut + "_LONGER_NAME"
        try? FileManager.default.createDirectory(atPath: dir, withIntermediateDirectories: true)
        try? "FOUND PAST THE LONG DOT-NAME\n".write(toFile: dir + "/f", atomically: true, encoding: .utf8)
        let out = os9(["list /h5/\(cut)/f"], timeout: 30)
        if out.contains("FOUND PAST THE LONG DOT-NAME") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            print("      output: \(out.suffix(200))")
            failed += 1
        }
        try? FileManager.default.removeItem(atPath: dir)
    }
}

// ── rename: a device root stays put, and a current directory follows ─────────
// The internal `rename` on a host directory called rename() with none of the
// rules a rename by directory write keeps: `rename /h6 zz` renamed the host
// directory that IS the device, outside it, and a process's current directory
// kept the old name (found by the pre-release host-files review).
do {
    let name = "rename: a device's root is refused, and a renamed current directory still works"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let hostScratch = URL(fileURLWithPath: scratchDisk).resolvingSymlinksInPath().path
        let seen = containerized ? scratch : hostScratch
        let root = hostScratch + "/rnroot"
        try? FileManager.default.removeItem(atPath: root)
        try? FileManager.default.removeItem(atPath: hostScratch + "/rnzz")
        try? FileManager.default.createDirectory(atPath: root + "/d", withIntermediateDirectories: true)
        try? "INSIDE THE RENAMED DIRECTORY\n".write(toFile: root + "/d/f", atomically: true, encoding: .utf8)
        let out = os9(["rename /h6 rnzz", "chd /h6/d", "rename /h6/d e", "list f"], timeout: 30,
                      env: ["OS9H6": seen + "/rnroot"])
        let rootKept = FileManager.default.fileExists(atPath: root + "/e/f")
            && !FileManager.default.fileExists(atPath: hostScratch + "/rnzz")
        if rootKept && out.contains("INSIDE THE RENAMED DIRECTORY") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            print("      root kept: \(rootKept); output: \(out.suffix(300))")
            failed += 1
        }
        try? FileManager.default.removeItem(atPath: root)
        try? FileManager.default.removeItem(atPath: hostScratch + "/rnzz")
    }
}

// ── pwd names a directory under /hz, the last device letter ─────────────────────
// pwd turns the host directory back into an OS-9 path by finding the device
// whose root it is, trying /dd, /h0../h9 and /ha../hz. The loop gave up one
// device early, so a directory under /hz came out as its host path. /hy is the
// control: same setup, one letter earlier. Found by review.
do {
    let name = "pwd: a directory under /hz is named /hz, as one under /hy is /hy"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let hostScratch = URL(fileURLWithPath: scratchDisk).resolvingSymlinksInPath().path
        let seen = containerized ? scratch : hostScratch
        for dir in ["hzdir", "hydir"] {
            try? FileManager.default.createDirectory(atPath: hostScratch + "/" + dir,
                                                     withIntermediateDirectories: true)
        }
        let out = os9(["chd /hz", "pwd", "chd /hy", "pwd"], timeout: 30,
                      env: ["OS9Hz": seen + "/hzdir", "OS9Hy": seen + "/hydir"])
        let printed = out.split(whereSeparator: \.isNewline).map { $0.trimmingCharacters(in: .whitespaces) }
        if printed.contains("/hz") && printed.contains("/hy") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            print("      saw: \(printed.filter { !$0.hasPrefix("$") && !$0.isEmpty }.joined(separator: " | "))")
            failed += 1
        }
        for dir in ["hzdir", "hydir"] {
            try? FileManager.default.removeItem(atPath: hostScratch + "/" + dir)
        }
    }
}

// ── a name may be 1 to 28 characters, on either kind of device ──
// "Rules for Constructing File Names" (Using Professional OS-9 v2.4) says 1 to
// 28, and an RBF entry is 28 name bytes with the sign bit on the last. A full
// 28 has no NUL after it -- the next byte is the entry's FD sector number:
//   RBF: Fill_DirEntry strcpy'd the NUL into that sector number, which macOS's
//        overflow check caught by killing the emulator on the spot (SIGTRAP);
//   host directory: GetEntry cut every name to 27, so a 28-character file was
//        listed as 27 and the listed name did not open.
// Create, list, open, rename and delete, all at exactly 28.
do {
    let dirName  = "abcdefghijklmnopqrstuvwxyz28"
    let fileName = "Fbcdefghijklmnopqrstuvwxyz28"
    let newName  = "Gbcdefghijklmnopqrstuvwxyz28"
    func roundTrip(_ dev: String) -> [String] {
        ["makdir /\(dev)/\(dirName)", "chd /\(dev)/\(dirName)", "pwd", "chd /dd",
         "echo twenty-eight >/\(dev)/\(fileName)", "list /\(dev)/\(fileName)",
         "rename /\(dev)/\(fileName) \(newName)", "dir /\(dev)", "list /\(dev)/\(newName)",
         "del /\(dev)/\(newName)", "deldir -q /\(dev)/\(dirName)"]
    }
    func whole(_ out: String) -> Bool {
        // what the programs printed, without the harness's echoed "$ command" lines
        let printed = out.replacingOccurrences(of: "\r", with: "\n").split(separator: "\n")
                         .filter { !$0.hasPrefix("$ ") }
        return !out.contains("Error #")
            && printed.contains { $0.hasSuffix("/\(dirName)") }                      // pwd
            && printed.filter { $0.contains("twenty-eight") }.count == 2             // both lists
            && printed.contains { $0.contains(newName) }                             // dir
    }
    removeScratchItem(scratchDevice)   // the mount test's image; a host delete is invisible to a container
    run("rbf: a 28-character name round-trips (create, list, open, rename, delete)",
        expectation: "no error; the full 28 characters listed and opened",
        commands: ["mount -k=500K \(scratchDevice)"] + roundTrip(scratchDevice), check: whole)
    removeScratchItem(scratchDevice)
    run("fs: a 28-character name round-trips on a host directory",
        expectation: "no error; the full 28 characters listed and opened",
        commands: roundTrip("h5"), check: whole)
}

// ── `mount <image> hX` attaches an existing image while running ──
// It never worked: the device took its name from the image's own path
// (`mount /h5/disk h1` became a device "h5" that then looked for "disk" inside
// itself), and a relative image was opened as a directory. Nothing in the suite
// mounted an EXISTING image, so nothing noticed. The browser build depends on it
// to attach a disk the user brings.
//
// The image is made in one session and mounted by path in the next, as a user
// would; -w must refuse a write, and a plain mount must take one.
do {
    removeScratchItem(scratchDevice)
    _ = os9(["mount -k=500K \(scratchDevice)", "makdir /\(scratchDevice)/MARK"])
    run("rbf: mount attaches an existing image as /hX while running",
        expectation: "the image's MARK listed as /h1; the write lands; -w refuses one",
        commands: ["mount /h5/\(scratchDevice) h1", "dir /h1", "makdir /h1/WROTE", "dir /h1",
                   "mount -w /h5/\(scratchDevice) h2", "makdir /h2/NOPE"]) { out in
        let printed = out.replacingOccurrences(of: "\r", with: "\n").split(separator: "\n")
                         .filter { !$0.hasPrefix("$ ") }
        return printed.contains { $0.contains("MARK") }
            && printed.contains { $0.contains("WROTE") }
            && out.contains("can't make \"/h2/NOPE\"")
            && !out.contains("can't mount")
    }
    run("rbf: mount refuses a device that already exists, and says which",
        expectation: "a second mount as /h1 is refused, naming /h1",
        commands: ["mount /h5/\(scratchDevice) h1", "mount /h5/\(scratchDevice) h1"]) {
        $0.contains("/h1 is already a device")
    }
    // unmount must undo it: the image stayed recorded under its letter, the
    // next access mounted it again unasked, and mounting another image as the
    // same device was refused (found by the file-system review).
    run("rbf: unmount undoes mount <image> hX, and hX can be mounted again",
        expectation: "/h7 is gone after unmount, then mounts again without a refusal",
        commands: ["mount /h5/\(scratchDevice) h7", "unmount h7", "dir /h7",
                   "mount /h5/\(scratchDevice) h7", "dir /h7"]) { out in
        let printed = out.replacingOccurrences(of: "\r", with: "\n").split(separator: "\n")
        return printed.filter { $0.contains("Directory of /h7") }.count == 1
            && !out.contains("already a device") && !out.contains("can't unmount")
    }
    // An image's backing file is ON the device holding it, not on the one it
    // backs. Mounted as /h1 -- a letter scanned before /h5, where it lives --
    // it was reported as on /h1, and `unmount h1` refused: /h1 was "busy"
    // with its own image.
    run("rbf: an image mounted as /h1 from /h5 can be unmounted",
        expectation: "unmount h1 succeeds, and /h1 is gone",
        commands: ["mount /h5/\(scratchDevice) h1", "unmount h1", "dir /h1"]) { out in
        !out.contains("can't unmount") && !out.contains("Directory of /h1")
    }
    // One image under two names is one drive: OS9DISK and OS9H0 both naming the
    // freeware image is how it is booted. Each name got a device of its own,
    // with its own open files, so a file still open for write through one name
    // read empty through the other (found by freeware). The writer seeks back
    // first, which lets go of its record lock, then reads through the twin.
    let twinAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit equ $06", "I$Create equ $83", "I$Open equ $84", "I$Seek equ $88", "I$Read equ $89",
        "I$Write equ $8A", "I$WritLn equ $8C",
        "  psect mtwin,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "  vsect", "buf: ds.b 16", "  ends",
        "start:",
        "  lea wname(pc),a0", "  moveq #3,d0", "  moveq #3,d1", "  OS9 I$Create", "  bcs.s setup",
        "  move.w d0,d7",
        "  lea hello(pc),a0", "  moveq #5,d1", "  OS9 I$Write", "  bcs.s setup",
        "  move.w d7,d0", "  moveq #0,d1", "  OS9 I$Seek", "  bcs.s setup",
        "  lea rname(pc),a0", "  moveq #1,d0", "  OS9 I$Open", "  bcs.s setup",
        "  lea buf(a6),a0", "  moveq #16,d1", "  OS9 I$Read", "  bcs.s empty",
        "  cmpi.l #5,d1", "  bne.s empty",
        "  lea allm(pc),a0", "  bra.s tell",
        "empty:", "  lea nonem(pc),a0", "  bra.s tell",
        "setup:", "  lea setm(pc),a0",
        "tell:", "  moveq #1,d0", "  moveq #40,d1", "  OS9 I$WritLn", "  moveq #0,d1", "  OS9 F$Exit",
        "wname: dc.b \"/h1/TWIN\",0", "rname: dc.b \"/h2/TWIN\",0", "hello: dc.b \"hello\"",
        "allm: dc.b \"TWIN READ ALL\",13", "nonem: dc.b \"TWIN READ SHORT\",13", "setm: dc.b \"TWIN SETUP FAILED\",13",
        "  ends", ""
    ].joined(separator: "\r")
    let twinName = "rbf: one image under two names is one device, so an open file reads the same through both"
    if filter.isEmpty || twinName.localizedCaseInsensitiveContains(filter) {
        try? twinAsm.write(toFile: scratchDisk + "/mtwin.a", atomically: true, encoding: .utf8)
        _ = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                 "r68 /h5/mtwin.a -o=/h5/mtwin.r", "l68 /h5/mtwin.r -o=/h5/mtwin"], timeout: 60)
        let out = os9(["mount /h5/\(scratchDevice) h1", "mount /h5/\(scratchDevice) h2", "/h5/mtwin"], timeout: 30)
        if out.contains("TWIN READ ALL") {
            print("PASS: \(twinName)")
            passed += 1
        } else {
            print("FAIL: \(twinName)")
            let seen = out.split(whereSeparator: \.isNewline).filter { $0.contains("TWIN") || $0.contains("rror") }
            print("      saw: \(seen)")
            failed += 1
        }
        for item in ["mtwin.a", "mtwin.r", "mtwin"] { removeScratchItem(item) }
    }
    removeScratchItem(scratchDevice)
}

// A RAW device open ("/dd@") of a host-DIRECTORY device ANSWERS, with one
// synthesized identification sector, and nothing past it (2026-09-10; it was
// refused with E$Unit from 063f8d1 until then). The reason is stat(): Microware's
// C library will not describe a file until it has opened "<device>@" and read
// 256 bytes of it, and bash finds commands, and answers `[ -f ]', through
// stat() -- so while the open was refused, no command on a host-directory
// device could be run by name (`tmode` was "command not found" with
// /h1/CMDS/tmode running fine). `free` is the visible face of the other half:
// it reads the sector, then asks for the allocation map, which the device has
// not got, and must stop there honestly -- neither E$MNF (221, "no such
// device") nor, as an off-by-one in the raw read once made it, a silent loop
// on zero-byte reads that never ended. So: the volume line, the bitmap
// refusal, no 221, and the command comes back.
run("fs: raw open of a host-directory device answers one sector, then stops",
    expectation: "free /dd names the volume, then can't read bitmap; never 221; never hangs",
    commands: ["free /dd"]) {
        $0.contains("created on") && $0.contains("bitmap") && !$0.contains("221")
    }

// A raw path names its device, and its name is the device root's host
// directory -- so SS_Attr and SS_FD through it reached that directory: a chmod
// of the whole device, and its time set from the caller's FD (found by the
// pre-release review, after the raw path gained a name). There is nothing to
// set on a device through its raw path; both are E$BMode (203).
do {
    let rawAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit equ $06", "I$Open equ $84", "I$SetStt equ $8E", "I$WritLn equ $8C",
        "  psect mrawset,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "  vsect", "fd: ds.b 16", "  ends",
        "start:",
        "  lea dev(pc),a0", "  moveq #1,d0", "  OS9 I$Open", "  bcs.s bad", "  move.w d0,d7",
        "  move.w #$1C,d1", "  moveq #0,d2", "  OS9 I$SetStt", "  bcc.s bad",
        "  cmpi.w #203,d1", "  bne.s bad",
        "  move.w d7,d0", "  move.w #$0F,d1", "  lea fd(a6),a0", "  moveq #16,d2", "  OS9 I$SetStt",
        "  bcc.s bad", "  cmpi.w #203,d1", "  bne.s bad",
        "  lea okm(pc),a0", "  bra.s tell",
        "bad:", "  lea badm(pc),a0",
        "tell:", "  moveq #1,d0", "  moveq #40,d1", "  OS9 I$WritLn", "  moveq #0,d1", "  OS9 F$Exit",
        "dev: dc.b \"/h5@\",0",
        "okm: dc.b \"RAW SETSTAT REFUSED\",13", "badm: dc.b \"RAW SETSTAT NOT REFUSED\",13",
        "  ends", ""
    ].joined(separator: "\r")

    let name = "fs: SS_Attr and SS_FD through a raw path leave the device's host directory alone"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? rawAsm.write(toFile: scratchDisk + "/mrawset.a", atomically: true, encoding: .utf8)
        _ = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                 "r68 /h5/mrawset.a -o=/h5/mrawset.r", "l68 /h5/mrawset.r -o=/h5/mrawset"], timeout: 60)
        let files  = FileManager.default
        let before = try? files.attributesOfItem(atPath: scratchDisk)
        let out    = os9(["/h5/mrawset"], timeout: 30)
        let after  = try? files.attributesOfItem(atPath: scratchDisk)
        let mode   = { (attrs: [FileAttributeKey: Any]?) in (attrs?[.posixPermissions] as? NSNumber)?.intValue ?? -1 }
        let time   = { (attrs: [FileAttributeKey: Any]?) in attrs?[.modificationDate] as? Date }
        let untouched = mode(before) == mode(after) && time(before) == time(after)
        if out.contains("RAW SETSTAT REFUSED") && untouched {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            print("      refused: \(out.contains("RAW SETSTAT REFUSED")), host dir untouched: \(untouched)")
            print("      mode \(String(mode(before), radix: 8)) -> \(String(mode(after), radix: 8))")
            failed += 1
        }
        if let old = before {                     // put the scratch device back as it was
            try? files.setAttributes([.posixPermissions: old[.posixPermissions] as Any,
                                      .modificationDate: old[.modificationDate] as Any], ofItemAtPath: scratchDisk)
        }
        for leftover in ["mrawset.a", "mrawset.r", "mrawset"] { removeScratchItem(leftover) }
    }
}

// `mount -k` names its image "<startPath>/<dev>" and prints that name, which is
// the only place the emulator's computed startPath is observable from outside.
// StartDir used to rebuild the cwd by climbing ".." and matching each child's
// stat() st_ino against the parent's dirent d_ino -- two numbers that legitimately
// differ for the same name at a MOUNT POINT (component came back "?", so
// "mount -k: can't create '/System/Volumes/?/h9'") and at a macOS FIRMLINK
// (component silently dropped: cwd /private/var/... came back as /var/...).
//
// The firmlink case is why nothing here ever caught it -- /var is a symlink to
// private/var, so the mangled path still resolved and every test passed. Hence
// the assertion is on the PHYSICALLY resolved path, which is what distinguishes
// the two. Honest limits: this fails on the old code only where the temp dir sits
// behind a symlink/firmlink (true on macOS, where NSTemporaryDirectory is
// /var/folders/...); on a Linux /tmp it passes either way, so treat it as a macOS
// guard. It is skipped under a container, where cwd is the image's WORKDIR
// rather than the host scratch dir.
if !containerized {
    // POSIX realpath(), not URL.resolvingSymlinksInPath() -- Foundation
    // deliberately keeps the /var form rather than resolving to /private/var,
    // which is precisely the component in question here.
    let resolvedScratch: String = {
        guard let r = realpath(scratchDisk, nil) else { return scratchDisk }
        defer { free(r) }
        return String(cString: r)
    }()
    run("rbf: mount -k names its image by the physically resolved cwd",
        expectation: "created '\(resolvedScratch)/\(scratchDevice)'",
        commands: ["mount -k=500K \(scratchDevice)"]) {
            $0.contains("created '\(resolvedScratch)/\(scratchDevice)'")
        }
    removeScratchItem(scratchDevice)
}

// Run the emulator DIRECTLY -- no shell, no system disk -- with a chosen
// WORKING DIRECTORY, environment and bind mounts.
//
// os9() cannot serve these: it pins the working directory to the scratch, and
// the working directory is the variable under test. This runs whichever binary
// the suite is testing: the local build, or the SAME container image every
// other test uses. Both tests below used to skip under a container, which meant
// the Linux and big-endian legs of a release run exercised neither -- the exact
// place the defects they cover actually live.
//
// Internal commands only, so nothing here depends on a system disk being
// present. Output is discarded: every assertion is on the BYTES COPIED, because
// os9exec's exit status does not distinguish "copied nothing" from "copied".
@discardableResult
func rawEmulator( _ args: [String], cwd: String,
                  env vars: [String: String] = [:],
                  mounts: [(host: String, guest: String)] = [] ) -> Bool {
    let process = Process()
    if let image = dockerImage ?? containerImage {
        let runner = dockerImage != nil ? "docker" : "container"
        var a = [runner, "run", "--rm", "-w", cwd]
        for m in mounts                                  { a += ["-v", "\(m.host):\(m.guest)"] }
        for (k, v) in vars.sorted(by: { $0.key < $1.key }) { a += ["-e", "\(k)=\(v)"] }
        process.executableURL = URL(fileURLWithPath: "/usr/bin/env")
        process.arguments     = a + [image, "-r"] + args
    } else {
        // OS9H0/OS9DISK must not leak in from the operator's shell: OS9H0 in
        // particular short-circuits the very code path under test.
        var env = ProcessInfo.processInfo.environment
        env.removeValue(forKey: "OS9H0")
        env.removeValue(forKey: "OS9DISK")
        for (k, v) in vars { env[k] = v }
        process.executableURL       = execURL
        process.arguments           = ["-r"] + args
        process.environment         = env.merging(inheritedByChildren) { mine, _ in mine }
        process.currentDirectoryURL = URL(fileURLWithPath: cwd)
    }
    // stdin MUST be detached. Without this the emulator inherits the terminal
    // the suite was launched from, puts it into raw mode and waits for a key --
    // so `make test` run interactively hung here forever while the same code
    // passed when stdin was already a pipe. Piping it is not enough either:
    // these are internal commands that read nothing, and a closed stdin is the
    // honest description of that.
    process.standardInput  = FileHandle.nullDevice
    process.standardOutput = FileHandle.nullDevice
    process.standardError  = FileHandle.nullDevice
    do { try process.run() } catch { return false }

    // And bounded, for the same reason every other run in this file is: a hang
    // must cost one test its verdict, never the whole suite.
    let deadline = Date().addingTimeInterval(60)
    while process.isRunning && Date() < deadline { usleep(50_000) }
    if process.isRunning {
        process.terminate()
        usleep(200_000)
        if process.isRunning { kill(process.processIdentifier, SIGKILL) }
    }
    process.waitUntilExit()
    return true
}

/// True when the suite drives a container rather than the local binary.
let viaContainer = (dockerImage ?? containerImage) != nil

// `/dd` must reach an RBF image from ANY working directory -- including the
// filesystem root.
//
// It did not. CheckH0's fallback for an unset OS9H0 looks for a "dd" disk
// beside the emulator by building "<startPath>/dd", and it tries the PARENT
// too; run from "/" or from a direct child of it, that string is exactly
// "/dd" -- which is not a host path at all but the OS-9 DEVICE name. MountDev
// resolved it through OS9DISK, mounted the image, and registered it under
// mnt_name "h0". The disk then belonged to h0, the real /dd mount that
// followed was refused E$DevBsy, and every /dd/... lookup failed (E$PNNF for a
// full path, E$UNIT for a bare name) while the SAME image reached through /hN
// worked perfectly.
//
// It looked like a Linux-only defect for a while, and is not: containers just
// happen to run in /work, /src or /repo, all one level below the root, whereas
// a developer shell sits deep in a home directory and usually has OS9H0 set,
// which returns from CheckH0 long before this point. Reproduced on macOS with
// `cd /` and OS9H0 unset, which is what this test does.
//
// Runs the emulator DIRECTLY rather than through os9(): the whole point is to
// control its working directory, which os9() deliberately pins to the scratch.
// Internal commands only -- no shell, no SDK, no system disk -- so what it
// proves is not entangled with what is installed. The assertion is on the
// COPIED BYTES: os9exec's exit status does not distinguish "copied nothing"
// from "copied something", and the failure mode here is silence.
//
// Runs in BOTH modes: locally the emulator's own cwd is set to "/", and under a
// container the container's is, which is the same question asked of the same
// binary.
do {
    let name = "rbf: /dd resolves to an RBF image from the filesystem root"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let base = scratchDisk + "/ddroot", out = base + "/out"
        let payload = Data("dd-from-root".utf8)
        try? FileManager.default.removeItem(atPath: base)
        try? FileManager.default.createDirectory(atPath: out,
                                                 withIntermediateDirectories: true)
        FileManager.default.createFile(atPath: base + "/payload", contents: payload)

        // Where the fixture lives as the EMULATOR sees it, and what to mount.
        let fix   = viaContainer ? "/fix" : base
        let outD  = viaContainer ? "/out" : out
        let mnts: [(host: String, guest: String)] =
            viaContainer ? [(base, "/fix"), (out, "/out")] : []
        let img   = fix + "/h7"

        rawEmulator(["mount", "-k=200K", "h7"], cwd: fix, mounts: mnts)
        rawEmulator(["imakdir", "/h7/CMDS"], cwd: fix,
                    env: ["OS9H7": img], mounts: mnts)
        rawEmulator(["icopy", "/h8/payload", "/h7/CMDS/probe"], cwd: fix,
                    env: ["OS9H7": img, "OS9H8": fix], mounts: mnts)
        // Fixture check: without it the real assertion could fail for want of a
        // file to copy and read as the defect returning.
        rawEmulator(["icopy", "/h7/CMDS/probe", "/h8/viaHN"], cwd: fix,
                    env: ["OS9H7": img, "OS9H8": outD], mounts: mnts)
        let built = FileManager.default.contents(atPath: out + "/viaHN") == payload

        rawEmulator(["icopy", "/dd/CMDS/probe", "/h8/viaDD"], cwd: "/",
                    env: ["OS9DISK": img, "OS9H8": outD], mounts: mnts)
        let viaDD = FileManager.default.contents(atPath: out + "/viaDD")

        if built && viaDD == payload {
            print("PASS: \(name)"); passed += 1
        } else {
            print("FAIL: \(name)")
            print("      [/dd/CMDS/probe copied with the emulator running in \"/\"]")
            print("      output: image built via /h7: \(built); "
                  + "bytes via /dd: \(viaDD?.count ?? -1) of \(payload.count)")
            failed += 1
        }
        try? FileManager.default.removeItem(atPath: base)
    }
}

// An RBF image FILE sitting directly in the filesystem root must work, from any
// working directory. It did not, and three separate root-directory blind spots
// had to be cleared: AdjustPath's backward walk NUL'd the leading '/' (leaving
// "" rather than "/", so the root was never tried as an anchor), CaseSens split
// a top-level component the same way and called opendir(""), and DeviceInit
// classified the resolved HOST path with IO_Type, which re-parses its argument
// as an OS-9 path -- harmless for "/deep/img" but not for a single-component
// path, which is exactly the shape of a device name.
//
// Not a container-only curiosity: `docker run -v disk.img:/dd` is the shape the
// Dockerfile itself suggests, and `mount -k` in "/" hits the same wall.
//
// Under a container the image is BIND-MOUNTED at the container's root, which is
// both writable and exactly the shape a user hits (`docker run -v disk.img:/dd`).
// Locally it has to be MOVED to "/", which macOS forbids even to root (the root
// volume is read-only), so there the test says so and skips rather than passing
// vacuously. A release run's Linux and big-endian legs are containerised, so
// this does execute where it matters.
do {
    let name = "rbf: an RBF image in the filesystem root is usable"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let rootImage = "/os9test-rootimage.dsk"
        let base = scratchDisk + "/rootimg", out = base + "/out"
        let payload = Data("root-image".utf8)
        try? FileManager.default.removeItem(atPath: base)
        try? FileManager.default.createDirectory(atPath: out,
                                                 withIntermediateDirectories: true)
        FileManager.default.createFile(atPath: base + "/payload", contents: payload)

        let fix  = viaContainer ? "/fix" : base
        let outD = viaContainer ? "/out" : out
        let mnts: [(host: String, guest: String)] =
            viaContainer ? [(base, "/fix"), (out, "/out")] : []
        let staged = fix + "/h7"

        // Built somewhere ordinary, then put at the root -- its FINAL location
        // is the whole point.
        rawEmulator(["mount", "-k=200K", "h7"], cwd: fix, mounts: mnts)
        rawEmulator(["imakdir", "/h7/SUB"], cwd: fix,
                    env: ["OS9H7": staged], mounts: mnts)
        rawEmulator(["icopy", "/h8/payload", "/h7/SUB/probe"], cwd: fix,
                    env: ["OS9H7": staged, "OS9H8": fix], mounts: mnts)

        var placed = true
        var probeMounts = mnts
        if viaContainer {
            probeMounts = [(base + "/h7", rootImage), (out, "/out")]
        } else {
            try? FileManager.default.removeItem(atPath: rootImage)
            placed = (try? FileManager.default.moveItem(atPath: base + "/h7",
                                                        toPath: rootImage)) != nil
        }

        if !placed {
            print("SKIP: \(name) (the filesystem root is not writable here)")
        } else {
            rawEmulator(["icopy", "/dd/SUB/probe", "/h8/got"], cwd: outD,
                        env: ["OS9DISK": rootImage, "OS9H8": outD],
                        mounts: probeMounts)
            let got = FileManager.default.contents(atPath: out + "/got")
            if !viaContainer { try? FileManager.default.removeItem(atPath: rootImage) }

            if got == payload {
                print("PASS: \(name)"); passed += 1
            } else {
                print("FAIL: \(name)")
                print("      [/dd/SUB/probe copied from an image at \(rootImage)]")
                print("      output: bytes via /dd: \(got?.count ?? -1) of \(payload.count)")
                failed += 1
            }
        }
        try? FileManager.default.removeItem(atPath: base)
    }
}

// Mounts its own image (self-contained, so a container's throwaway filesystem is
// fine), and asserts on the DUMPED BYTES of the copied file ("dsav" = 6473 6176)
// rather than on the name "f1": the shell echoes every command line back, so
// `contains: "f1"` matched the echo of `copy ... /f1` and would have passed even
// if dsave had written nothing at all.
check  ("rbf: dsave -ive populates+verifies", contains: "6473 6176",
    "mount -k=500K \(scratchDevice)",
    "echo dsave test content >/h5/t_dsavesrc",
    "makdir /h5/t_dsavedir",
    "copy /h5/t_dsavesrc /h5/t_dsavedir/f1",
    "chd /h5/t_dsavedir", "dsave -ive /h9",
    "chd /dd", "dump /h9/f1",
    "del /h5/t_dsavesrc", "del /h5/t_dsavedir/f1", "deldir -q /h5/t_dsavedir")

removeScratchItem(scratchDevice)

// A pathlist climbs with runs of dots: a run of n dots is n-1 levels up, clamped
// at the device root, and a climb may be spelled as any mix of runs -- `...`,
// `../..` and `../......./.././` are all legal (Using Professional OS-9 v2.4,
// p. 4-9, and rdoggett from real OS-9). On an RBF image every RELATIVE path with
// a run following another component used to resolve wrongly: EatBack/CutUp
// treated the start of a relative path as the device root, so `../..` collapsed
// to `..` and `A/..` to `A`, and the open answered E$PNNF. A host-directory
// device resolved the same spellings on the host and got them right. Asserted
// on DUMPED BYTES ("dotmark\r"), because the shell echoes every command line and
// a spelled-out marker would match its own echo.
do {
    let dotMark = "646f 746d 6172 6b0d"
    let tree    = ["mount -k=500K \(scratchDevice)", "makdir /h9/A", "makdir /h9/A/B",
                   "makdir /h9/A/B/C", "makdir /h9/SYS", "echo dotmark >/h9/SYS/f"]

    func climbs(_ label: String, from dir: String, _ commands: String...) {
        removeScratchItem(scratchDevice)
        run("rbf: dots \(label)", expectation: "from \(dir): \(commands.joined(separator: "; ")) reads /h9/SYS/f",
            commands: tree + ["chd \(dir)"] + commands) { $0.contains(dotMark) }
    }
    climbs("... (control)", from: "/h9/A/B", "dump .../SYS/f")
    climbs("../..", from: "/h9/A/B", "dump ../../SYS/f")
    climbs("../...", from: "/h9/A/B/C", "dump ../.../SYS/f")
    climbs(".../..", from: "/h9/A/B/C", "dump .../../SYS/f")
    climbs("mixed runs clamp at root", from: "/h9/A/B/C", "dump ../......./.././SYS/f")
    climbs("name/..", from: "/h9", "dump A/../SYS/f")
    climbs("name/name/...", from: "/h9", "dump A/B/.../SYS/f")
    climbs("names then ../../..", from: "/h9", "dump A/B/C/../../../SYS/f")
    climbs("absolute mixed runs", from: "/h9/A", "dump /h9/A/B/C/.../../SYS/f")
    climbs("chd ../..", from: "/h9/A/B/C", "chd ../..", "dump ../SYS/f")

    // Every run length in one pathlist, from deep enough that a miscount cannot
    // hide behind the root clamp: `./../.../..../.` is 0+1+2+3+0 = 6 levels, so
    // from depth 7 it lands on /h9/A. Its SYS/g must open, and /h9/SYS/f -- one
    // level too far -- must NOT be what answers the second dump. rdoggett,
    // 2026-09-13: "./../.../...././file" should work.
    let sixUp = "7369 7875 700d"   // dump of "sixup\r"
    removeScratchItem(scratchDevice)
    run("rbf: dots every run length from depth 7",
        expectation: "./../.../...././SYS/g reads /h9/A/SYS/g, and the same climb does not reach /h9/SYS/f",
        commands: tree + ["makdir /h9/A/B/C/D", "makdir /h9/A/B/C/D/E", "makdir /h9/A/B/C/D/E/F",
                          "makdir /h9/A/B/C/D/E/F/G", "makdir /h9/A/SYS", "echo sixup >/h9/A/SYS/g",
                          "chd /h9/A/B/C/D/E/F/G", "dump ./../.../...././SYS/g", "dump ./../.../...././SYS/f"]) {
        $0.contains(sixUp) && !$0.contains(dotMark)
    }
    removeScratchItem(scratchDevice)
}

// Two update paths on one file in one process must not deadlock each other at
// its end. An update-mode open walks the directory through the path it is
// opening, reads the directory to its end, and so takes the DIRECTORY's EOF
// lock -- which RingJoin carried onto the file along with the path (it dropped
// the walk's record locks and forgot the end one). Each path then held the other's
// end, and the first read at EOF on either was E$DEADLK (254), "the writer is us".
// dbz opens history.pag twice for update and failed "store failed" on every RBF
// image; a host directory has no locking and never showed it. The module creates
// an empty file in a fresh directory, opens it for update twice, and reads on the
// second path: the only right answer is E$EOF (211). Anything else exits with
// that error, so the shell prints it.
do {
    let eofName = "rbf: two update paths on one file do not deadlock each other at its end"
    if filter.isEmpty || eofName.localizedCaseInsensitiveContains(filter) {
        let asm = [
            "  use /dd/DEFS/oskdefs.d",
            "",
            "F$Exit   equ  $06",
            "I$Open   equ  $84",
            "I$Create equ  $83",
            "I$Read   equ  $89",
            "I$Close  equ  $8F",
            "",
            "  psect eofdl,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start", "  vsect", "scr: ds.b 4096", "  ends",
            "",
            "start:",
            "  lea     fname(pc),a0",
            "  moveq   #3,d0",
            "  moveq   #3,d1",
            "  OS9     I$Create",
            "  bcs     fail",
            "  OS9     I$Close",
            "  lea     fname(pc),a0",
            "  moveq   #3,d0",
            "  OS9     I$Open",
            "  bcs     fail",
            "  lea     fname(pc),a0",
            "  moveq   #3,d0",
            "  OS9     I$Open",
            "  bcs     fail",
            "  lea     scr(a6),a0",
            "  moveq   #16,d1",
            "  OS9     I$Read",
            "  bcc     wrong",
            "  cmpi.w  #211,d1",
            "  bne     fail",
            "  moveq   #0,d1",
            "  OS9     F$Exit",
            "wrong:",
            "  moveq   #1,d1",
            "fail:",
            "  OS9     F$Exit",
            "fname:",
            "  dc.b    \"/h9/DL/f\",0",
            "",
            "  ends",
            ""
        ].joined(separator: "\r")
        try? asm.write(toFile: scratchDisk + "/eofdl.a", atomically: true, encoding: .utf8)
        removeScratchItem(scratchDevice)

        let out = os9([
            "mount -k=500K \(scratchDevice)",
            "makdir /h9/DL",
            "load /dd/CMDS/r68 /dd/CMDS/l68",
            "r68 /h5/eofdl.a -o=/h5/eofdl.r",
            "l68 /h5/eofdl.r -o=/h5/eofdl",
            "/h5/eofdl",
            "echo EOFDL-END"
        ], timeout: 60)
        let built = FileManager.default.fileExists(atPath: scratchDisk + "/eofdl")
        let clean = out.contains("EOFDL-END") && !out.contains("Error #")
        if built && clean {
            print("PASS: \(eofName)")
            passed += 1
        } else {
            print("FAIL: \(eofName)")
            if !built { print("      the module was never built, so this proves nothing") }
            let errors = out.replacingOccurrences(of: "\r", with: "\n")
                .split(separator: "\n").filter { $0.contains("Error #") }
            for line in errors.prefix(3) { print("      | \(line.trimmingCharacters(in: .whitespaces))") }
            failed += 1
        }
        for leftover in ["eofdl.a", "eofdl.r", "eofdl"] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
        }
        removeScratchItem(scratchDevice)
    }
}

// ── RBF: a reader in another process follows a writer's end of file ──────────
// Two things the Technical Manual says a reader following a writer sees, both
// measured wrong by the skills session on an RBF image, writer and reader in
// separate processes:
//  1. "As soon as the file is created, EOF lock is gained, and no other process
//     is able to pass the writer" (ch.7): a reader opening the file before the
//     creator has written must wait for the write, not read EOF. The creator's
//     lock was set, then dropped by the ring joins on the way out of the open.
//  2. A reader that opens after a writer has appended must see those bytes: it
//     read the size from the device, where a growing file's new end was not
//     yet, and stopped at the old end.
do {
    let rbfHeader = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit equ $06", "F$Sleep equ $0A", "I$Create equ $83", "I$Open equ $84", "I$Seek equ $88",
        "I$Read equ $89", "I$Write equ $8A", "I$WritLn equ $8C", "I$GetStt equ $8D", "I$Close equ $8F"
    ]
    func sleep(_ ticks: Int) -> [String] { ["  move.l #\(ticks),d0", "  OS9 F$Sleep"] }
    func say(_ label: String) -> [String] {
        ["  lea \(label)(pc),a0", "  moveq #\(label)l,d1", "  moveq #1,d0", "  OS9 I$WritLn"]
    }
    func message(_ label: String, _ text: String) -> [String] {
        ["\(label): dc.b \"\(text)\",$0D", "\(label)l equ *-\(label)"]
    }
    // creates the file, holds it unwritten for a second, then writes "B"
    let creator = rbfHeader + [
        "  psect mlkcre,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start", "  vsect", "scr: ds.b 4096", "  ends",
        "start:",
        "  lea fname(pc),a0", "  moveq #2,d0", "  moveq #3,d1", "  OS9 I$Create", "  bcs.s done",
        "  move.w d0,d7"] + sleep(100) + [
        "  move.w d7,d0", "  lea bee(pc),a0", "  moveq #1,d1", "  OS9 I$Write"] + sleep(50) + [
        "  move.w d7,d0", "  OS9 I$Close", "  moveq #0,d1",
        "done:", "  OS9 F$Exit",
        "fname: dc.b \"/h9/LK/new\",0", "bee: dc.b \"B\"", "  ends", ""]
    // opens the existing 11-byte file, appends "A", holds it open a second
    let appender = rbfHeader + [
        "  psect mlkapp,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start", "  vsect", "scr: ds.b 4096", "  ends",
        "start:",
        "  lea aname(pc),a0", "  moveq #2,d0", "  OS9 I$Open", "  bcs.s done",
        "  move.w d0,d7", "  moveq #11,d1", "  OS9 I$Seek",
        "  move.w d7,d0", "  lea ay(pc),a0", "  moveq #1,d1", "  OS9 I$Write"] + sleep(100) + [
        "  move.w d7,d0", "  OS9 I$Close", "  moveq #0,d1",
        "done:", "  OS9 F$Exit",
        "aname: dc.b \"/h9/LK/old\",0", "ay: dc.b \"A\"", "  ends", ""]
    // reads the new file (must wait, then get B) and the appended one (12 bytes)
    let reader = rbfHeader + [
        "  psect mlkrd,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start", "  vsect", "scr: ds.b 4096", "  ends",
        "start:"] + sleep(40) + [
        "  lea fname(pc),a0", "  moveq #1,d0", "  OS9 I$Open", "  bcs.w done",
        "  lea scr(a6),a0", "  moveq #1,d1", "  OS9 I$Read", "  bcs.s notwait",
        "  cmpi.b #'B',scr(a6)", "  bne.s notwait"] + say("mwait") + ["  bra.s second", "notwait:"] + say("mnowait") + [
        "second:"] + sleep(10) + [
        "  lea aname(pc),a0", "  moveq #1,d0", "  OS9 I$Open", "  bcs.s done",
        "  lea scr(a6),a0", "  moveq #64,d1", "  OS9 I$Read", "  bcs.s short",
        "  cmpi.l #12,d1", "  bne.s short"] + say("mall") + ["  bra.s fin", "short:"] + say("mshort") + [
        "fin:", "  moveq #0,d1",
        "done:", "  OS9 F$Exit",
        "fname: dc.b \"/h9/LK/new\",0", "aname: dc.b \"/h9/LK/old\",0"] +
        message("mwait", "READER WAITED FOR THE CREATOR") + message("mnowait", "READER PASSED THE CREATOR") +
        message("mall", "READER SAW THE APPENDED BYTE") + message("mshort", "READER MISSED THE APPENDED BYTE") +
        ["  ends", ""]

    let modules = ["mlkcre": creator, "mlkapp": appender, "mlkrd": reader]
    for (module, lines) in modules {
        try? lines.joined(separator: "\r").write(toFile: scratchDisk + "/\(module).a",
                                                  atomically: true, encoding: .utf8)
    }
    let names = ["rbf: a reader in another process waits for a creator that has not yet written",
                 "rbf: a reader that opens after a writer appended sees the appended bytes"]
    if names.contains(where: { filter.isEmpty || $0.localizedCaseInsensitiveContains(filter) }) {
        var build = ["load /dd/CMDS/r68 /dd/CMDS/l68"]
        for module in modules.keys.sorted() {
            build += ["r68 /h5/\(module).a -o=/h5/\(module).r", "l68 /h5/\(module).r -o=/h5/\(module)"]
        }
        _ = os9(build, timeout: 60)
        removeScratchItem(scratchDevice)
        let out = os9(["mount -k=500K \(scratchDevice)", "makdir /h9/LK",
                       "echo 0123456789 >/h9/LK/old",
                       "/h5/mlkcre &", "/h5/mlkapp &", "/h5/mlkrd", "sleep -s 2"], timeout: 45)
        let outcomes = [("READER WAITED FOR THE CREATOR", names[0]), ("READER SAW THE APPENDED BYTE", names[1])]
        for (want, name) in outcomes where filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
            if out.contains(want) {
                print("PASS: \(name)")
                passed += 1
            } else {
                print("FAIL: \(name)")
                let seen = out.split(whereSeparator: \.isNewline)
                    .filter { $0.contains("READER") || $0.contains("Error") }
                print("      saw: \(seen.joined(separator: " | "))")
                failed += 1
            }
        }
        removeScratchItem(scratchDevice)
    }
    for module in modules.keys {
        for suffix in [".a", ".r", ""] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/\(module)" + suffix)
        }
    }
}

// ── RBF: an image that claims sectors bigger than os9exec reads is refused ────
// An image's sector size is its own claim (the word at $68 of its sector 0),
// as untrusted as the rest of it. It was checked for a RAM disk and SCSI but
// not for an image, and every path's FD and data buffers are 2048 bytes: an
// image saying 4096 had each sector read run 2048 bytes past its buffer, inside
// the arena where no sanitizer sees it. Found by review.
do {
    let name = "rbf: an image claiming 4096-byte sectors is refused E$SectSize, not read past the buffers"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        removeScratchItem(scratchDevice)
        _ = os9(["mount -k=512K \(scratchDevice)", "echo seed >/h9/seed"], timeout: 30)
        var patched = false
        if let handle = FileHandle(forUpdatingAtPath: scratchHostPath) {
            handle.seek(toFileOffset: 0x68)
            handle.write(Data([0x10, 0x00]))          // 4096, big-endian
            handle.closeFile()
            patched = true
        }
        let out = os9(["list /h9/seed"], timeout: 30)
        if patched && out.contains("000:176") && !out.split(whereSeparator: \.isNewline).contains("seed") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = out.split(whereSeparator: \.isNewline).filter { $0.contains("Error") || $0.contains("seed") }
            print("      saw (patched=\(patched)): \(seen.joined(separator: " | "))")
            failed += 1
        }
        removeScratchItem(scratchDevice)
    }
}

// ── RBF: an image whose sector-size word is 0 opens as 256-byte sectors ───────
// Sector 0's word at $68 is the sector size, and images from formats that
// predate the field carry 0 there, which has always meant 256. The check added
// for oversized sectors ran before that fallback and refused such images with
// E$SectSize -- a user's own disk that had opened for years. Found by rdoggett.
do {
    let name = "rbf: an image whose sector-size word is 0 still opens, as 256-byte sectors"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        removeScratchItem(scratchDevice)
        _ = os9(["mount -k=512K \(scratchDevice)", "echo seed >/h9/seed"], timeout: 30)
        var patched = false
        if let handle = FileHandle(forUpdatingAtPath: scratchHostPath) {
            handle.seek(toFileOffset: 0x68)
            handle.write(Data([0x00, 0x00]))          // no sector size recorded
            handle.closeFile()
            patched = true
        }
        let out = os9(["list /h9/seed"], timeout: 30)
        let listed = out.split(whereSeparator: \.isNewline)
            .contains { $0.trimmingCharacters(in: .whitespaces) == "seed" }
        if patched && listed && !out.contains("Error") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = out.split(whereSeparator: \.isNewline).filter { $0.contains("Error") || $0.contains("seed") }
            print("      saw (patched=\(patched)): \(seen.joined(separator: " | "))")
            failed += 1
        }
        removeScratchItem(scratchDevice)
    }
}

// ── RBF: an unmarked disk opens only with -6; a file of junk never does ────────
// os9exec takes a file for an RBF disk when sector 0 carries "Cruz" at $60, the
// OS-9/68000 format's mark, which 6809 (CoCo) disks never have. The mark looks
// deliberate -- a guard against taking a 6809 disk for a 68000 one -- so an
// unmarked disk opens only when asked for with -6, then recognised by a sector 0
// describing a disk the file can hold. A fresh image with its mark blanked
// stands in for an unmarked disk; a file of arbitrary bytes named like a disk
// must not be taken for one even with -6.
do {
    let name = "rbf: an unmarked disk (as 6809 disks are) opens only with -6; junk never does"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        removeScratchItem(scratchDevice)
        _ = os9(["mount -k=512K \(scratchDevice)", "echo unmarked >/h9/seed"], timeout: 30)
        var patched = false
        if let handle = FileHandle(forUpdatingAtPath: scratchHostPath) {
            handle.seek(toFileOffset: 0x60)
            handle.write(Data([0, 0, 0, 0]))          // no "Cruz"
            handle.closeFile()
            patched = true
        }
        func lists(_ out: String) -> Bool {
            out.split(whereSeparator: \.isNewline).contains { $0.trimmingCharacters(in: .whitespaces) == "unmarked" }
        }
        let plain = lists(os9(["list /h9/seed"], timeout: 30))
        let asked = lists(os9(["list /h9/seed"], timeout: 30, flags: ["-6"]))
        removeScratchItem(scratchDevice)
        var junk = Data(count: 64 * 1024)
        for index in 0..<junk.count { junk[index] = UInt8(truncatingIfNeeded: index * 131 + 17) }
        FileManager.default.createFile(atPath: scratchHostPath, contents: junk)
        let junkIsNoDisk = !os9(["dir /h9"], timeout: 30, flags: ["-6"]).contains("Directory of /h9")
        if patched && !plain && asked && junkIsNoDisk {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            print("      opened without -6: \(plain), with -6: \(asked), junk refused: \(junkIsNoDisk)")
            failed += 1
        }
        removeScratchItem(scratchDevice)
    }
}

// ── RBF: a byte patched after a multi-sector write lands in the written data ──
// A write of whole sectors goes to the device in one transfer, and the path's
// one-sector cache was then labelled with the last sector written without
// holding its bytes. Patching one byte there afterwards copied it into the
// stale buffer, and closing flushed the stale sector back over the write.
// Found by review (older than v4.0.0).
do {
    let patchAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit equ $06", "I$Create equ $83", "I$Open equ $84", "I$Seek equ $88", "I$Read equ $89",
        "I$Write equ $8A", "I$WritLn equ $8C", "I$Close equ $8F",
        "  psect mpatch,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,2048,start", "  vsect", "scr: ds.b 4096", "  ends",
        "start:",
        "  lea scr(a6),a0", "  move.w #511,d0",
        "fill:", "  move.b #'Q',(a0)+", "  dbra d0,fill",
        "  lea fname(pc),a0", "  moveq #3,d0", "  moveq #3,d1", "  OS9 I$Create", "  bcs.w fail",
        "  move.w d0,d7",
        "  move.w d7,d0", "  lea scr(a6),a0", "  move.l #512,d1", "  OS9 I$Write", "  bcs.w fail",
        "  move.w d7,d0", "  move.l #500,d1", "  OS9 I$Seek", "  bcs.w fail",
        "  move.w d7,d0", "  lea zee(pc),a0", "  moveq #1,d1", "  OS9 I$Write", "  bcs.w fail",
        "  move.w d7,d0", "  OS9 I$Close",
        "  lea fname(pc),a0", "  moveq #1,d0", "  OS9 I$Open", "  bcs.w fail", "  move.w d0,d7",
        "  move.w d7,d0", "  lea scr+512(a6),a0", "  move.l #512,d1", "  OS9 I$Read", "  bcs.w fail",
        "  lea scr+512(a6),a0", "  move.w #499,d0",
        "c1:", "  cmpi.b #'Q',(a0)+", "  bne.s bad", "  dbra d0,c1",
        "  cmpi.b #'Z',(a0)+", "  bne.s bad", "  moveq #10,d0",
        "c2:", "  cmpi.b #'Q',(a0)+", "  bne.s bad", "  dbra d0,c2",
        "  lea mok(pc),a0", "  moveq #mokl,d1", "  bra.s say",
        "bad:", "  lea mbad(pc),a0", "  moveq #mbadl,d1",
        "say:", "  moveq #1,d0", "  OS9 I$WritLn", "  moveq #0,d1",
        "fail:", "  OS9 F$Exit",
        "fname: dc.b \"/h9/patched\",0", "zee: dc.b \"Z\"",
        "mok:  dc.b \"PATCHED BYTE LANDED IN THE WRITTEN DATA\",$0D", "mokl equ *-mok",
        "mbad: dc.b \"PATCH BROUGHT BACK A STALE SECTOR\",$0D", "mbadl equ *-mbad",
        "  ends", ""
    ].joined(separator: "\r")

    let name = "rbf: a byte patched after a multi-sector write lands in the written data"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? patchAsm.write(toFile: scratchDisk + "/mpatch.a", atomically: true, encoding: .utf8)
        removeScratchItem(scratchDevice)
        let out = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                       "r68 /h5/mpatch.a -o=/h5/mpatch.r", "l68 /h5/mpatch.r -o=/h5/mpatch",
                       "mount -k=500K \(scratchDevice)", "/h5/mpatch"], timeout: 45)
        if out.contains("PATCHED BYTE LANDED IN THE WRITTEN DATA") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = out.split(whereSeparator: \.isNewline).filter { $0.contains("PATCH") || $0.contains("Error") }
            print("      saw: \(seen.joined(separator: " | "))")
            failed += 1
        }
        for leftover in ["mpatch.a", "mpatch.r", "mpatch"] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
        }
        removeScratchItem(scratchDevice)
    }
}

// ── RBF: closing one writer does not free sectors another is writing into ────
// A write path closing at the end of the file trimmed it there and freed the
// preallocated sectors past that point, although another path open on the
// file had taken the same segment list and went on writing into them without
// allocating. The next file created was given those sectors: two files on one
// sector. Found by review; reachable since RingAdopt (ddefbe6) gave the second
// path the first one's preallocation, which the old code then freed under it.
do {
    let crossAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit equ $06", "I$Create equ $83", "I$Open equ $84", "I$Seek equ $88", "I$Read equ $89",
        "I$Write equ $8A", "I$WritLn equ $8C", "I$Close equ $8F",
        "  psect mcross,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,4096,start", "  vsect", "scr: ds.b 4096", "  ends",
        "start:",
        "  lea scr(a6),a0", "  move.w #299,d0",
        "fl:", "  move.b #'L',(a0)+", "  dbra d0,fl",
        "  lea scr+512(a6),a0", "  move.w #1023,d0",
        "fx:", "  move.b #'X',(a0)+", "  dbra d0,fx",
        "  lea lname(pc),a0", "  moveq #3,d0", "  moveq #3,d1", "  OS9 I$Create", "  bcs.w fail",
        "  move.w d0,d7",
        "  move.w d7,d0", "  lea ten(pc),a0", "  moveq #10,d1", "  OS9 I$Write", "  bcs.w fail",
        "  lea lname(pc),a0", "  moveq #3,d0", "  OS9 I$Open", "  bcs.w fail", "  move.w d0,d6",
        "  move.w d7,d0", "  OS9 I$Close",                       // at its end: it used to trim here
        "  move.w d6,d0", "  moveq #10,d1", "  OS9 I$Seek", "  bcs.w fail",
        "  move.w d6,d0", "  lea scr(a6),a0", "  move.l #300,d1", "  OS9 I$Write", "  bcs.w fail",
        "  move.w d6,d0", "  OS9 I$Close",
        "  lea oname(pc),a0", "  moveq #3,d0", "  moveq #3,d1", "  OS9 I$Create", "  bcs.w fail",
        "  move.w d0,d7",
        "  move.w d7,d0", "  lea scr+512(a6),a0", "  move.l #1024,d1", "  OS9 I$Write", "  bcs.w fail",
        "  move.w d7,d0", "  OS9 I$Close",
        "  lea lname(pc),a0", "  moveq #1,d0", "  OS9 I$Open", "  bcs.w fail", "  move.w d0,d7",
        "  move.w d7,d0", "  moveq #10,d1", "  OS9 I$Seek", "  bcs.w fail",
        "  move.w d7,d0", "  lea scr+2048(a6),a0", "  move.l #300,d1", "  OS9 I$Read", "  bcs.w fail",
        "  lea scr+2048(a6),a0", "  move.w #299,d0",
        "ck:", "  cmpi.b #'L',(a0)+", "  bne.s bad", "  dbra d0,ck",
        "  lea mok(pc),a0", "  moveq #mokl,d1", "  bra.s say",
        "bad:", "  lea mbad(pc),a0", "  moveq #mbadl,d1",
        "say:", "  moveq #1,d0", "  OS9 I$WritLn", "  moveq #0,d1",
        "fail:", "  OS9 F$Exit",
        "lname: dc.b \"/h9/log\",0", "oname: dc.b \"/h9/other\",0", "ten: dc.b \"0123456789\"",
        "mok:  dc.b \"SECOND WRITER KEPT ITS SECTORS\",$0D", "mokl equ *-mok",
        "mbad: dc.b \"ANOTHER FILE TOOK THE WRITER'S SECTORS\",$0D", "mbadl equ *-mbad",
        "  ends", ""
    ].joined(separator: "\r")

    let name = "rbf: closing one writer does not free sectors another open path is writing into"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? crossAsm.write(toFile: scratchDisk + "/mcross.a", atomically: true, encoding: .utf8)
        removeScratchItem(scratchDevice)
        let out = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                       "r68 /h5/mcross.a -o=/h5/mcross.r", "l68 /h5/mcross.r -o=/h5/mcross",
                       "mount -k=500K \(scratchDevice)", "/h5/mcross", "dcheck /h9"], timeout: 60)
        // dcheck is the arbiter: a freed sector still in a file's segment list
        // is "not in bit map" whether or not the next file happens to take it
        if out.contains("SECOND WRITER KEPT ITS SECTORS") && dcheckClean(out) {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = out.split(whereSeparator: \.isNewline)
                .filter { $0.contains("WRITER") || $0.contains("Error") || $0.contains("bit map") ||
                          $0.contains("intact") }
            print("      saw: \(seen.joined(separator: " | "))")
            failed += 1
        }
        for leftover in ["mcross.a", "mcross.r", "mcross"] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
        }
        removeScratchItem(scratchDevice)
    }
}

// ── RBF: deleting one name of a file with two keeps the file ─────────────────
// "Decrements link count in file descriptor. If the link count becomes zero,
// all disk space associated with the file is returned ... If the link count is
// non-zero, no disk space is returned" (Technical I/O Manual, RBF, I$Delete).
// The space went back whatever the count, so a file linked under a second name
// lost its FD and data under the surviving name (osk-freeware: C News's LOCK
// file came back listing as a directory). The program makes the second name the
// way period ln tools did -- a directory entry for the same FD, and FD_LNK
// raised through the raw device -- deletes the first, and reads the second.
do {
    let linkAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit equ $06", "I$Create equ $83", "I$Open equ $84", "I$Delete equ $87", "I$Seek equ $88",
        "I$Read equ $89", "I$Write equ $8A", "I$WritLn equ $8C", "I$GetStt equ $8D", "I$Close equ $8F",
        "  psect mlink,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,2048,start", "  vsect", "scr: ds.b 4096", "  ends",
        "start:",
        "  lea aname(pc),a0", "  moveq #3,d0", "  moveq #3,d1", "  OS9 I$Create", "  bcs.w fail",
        "  move.w d0,d7", "  lea hello(pc),a0", "  moveq #5,d1", "  OS9 I$Write", "  bcs.w fail",
        "  move.w d7,d0", "  OS9 I$Close",
        // find a's entry: 32-byte records, name's last byte has its top bit set
        "  lea dname(pc),a0", "  move.w #$81,d0", "  OS9 I$Open", "  bcs.w fail", "  move.w d0,d7",
        "next:", "  move.w d7,d0", "  lea scr(a6),a0", "  moveq #32,d1", "  OS9 I$Read", "  bcs.w fail",
        "  cmpi.b #$E1,scr(a6)", "  bne.s next",
        "  moveq #0,d6", "  move.b scr+29(a6),d6", "  lsl.l #8,d6", "  move.b scr+30(a6),d6",
        "  lsl.l #8,d6", "  move.b scr+31(a6),d6",                 // d6 = the FD's LSN
        "  move.w d7,d0", "  OS9 I$Close",
        // append an entry "b" for the same FD
        "  lea dname(pc),a0", "  move.w #$83,d0", "  OS9 I$Open", "  bcs.w fail", "  move.w d0,d7",
        "  move.w d7,d0", "  moveq #2,d1", "  OS9 I$GetStt", "  bcs.w fail",   // SS_Size -> d2
        "  move.w d7,d0", "  move.l d2,d1", "  OS9 I$Seek", "  bcs.w fail",
        "  lea scr+64(a6),a0", "  moveq #31,d0",
        "clr:", "  clr.b (a0)+", "  dbra d0,clr",
        "  move.b #$E2,scr+64(a6)", "  move.l d6,d0", "  move.b d0,scr+95(a6)", "  lsr.l #8,d0",
        "  move.b d0,scr+94(a6)", "  lsr.l #8,d0", "  move.b d0,scr+93(a6)",
        "  move.w d7,d0", "  lea scr+64(a6),a0", "  moveq #32,d1", "  OS9 I$Write", "  bcs.w fail",
        "  move.w d7,d0", "  OS9 I$Close",
        // FD_LNK (FD offset 8) = 2, through the raw device; 256-byte sectors
        "  lea rname(pc),a0", "  moveq #3,d0", "  OS9 I$Open", "  bcs.w fail", "  move.w d0,d7",
        "  move.l d6,d1", "  lsl.l #8,d1", "  addq.l #8,d1", "  move.w d7,d0", "  OS9 I$Seek", "  bcs.w fail",
        "  move.w d7,d0", "  lea two(pc),a0", "  moveq #1,d1", "  OS9 I$Write", "  bcs.w fail",
        "  move.w d7,d0", "  OS9 I$Close",
        // delete a, read b
        "  lea aname(pc),a0", "  moveq #2,d0", "  OS9 I$Delete", "  bcs.w fail",
        "  lea bname(pc),a0", "  moveq #1,d0", "  OS9 I$Open", "  bcs.s gone", "  move.w d0,d7",
        "  move.w d7,d0", "  lea scr+128(a6),a0", "  moveq #5,d1", "  OS9 I$Read", "  bcs.s gone",
        "  cmpi.l #'HELL',scr+128(a6)", "  bne.s gone",
        "  lea mok(pc),a0", "  moveq #mokl,d1", "  bra.s say",
        "gone:", "  lea mbad(pc),a0", "  moveq #mbadl,d1",
        "say:", "  moveq #1,d0", "  OS9 I$WritLn", "  moveq #0,d1",
        "fail:", "  OS9 F$Exit",
        "aname: dc.b \"/h9/a\",0", "bname: dc.b \"/h9/b\",0", "dname: dc.b \"/h9\",0",
        "rname: dc.b \"/h9@\",0", "hello: dc.b \"HELLO\"", "two: dc.b 2",
        "mok:  dc.b \"SECOND NAME STILL READS\",$0D", "mokl equ *-mok",
        "mbad: dc.b \"SECOND NAME LOST ITS FILE\",$0D", "mbadl equ *-mbad",
        "  ends", ""
    ].joined(separator: "\r")

    let name = "rbf: deleting one name of a file with two keeps its descriptor and space"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? linkAsm.write(toFile: scratchDisk + "/mlink.a", atomically: true, encoding: .utf8)
        removeScratchItem(scratchDevice)
        // built in a call of its own: r68's listing plus dcheck's report at the
        // paced console rate do not fit one call's budget
        _ = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                 "r68 /h5/mlink.a -o=/h5/mlink.r", "l68 /h5/mlink.r -o=/h5/mlink"], timeout: 60)
        // dcheck in the same session, after modules are loaded (os9() loads
        // math and cio first): this once made dcheck loop, because mlink used
        // plain (a6) as its buffer -- a6 points $8000 into the data area, so
        // that wrote 28K past it, into the resident csl library dcheck runs.
        let out = os9(["mount -k=500K \(scratchDevice)", "/h5/mlink", "dcheck /h9"], timeout: 60)
        if out.contains("SECOND NAME STILL READS") && dcheckClean(out) {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = out.split(whereSeparator: \.isNewline)
                .filter { $0.contains("NAME") || $0.contains("Error") || $0.contains("bit map") ||
                          $0.contains("intact") || $0.contains("dcheck:") }
            print("      saw: \(seen.joined(separator: " | "))")
            failed += 1
        }
        for leftover in ["mlink.a", "mlink.r", "mlink"] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
        }
        removeScratchItem(scratchDevice)
    }
}

// ── RBF: a single allocation of 65536 sectors or more is recorded in full ─────
// The routine that enters an allocation in the FD's segment list held its
// sector count in 16 bits. SS_Size can ask for that much in one call, and on an
// image with large clusters one search returns it: the count was cut, the FD
// named a fraction of the sectors, and the rest stayed set in the bitmap with
// no file owning them. Found by review. 17 MB on a 20 MB image with 64-sector
// clusters is 66407 sectors in one allocation.
do {
    let bigAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit equ $06", "I$Create equ $83", "I$SetStt equ $8E", "I$Close equ $8F",
        "  psect mbig,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  lea fname(pc),a0", "  moveq #3,d0", "  moveq #3,d1", "  OS9 I$Create", "  bcs.s fail",
        "  move.w d0,d7", "  move.l #17000000,d2", "  moveq #2,d1", "  OS9 I$SetStt", "  bcs.s fail",
        "  move.w d7,d0", "  OS9 I$Close", "  moveq #0,d1",
        "fail:", "  OS9 F$Exit",
        "fname: dc.b \"/h9/big\",0",
        "  ends", ""
    ].joined(separator: "\r")

    let name = "rbf: an allocation of 65536 sectors or more is entered in the FD in full"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? bigAsm.write(toFile: scratchDisk + "/mbig.a", atomically: true, encoding: .utf8)
        removeScratchItem(scratchDevice)
        _ = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                 "r68 /h5/mbig.a -o=/h5/mbig.r", "l68 /h5/mbig.r -o=/h5/mbig"], timeout: 60)
        let run = os9(["mount -k=20M -c=64 \(scratchDevice)", "/h5/mbig"], timeout: 60)
        let out = run + os9(["dcheck /h9"], timeout: 120)
        if dcheckClean(out) && !out.contains("Error #") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = out.split(whereSeparator: \.isNewline)
                .filter { $0.contains("Error") || $0.contains("not in") || $0.contains("intact") }
                .prefix(4)
            print("      saw: \(seen.joined(separator: " | "))")
            failed += 1
        }
        for leftover in ["mbig.a", "mbig.r", "mbig"] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
        }
        removeScratchItem(scratchDevice)
    }
}

// ── RBF: SS_Size that fills the disk part way leaves the FD naming what it took ──
// SS_Size allocates in as many pieces as the free space comes in. When the disk
// ran out part way (E$Full) the pieces taken so far were written to the disk's
// FD but not handed to the file's other paths, and the next of those to write
// its FD (here with SS_Attr) put its own older copy back over them: set in the
// bitmap, named by no FD. The program opens a second path, asks the first for
// more than the image holds, sets the attributes through the second, and runs
// dcheck with both still open. Found by review.
do {
    let fullAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Fork equ $03", "F$Wait equ $04", "F$Exit equ $06",
        "I$Create equ $83", "I$Open equ $84", "I$SetStt equ $8E", "I$Close equ $8F",
        "  psect mfull,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  lea fname(pc),a0", "  moveq #3,d0", "  moveq #3,d1", "  OS9 I$Create", "  bcs.s fail",
        "  move.w d0,d7",
        "  lea fname(pc),a0", "  moveq #3,d0", "  OS9 I$Open", "  bcs.s fail", "  move.w d0,d6",
        "  move.w d7,d0", "  move.l #4000000,d2", "  moveq #2,d1", "  OS9 I$SetStt", "  bcc.s fail",
        "  move.w d6,d0", "  moveq #$1B,d2", "  moveq #$1C,d1", "  OS9 I$SetStt", "  bcs.s fail",
        "  lea cmd(pc),a0", "  lea parm(pc),a1", "  moveq #0,d0", "  moveq #0,d1", "  moveq #parml,d2",
        "  moveq #3,d3", "  moveq #0,d4", "  OS9 F$Fork", "  bcs.s fail", "  OS9 F$Wait",
        "  move.w d6,d0", "  OS9 I$Close", "  move.w d7,d0", "  OS9 I$Close", "  moveq #0,d1",
        "fail:", "  OS9 F$Exit",
        "fname: dc.b \"/h9/filler\",0", "cmd: dc.b \"dcheck\",0",
        "parm: dc.b \"/h9\",$0D", "parml equ *-parm",
        "  ends", ""
    ].joined(separator: "\r")

    let name = "rbf: SS_Size that fills the disk part way hands its FD to the file's other paths"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? fullAsm.write(toFile: scratchDisk + "/mfull.a", atomically: true, encoding: .utf8)
        removeScratchItem(scratchDevice)
        _ = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                 "r68 /h5/mfull.a -o=/h5/mfull.r", "l68 /h5/mfull.r -o=/h5/mfull"], timeout: 60)
        let out = os9(["mount -k=300K \(scratchDevice)", "/h5/mfull"], timeout: 120)
        if dcheckClean(out) {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = out.split(whereSeparator: \.isNewline)
                .filter { $0.contains("Error") || $0.contains("not in") || $0.contains("intact") }
                .prefix(4)
            print("      saw: \(seen.joined(separator: " | "))")
            failed += 1
        }
        for leftover in ["mfull.a", "mfull.r", "mfull"] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
        }
        removeScratchItem(scratchDevice)
    }
}

// ── RBF: a chd too deep for the path field is refused, not written past it ──────
// The process's current path is a 255-byte field, and a relative chd appended to
// it with no bound: a tree of 28-character directories nested ten deep, entered
// one level at a time, ran past the field into the rest of the process
// descriptor. Found by the pre-release review. The level that would not fit must
// be refused E$BPNam, and pwd must still answer from the level before.
do {
    let name = "rbf: a chd too deep for the 255-byte path field is refused E$BPNam"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        removeScratchItem(scratchDevice)
        let level = "abcdefghijklmnopqrstuvwxyz28"
        var commands = ["mount -k=512K \(scratchDevice)", "chd /h9"]
        for _ in 0..<10 { commands += ["makdir \(level)", "chd \(level)"] }
        commands += ["echo DEPTH DONE"]
        let out = os9(commands, timeout: 60)
        let refused = out.contains("000:215")
        if refused && out.contains("DEPTH DONE") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            print("      refused E$BPNam: \(refused)")
            failed += 1
        }
        removeScratchItem(scratchDevice)
    }
}

// ── RBF: a directory with an unwritten entry is not taken for an empty one ──────
// SS_Attr refuses to clear the directory bit of a directory that is not empty,
// but the emptiness test read the device: an entry still unwritten in a path's
// sector buffer was invisible, and the directory became a plain file with a live
// entry in it -- orphaning that entry's file. Found by the pre-release review. A
// directory gets one deleted slot; an update path on it writes an entry into
// that slot (held in its buffer) and asks, on the same path, to clear the bit.
do {
    let dneAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit equ $06", "I$Open equ $84", "I$Seek equ $88", "I$Write equ $8A",
        "I$WritLn equ $8C", "I$SetStt equ $8E", "I$Close equ $8F",
        "  psect mdne,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "  vsect", "entry: ds.b 32", "  ends",
        "start:",
        "  lea entry(a6),a0", "  move.b #$F9,(a0)", "  move.b #1,31(a0)",       // "y", FD at sector 1
        "  lea dname(pc),a0", "  move.w #$83,d0", "  OS9 I$Open", "  bcs.s bad", "  move.w d0,d7",
        "  move.w d7,d0", "  moveq #64,d1", "  OS9 I$Seek", "  bcs.s bad",
        "  move.w d7,d0", "  lea entry(a6),a0", "  moveq #32,d1", "  OS9 I$Write", "  bcs.s bad",
        "  move.w d7,d0", "  moveq #$1C,d1", "  moveq #$3F,d2", "  OS9 I$SetStt",
        "  bcc.s bad", "  cmpi.w #238,d1", "  bne.s bad",
        "  lea mok(pc),a0", "  moveq #mokl,d1", "  bra.s say",
        "bad:", "  lea mbad(pc),a0", "  moveq #mbadl,d1",
        "say:", "  moveq #1,d0", "  OS9 I$WritLn", "  moveq #0,d1", "  OS9 F$Exit",
        "dname: dc.b \"/h9/d\",0",
        "mok:  dc.b \"UNWRITTEN ENTRY COUNTS\",$0D", "mokl equ *-mok",
        "mbad: dc.b \"DIRECTORY TAKEN FOR EMPTY\",$0D", "mbadl equ *-mbad",
        "  ends", ""
    ].joined(separator: "\r")

    let name = "rbf: a directory with an entry not yet written is not taken for an empty one"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? dneAsm.write(toFile: scratchDisk + "/mdne.a", atomically: true, encoding: .utf8)
        removeScratchItem(scratchDevice)
        _ = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                 "r68 /h5/mdne.a -o=/h5/mdne.r", "l68 /h5/mdne.r -o=/h5/mdne"], timeout: 60)
        let out = os9(["mount -k=512K \(scratchDevice)", "makdir /h9/d", "echo x >/h9/d/x", "del /h9/d/x",
                       "/h5/mdne"], timeout: 60)
        if out.contains("UNWRITTEN ENTRY COUNTS") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = out.split(whereSeparator: \.isNewline)
                .filter { $0.contains("ENTRY") || $0.contains("EMPTY") || $0.contains("Error") }
            print("      saw: \(seen.joined(separator: " | "))")
            failed += 1
        }
        for leftover in ["mdne.a", "mdne.r", "mdne"] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
        }
        removeScratchItem(scratchDevice)
    }
}

// ── RBF: a full segment list leaves no freed sectors in the file's FD ───────────
// When an allocation found the FD's segment list full (E$SLF), the new run had
// already been written into the path's copy of the FD, and its sectors were then
// freed; SS_Size's error path also handed that copy to the file's other paths.
// A path holding it then grew the file into the freed run with no allocation --
// writing sectors the bitmap calls free, which the next allocation hands to
// another file -- and wrote the FD with the run in it. Found by the pre-release
// review. Two files are written in turns until the first has 47 of its 48
// segment slots; a second path opens it; SS_Size asks for more than one segment
// can hold (32767 sectors) -- on 16-sector clusters, so that one bitmap sector
// can give a run that long -- and the run fills the last slot and runs out. The
// second path writes its FD (SS_Attr) and the first writes 4K at the end, which
// now takes a proper allocation. dcheck must pass: on the build before, it
// reports the 4K's sectors as "not in bit map".
do {
    let slfAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit equ $06", "I$Create equ $83", "I$Open equ $84", "I$Write equ $8A",
        "I$SetStt equ $8E", "I$Close equ $8F",
        "  psect mslf,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "  vsect", "scr: ds.b 4096", "  ends",
        "start:",
        "  lea aname(pc),a0", "  moveq #3,d0", "  moveq #3,d1", "  OS9 I$Create", "  bcs.w done",
        "  move.w d0,d7",
        "  lea bname(pc),a0", "  moveq #3,d0", "  moveq #3,d1", "  OS9 I$Create", "  bcs.w done",
        "  move.w d0,d6",
        "  moveq #45,d5",                                     // 46 turns: 47 of 48 slots
        "turns:", "  move.w d7,d0", "  lea scr(a6),a0", "  move.l #4096,d1", "  OS9 I$Write",   // one cluster
        "  move.w d6,d0", "  lea scr(a6),a0", "  move.l #4096,d1", "  OS9 I$Write",
        "  dbra d5,turns",
        "  lea aname(pc),a0", "  moveq #3,d0", "  OS9 I$Open", "  bcs.w done", "  move.w d0,d4",
        "  move.w d7,d0", "  moveq #2,d1", "  move.l #10000000,d2", "  OS9 I$SetStt",  // > one segment
        "  move.w d4,d0", "  moveq #$1C,d1", "  moveq #$1B,d2", "  OS9 I$SetStt",
        "  move.w d7,d0", "  lea scr(a6),a0", "  move.l #4096,d1", "  OS9 I$Write",   // grow into it
        "  move.w d4,d0", "  OS9 I$Close", "  move.w d6,d0", "  OS9 I$Close",
        "  move.w d7,d0", "  OS9 I$Close",
        "done:", "  moveq #0,d1", "  OS9 F$Exit",
        "aname: dc.b \"/h9/segs\",0", "bname: dc.b \"/h9/between\",0",
        "  ends", ""
    ].joined(separator: "\r")

    let name = "rbf: a full segment list leaves no freed sectors in the file's FD (E$SLF)"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? slfAsm.write(toFile: scratchDisk + "/mslf.a", atomically: true, encoding: .utf8)
        removeScratchItem(scratchDevice)
        _ = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                 "r68 /h5/mslf.a -o=/h5/mslf.r", "l68 /h5/mslf.r -o=/h5/mslf"], timeout: 60)
        let out = os9(["mount -k=16M -c=16 \(scratchDevice)", "/h5/mslf"], timeout: 60)
            + os9(["dcheck /h9"], timeout: 120)
        if dcheckClean(out) {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = out.split(whereSeparator: \.isNewline)
                .filter { $0.contains("RUN") || $0.contains("Error") || $0.contains("not in") }.prefix(4)
            print("      saw: \(seen.joined(separator: " | "))")
            failed += 1
        }
        for leftover in ["mslf.a", "mslf.r", "mslf"] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
        }
        removeScratchItem(scratchDevice)
    }
}

// ── RBF: a write that runs out of disk leaves the file's size alone ─────────────
// A write that needed a new allocation and found the disk full set the file's
// size to where that write began. Begun inside the file, that cut off whatever
// lay past it: a file of 200 bytes, a write of 2000 at 150 on a full disk, and
// the file closed at 150. Found by the pre-release review. The program writes
// 200 bytes, fills the disk with a second file (SS_Size far past its end),
// writes 2000 at offset 150 of the first (E$Full), closes it, and reads its
// size back.
do {
    let fullAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit equ $06", "I$Create equ $83", "I$Open equ $84", "I$Seek equ $88", "I$Write equ $8A",
        "I$WritLn equ $8C", "I$GetStt equ $8D", "I$SetStt equ $8E", "I$Close equ $8F",
        "  psect mfullsz,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "  vsect", "scr: ds.b 2048", "  ends",
        "start:",
        "  lea fname(pc),a0", "  moveq #3,d0", "  moveq #3,d1", "  OS9 I$Create", "  bcs.w bad",
        "  move.w d0,d7",
        "  move.w d7,d0", "  lea scr(a6),a0", "  move.l #200,d1", "  OS9 I$Write", "  bcs.w bad",
        "  lea gname(pc),a0", "  moveq #3,d0", "  moveq #3,d1", "  OS9 I$Create", "  bcs.w bad",
        "  move.w d0,d6",
        "  move.w d6,d0", "  moveq #2,d1", "  move.l #4000000,d2", "  OS9 I$SetStt",   // fills the disk
        "  move.w d6,d0", "  OS9 I$Close",
        "  move.w d7,d0", "  move.l #150,d1", "  OS9 I$Seek", "  bcs.w bad",
        "  move.w d7,d0", "  lea scr(a6),a0", "  move.l #2000,d1", "  OS9 I$Write", "  bcc.w bad",
        "  move.w d7,d0", "  OS9 I$Close",
        "  lea fname(pc),a0", "  moveq #1,d0", "  OS9 I$Open", "  bcs.w bad", "  move.w d0,d7",
        "  move.w d7,d0", "  moveq #2,d1", "  OS9 I$GetStt", "  bcs.w bad",
        "  cmpi.l #200,d2", "  bne.s bad",
        "  lea mok(pc),a0", "  moveq #mokl,d1", "  bra.s say",
        "bad:", "  lea mbad(pc),a0", "  moveq #mbadl,d1",
        "say:", "  moveq #1,d0", "  OS9 I$WritLn", "  moveq #0,d1", "  OS9 F$Exit",
        "fname: dc.b \"/h9/keep\",0", "gname: dc.b \"/h9/filler\",0",
        "mok:  dc.b \"SIZE KEPT AT 200\",$0D", "mokl equ *-mok",
        "mbad: dc.b \"SIZE CUT BY THE FAILED WRITE\",$0D", "mbadl equ *-mbad",
        "  ends", ""
    ].joined(separator: "\r")

    let name = "rbf: a write that runs out of disk leaves the file's size alone"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? fullAsm.write(toFile: scratchDisk + "/mfullsz.a", atomically: true, encoding: .utf8)
        removeScratchItem(scratchDevice)
        _ = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                 "r68 /h5/mfullsz.a -o=/h5/mfullsz.r", "l68 /h5/mfullsz.r -o=/h5/mfullsz"], timeout: 60)
        let out = os9(["mount -k=300K \(scratchDevice)", "/h5/mfullsz"], timeout: 60)
        if out.contains("SIZE KEPT AT 200") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = out.split(whereSeparator: \.isNewline).filter { $0.contains("SIZE") || $0.contains("Error") }
            print("      saw: \(seen.joined(separator: " | "))")
            failed += 1
        }
        for leftover in ["mfullsz.a", "mfullsz.r", "mfullsz"] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
        }
        removeScratchItem(scratchDevice)
    }
}

// ── RBF: a directory held open does not flush a stale sector over a new entry ──
// The path RBF adds and removes directory entries through was a ring of its
// own, so a user path holding the same directory sector neither lost its copy
// when the entry was written nor handed over its own. Rewriting an entry it had
// read (as rename tools do) dirtied that stale copy, and its close wrote the
// sector back without the new file's name. Found by review (older than v4.0.0).
do {
    let dirAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit equ $06", "I$Create equ $83", "I$Open equ $84", "I$Seek equ $88", "I$Read equ $89",
        "I$Write equ $8A", "I$WritLn equ $8C", "I$Close equ $8F",
        "  psect mdirrc,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start", "  vsect", "scr: ds.b 4096", "  ends",
        "start:",
        "  lea dname(pc),a0", "  move.w #$83,d0", "  OS9 I$Open", "  bcs.w fail", "  move.w d0,d7",
        "  move.w d7,d0", "  lea scr(a6),a0", "  moveq #32,d1", "  OS9 I$Read", "  bcs.w fail",
        "  lea fname(pc),a0", "  moveq #3,d0", "  moveq #3,d1", "  OS9 I$Create", "  bcs.w fail",
        "  OS9 I$Close",
        "  move.w d7,d0", "  moveq #0,d1", "  OS9 I$Seek", "  bcs.w fail",
        "  move.w d7,d0", "  lea scr(a6),a0", "  moveq #32,d1", "  OS9 I$Write", "  bcs.w fail",
        "  move.w d7,d0", "  OS9 I$Close",
        "  lea fname(pc),a0", "  moveq #1,d0", "  OS9 I$Open", "  bcs.s lost",
        "  OS9 I$Close",
        "  lea mok(pc),a0", "  moveq #mokl,d1", "  bra.s say",
        "lost:", "  lea mbad(pc),a0", "  moveq #mbadl,d1",
        "say:", "  moveq #1,d0", "  OS9 I$WritLn", "  moveq #0,d1",
        "fail:", "  OS9 F$Exit",
        "dname: dc.b \"/h9\",0", "fname: dc.b \"/h9/fresh\",0",
        "mok:  dc.b \"NEW ENTRY SURVIVED\",$0D", "mokl equ *-mok",
        "mbad: dc.b \"NEW ENTRY WAS OVERWRITTEN\",$0D", "mbadl equ *-mbad",
        "  ends", ""
    ].joined(separator: "\r")

    let name = "rbf: a directory held open does not flush a stale sector over a new entry"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? dirAsm.write(toFile: scratchDisk + "/mdirrc.a", atomically: true, encoding: .utf8)
        removeScratchItem(scratchDevice)
        _ = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                 "r68 /h5/mdirrc.a -o=/h5/mdirrc.r", "l68 /h5/mdirrc.r -o=/h5/mdirrc"], timeout: 60)
        let run = os9(["mount -k=500K \(scratchDevice)", "/h5/mdirrc"], timeout: 60)
        let out = run + os9(["dcheck /h9"], timeout: 60)
        if out.contains("NEW ENTRY SURVIVED") && dcheckClean(out) {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = out.split(whereSeparator: \.isNewline)
                .filter { $0.contains("ENTRY") || $0.contains("Error") || $0.contains("not in") }
                .prefix(4)
            print("      saw: \(seen.joined(separator: " | "))")
            failed += 1
        }
        for leftover in ["mdirrc.a", "mdirrc.r", "mdirrc"] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
        }
        removeScratchItem(scratchDevice)
    }
}

// ── host dirs: a long host name matched by its 28-character cut, mid-path ────
// A host directory can hold names longer than OS-9's 28 characters; they are
// listed cut to 28, and a path naming the cut form is matched to the real name.
// That name was strcpy'd over the path at the component's place, so as a MIDDLE
// component it overwrote the components after it (and a long enough path ran
// off the buffer): "/h5/<cut>/inner" looked for something else entirely.
// Found by review.
do {
    let name = "fs: a long host directory name matched by its 28-character cut works mid-path"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let longDir = "abcdefghijklmnopqrstuvwxyz0123456789ABCD"          // 40 characters
        let cut = String(longDir.prefix(28))
        let hostDir = scratchDisk + "/" + longDir
        try? FileManager.default.removeItem(atPath: hostDir)
        try? FileManager.default.createDirectory(atPath: hostDir, withIntermediateDirectories: true)
        try? "INNERDATA\r".write(toFile: hostDir + "/inner", atomically: true, encoding: .utf8)
        let out = os9(["list /h5/\(cut)/inner"], timeout: 30)
        if out.contains("INNERDATA") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = out.split(whereSeparator: \.isNewline).filter { $0.contains("Error") || $0.contains("list") }
            print("      saw: \(seen.joined(separator: " | "))")
            failed += 1
        }
        try? FileManager.default.removeItem(atPath: hostDir)
    }
}

// ── RBF: a 28-character name works in the middle of a path, not only at its end ──
// 28 characters is the longest name RBF allows, and it worked as the last
// element of a path. In the middle, the name splitter counted the '/' after it
// as a 29th character and refused the whole path E$BPNam: a directory with a
// full-length name could be made but nothing could be made or found inside it.
// Found while building a test for the pre-release review.
do {
    let name = "rbf: a 28-character directory name works in the middle of a path"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let comp = String(repeating: "q", count: 27) + "z"        // 28 characters
        removeScratchItem(scratchDevice)
        let out = os9(["mount -k=500K \(scratchDevice)",
                       "makdir /h9/\(comp)", "makdir /h9/\(comp)/\(comp)",
                       "echo DEEP >/h9/\(comp)/\(comp)/f", "list /h9/\(comp)/\(comp)/f"], timeout: 60)
        // by line: "\r\n" is a single Character to Swift, so "DEEP\r" never matches
        if out.split(whereSeparator: \.isNewline).contains("DEEP"), !out.contains("Error #") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = out.split(whereSeparator: \.isNewline).filter { $0.contains("Error") }.prefix(3)
            print("      saw: \(seen.joined(separator: " | "))")
            failed += 1
        }
        removeScratchItem(scratchDevice)
    }
}

// A dot-name on an RBF image is stored as a dot-name. The Linux build ran every
// OS-9 pathname through the host-file rule that spells a leading "." as ":2e"
// (netatalk's convention, from the 2002 sources), so on an IMAGE it wrote
// `:2edotroot` into the directory and looked `/dd/.newsrc` up as `:2enewsrc`.
// An image made anywhere else then had names Linux could not open by absolute
// path -- ELM's /dd/.ELM/aliases.text, /dd/.newsrc -- and an image made on Linux
// carried `:2e` names everywhere else. Only the Linux build compiles that rule,
// so this can fail only there (make test-linux). The listing is written to a
// host file and read from Swift, because the shell echoes every command line
// and `.dotroot` appears in the one that creates it.
do {
    let dotName = "rbf: a dot-name is stored as a dot-name, not netatalk's :2e"
    if filter.isEmpty || dotName.localizedCaseInsensitiveContains(filter) {
        let listing = scratchDisk + "/dotlist"
        try? FileManager.default.removeItem(atPath: listing)
        removeScratchItem(scratchDevice)
        _ = os9([
            "mount -k=500K \(scratchDevice)",
            "echo dotmark >/h9/.dotroot",
            "dir -a /h9 >\(scratch)/dotlist"
        ], timeout: 60)
        let text = (try? String(contentsOfFile: listing, encoding: .isoLatin1)) ?? ""
        if text.contains(".dotroot") && !text.contains(":2e") {
            print("PASS: \(dotName)")
            passed += 1
        } else {
            print("FAIL: \(dotName)")
            let shown = text.replacingOccurrences(of: "\r", with: " ").replacingOccurrences(of: "\n", with: " ")
            print("      [dir -a /h9 should list .dotroot and no :2e name] listing: \(shown.prefix(160))")
            failed += 1
        }
        try? FileManager.default.removeItem(atPath: listing)
        removeScratchItem(scratchDevice)
    }
}

// An RBF image is a device wherever it lives. It used to be one only at
// "<startPath>/hN": DeviceInit named the device after the IMAGE FILE'S BASENAME
// and then rebuilt the image's host path by feeding "/" + that basename back
// through parsepath -- a round trip that only lands on the same file when the
// basename is itself a device name. Point OS9H9 at /anywhere/img.rbf and the
// device registered as "img.rbf" while its image path became the meaningless
// OS-9 path "/img.rbf", so every access answered E$FNA (#000:214). Renaming that
// very same file to "h9" made it work, which is what identified the decision as
// lexical rather than as anything about the file. Host DIRECTORIES behind OS9Hx
// never came through that code and honoured the variable from anywhere all along.
//
// Two images of DIFFERENT SIZES, so which one answered is VISIBLE in free's
// capacity line rather than inferred: 1M = 4096 sectors, 500K = 2016. `mount -k`
// writes into the emulator's cwd, which is <startPath>, so the host moves the
// first image out of the naming convention before the second one is made.
let awayHostPath = scratchDisk + "/not-a-device-name.rbf"
let awayDevPath  = scratchInEmulator + "/not-a-device-name.rbf"
try? FileManager.default.removeItem(atPath: awayHostPath)
_ = os9(["mount -k=1M \(scratchDevice)"])
try? FileManager.default.moveItem(atPath: scratchHostPath, toPath: awayHostPath)

run("rbf: OS9Hx mounts an image that is not at <startPath>/hN",
    expectation: "free /h9 reports the moved 1M image (4096 sectors), no error",
    commands: ["free /h9"], env: ["OS9H9": awayDevPath]) {
        !$0.contains("Error #") && $0.contains("4096 sectors")
    }

// Explicit configuration beats ambient discovery, and now says so once. Both
// candidates are live here -- a 500K image sitting at <startPath>/h9 and the 1M
// one OS9H9 names -- so the capacity line is the only thing that can tell which
// of them the emulator actually opened.
_ = os9(["mount -k=500K \(scratchDevice)"])
run("rbf: OS9Hx wins over an image of the same name beside the emulator",
    expectation: "free /h9 reports OS9H9's 1M image (4096 sectors), announced once",
    commands: ["free /h9"], env: ["OS9H9": awayDevPath]) {
        $0.contains("4096 sectors") && !$0.contains("2016 sectors")
                                    && $0.contains("using OS9H9=")
    }

// ...but only when there ARE two. OS9H9 naming the very image that sits at
// <startPath>/h9 used to announce "using '<p>', ignoring '<p>'", the same path
// twice, reporting a conflict that did not exist.
run("rbf: OS9Hx naming the image beside the emulator announces no override",
    expectation: "free /h9 reports the 500K image (2016 sectors) and says nothing about ignoring",
    commands: ["free /h9"], env: ["OS9H9": scratchInEmulator + "/h9"]) {
        $0.contains("2016 sectors") && !$0.contains("ignoring")
    }

removeScratchItem(scratchDevice)
try? FileManager.default.removeItem(atPath: awayHostPath)

// ── RAM disk regression test ──────────────────────────────────────────────────
// mount -r=<size> builds a complete filesystem in memory -- no host file,
// released again via unmount. Also verified with dsave -ive, not just touch.
// Note the leading '/' on /ram9: mount -r=<size> <name> requires an
// absolute device name -- a bare "ram9" fails classification entirely
// (unrelated to this feature; see the plan's Global Constraints note).
noError("ramdisk: mount -r creates disk", "mount -r=200 /ram9", "dir /ram9", "unmount ram9")

// A sector size this RBF cannot use is refused as E$SectSize (000:176) -- the
// code the manual defines for exactly this ("must be a binary multiple of 256
// ... maximum 32768"). 2048 is our ceiling because GetBuffers sizes a path's
// sector buffers to it; 4096 is legal per the manual and still not usable here.
// Until 2026-08-24 the RAM-disk path took the value unchecked and it surfaced
// as E$NotRdy -- "device not ready", which is not why it failed -- and the SCSI
// path returned SUCCESS for a size it had just refused.
check("ramdisk: an unusable sector size reports E$SectSize, not E$NotRdy",
    contains: "176", "mount -r=400 -n=4096 /ram9")
check("ramdisk: a sector size that is not 256<<n is refused too",
    contains: "176", "mount -r=400 -n=3000 /ram9")
noError("ramdisk: 2048 is still accepted", "mount -r=400 -n=2048 /ram9", "unmount ram9")
check  ("ramdisk: dsave -ive populates+verifies", contains: "f1",
    "echo ramdisk test content >/h5/t_ramsrc",
    "makdir /h5/t_ramdir",
    "copy /h5/t_ramsrc /h5/t_ramdir/f1",
    "chd /h5/t_ramdir", "mount -r=200 /ram9", "dsave -ive /ram9", "dir /ram9", "unmount ram9",
    "chd /dd", "del /h5/t_ramsrc", "del /h5/t_ramdir/f1", "deldir -q /h5/t_ramdir")

// ── F$PrsNam: one-character path components ───────────────────────────────────
// Regression test for the TO68K double-evaluation bug. TO68K was a macro that
// mentioned its argument twice, so F$PrsNam's `rp->a[0]=TO68K(++p)` advanced p
// by two -- skipping the '/' AND the name's first character. Every path element
// then parsed one character short, and a FINAL element of exactly one character
// parsed as the empty name and returned E$BNam, which the shell renders as
// "^syntax error". So `echo x >/ram9/a` failed while `>/ram9/ab` appeared to
// work (it silently parsed only "b").
//
// The redirect target is what matters here: a path passed as a command ARGUMENT
// never goes through F$PrsNam, so `list /ram9/a` stayed working throughout and
// would NOT have caught this. Keep the assertions on `>` and `<`.
noError("f$prsnam: redirect to a one-character file name",
    "mount -r=200 /ram9", "echo t >/ram9/a", "list /ram9/a", "unmount ram9")
// Asserted as noError, NOT `contains: "deep"`. The shell echoes the offending
// command line back as part of its error report, so a `contains:` check on the
// written text matches the ERROR message just as happily as the file content --
// verified: that form passed against the known-buggy binary. The trailing
// `list` failing with E$PNNF is what actually proves the file got created.
noError("f$prsnam: one-character components at every depth",
    "mount -r=200 /ram9", "makdir /ram9/a", "makdir /ram9/a/b",
    "echo deep >/ram9/a/b/c", "list /ram9/a/b/c", "unmount ram9")
// Input redirect gets its own case: `<` and `>` are parsed separately, and the
// bug hit both. Asserted as "no syntax error" rather than "no error at all"
// because `list <file` legitimately complains that it still needs a file-name
// argument -- an E$BNam from F$PrsNam surfaced as the distinct text
// "^syntax error", which is exactly what this pins down.
check  ("f$prsnam: input redirect from a one-character file name",
    absent: "syntax error",
    "mount -r=200 /ram9", "echo t >/ram9/a", "list </ram9/a", "unmount ram9")

// ---- move / mv (int_move.c) ----------------------------------------------------
// int_move.c was 0%-covered by the suite though `move` is a live, platform-active
// internal command (vmod/printer/filescsi, the other 0% files, are dead code or
// SCSI-hardware paths on this platform). The positive cases assert `noError` on a
// trailing `list` of the DESTINATION: a `move` that did nothing leaves that `list`
// failing E$PNNF, so the test goes red -- and, unlike a `contains:` on the moved
// text, the shell's command echo cannot fake that (it can't manufacture an error).
noError("move: the file is listable at its new name after a rename",
    "mount -r=200 /ram9", "echo x >/ram9/a.txt",
    "move /ram9/a.txt /ram9/b.txt", "list /ram9/b.txt", "unmount ram9")
noError("move: -w wildcard delivers a matching file to the target dir",
    "mount -r=200 /ram9", "makdir /ram9/dst",
    "echo x >/ram9/f.txt", "move -w=/ram9/dst /ram9/*.txt",
    "list /ram9/dst/f.txt", "unmount ram9")
noError("move: -w wildcard leaves a non-matching file in place",
    "mount -r=200 /ram9", "makdir /ram9/dst",
    "echo f >/ram9/f.txt", "echo g >/ram9/g.dat",
    "move -w=/ram9/dst /ram9/*.txt", "list /ram9/g.dat", "unmount ram9")
// The rest of move's options, none of which the suite reached: a RAM disk keeps
// it on RBF, where move is a directory-entry rewrite rather than a copy.
noError("move: -d moves a directory, entry and contents",
    "mount -r=200 /ram9", "makdir /ram9/src", "echo x >/ram9/src/inside",
    "move -d /ram9/src /ram9/dst", "list /ram9/dst/inside", "unmount ram9")
run("move: an existing target is refused, and -r rewrites it",
    expectation: "the first move says it already exists; -r then replaces the target's contents",
    commands: ["mount -r=200 /ram9", "echo source >/ram9/a", "echo target >/ram9/b",
               "move /ram9/a /ram9/b", "list /ram9/b",
               "move -r /ram9/a /ram9/b", "list /ram9/b", "unmount ram9"]) { out in
    let printed = out.replacingOccurrences(of: "\r", with: "\n").split(separator: "\n")
                     .filter { !$0.hasPrefix("$ ") }
    return out.contains("already exists")
        && printed.contains { $0.trimmingCharacters(in: .whitespaces) == "target" }   // refused: unchanged
        && printed.contains { $0.trimmingCharacters(in: .whitespaces) == "source" }   // -r: replaced
}
run("move: -? prints its usage, and an unknown option is named",
    expectation: "the syntax line and every option letter, then 'unknown option'",
    commands: ["move -?", "move -q /h5/nosuch /h5/nor"]) {
    $0.contains("Syntax:") && $0.contains("-w=<dir name>") && $0.contains("unknown option 'q'")
}

// A target name longer than a pathlist was concatenated into a 256-byte stack
// buffer unchecked: the emulator died on the spot, with no output at all (found
// by ASan: a 401-byte write). Now it is refused as a bad pathlist and the next
// command still runs.
run("move: a target too long for a pathlist is refused, and the emulator lives",
    expectation: "E$BPNam (215) from move, then the following echo runs",
    commands: ["move nosuchsrc " + String(repeating: "X", count: 400), "echo MOVELIVES"]) { out in
    out.contains("215") &&
        out.split(whereSeparator: \.isNewline).contains { $0.trimmingCharacters(in: .whitespaces) == "MOVELIVES" }
}
// The same shape in three more internal commands, found by running every one
// of them under ASan with 450-character arguments: rename copied both names
// unchecked, and mount and idbg -o handed theirs to helpers (pDopen,
// InstalledDev) that concatenated into 256-byte buffers. Each killed the
// emulator outright.
for (label, command) in [("rename", "rename src " + String(repeating: "X", count: 450)),
                         ("mount", "mount " + String(repeating: "X", count: 450)),
                         ("idbg -o", "idbg -o /h5/" + String(repeating: "Y", count: 250)
                                                    + "/" + String(repeating: "Y", count: 250))] {
    run("\(label): an over-long argument is refused, and the emulator lives",
        expectation: "an error from \(label), then the following echo runs",
        commands: [command, "echo \(label.prefix(4))LIVES"]) { out in
        out.split(whereSeparator: \.isNewline)
           .contains { $0.trimmingCharacters(in: .whitespaces) == "\(label.prefix(4))LIVES" }
    }
}
// And from the host command line: the program name went into a 256-byte
// buffer unchecked in link_module, so `os9exec <450 characters>` died on a
// signal (SIGTRAP, the stack protector) instead of saying it could not start.
// Local only: the container adds its own entrypoint in front of the name.
do {
    let name = "startup: an over-long program name is refused, not a crash"
    if (filter.isEmpty || name.localizedCaseInsensitiveContains(filter)) && !containerized {
        let process = Process()
        let pipe = Pipe()
        process.executableURL  = execURL
        process.arguments      = ["-r", String(repeating: "X", count: 450)]
        process.environment    = ["OS9DISK": diskPath].merging(inheritedByChildren) { mine, _ in mine }
        process.standardInput  = FileHandle.nullDevice
        process.standardOutput = pipe
        process.standardError  = pipe
        var said = ""
        if (try? process.run()) != nil {
            let deadline = Date().addingTimeInterval(30)
            while process.isRunning && Date() < deadline { usleep(50_000) }
            if process.isRunning { process.terminate() }
            process.waitUntilExit()
            said = String(decoding: pipe.fileHandleForReading.readDataToEndOfFile(), as: UTF8.self)
        }
        if process.terminationReason == .exit && said.contains("E_BPNAM") {
            print("PASS: \(name)"); passed += 1
        } else {
            print("FAIL: \(name)")
            print("      [exits normally with E_BPNAM; reason=\(process.terminationReason.rawValue) status=\(process.terminationStatus)]")
            failed += 1
        }
    }
}
// The debugger menu that `idbg` opens on an argument it does not parse waited
// for a key from stdin. Redirected and at end of input, nothing could ever
// answer, and it waited forever at 100% CPU: a script running `idbg` sat there
// for hours. End of input now counts as [G]o. Local only, for the same reason
// as the test above; bounded so a hang costs this test and no more.
do {
    let name = "debug: the debugger menu continues when stdin has run out"
    if (filter.isEmpty || name.localizedCaseInsensitiveContains(filter)) && !containerized {
        let process = Process()
        let pipe = Pipe()
        process.executableURL  = execURL
        process.arguments      = ["-r", "idbg", "src"]
        process.environment    = ["OS9DISK": diskPath].merging(inheritedByChildren) { mine, _ in mine }
        process.standardInput  = FileHandle.nullDevice
        process.standardOutput = pipe
        process.standardError  = pipe
        var finished = false
        var said = ""
        if (try? process.run()) != nil {
            let deadline = Date().addingTimeInterval(30)
            while process.isRunning && Date() < deadline { usleep(50_000) }
            finished = !process.isRunning
            if process.isRunning { process.terminate() }
            process.waitUntilExit()
            said = String(decoding: pipe.fileHandleForReading.readDataToEndOfFile(), as: UTF8.self)
        }
        if finished && said.contains("no input left") {
            print("PASS: \(name)"); passed += 1
        } else {
            print("FAIL: \(name)")
            print("      [the menu gives up on an exhausted stdin; finished=\(finished)]")
            failed += 1
        }
    }
}
check  ("move: a cross-device move is refused",
    contains: "can't move",
    "mount -r=200 /ram9", "mount -r=200 /ram8", "echo x >/ram9/a.txt",
    "move /ram9/a.txt /ram8/a.txt", "unmount ram9", "unmount ram8")
check  ("move: a missing source reports it cannot be found",
    contains: "can't find",
    "mount -r=200 /ram9", "move /ram9/nosuch.txt /ram9/x.txt", "unmount ram9")

// ══════════════════════════════════════════════════════════════════════════════
// FILESYSTEM SELF-TESTS   (name prefix "fs:" — run just these with
//   swift run --package-path test OS9Tests fs:)
// ══════════════════════════════════════════════════════════════════════════════
// Two mental categories of test live in this file:
//   1. COMMAND SMOKE TESTS (everything above) — "does `grep` / `tar` / `dsave`
//      run and produce plausible output" — they depend on which command modules
//      we happen to have working.
//   2. SELF-TESTS (this section, plus the RBF/ramdisk/baud ones above) — they
//      test the emulator's OWN guaranteed behavior, provision everything they
//      need, and assert exact outcomes. Anyone can run them; nothing external
//      is assumed.
// These verify the file system itself: that every legal spelling of a path
// resolves to the SAME right place, that NO path trick escapes a host-native
// device root into the host OS (the confinement the emulator must guarantee —
// see the '..'-past-root regression, git log), and that OS-9 permissions are
// honored on an RBF image. These run in container mode too: the canary is
// mounted at the container's "/" (which really is /dd's parent there) and the
// disk at its own host path so the /h0 symlink resolves -- see containerRunArgs.
do {
    // Per-run name, for the same reason the fixtures moved to /h5: this dir
    // lives inside the SHARED system disk (it must -- these tests assert on the
    // /dd and /h0 spellings themselves, so they cannot move to a scratch
    // device), and the suite DELETES it when done. Two sessions with the same
    // name deleted it out from under each other. The suffix is digits so both
    // the lower- and UPPER-case spellings below stay valid.
    let fsRun        = String(ProcessInfo.processInfo.processIdentifier)
    let fsHostDir    = diskPath + "/USR/CLAUDE/fsselftest\(fsRun)"   // under /dd, host-visible
    let fsSubHost    = fsHostDir + "/SUB"
    let marker       = "FSMARK_\(UUID().uuidString.prefix(8))"
    // The canary itself (in the device root's host parent) is planted up in the
    // configuration section -- container mode must mount it, which happens
    // before any test runs. Here we only add the fixtures that live inside the
    // device.

    // provision on the host (deterministic; OS-9 files use CR line endings)
    try? FileManager.default.createDirectory(atPath: fsSubHost, withIntermediateDirectories: true)
    try? (marker + "\r").write(toFile: fsSubHost + "/deep", atomically: true, encoding: .utf8)
    // a host symlink INSIDE the device pointing OUT at the canary — the realpath
    // confinement must refuse to follow it out of the device root. The host path
    // works verbatim in container mode too, because the canary is mounted there
    // under its own name; a dangling link would make this pass on a broken
    // symlink rather than on confinement.
    try? FileManager.default.createSymbolicLink(atPath: fsSubHost + "/esclink",
                                                withDestinationPath: canaryHost)

    // guard: the whole confinement half is vacuous if the canary wasn't written
    if (try? String(contentsOfFile: canaryHost, encoding: .utf8))?.contains(canarySecret) != true {
        print("FAIL: fs: setup — canary file not planted"); failed += 1
    }

    let sub = "/dd/USR/CLAUDE/fsselftest\(fsRun)/SUB"   // OS-9 working dir for these

    // ---- resolution: every legal spelling must read the SAME marker file ----
    // (the marker tests double as the positive control for the confinement
    //  tests below: they prove `list` really does surface a file's contents.)
    func resolves(_ label: String, _ spelling: String) {
        run("fs: resolve \(label)", expectation: "reads the marker via '\(spelling)'",
            commands: ["chd \(sub)", "list \(spelling)"]) { $0.contains(marker) }
    }
    resolves("relative",              "deep")
    resolves("dot-relative",          "./deep")
    resolves("absolute /dd",          "/dd/USR/CLAUDE/fsselftest\(fsRun)/SUB/deep")
    resolves("/h0 device alias",      "/h0/USR/CLAUDE/fsselftest\(fsRun)/SUB/deep")
    resolves("double slash",          "/dd//USR/CLAUDE/fsselftest\(fsRun)/SUB/deep")
    resolves("embedded /./",          "/dd/./USR/CLAUDE/fsselftest\(fsRun)/SUB/deep")
    resolves("parent round-trip",     "../SUB/deep")
    resolves("stacked ../..", "../../fsselftest\(fsRun)/SUB/deep") // same climb as ...
    resolves("mixed runs ../...", "../.../CLAUDE/fsselftest\(fsRun)/SUB/deep") // 1 + 2 levels
    resolves("through SYS and back",  "/dd/SYS/../USR/CLAUDE/fsselftest\(fsRun)/SUB/deep")
    resolves("case-insensitive",      "/dd/usr/claude/FSSELFTEST\(fsRun)/sub/DEEP")
    resolves("multi-dot to root",     "...../USR/CLAUDE/fsselftest\(fsRun)/SUB/deep")       // up-4 == /dd, then descend
    resolves("over-walk clamps+keeps","............/USR/CLAUDE/fsselftest\(fsRun)/SUB/deep") // '..' past root: clamp, keep tail (regression guard)

    // ---- confinement: the host canary outside the root must be UNREACHABLE ----
    func blocked(_ label: String, _ spelling: String) {
        run("fs: confine \(label)", expectation: "canary NOT leaked via '\(spelling)'",
            commands: ["chd \(sub)", "list \(spelling)"]) { !$0.contains(canarySecret) }
    }
    blocked("/dd/../canary",        "/dd/../\(canaryName)")
    blocked("/dd/../../canary",     "/dd/../../\(canaryName)")
    blocked("deep ../ escape",      "../../../../../\(canaryName)")
    blocked("over-walk escape",     "............/\(canaryName)")
    blocked("through SYS escape",   "/dd/SYS/../../\(canaryName)")
    blocked("/h0 alias escape",     "/h0/../\(canaryName)")
    blocked("symlink out of device","esclink")            // realpath confinement must not follow it out

    // Refused as a name that does not exist, E$PNNF, like any other name the
    // device does not have. Spelt as an absolute path it was E$MNF, "module
    // not found": IO_Type saw a path leading out of every device and gave it
    // no file manager at all, as it does a device that does not exist.
    run("fs: confine a file symlink out of the device, named absolutely, as E$PNNF",
        expectation: "list \(sub)/esclink reports Error #000:216, not 221",
        commands: ["list \(sub)/esclink"]) {
        $0.contains("Error #000:216") && !$0.contains("#000:221") && !$0.contains(canarySecret)
    }

    try? FileManager.default.removeItem(atPath: fsHostDir)
    // canaryHost is removed in the epilogue, not here -- see the note there.

    // ---- nested device roots: '..' must stop at the INNERMOST root ----
    // The scratch device's host dir is also the emulator's working directory,
    // so `mount -k=0 he` plants a second device root INSIDE the first one --
    // /he's host path is <h5's host root>/he. OS-9 semantics: extra ".."s at a
    // device root are no-ops, so nothing under /he may reach h5's own files.
    // Before the fix, AdjustPath asked which configured root a path started in
    // and got back the FIRST prefix match in scan order (dd, h0-h9, ha-hz),
    // which for a path under /he is the ENCLOSING h5 -- so the clamp compared
    // against the wrong root and let '..' walk out. It now takes the longest
    // (innermost) match. Guarded as a leak test, not a "does it error" test:
    // asserting on the parent's CONTENT means a future regression has to
    // actually surface h5's file to fail this, and the E_PNNF spelling is free
    // to change.
    let nestSecret = "NESTMARK_\(UUID().uuidString.prefix(8))"
    let nestFile   = "nestparent\(fsRun)"
    try? (nestSecret + "\r").write(toFile: scratchDisk + "/" + nestFile,
                                   atomically: true, encoding: .utf8)

    // Positive control FIRST: the file has to be readable through h5 itself,
    // or both leak tests below pass on its absence -- the exact false-pass
    // shape the canary guard above exists to prevent.
    run("fs: nested roots — parent file IS readable from the outer device",
        expectation: "control: h5's own file reads normally via /h5",
        commands: ["chd \(scratch)", "list \(nestFile)"]) { $0.contains(nestSecret) }

    run("fs: nested roots — '..' from the inner device cannot read the outer one",
        expectation: "list ../\(nestFile) from /he must not surface h5's file",
        commands: ["mount -k=0 he", "chd /he",
                   "list ../\(nestFile)"]) { !$0.contains(nestSecret) }

    run("fs: nested roots — 'dir ..' from the inner device stays inside it",
        expectation: "dir .. from /he must not list h5's root",
        commands: ["mount -k=0 he", "chd /he",
                   "dir .."]) { !$0.contains(nestFile) }

    removeScratchItem(nestFile)
    removeScratchItem("he")

    // ---- a directory symlink pointing out of every device is refused ----
    // AdjustPath clamps a `..` climb above a device root back to that root, and
    // its last check used to clamp ANY result outside every device the same way.
    // A symlink reaches there too, so `dir /h5/<dir>/out` with out -> ../.. (the
    // scratch device's host parent) listed /h5's own root under the link's name:
    // no error, wrong data, and dsave/deldir walked the root again. The climb is
    // clamped earlier, textually; what is left outside must be refused. The link
    // is relative so it means the same thing in a container, where /h5's parent
    // is "/". Positive control first: a symlink that stays inside the device
    // still resolves, which also proves the marker is visible when listed.
    let symEscDir   = "symesc\(fsRun)"
    let symRootMark = "SYMROOTMARK\(UUID().uuidString.prefix(8))"
    try? FileManager.default.createDirectory(atPath: scratchDisk + "/" + symEscDir,
                                             withIntermediateDirectories: true)
    try? FileManager.default.createSymbolicLink(atPath: scratchDisk + "/" + symEscDir + "/in",
                                                withDestinationPath: "..")
    try? FileManager.default.createSymbolicLink(atPath: scratchDisk + "/" + symEscDir + "/out",
                                                withDestinationPath: "../..")
    try? "x\r".write(toFile: scratchDisk + "/" + symRootMark, atomically: true, encoding: .utf8)

    run("fs: resolve a directory symlink that stays inside the device",
        expectation: "control: dir through in -> .. lists /h5's root",
        commands: ["dir \(scratch)/\(symEscDir)/in"]) { $0.contains(symRootMark) }

    run("fs: confine a directory symlink out of every device, not to the device root",
        expectation: "dir through out -> ../.. is E$PNNF and does not list /h5's root",
        commands: ["dir \(scratch)/\(symEscDir)/out"]) {
        $0.contains("Error #000:216") && !$0.contains(symRootMark)
    }

    // deldir through such a link is the destructive case, not only a wrong
    // listing: before the fix `chd` landed in the device root, and deldir then
    // deleted the root's own files by their relative names before failing on
    // the link (measured on 4468753: one of two root files gone). Every root
    // file must survive, and the directory the link points at too.
    let deldirKeep = "DELDIRKEEP\(UUID().uuidString.prefix(8))"
    try? "k\r".write(toFile: scratchDisk + "/" + symEscDir + "/" + deldirKeep,
                     atomically: true, encoding: .utf8)
    run("fs: confine deldir through a directory symlink out of every device deletes nothing",
        expectation: "deldir -q through out -> ../.. is refused; /h5's files and the link's own directory survive",
        commands: ["chd \(scratch)/\(symEscDir)", "deldir -q out"]) { _ in
        let fileManager = FileManager.default
        return fileManager.fileExists(atPath: scratchDisk + "/" + symRootMark)
            && fileManager.fileExists(atPath: scratchDisk + "/" + symEscDir + "/" + deldirKeep)
    }

    // Creating a file through that link is refused the same way, as a name the
    // device does not have (E$PNNF; it was E$MNF), and nothing is created in
    // the directory the link leads to.
    let symEscNew = "SYMESCNEW\(UUID().uuidString.prefix(8))"
    let symEscNewHost = (scratchDisk as NSString).deletingLastPathComponent + "/" + symEscNew
    run("fs: confine a file created through a directory symlink out of every device, as E$PNNF",
        expectation: "echo into out -> ../.. reports Error #000:216, not 221, and creates nothing there",
        commands: ["echo x >\(scratch)/\(symEscDir)/out/\(symEscNew)"]) {
        $0.contains("Error #000:216") && !$0.contains("#000:221")
            && !FileManager.default.fileExists(atPath: symEscNewHost)
    }
    try? FileManager.default.removeItem(atPath: symEscNewHost)

    removeScratchItem(symEscDir)
    removeScratchItem(symRootMark)

    // ---- a device whose host path has a space in it ----
    // AdjustPath turned every space in the host path into '_' -- meant for the
    // names below a device, which in OS-9 cannot hold a space anyway -- and so
    // also mangled the device's own host path: OS9H7="/tmp/has space" made
    // `dir /h7` E$PNNF. `attr -nd` must work there too: it removes the empty
    // directory and makes a file of it, and on macOS the removal was a shell
    // command line, "rmdir <path>", which split the path at the space.
    let spaceDirName = "has space\(fsRun)"
    let spacedHost   = scratchDisk + "/" + spaceDirName
    let spaceMark    = "SPACEMARK\(UUID().uuidString.prefix(8))"
    try? FileManager.default.createDirectory(atPath: spacedHost + "/victim",
                                             withIntermediateDirectories: true)
    try? (spaceMark + "\r").write(toFile: spacedHost + "/f", atomically: true, encoding: .utf8)

    run("fs: a device whose host path has a space in it reads and clears a directory",
        expectation: "list /h7/f shows the marker, attr -nd turns /h7/victim into a file, no error",
        commands: ["list /h7/f", "attr -nd /h7/victim"],
        env: ["OS9H7": scratchInEmulator + "/" + spaceDirName]) {
        var isDir: ObjCBool = true
        let exists = FileManager.default.fileExists(atPath: spacedHost + "/victim", isDirectory: &isDir)
        return $0.contains(spaceMark) && !$0.contains("Error #") && exists && !isDir.boolValue
    }

    removeScratchItem(spaceDirName)

    // ---- host-native devices: attr round-trip only, NOT permission enforcement ----
    // A host directory cannot carry OS-9 ownership and attributes faithfully --
    // that is what an RBF image is for, and the "fs: permission" tests above own
    // that subject. So this asserts only what a host-native device can honestly
    // promise: attr sets the bits and reads them back, and clearing every bit
    // does not cost attr its own access (its F$Open requests neither read nor
    // write -- mode==0, it just needs a path number for the GetStat/SetStat --
    // so it can always grant access back, mirroring RBF's has_open_perm()).
    // Deliberately no assertion that the HOST refused a read: it is unfalsifiable
    // on a Docker bind mount, which fakes ownership to match whatever uid asks
    // and ignores the mode outright (measured 2026-07-25; project memory
    // docker-macos-bindmount-ignores-permissions).
    // Every bit cleared reads back as every bit cleared. This asserted
    // "--e--e--" until 2026-07-25, which was the old forced-execute mapping
    // showing through: `e` was the one attribute a host mount could not
    // round-trip, so the test was documenting the bug.
    check("fs: attr — host-native device round-trips cleared attributes",
        contains: "--------",
        "mount -k=0 hb", "chd /hb", "echo abc >f",
        "attr f -nr -nw -ne -npr -npw -npe", "attr f")
    removeScratchItem("hb")

    // The execute bit specifically: a freshly created data file must NOT claim
    // to be executable, and an `e` granted afterwards must survive being read
    // back. Both host reads were forced to report `e` until 2026-07-25, so this
    // fails outright on the old mapping -- which is the point of asserting the
    // two states in one run rather than just the final one.
    check("fs: attr — host-native execute bit is real, not forced on",
        contains: "------wr",
        "mount -k=0 hb", "chd /hb", "echo abc >f", "attr f")
    removeScratchItem("hb")

    check("fs: attr — host-native execute bit survives a set/read round-trip",
        contains: "-----ewr",
        "mount -k=0 hb", "chd /hb", "echo abc >f", "attr f -e", "attr f")
    removeScratchItem("hb")

    check("fs: attr — host-native: attr still reaches a file whose bits it cleared",
        contains: "6162 63",
        "mount -k=0 hb", "chd /hb", "echo abc >f",
        "attr f -nr -nw -ne -npr -npw -npe", "attr f -r -pr", "dump f")
    removeScratchItem("hb")
}

// ── permissions on RBF images: os9exec's OWN enforcement, host-independent ───
// Split out of the local-only block above (2026-07-25) so container mode runs
// them too. These assert OS-9 permission semantics: they provision their own
// RBF image with `mount -k`, log in as OS-9 identities from /dd/SYS/password,
// and set OS-9 attribute bits. Enforcement is os9exec's RBF code reading owner
// IDs and attribute bytes from INSIDE the image, so the host filesystem and the
// container's uid are irrelevant -- running as root does NOT make these vacuous,
// unlike the host-native permission checks that remain local-only (a container
// bind mount on macOS is type `fakeowner` and enforces no mode bits at all).
//
// They share one `mount -k` device across several separate os9exec runs, which
// only works in container mode because the container's cwd is now the
// bind-mounted scratch (`-w` in os9(), above) -- without it the image landed in
// the container-local /work and vanished between the per-test containers, and
// every `contains "Error #"` check passed for the wrong reason.
// ---- permissions: ENFORCED on RBF images (real ownership + attribute bits) ----
// claude (1.7) and dog (1.3) are blank-password non-super accounts already in
// this disk's /dd/SYS/password -- see os9-dev skill's REPL notes for how this
// was live-verified (login really does F$SUser to a distinct Grp.Usr). su (0.0)
// is just this suite's default top-level session -- no login needed for it.
let permDev     = "h8"
let permDevPath = "/\(permDev)"
try? FileManager.default.removeItem(atPath: scratchDisk + "/" + permDev)

// NOTE: every sequence below that ends still logged in as claude/dog closes
// with an explicit "logout" before the run/check helpers' implicit final
// ESC. Confirmed via direct os9exec REPL runs (see task-2-report.md): login
// forks a nested "claude:"/"dog:" shell, and the harness only sends ONE
// terminating ESC. If the sequence ends inside that nested shell, the ESC
// is consumed there and the outer top-level "$" shell hangs forever waiting
// for more input that will never come -- the process times out and os9()
// returns the literal string "(timeout)", which trivially fails a
// `contains: "Error #"` check and trivially PASSES a `!contains("Error #")`
// check, silently masking the real result either way. This is a harness/
// login-nesting artifact, unrelated to permission enforcement -- adding the
// trailing "logout" (already used correctly elsewhere in this block) fixes
// it and lets the real output flow through to the assertions.
run("fs: permission — claude creates+owns a file, can read it back",
    expectation: "dump of a freshly created file shows its bytes to its own creator",
    commands: ["mount -k=200K \(permDev)", "chd \(permDevPath)",
               "login claude", "chd \(permDevPath)",
               "echo abc >f", "dump f", "logout"]) { $0.contains("6162 63") }

check("fs: permission — owner locks self out by clearing owner-read",
    contains: "Error #",
    "chd \(permDevPath)", "login claude", "chd \(permDevPath)",
    "attr f -nr", "dump f", "logout")

check("fs: permission — super-user still bypasses every check",
    contains: "6162 63",
    "chd \(permDevPath)", "dump f")

check("fs: permission — non-owner (dog) blocked from a file with no public bits",
    contains: "Error #",
    "chd \(permDevPath)", "login dog", "chd \(permDevPath)", "dump f", "logout")

check("fs: permission — owner restores public-read, non-owner can now read",
    contains: "6162 63",
    "chd \(permDevPath)", "login claude", "chd \(permDevPath)", "attr f -pr", "logout",
    "login dog", "chd \(permDevPath)", "dump f", "logout")

check("fs: permission — non-owner cannot change attributes on a file they don't own",
    contains: "Error #",
    "chd \(permDevPath)", "login dog", "chd \(permDevPath)", "attr f -nr", "logout")

// ---- super user is GROUP zero, whatever the user number ----
// admin is 0.7 in this disk's /dd/SYS/password: group 0 with a NON-ZERO user
// number, deliberately the same user half as claude (1.7), so the pair differ
// in nothing but the group. Microware defines the super user by that half
// alone -- "a user with a group ID of 0 is referred to as a super user"
// (Training, OS-9 Starter) and "any process owned by group zero" (Training,
// OS-9 Advanced) -- and makes it concrete with the password line
// `amy,love,0.153,...`, "she will have super user privileges". os9exec used to
// require 0.0, so 0.7 was silently an ordinary user.
//
// The test uses its OWN file `s`, with every public bit cleared here and now.
// Reusing the shared `f` made it vacuous: by this point f has had public-read
// restored, so admin read it as a member of the public and the test passed
// even with the old 0.0-only rule still in place (verified by reverting the
// fix -- it still passed). Nothing but super-user status can open `s`.
run("fs: permission — group-0 super user (0.7) sees through another owner's file",
    expectation: "0.7 dumps a 1.7-owned file that has no public bits at all",
    commands: ["chd \(permDevPath)", "login claude", "chd \(permDevPath)",
               "echo abc >s", "attr s -npr -npw -npe", "logout",
               "login admin", "chd \(permDevPath)",
               "dump s", "logout"]) { $0.contains("6162 63") }

// Control for the above: the same file, same moment, read by an ordinary
// non-owner. If this ever passes, "super user" has stopped meaning anything
// and the test above is just measuring an unenforced permission check.
check("fs: permission — ...while an ordinary non-owner (dog) is still refused it",
    contains: "Error #",
    "chd \(permDevPath)", "login dog", "chd \(permDevPath)", "dump s", "logout")

// The other half of the same fix: making group 0 privileged means a non-super
// process must not be able to PUT itself in group 0. chown writes the file
// descriptor's owner word, which "Only the super user can change" (I$SetStt
// SS_FD, p.2-24) -- to group zero above all, which would mint a privileged
// identity out of a file they merely own. Concretely here: claude is 1.7 and
// admin is 0.7, so `chown 0.7` is claude reaching for the super-user identity
// one group digit away from its own.
//
// On its OWN file `g`, not the shared `f`: f still has owner-read cleared from
// the lockout test above, so chown could not even open it and the refusal came
// back E_FNA -- which "contains Error #" would have accepted, passing this test
// without ever reaching the check it exists for. Hence E_PERMIT by name.
check("fs: permission — owner cannot give a file away to group 0",
    contains: "E_PERMIT",
    "chd \(permDevPath)", "login claude", "chd \(permDevPath)",
    "echo abc >g", "chown 0.7 g", "logout")

// An owner used to be allowed to move the GROUP half (1.7 -> 2.7), a partial
// give-away kept on purpose; rdoggett 2026-09-15: follow the manual. The super
// user (admin, 0.7) still can, which is the control that the refusal is about
// who asks.
check("fs: permission — the owner cannot give its file to another ordinary group either",
    contains: "E_PERMIT",
    "chd \(permDevPath)", "login claude", "chd \(permDevPath)", "chown 2.7 g", "logout")

run("fs: permission — the super user can give that file to another group",
    expectation: "control: admin (0.7) chowns claude's file to 2.7 without an error",
    commands: ["chd \(permDevPath)", "login admin", "chd \(permDevPath)",
               "chown 2.7 g", "logout"]) { !$0.contains("Error #") }

try? FileManager.default.removeItem(atPath: scratchDisk + "/" + permDev)

// ---- permissions: file-level write bit (has_open_perm's write path) ----
// `>` redirection always requests create, so re-running it against a file
// that already exists hits E_CEF ("creating existing file") before the
// write-bit check is ever reached -- that would pass trivially regardless
// of the write bit, which is not what we want to test. `touch` opens an
// EXISTING file for write without requesting create, so it lands squarely
// on has_open_perm's write path (live-verified: E_FNA when owner-write is
// cleared, succeeds when it's set).
let filePermDev     = "hc"
let filePermDevPath = "/\(filePermDev)"
try? FileManager.default.removeItem(atPath: scratchDisk + "/" + filePermDev)

run("fs: permission — owner locks self out of writing own file (write bit via touch)",
    expectation: "clearing only owner-write blocks touch (open-for-write) on the owner's own file",
    commands: ["mount -k=200K \(filePermDev)", "chd \(filePermDevPath)",
               "login claude", "chd \(filePermDevPath)",
               "echo abc >f", "attr f -nw", "touch f", "logout"]) { $0.contains("Error #") }

check("fs: permission — owner can still read that same file (write lockout is write-specific)",
    contains: "6162 63",
    "chd \(filePermDevPath)", "login claude", "chd \(filePermDevPath)", "dump f", "logout")

try? FileManager.default.removeItem(atPath: scratchDisk + "/" + filePermDev)

// ---- permissions: directories (read gates traversal, write gates create/delete) ----
let dirPermDev  = "ha"
let dirPermPath = "/\(dirPermDev)"
try? FileManager.default.removeItem(atPath: scratchDisk + "/" + dirPermDev)

run("fs: permission dir — dog can create inside claude's dir while public r+w are set",
    expectation: "makdir's default attrs (owner+public rwx) let a non-owner create inside",
    commands: ["mount -k=200K \(dirPermDev)", "chd \(dirPermPath)",
               "login claude", "chd \(dirPermPath)", "makdir sub", "logout",
               "login dog", "chd \(dirPermPath)/sub", "echo x >g",
               "logout"]) { !$0.contains("Error #") }

check("fs: permission dir — write blocked once public-write is cleared",
    contains: "Error #",
    "chd \(dirPermPath)", "login claude", "chd \(dirPermPath)", "attr sub -npw", "logout",
    "login dog", "chd \(dirPermPath)/sub", "echo x >g2", "logout")

check("fs: permission dir — directory itself unreachable once public-read is also cleared",
    contains: "Error #",
    "chd \(dirPermPath)", "login claude", "chd \(dirPermPath)", "attr sub -npr", "logout",
    "login dog", "chd \(dirPermPath)/sub", "logout")

try? FileManager.default.removeItem(atPath: scratchDisk + "/" + dirPermDev)

// ---- permissions: pRdelete's parent-directory write check ----
// Deletion is gated on the PARENT DIRECTORY's write permission, not on who
// owns the file being deleted (live-verified below): dog lacks public-write
// on claude's "sub2", so dog's "del f" is blocked even though dog can still
// see/traverse into sub2 (public-read stays set). claude, who has owner-write
// on the directory, deletes the same file with no trouble -- the positive
// control that proves the negative result above isn't vacuous.
let delDev     = "hd"
let delDevPath = "/\(delDev)"
try? FileManager.default.removeItem(atPath: scratchDisk + "/" + delDev)

run("fs: permission del — dog blocked from deleting a file in claude's dir (no public-write)",
    expectation: "pRdelete's parent-directory write check rejects a non-owner without dir write",
    commands: ["mount -k=200K \(delDev)", "chd \(delDevPath)",
               "login claude", "chd \(delDevPath)", "makdir sub2", "chd sub2", "echo abc >f",
               "chd ..", "attr sub2 -npw", "logout",
               "login dog", "chd \(delDevPath)/sub2", "del f", "logout"]) {
    $0.contains("Error #")
}

check("fs: permission del — claude (dir owner, has write) deletes the same file fine",
    absent: "Error #",
    "chd \(delDevPath)/sub2", "login claude", "chd \(delDevPath)/sub2", "del f", "logout")

try? FileManager.default.removeItem(atPath: scratchDisk + "/" + delDev)

// ---- permissions: RAM disk (mount -r) backed RBF gets identical enforcement ----
// A RAM disk is still a genuine RBF filesystem (same file_rbf.c path as an
// on-disk image, just backed by the emulator's own memory arena instead of a
// host file) -- this proves enforcement isn't accidentally specific to
// file-backed images. Each test below is fully self-contained (mounts its
// own fresh /ram7, does its own login(s), unmounts at the end): unlike a
// `mount -k` image, a RAM disk has no host file backing it, so nothing
// persists between separate os9exec processes -- each `run()`/`check()`
// call here is its own process and must build the whole scenario itself.
// All four scenarios below were first live-verified by hand via
// tools/os9repl.sh (see the os9-dev skill's REPL notes) before being
// written here, including the "logout" gotcha noted above.
run("fs: permission ramdisk — claude creates+owns a file, can read it back",
    expectation: "dump of a freshly created file on a RAM-backed RBF device shows its bytes to its own creator",
    commands: ["mount -r=200 /ram7", "chd /ram7",
               "login claude", "chd /ram7",
               "echo abc >f", "dump f", "logout", "unmount ram7"]) { $0.contains("6162 63") }

check("fs: permission ramdisk — owner locks self out by clearing owner-read",
    contains: "Error #",
    "mount -r=200 /ram7", "chd /ram7", "login claude", "chd /ram7",
    "echo abc >f", "attr f -nr", "dump f", "logout", "unmount ram7")

check("fs: permission ramdisk — super-user still bypasses even after owner-read is cleared",
    contains: "6162 63",
    "mount -r=200 /ram7", "chd /ram7", "login claude", "chd /ram7",
    "echo abc >f", "attr f -nr", "logout",
    "chd /ram7", "dump f", "unmount ram7")

check("fs: permission ramdisk — non-owner (dog) blocked from a file with no public bits",
    contains: "Error #",
    "mount -r=200 /ram7", "chd /ram7", "login claude", "chd /ram7",
    "echo abc >f", "logout",
    "login dog", "chd /ram7", "dump f", "logout", "unmount ram7")


// ── fs: a host file the super user creates with no permissions reads back ─────
// combine creates its output with I$Create attributes $0000, writes through the
// path that gives it, and closes it. On an RBF image the super user can open it
// again ("any super-user may access any file", Technical Manual 7-11). On a
// host directory the attributes became host mode 000 and nobody could, so
// `cat out` answered E$FNA. A super-user create now keeps the owner-read bit on
// the host file -- read only, never write (rdoggett, 2026-09-15): reopening to
// read must work and see the data, reopening to write must still be refused.
do {
    let noBitsAsm = [
        "ICreate set $83", "IOpen set $84", "IRead set $89", "IWrite set $8A",
        "IWritLn set $8C", "IClose set $8F", "FExit set $06",
        " psect nobits,$0101,$8001,0,2048,start",
        "start", " sub.l #16,a7", " movea.l a7,a4",
        " lea fname(pc),a0", " moveq #3,d0", " moveq #0,d1", " clr.l d2",
        " trap #0", " dc.w ICreate", " bcs.w bad", " move.w d0,d7",
        " moveq #0,d0", " move.w d7,d0", " lea chR(pc),a0", " moveq #1,d1",
        " trap #0", " dc.w IWrite", " bcs.w bad",
        " moveq #0,d0", " move.w d7,d0", " trap #0", " dc.w IClose",
        " lea fname(pc),a0", " moveq #1,d0", " trap #0", " dc.w IOpen", " bcs.w bad",
        " move.w d0,d7",
        " moveq #0,d0", " move.w d7,d0", " movea.l a4,a0", " moveq #1,d1",
        " trap #0", " dc.w IRead", " bcs.w bad",
        " moveq #0,d0", " move.w d7,d0", " trap #0", " dc.w IClose",
        " cmpi.b #'R',(a4)", " bne.w bad",
        " lea okread(pc),a0", " moveq #1,d0", " moveq #okrl,d1", " trap #0", " dc.w IWritLn",
        " lea fname(pc),a0", " moveq #2,d0", " trap #0", " dc.w IOpen", " bcc.w bad",
        " cmpi.w #214,d1", " bne.w bad",
        " lea okwrite(pc),a0", " moveq #1,d0", " moveq #okwl,d1", " trap #0", " dc.w IWritLn",
        " moveq #0,d1", " trap #0", " dc.w FExit",
        "bad", " trap #0", " dc.w FExit",
        "fname dc.b \"/h5/nobits.dat\",0",
        "chR dc.b 'R'",
        "okread dc.b \"READ BACK A FILE CREATED WITH NO PERMISSIONS\",$0D",
        "okrl equ *-okread",
        "okwrite dc.b \"WRITE STILL REFUSED\",$0D",
        "okwl equ *-okwrite",
        " ends", ""
    ].joined(separator: "\r")

    let name = "fs: a host file the super user creates with no permissions reads back, write refused"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        removeScratchItem("nobits.dat")
        try? noBitsAsm.write(toFile: scratchDisk + "/nobits.a", atomically: true, encoding: .utf8)
        let out = os9([
            "load /dd/CMDS/r68 /dd/CMDS/l68",
            "r68 /h5/nobits.a -o=/h5/nobits.r",
            "l68 /h5/nobits.r -o=/h5/nobits",
            "/h5/nobits"
        ], timeout: 30)
        if out.contains("READ BACK A FILE CREATED WITH NO PERMISSIONS") && out.contains("WRITE STILL REFUSED") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            print("      [a super-user create with attributes 0 must reopen for read, not for write (214)]")
            let preview = out.split(whereSeparator: \.isNewline)
                .filter { $0.contains("READ BACK") || $0.contains("WRITE STILL") || $0.contains("rror #") }
                .prefix(4).joined(separator: " | ")
            print("      output: \(preview)")
            failed += 1
        }
        for leftover in ["nobits.a", "nobits.r", "nobits", "nobits.dat"] { removeScratchItem(leftover) }
    }
}

// ── fs: a zero-length read or write with no buffer on a host file ─────────────
// I$Read, I$ReadLn, I$Write and I$WritLn range-check the buffer only when the
// count is non-zero, so a count of 0 with A0=0 reached the host-file manager,
// whose assert(buffer!=NULL) then aborted the whole emulator. games4 adlrun
// does exactly this on its data file. A count of 0 transfers nothing, and RBF
// already answered it so; the probe must get four clean returns and live to say
// so.
do {
    let zeroAsm = [
        "IOpen set $84", "ICreate set $83", "IRead set $89", "IReadLn set $8B",
        "IWrite set $8A", "IWritLn set $8C", "IClose set $8F", "FExit set $06",
        " psect zerolen,$0101,$8001,0,2048,start",
        "start",
        " lea wname(pc),a0", " moveq #2,d0", " move.w #$1B,d1", " clr.l d2",
        " trap #0", " dc.w ICreate", " bcs.w bad", " move.w d0,d7",
        " moveq #0,d0", " move.w d7,d0", " moveq #0,d1", " suba.l a0,a0",
        " trap #0", " dc.w IWrite", " bcs.w bad", " tst.l d1", " bne.w bad",
        " moveq #0,d0", " move.w d7,d0", " moveq #0,d1", " suba.l a0,a0",
        " trap #0", " dc.w IWritLn", " bcs.w bad", " tst.l d1", " bne.w bad",
        " moveq #0,d0", " move.w d7,d0", " lea text(pc),a0", " moveq #textl,d1",
        " trap #0", " dc.w IWrite", " bcs.w bad",
        " moveq #0,d0", " move.w d7,d0", " trap #0", " dc.w IClose",
        " lea wname(pc),a0", " moveq #1,d0", " trap #0", " dc.w IOpen", " bcs.w bad",
        " move.w d0,d7",
        " moveq #0,d0", " move.w d7,d0", " moveq #0,d1", " suba.l a0,a0",
        " trap #0", " dc.w IRead", " bcs.w bad", " tst.l d1", " bne.w bad",
        " moveq #0,d0", " move.w d7,d0", " moveq #0,d1", " suba.l a0,a0",
        " trap #0", " dc.w IReadLn", " bcs.w bad", " tst.l d1", " bne.w bad",
        " lea okmsg(pc),a0", " moveq #1,d0", " moveq #okl,d1", " trap #0", " dc.w IWritLn",
        " moveq #0,d1", " trap #0", " dc.w FExit",
        "bad", " trap #0", " dc.w FExit",
        "wname dc.b \"/h5/zerolen.dat\",0",
        "text dc.b \"some text\",$0D",
        "textl equ *-text",
        "okmsg dc.b \"FOUR ZERO-LENGTH CALLS RETURNED\",$0D",
        "okl equ *-okmsg",
        " ends", ""
    ].joined(separator: "\r")

    let name = "fs: a zero-length read or write with no buffer returns on a host file"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? zeroAsm.write(toFile: scratchDisk + "/zerolen.a", atomically: true, encoding: .utf8)
        let out = os9([
            "load /dd/CMDS/r68 /dd/CMDS/l68",
            "r68 /h5/zerolen.a -o=/h5/zerolen.r",
            "l68 /h5/zerolen.r -o=/h5/zerolen",
            "/h5/zerolen"
        ], timeout: 30)
        if out.contains("FOUR ZERO-LENGTH CALLS RETURNED") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            print("      [I$Read/ReadLn/Write/WritLn with d1=0, a0=0 must return 0 bytes, no error]")
            let preview = out.split(whereSeparator: \.isNewline)
                .filter { $0.contains("rror") || $0.contains("ssert") }
                .prefix(4).joined(separator: " | ")
            print("      output: \(preview)")
            failed += 1
        }
        for leftover in ["zerolen.a", "zerolen.r", "zerolen", "zerolen.dat"] { removeScratchItem(leftover) }
    }
}

// ── system globals: D_Init points at the init module ──────────────────────────
// F$SetSys D_Init ($20) answered the host's own address of the init module,
// cut to 32 bits -- getsys printed $e8447dc0 -- so a program that followed it
// read nothing it could make sense of, or faulted. It must lead to a module
// header: the sync word, and a name offset that names "init".
do {
    let initAsm = [
        "FSetSys set $27", "IWritLn set $8C", "FExit set $06",
        " psect initptr,$0101,$8001,0,2048,start",
        "start",
        " moveq #$20,d0", " move.l #$80000004,d1",
        " trap #0", " dc.w FSetSys", " bcs.s bad",
        " movea.l d2,a0",
        " cmpi.w #$4AFC,(a0)", " bne.s bad",
        " move.l $C(a0),d0", " lea 0(a0,d0.l),a1",
        " move.b (a1)+,d0", " ori.b #$20,d0", " cmpi.b #'i',d0", " bne.s bad",
        " move.b (a1)+,d0", " ori.b #$20,d0", " cmpi.b #'n',d0", " bne.s bad",
        " move.b (a1)+,d0", " ori.b #$20,d0", " cmpi.b #'i',d0", " bne.s bad",
        " move.b (a1)+,d0", " ori.b #$20,d0", " cmpi.b #'t',d0", " bne.s bad",
        " tst.b (a1)", " bne.s bad",
        " lea okmsg(pc),a0", " moveq #1,d0", " moveq #okl,d1", " trap #0", " dc.w IWritLn",
        " moveq #0,d1", " trap #0", " dc.w FExit",
        "bad", " moveq #1,d1", " trap #0", " dc.w FExit",
        "okmsg dc.b \"D_INIT LEADS TO THE INIT MODULE\",$0D",
        "okl equ *-okmsg",
        " ends", ""
    ].joined(separator: "\r")

    let name = "globals: F$SetSys D_Init points at the init module's header"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? initAsm.write(toFile: scratchDisk + "/initptr.a", atomically: true, encoding: .utf8)
        let out = os9([
            "load /dd/CMDS/r68 /dd/CMDS/l68",
            "r68 /h5/initptr.a -o=/h5/initptr.r",
            "l68 /h5/initptr.r -o=/h5/initptr",
            "/h5/initptr"
        ], timeout: 30)
        if out.contains("D_INIT LEADS TO THE INIT MODULE") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let preview = out.split(whereSeparator: \.isNewline)
                .filter { $0.contains("rror") || $0.contains("initptr") }
                .prefix(4).joined(separator: " | ")
            print("      output: \(preview)")
            failed += 1
        }
        for leftover in ["initptr.a", "initptr.r", "initptr"] { removeScratchItem(leftover) }
    }
}

// ── system globals: the date and the current process ─────────────────────────
// F$SetSys answered 0 for year ($2A), month ($2C) and day ($2D), and for the
// current process's descriptor ($4C), all things os9exec knows. The date must
// agree with F$Time's, and D_Proc must lead to a descriptor carrying the
// caller's own ID (P$ID, its first word).
do {
    let globAsm = [
        "FSetSys set $27", "FID set $0C", "FTime set $15", "IWritLn set $8C", "FExit set $06",
        " psect globals,$0101,$8001,0,2048,start",
        "start",
        " moveq #0,d0", " trap #0", " dc.w FTime", " bcs.w bad", " move.l d1,d6",
        " moveq #$2A,d0", " move.l #$80000002,d1", " trap #0", " dc.w FSetSys", " bcs.w bad",
        " move.l d6,d3", " swap d3", " cmp.w d3,d2", " bne.w bad",
        " moveq #$2C,d0", " move.l #$80000001,d1", " trap #0", " dc.w FSetSys", " bcs.w bad",
        " move.l d6,d3", " lsr.l #8,d3", " cmp.b d3,d2", " bne.w bad",
        " moveq #$2D,d0", " move.l #$80000001,d1", " trap #0", " dc.w FSetSys", " bcs.w bad",
        " cmp.b d6,d2", " bne.w bad",
        " trap #0", " dc.w FID", " bcs.w bad", " move.w d0,d5",
        " moveq #$4C,d0", " move.l #$80000004,d1", " trap #0", " dc.w FSetSys", " bcs.w bad",
        " tst.l d2", " beq.w bad", " movea.l d2,a0", " cmp.w (a0),d5", " bne.w bad",
        " lea okmsg(pc),a0", " moveq #1,d0", " moveq #okl,d1", " trap #0", " dc.w IWritLn",
        " moveq #0,d1", " trap #0", " dc.w FExit",
        "bad", " moveq #1,d1", " trap #0", " dc.w FExit",
        "okmsg dc.b \"DATE AND CURRENT PROCESS AGREE\",$0D",
        "okl equ *-okmsg",
        " ends", ""
    ].joined(separator: "\r")

    let name = "globals: F$SetSys gives the date F$Time does, and D_Proc is the caller"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? globAsm.write(toFile: scratchDisk + "/globals.a", atomically: true, encoding: .utf8)
        let out = os9([
            "load /dd/CMDS/r68 /dd/CMDS/l68",
            "r68 /h5/globals.a -o=/h5/globals.r",
            "l68 /h5/globals.r -o=/h5/globals",
            "/h5/globals"
        ], timeout: 30)
        if out.contains("DATE AND CURRENT PROCESS AGREE") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let preview = out.split(whereSeparator: \.isNewline)
                .filter { $0.contains("rror") || $0.contains("globals") }
                .prefix(4).joined(separator: " | ")
            print("      output: \(preview)")
            failed += 1
        }
        for leftover in ["globals.a", "globals.r", "globals"] { removeScratchItem(leftover) }
    }
}

// ── system globals: D_Second counts down to midnight ─────────────────────────
// D_Second ($34) is the seconds LEFT until midnight (the Guru, getsys's label,
// and aprocs's arithmetic all agree), where F$Time's Julian form gives seconds
// since. Answered as seconds since, aprocs aged every process by ~2^32 s. The
// two must add up to a day, give or take the second that may tick between.
do {
    let secAsm = [
        "FSetSys set $27", "FTime set $15", "IWritLn set $8C", "FExit set $06",
        " psect dsecond,$0101,$8001,0,2048,start",
        "start",
        " moveq #1,d0", " trap #0", " dc.w FTime", " bcs.s bad", " move.l d0,d6",
        " moveq #$34,d0", " move.l #$80000004,d1", " trap #0", " dc.w FSetSys", " bcs.s bad",
        " add.l d6,d2", " subi.l #86399,d2", " bmi.s bad", " cmpi.l #2,d2", " bhi.s bad",
        " lea okmsg(pc),a0", " moveq #1,d0", " moveq #okl,d1", " trap #0", " dc.w IWritLn",
        " moveq #0,d1", " trap #0", " dc.w FExit",
        "bad", " moveq #1,d1", " trap #0", " dc.w FExit",
        "okmsg dc.b \"D_SECOND COUNTS DOWN TO MIDNIGHT\",$0D",
        "okl equ *-okmsg",
        " ends", ""
    ].joined(separator: "\r")

    let name = "globals: F$SetSys D_Second is the seconds left until midnight"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? secAsm.write(toFile: scratchDisk + "/dsecond.a", atomically: true, encoding: .utf8)
        let out = os9([
            "load /dd/CMDS/r68 /dd/CMDS/l68",
            "r68 /h5/dsecond.a -o=/h5/dsecond.r",
            "l68 /h5/dsecond.r -o=/h5/dsecond",
            "/h5/dsecond"
        ], timeout: 30)
        if out.contains("D_SECOND COUNTS DOWN TO MIDNIGHT") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let preview = out.split(whereSeparator: \.isNewline)
                .filter { $0.contains("rror") || $0.contains("dsecond") }
                .prefix(4).joined(separator: " | ")
            print("      output: \(preview)")
            failed += 1
        }
        for leftover in ["dsecond.a", "dsecond.r", "dsecond"] { removeScratchItem(leftover) }
    }
}

// ── fs: I$Create's mode byte has no directory bit ────────────────────────────
// Unix code ported to OS-9 calls creat(name, 0666), and 0666 cut to a byte is
// $B6: bit 7 set. I$Create cannot make a directory ("see I$MakDir"), and an RBF
// image ignores that bit and makes the file; a host directory took it as a
// directory open and answered E$PNNF, so patch could not make its temporary.
do {
    let creAsm = [
        "ICreate set $83", "IClose set $8F", "IWritLn set $8C", "FExit set $06",
        " psect crebit7,$0101,$8001,0,2048,start",
        "start",
        " lea fname(pc),a0", " move.b #$B6,d0", " moveq #$1B,d1", " moveq #0,d2",
        " trap #0", " dc.w ICreate", " bcs.s bad",
        " trap #0", " dc.w IClose", " bcs.s bad",
        " lea okmsg(pc),a0", " moveq #1,d0", " moveq #okl,d1", " trap #0", " dc.w IWritLn",
        " moveq #0,d1", " trap #0", " dc.w FExit",
        "bad", " trap #0", " dc.w FExit",
        "fname dc.b \"/h5/crebit7.dat\",0",
        "okmsg dc.b \"CREATED WITH BIT 7 IN THE MODE\",$0D",
        "okl equ *-okmsg",
        " ends", ""
    ].joined(separator: "\r")

    let name = "fs: I$Create with mode bit 7 set makes a plain file on a host directory"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? creAsm.write(toFile: scratchDisk + "/crebit7.a", atomically: true, encoding: .utf8)
        let out = os9([
            "load /dd/CMDS/r68 /dd/CMDS/l68",
            "r68 /h5/crebit7.a -o=/h5/crebit7.r",
            "l68 /h5/crebit7.r -o=/h5/crebit7",
            "/h5/crebit7"
        ], timeout: 30)
        var isDir: ObjCBool = false
        let made = FileManager.default.fileExists(atPath: scratchDisk + "/crebit7.dat", isDirectory: &isDir)
        if out.contains("CREATED WITH BIT 7 IN THE MODE") && made && !isDir.boolValue {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let preview = out.split(whereSeparator: \.isNewline)
                .filter { $0.contains("rror") || $0.contains("crebit7") }
                .prefix(4).joined(separator: " | ")
            print("      output: \(preview) made=\(made) dir=\(isDir.boolValue)")
            failed += 1
        }
        for leftover in ["crebit7.a", "crebit7.r", "crebit7", "crebit7.dat"] { removeScratchItem(leftover) }
    }
}

// ── memory: -W refuses a write outside the process's own memory ──────────────
// A debugging aid, as OS-9's SSM is on real hardware: with -W a user-state
// write must land in the process's data area, its F$SRqMem blocks or a loaded
// module, and anywhere else is a bus error that names the address. Fourteen of
// our own test programs wrote 32K past their data area for months, unseen,
// until one session layout made dcheck loop. The program writes its variables,
// its stack and a requested block, returns the block, then writes to it again:
// a freed block is also exactly what the check's one-slot cache must not
// remember. The same program without -W is the control: the late write lands.
do {
    let wildAsm = [
        "FSRqMem set $28", "FSRtMem set $29", "IWritLn set $8C", "FExit set $06",
        " psect wcheck,$0101,$8001,0,2048,start",
        " vsect", "own ds.l 1", " ends",
        "start",
        " move.l #$11111111,own(a6)",
        " bsr.s sub",
        " move.l #4096,d0", " trap #0", " dc.w FSRqMem", " bcs.s bad",
        " movea.l a2,a3", " move.l #$22222222,(a3)",
        " lea okmsg(pc),a0", " moveq #1,d0", " moveq #okl,d1", " trap #0", " dc.w IWritLn",
        " move.l #4096,d0", " movea.l a3,a2", " trap #0", " dc.w FSRtMem", " bcs.s bad",
        " move.l #$33333333,(a3)",
        " lea latemsg(pc),a0", " moveq #1,d0", " moveq #latel,d1", " trap #0", " dc.w IWritLn",
        " moveq #0,d1",
        "bad", " trap #0", " dc.w FExit",
        "sub", " move.l d0,-(a7)", " move.l (a7)+,d0", " rts",
        "okmsg dc.b \"OWN STACK HEAP OK\",$0D", "okl equ *-okmsg",
        "latemsg dc.b \"WROTE AFTER RETURN\",$0D", "latel equ *-latemsg",
        " ends", ""
    ].joined(separator: "\r")

    let name = "memory: -W refuses a write to a returned block, naming it, and nothing else"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? wildAsm.write(toFile: scratchDisk + "/wcheck.a", atomically: true, encoding: .utf8)
        let build = ["load /dd/CMDS/r68 /dd/CMDS/l68",
                     "r68 /h5/wcheck.a -o=/h5/wcheck.r", "l68 /h5/wcheck.r -o=/h5/wcheck"]
        _ = os9(build, timeout: 60)
        let plain   = os9(["/h5/wcheck"], timeout: 30)
        let checked = os9(build + ["/h5/wcheck"], timeout: 60, flags: ["-W"])

        // under OS9_FLAGS=-W (the whole suite run with the check on) there is no control
        let everyRunChecked = (ProcessInfo.processInfo.environment["OS9_FLAGS"] ?? "")
            .split(separator: " ").contains("-W")
        let controlLands = everyRunChecked
            || (plain.contains("OWN STACK HEAP OK") && plain.contains("WROTE AFTER RETURN") && !plain.contains("-W:"))
        let ownAllowed   = checked.contains("OWN STACK HEAP OK")
        let lateRefused  = checked.contains("wrote 4 bytes at $") && !checked.contains("WROTE AFTER RETURN")
        if controlLands && ownAllowed && lateRefused {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            if !controlLands { print("      without -W the late write did not land, or -W spoke anyway") }
            if !ownAllowed { print("      -W refused the program's own memory (or r68/l68/the shell)") }
            if !lateRefused { print("      -W let the write to the returned block through, or did not name it") }
            let seen = checked.split(whereSeparator: \.isNewline)
                .filter { $0.contains("-W") || $0.contains("OK") || $0.contains("WROTE") || $0.contains("rror") }
            print("      saw: \(seen.prefix(6))")
            failed += 1
        }
        for leftover in ["wcheck.a", "wcheck.r", "wcheck"] { removeScratchItem(leftover) }
    }
}

// ── memory: a process may hold more than 512 separate blocks ─────────────────
// os9exec kept a fixed 512-slot table of each process's F$SRqMem blocks and,
// unlike OS-9, never joins adjacent ones -- so the 513th request failed
// E$MemFul with the arena almost empty. utree, whose C library grows its heap
// 4 KB at a time, stopped partway through /dd at about 2 MB. Here one process
// holds 600 separate 4 KB blocks at once.
do {
    let blocksAsm = [
        "FSRqMem set $28", "IWritLn set $8C", "FExit set $06",
        " psect manyblks,$0101,$8001,0,2048,start",
        "start",
        " move.w #599,d5",
        "loop", " move.l #4096,d0", " trap #0", " dc.w FSRqMem", " bcs.s bad",
        " dbra d5,loop",
        " lea okmsg(pc),a0", " moveq #1,d0", " moveq #okl,d1", " trap #0", " dc.w IWritLn",
        " moveq #0,d1", " trap #0", " dc.w FExit",
        "bad", " trap #0", " dc.w FExit",
        "okmsg dc.b \"SIX HUNDRED BLOCKS HELD\",$0D",
        "okl equ *-okmsg",
        " ends", ""
    ].joined(separator: "\r")

    let name = "memory: one process holds 600 separate F$SRqMem blocks"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? blocksAsm.write(toFile: scratchDisk + "/manyblks.a", atomically: true, encoding: .utf8)
        let out = os9([
            "load /dd/CMDS/r68 /dd/CMDS/l68",
            "r68 /h5/manyblks.a -o=/h5/manyblks.r",
            "l68 /h5/manyblks.r -o=/h5/manyblks",
            "/h5/manyblks"
        ], timeout: 30)
        if out.contains("SIX HUNDRED BLOCKS HELD") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let preview = out.split(whereSeparator: \.isNewline)
                .filter { $0.contains("rror") || $0.contains("memory") || $0.contains("manyblks") }
                .prefix(4).joined(separator: " | ")
            print("      output: \(preview)")
            failed += 1
        }
        for leftover in ["manyblks.a", "manyblks.r", "manyblks"] { removeScratchItem(leftover) }
    }
}

// ── system globals: RAM, the tick, and the writable priority globals ─────────
// D_TotRAM ($6C) answered the pool of freed blocks ($c00 one run) instead of
// the arena; the allocatable top ($8B4) must equal it. $774, the current tick,
// is ticks since os9exec started -- it must advance across a sleep by at least
// the ticks slept. D_MinPty ($8A6) dropped a super-user's write: it must read
// back what was written, and the write must return the value before it.
do {
    let ramAsm = [
        "FSetSys set $27", "FSleep set $0A", "IWritLn set $8C", "FExit set $06",
        " psect ramtick,$0101,$8001,0,2048,start",
        "start",
        " moveq #$6C,d0", " move.l #$80000004,d1", " trap #0", " dc.w FSetSys", " bcs.w bad",
        " cmpi.l #$100000,d2", " bcs.w bad", " move.l d2,d6",
        " move.w #$8B4,d0", " move.l #$80000004,d1", " trap #0", " dc.w FSetSys", " bcs.w bad",
        " cmp.l d6,d2", " bne.w bad",
        " move.w #$774,d0", " move.l #$80000002,d1", " trap #0", " dc.w FSetSys", " bcs.w bad",
        " move.w d2,d5",
        " moveq #20,d0", " trap #0", " dc.w FSleep",
        " move.w #$774,d0", " move.l #$80000002,d1", " trap #0", " dc.w FSetSys", " bcs.w bad",
        " sub.w d5,d2", " cmpi.w #20,d2", " bcs.w bad",
        " move.w #$8A6,d0", " moveq #2,d1", " moveq #5,d2", " trap #0", " dc.w FSetSys", " bcs.w bad",
        " tst.l d2", " bne.w bad",
        " move.w #$8A6,d0", " move.l #$80000002,d1", " trap #0", " dc.w FSetSys", " bcs.w bad",
        " cmpi.w #5,d2", " bne.w bad",
        " move.w #$8A6,d0", " moveq #2,d1", " moveq #0,d2", " trap #0", " dc.w FSetSys", " bcs.w bad",
        " cmpi.l #5,d2", " bne.w bad",
        " lea okmsg(pc),a0", " moveq #1,d0", " moveq #okl,d1", " trap #0", " dc.w IWritLn",
        " moveq #0,d1", " trap #0", " dc.w FExit",
        "bad", " moveq #1,d1", " trap #0", " dc.w FExit",
        "okmsg dc.b \"RAM TICK AND MINPTY AGREE\",$0D",
        "okl equ *-okmsg",
        " ends", ""
    ].joined(separator: "\r")

    let name = "globals: F$SetSys gives the arena as RAM, a counting tick, and keeps D_MinPty"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? ramAsm.write(toFile: scratchDisk + "/ramtick.a", atomically: true, encoding: .utf8)
        let out = os9([
            "load /dd/CMDS/r68 /dd/CMDS/l68",
            "r68 /h5/ramtick.a -o=/h5/ramtick.r",
            "l68 /h5/ramtick.r -o=/h5/ramtick",
            "/h5/ramtick"
        ], timeout: 30)
        if out.contains("RAM TICK AND MINPTY AGREE") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let preview = out.split(whereSeparator: \.isNewline)
                .filter { $0.contains("rror") || $0.contains("ramtick") }
                .prefix(4).joined(separator: " | ")
            print("      output: \(preview)")
            failed += 1
        }
        for leftover in ["ramtick.a", "ramtick.r", "ramtick"] { removeScratchItem(leftover) }
    }
}

// ── system globals: the process queues and the event table ───────────────────
// The active, sleeping and waiting queue heads ($3AC/$3B4/$3BC) and the event
// table ($3CC, end at $3D0) answered 0. They now lead into the descriptor and
// event images, threaded through P$QueueN ($30) as on OS-9. The parent shell,
// waiting for this program, must be on the waiting queue; this program, the
// running one, on no queue; and an event it creates must be in the table.
do {
    let qAsm = [
        "FSetSys set $27", "FEvent set $53", "IWritLn set $8C", "FExit set $06",
        " psect queues,$0101,$8001,0,2048,start",
        "start",
        " moveq #$4C,d0", " move.l #$80000004,d1", " trap #0", " dc.w FSetSys", " bcs.w bad",
        " movea.l d2,a1", " move.w (a1),d6", " move.w 2(a1),d7",
        " move.w #$3BC,d0", " move.l #$80000004,d1", " trap #0", " dc.w FSetSys", " bcs.w bad",
        " movea.l d2,a0",
        "wloop", " move.l a0,d0", " beq.w bad", " cmp.w (a0),d7", " beq.s wfound",
        " movea.l $30(a0),a0", " bra.s wloop",
        "wfound",
        " move.w #$3AC,d0", " move.l #$80000004,d1", " trap #0", " dc.w FSetSys", " bcs.w bad",
        " movea.l d2,a0",
        "aloop", " move.l a0,d0", " beq.s adone", " cmp.w (a0),d6", " beq.w bad",
        " movea.l $30(a0),a0", " bra.s aloop",
        "adone",
        " lea evname(pc),a0", " moveq #0,d0", " moveq #2,d1", " moveq #0,d2", " moveq #0,d3",
        " trap #0", " dc.w FEvent", " bcs.w bad",
        " move.w #$3D0,d0", " move.l #$80000004,d1", " trap #0", " dc.w FSetSys", " bcs.w gone",
        " move.l d2,d4",
        " move.w #$3CC,d0", " move.l #$80000004,d1", " trap #0", " dc.w FSetSys", " bcs.w gone",
        " movea.l d2,a0",
        "eloop", " cmpa.l d4,a0", " bcc.w gone",
        " cmpi.b #'q',2(a0)", " bne.s enext", " cmpi.b #'t',3(a0)", " bne.s enext",
        " cmpi.b #'s',4(a0)", " bne.s enext", " cmpi.b #'t',5(a0)", " bne.s enext",
        " bra.s efound",
        "enext", " lea 32(a0),a0", " bra.s eloop",
        "efound",
        " lea evname(pc),a0", " moveq #3,d1", " trap #0", " dc.w FEvent",
        " lea okmsg(pc),a0", " moveq #1,d0", " moveq #okl,d1", " trap #0", " dc.w IWritLn",
        " moveq #0,d1", " trap #0", " dc.w FExit",
        "gone", " lea evname(pc),a0", " moveq #3,d1", " trap #0", " dc.w FEvent",
        "bad", " moveq #1,d1", " trap #0", " dc.w FExit",
        "evname dc.b \"qtst\",0",
        "okmsg dc.b \"QUEUES AND EVENT TABLE AGREE\",$0D",
        "okl equ *-okmsg",
        " ends", ""
    ].joined(separator: "\r")

    let name = "globals: F$SetSys process queues and event table lead to the right entries"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? qAsm.write(toFile: scratchDisk + "/queues.a", atomically: true, encoding: .utf8)
        let out = os9([
            "load /dd/CMDS/r68 /dd/CMDS/l68",
            "r68 /h5/queues.a -o=/h5/queues.r",
            "l68 /h5/queues.r -o=/h5/queues",
            "/h5/queues"
        ], timeout: 30)
        if out.contains("QUEUES AND EVENT TABLE AGREE") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let preview = out.split(whereSeparator: \.isNewline)
                .filter { $0.contains("rror") || $0.contains("queues") }
                .prefix(4).joined(separator: " | ")
            print("      output: \(preview)")
            failed += 1
        }
        for leftover in ["queues.a", "queues.r", "queues"] { removeScratchItem(leftover) }
    }
}

// ── terminal: two writers' lines arrive whole, never mixed ───────────────────
// SCF gives one write request the device until it is done (V_BUSY) and queues
// any other process that asks meanwhile. os9exec parks a terminal write
// partway when the terminal cannot take more, and another process's write went
// straight through while it was parked, so two programs writing one terminal
// came out mixed character by character. Two writers of 40 lines each: every
// line must be all one letter.
do {
    func linesAsm(_ letter: Character, _ mod: String) -> String {
        [
            "IWritLn set $8C", "FExit set $06",
            " psect \(mod),$0101,$8001,0,4096,start",
            "start",
            " moveq #39,d5",
            "loop", " lea line(pc),a0", " moveq #1,d0", " moveq #lnl,d1",
            " trap #0", " dc.w IWritLn", " bcs.s bad", " dbra d5,loop",
            " moveq #0,d1", " trap #0", " dc.w FExit",
            "bad", " trap #0", " dc.w FExit",
            "line dc.b \"\(String(repeating: letter, count: 70))\",$0D",
            "lnl equ *-line",
            " ends", ""
        ].joined(separator: "\r")
    }
    let name = "terminal: two processes writing one terminal get whole lines, never mixed"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? linesAsm("A", "linesa").write(toFile: scratchDisk + "/linesa.a", atomically: true, encoding: .utf8)
        try? linesAsm("B", "linesb").write(toFile: scratchDisk + "/linesb.a", atomically: true, encoding: .utf8)
        let out = os9([
            "load /dd/CMDS/r68 /dd/CMDS/l68",
            "r68 /h5/linesa.a -o=/h5/linesa.r", "l68 /h5/linesa.r -o=/h5/linesa",
            "r68 /h5/linesb.a -o=/h5/linesb.r", "l68 /h5/linesb.r -o=/h5/linesb",
            // one line, typed in full before either writer starts: nothing typed
            // later can be echoed into the middle of their output
            "/h5/linesa & /h5/linesb; w"
        ], timeout: 90, paced: true)   // paced: a write parks when the terminal is full
        let lines = out.split(whereSeparator: \.isNewline).map(String.init)
            .filter { $0.contains("AAAAAAAAAA") || $0.contains("BBBBBBBBBB") }
        let whole = lines.filter { $0.hasSuffix(String(repeating: "A", count: 70)) && !$0.contains("B")
                                || $0.hasSuffix(String(repeating: "B", count: 70)) && !$0.contains("A") }
        if lines.count >= 80 && whole.count == lines.count {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            print("      saw: \(lines.count) letter lines, \(whole.count) whole")
            if let mixed = lines.first(where: { l in !whole.contains(l) }) { print("      e.g. \(mixed)") }
            failed += 1
        }
        for leftover in ["linesa.a", "linesa.r", "linesa", "linesb.a", "linesb.r", "linesb"] {
            removeScratchItem(leftover)
        }
    }
}

// ── system globals: the time slice follows the system tick ───────────────────
// $776 (ticks per slice) and $778 (ticks left in this slice) answered 0. The
// tick ends the running process's turn every tick, so both are 1 while the
// clock runs and 0 with it off (-q). The program prints both as digits.
do {
    // The message is built in the data area: "SLICE a b" + CR.
    let sliceAsm = [
        "FSetSys set $27", "IWritLn set $8C", "FExit set $06",
        " psect slice,$0101,$8001,0,2048,start",
        " vsect",
        "msg ds.b 10",
        " ends",
        "start",
        " lea msg(a6),a0",
        " move.b #'S',(a0)", " move.b #'L',1(a0)", " move.b #'I',2(a0)", " move.b #'C',3(a0)",
        " move.b #'E',4(a0)", " move.b #' ',5(a0)", " move.b #' ',7(a0)", " move.b #$0D,9(a0)",
        " move.w #$776,d0", " move.l #$80000002,d1", " trap #0", " dc.w FSetSys", " bcs.s bad",
        " add.b #'0',d2", " lea msg(a6),a0", " move.b d2,6(a0)",
        " move.w #$778,d0", " move.l #$80000002,d1", " trap #0", " dc.w FSetSys", " bcs.s bad",
        " add.b #'0',d2", " lea msg(a6),a0", " move.b d2,8(a0)",
        " moveq #1,d0", " moveq #10,d1", " trap #0", " dc.w IWritLn",
        " moveq #0,d1", " trap #0", " dc.w FExit",
        "bad", " moveq #1,d1", " trap #0", " dc.w FExit",
        " ends", ""
    ].joined(separator: "\r")

    let name = "globals: F$SetSys time slice is one tick with the clock on, none with it off"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? sliceAsm.write(toFile: scratchDisk + "/slice.a", atomically: true, encoding: .utf8)
        let build = ["load /dd/CMDS/r68 /dd/CMDS/l68",
                     "r68 /h5/slice.a -o=/h5/slice.r", "l68 /h5/slice.r -o=/h5/slice"]
        let tickOffAlready = (ProcessInfo.processInfo.environment["OS9_FLAGS"] ?? "").contains("-q")
        let asRun = os9(build + ["/h5/slice"], timeout: 30)
        let offRun = os9(["/h5/slice"], timeout: 30, flags: ["-q"])
        let wantOn = tickOffAlready ? "SLICE 0 0" : "SLICE 1 1"
        if asRun.contains(wantOn) && offRun.contains("SLICE 0 0") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let pick = { (o: String) in o.split(whereSeparator: \.isNewline).filter { $0.contains("SLICE") || $0.contains("rror") }.joined(separator: " | ") }
            print("      want \(wantOn) and SLICE 0 0 with -q; saw: [\(pick(asRun))] [\(pick(offRun))]")
            failed += 1
        }
        for leftover in ["slice.a", "slice.r", "slice"] { removeScratchItem(leftover) }
    }
}

// ── process: the debugger calls refuse a process ID past the table ───────────
// F$DExec and F$DExit take the child's ID from the guest's d0.w and indexed the
// process table with it unchecked; F$DExit then WROTE through it. F$GPrDsc had
// the same hole and is CONF68K t60; these two are debugger calls, which a
// conformance suite has no business making on a real system, so they are here.
do {
    let dbgAsm = [
        "FDExec set $23", "FDExit set $24", "IWritLn set $8C", "FExit set $06",
        " psect dbgpid,$0101,$8001,0,2048,start",
        "start",
        " moveq #0,d0", " move.w #$FFFF,d0", " moveq #0,d1", " moveq #0,d2", " lea start(pc),a0",
        " trap #0", " dc.w FDExec", " bcc.s bad", " cmpi.w #224,d1", " bne.s bad",
        " moveq #0,d0", " move.w #$FFFF,d0",
        " trap #0", " dc.w FDExit", " bcc.s bad", " cmpi.w #224,d1", " bne.s bad",
        " lea okmsg(pc),a0", " moveq #1,d0", " moveq #okl,d1", " trap #0", " dc.w IWritLn",
        " moveq #0,d1", " trap #0", " dc.w FExit",
        "bad", " moveq #1,d1", " trap #0", " dc.w FExit",
        "okmsg dc.b \"BOTH DEBUGGER CALLS REFUSED THE ID\",$0D",
        "okl equ *-okmsg",
        " ends", ""
    ].joined(separator: "\r")

    let name = "process: F$DExec and F$DExit refuse a process ID past the table"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? dbgAsm.write(toFile: scratchDisk + "/dbgpid.a", atomically: true, encoding: .utf8)
        let out = os9([
            "load /dd/CMDS/r68 /dd/CMDS/l68",
            "r68 /h5/dbgpid.a -o=/h5/dbgpid.r",
            "l68 /h5/dbgpid.r -o=/h5/dbgpid",
            "/h5/dbgpid"
        ], timeout: 30)
        if out.contains("BOTH DEBUGGER CALLS REFUSED THE ID") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            print("      [F$DExec and F$DExit of ID $FFFF must both answer E$IPrcID (224)]")
            let preview = out.split(whereSeparator: \.isNewline)
                .filter { $0.contains("Error") || $0.contains("rror #") }
                .prefix(4).joined(separator: " | ")
            print("      output: \(preview)")
            failed += 1
        }
        for leftover in ["dbgpid.a", "dbgpid.r", "dbgpid"] { removeScratchItem(leftover) }
    }
}

// ── fs: a host directory moves a file by link-then-unlink ───────────────────
// move does not rewrite an entry: through one update path it appends an entry
// past the last, carrying the file's FD sector, and through a second it clears
// the old entry's first byte. A host directory has neither, so the append now
// becomes a host rename of the file that FD sector names, and the clear that
// follows is taken as already done -- but only right after such an append; a
// clear on its own is a delete, which a host directory still refuses. The
// probes run in order against /h5/mvd1 and /h5/mvd2, and the host directories
// are read back afterwards.
do {
    func entryName(_ name: String) -> String {
        let bytes = Array(name.utf8)
        let last = String(format: "$%02X", Int(bytes[bytes.count - 1]) | 0x80)
        return bytes.count == 1 ? "dc.b \(last)" : "dc.b \"\(String(name.dropLast()))\",\(last)"
    }

    struct MoveProbe {
        let module: String
        let srcDir: String
        let dstDir: String
        let from: String
        let into: String
        var append = true
        var clear = true
        let expect: Int
        let why: String
    }

    func source(_ probe: MoveProbe) -> String {
        var lines = [
            "IOpen set $84", "IRead set $89", "IWrite set $8A", "ISeek set $88",
            "IGetStt set $8D", "FExit set $06",
            " psect \(probe.module),$0101,$8001,0,2048,start",
            "start", " sub.l #64,a7", " movea.l a7,a4",
            " lea psrc(pc),a0", " moveq #0,d0", " move.b #$83,d0",
            " trap #0", " dc.w IOpen", " bcs.w pfail", " move.w d0,d6", " moveq #0,d5",
            "prd", " moveq #0,d0", " move.w d6,d0", " movea.l a4,a0", " moveq #32,d1",
            " trap #0", " dc.w IRead", " bcs.w pfail",
            " movea.l a4,a0", " lea pold(pc),a3", " moveq #\(probe.from.utf8.count - 1),d2",
            "pcmp", " cmpm.b (a0)+,(a3)+", " bne.s pnext", " dbra d2,pcmp", " bra.s pfound",
            "pnext", " addi.l #32,d5", " bra.s prd",
            "pfound"
        ]
        if probe.append {
            lines += [
                " lea pdst(pc),a0", " moveq #0,d0", " move.b #$83,d0",
                " trap #0", " dc.w IOpen", " bcs.w pfail", " move.w d0,d7",
                " moveq #0,d0", " move.w d7,d0", " moveq #2,d1", " trap #0", " dc.w IGetStt", " bcs.w pfail",
                " moveq #0,d0", " move.w d7,d0", " move.l d2,d1", " trap #0", " dc.w ISeek", " bcs.w pfail",
                " movea.l a4,a0", " lea pnew(pc),a3", " moveq #\(probe.into.utf8.count - 1),d2",
                "pcpy", " move.b (a3)+,(a0)+", " dbra d2,pcpy",
                " moveq #\(27 - probe.into.utf8.count),d2",
                "pclr", " clr.b (a0)+", " dbra d2,pclr",
                " moveq #0,d0", " move.w d7,d0", " movea.l a4,a0", " moveq #32,d1",
                " trap #0", " dc.w IWrite", " bcs.w pfail"
            ]
        }
        if probe.clear {
            lines += [
                " moveq #0,d0", " move.w d6,d0", " move.l d5,d1", " trap #0", " dc.w ISeek", " bcs.s pfail",
                " moveq #0,d0", " move.w d6,d0", " lea pzero(pc),a0", " moveq #1,d1",
                " trap #0", " dc.w IWrite", " bcs.s pfail"
            ]
        }
        lines += [
            " moveq #0,d1", " trap #0", " dc.w FExit",
            "pfail", " trap #0", " dc.w FExit",
            "psrc dc.b \"\(probe.srcDir)\",0",
            "pdst dc.b \"\(probe.dstDir)\",0",
            "pold \(entryName(probe.from))",
            "pnew \(entryName(probe.into))",
            "pzero dc.b 0",
            " ends", ""
        ]
        return lines.joined(separator: "\r")
    }

    let probes = [
        MoveProbe(module: "mv01", srcDir: "/h5/mvd1", dstDir: "/h5/mvd1", from: "mva", into: "mvb",
                  expect: 0, why: "a move within one directory"),
        MoveProbe(module: "mv02", srcDir: "/h5/mvd1", dstDir: "/h5/mvd2", from: "mvb", into: "mvc",
                  expect: 0, why: "a move into another directory"),
        MoveProbe(module: "mv03", srcDir: "/h5/mvd2", dstDir: "/h5/mvd2", from: "mvc", into: "mvc",
                  append: false, expect: 203, why: "a clear with no append before it (a delete)"),
        MoveProbe(module: "mv04", srcDir: "/h5/mvd2", dstDir: "/h5/mvd1", from: "mvc", into: "mvx",
                  clear: false, expect: 218, why: "an append onto a name the directory already has"),
        // ln: the append alone makes a second name, and the first stays. It was
        // one host rename at once, and the original name was lost (found by the
        // file-system review).
        MoveProbe(module: "mv05", srcDir: "/h5/mvd1", dstDir: "/h5/mvd1", from: "mvx", into: "mvy",
                  clear: false, expect: 0, why: "an append with no clear after it (ln)")
    ]

    let name = "fs: a host directory moves a file by link-then-unlink"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let fileManager = FileManager.default
        for leftover in ["mvd1", "mvd2"] { removeScratchItem(leftover) }
        try? fileManager.createDirectory(atPath: scratchDisk + "/mvd1", withIntermediateDirectories: false)
        try? fileManager.createDirectory(atPath: scratchDisk + "/mvd2", withIntermediateDirectories: false)
        try? "M".write(toFile: scratchDisk + "/mvd1/mva", atomically: false, encoding: .utf8)
        try? "X".write(toFile: scratchDisk + "/mvd1/mvx", atomically: false, encoding: .utf8)

        var build = ["load /dd/CMDS/r68 /dd/CMDS/l68"]
        for probe in probes {
            try? source(probe).write(toFile: scratchDisk + "/\(probe.module).a",
                                     atomically: true, encoding: .utf8)
            build += ["r68 /h5/\(probe.module).a -o=/h5/\(probe.module).r",
                      "l68 /h5/\(probe.module).r -o=/h5/\(probe.module)"]
        }
        _ = os9(build, timeout: 60)

        var faults: [String] = []
        for probe in probes {
            let out = os9(["/h5/\(probe.module)"], timeout: 20)
            let code = out.range(of: "#000:").flatMap { Int(out[$0.upperBound...].prefix(3)) } ?? 0
            if code != probe.expect {
                faults.append("\(probe.why): \(probe.from) -> \(probe.into) gave \(code), expected \(probe.expect)")
            }
        }

        func listing(_ dir: String) -> Set<String> {
            Set((try? fileManager.contentsOfDirectory(atPath: scratchDisk + "/" + dir)) ?? [])
        }
        let one = listing("mvd1"), two = listing("mvd2")
        let moved = try? String(contentsOfFile: scratchDisk + "/mvd2/mvc", encoding: .utf8)
        if moved != "M" || one.contains("mva") || one.contains("mvb") {
            faults.append("after the moves: expected mvd2/mvc holding M and neither mva nor mvb in mvd1; "
                          + "saw mvd1 \(one.sorted()) mvd2 \(two.sorted())")
        }
        if !one.contains("mvx") { faults.append("mvd1/mvx, which mv04 collided with and mv05 linked, is gone") }
        let linked = try? String(contentsOfFile: scratchDisk + "/mvd1/mvy", encoding: .utf8)
        if linked != "X" { faults.append("mv05's second name mvd1/mvy does not hold X: \(linked ?? "missing")") }

        if faults.isEmpty {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            for fault in faults { print("      \(fault)") }
            failed += 1
        }

        for leftover in ["mvd1/mva", "mvd1/mvb", "mvd1/mvx", "mvd1/mvy", "mvd2/mvc", "mvd1", "mvd2"] {
            removeScratchItem(leftover)
        }
        for probe in probes {
            for suffix in ["", ".a", ".r"] { removeScratchItem(probe.module + suffix) }
        }
    }
}

// ── fs: a host directory renames by entry write, and refuses the rest ─────────
// RBF renames a file when a program rewrites its directory entry spelt
// differently -- Microware's clib rename(), move, wndex and upperdir all do it.
// A host directory refused every such write with E$BMode until pDwrite turned
// a pure rename into a host rename. CONF68K t59 checks the rename on both kinds
// of device; these are the host directory's own refusals, which an RBF image
// has no reason to make. Each probe opens /h5 as a directory, reads to the
// entry spelt `from`, and writes it back spelt `into`, exiting with the error it
// got. The host directory is then read back to see what actually happened.
do {
    /// A directory-entry name as the assembler spells it: the characters, the
    /// last with its sign bit set.
    func entryName(_ name: String) -> String {
        let bytes = Array(name.utf8)
        let last = String(format: "$%02X", Int(bytes[bytes.count - 1]) | 0x80)
        return bytes.count == 1 ? "dc.b \(last)" : "dc.b \"\(String(name.dropLast()))\",\(last)"
    }

    struct RenameProbe {
        let module: String
        let from: String
        let into: String
        var mode = 0x83
        var changeFD = false
        var holding: String?
        var heldMode = 1
        let expect: Int
        let why: String
    }

    func source(_ probe: RenameProbe) -> String {
        var lines = [
            "IOpen set $84", "IRead set $89", "IWrite set $8A", "ISeek set $88", "FExit set $06",
            " psect \(probe.module),$0101,$8001,0,2048,start",
            "start", " sub.l #64,a7", " movea.l a7,a4"
        ]
        if probe.holding != nil {
            lines += [" lea pheld(pc),a0", " moveq #\(probe.heldMode),d0", " trap #0", " dc.w IOpen", " bcs.w pfail",
                      " move.w d0,d6"]
        }
        lines += [
            " lea pdir(pc),a0", " moveq #0,d0", String(format: " move.b #$%02X,d0", probe.mode),
            " trap #0", " dc.w IOpen", " bcs.w pfail", " move.w d0,d7", " moveq #0,d5",
            "prd", " moveq #0,d0", " move.w d7,d0", " movea.l a4,a0", " moveq #32,d1",
            " trap #0", " dc.w IRead", " bcs.w pfail",
            " movea.l a4,a0", " lea pold(pc),a3", " moveq #\(probe.from.utf8.count - 1),d2",
            "pcmp", " cmpm.b (a0)+,(a3)+", " bne.s pnext", " dbra d2,pcmp",
            " moveq #0,d0", " move.w d7,d0", " move.l d5,d1", " trap #0", " dc.w ISeek", " bcs.w pfail",
            " movea.l a4,a0", " lea pnew(pc),a3", " moveq #\(probe.into.utf8.count - 1),d2",
            "pcpy", " move.b (a3)+,(a0)+", " dbra d2,pcpy",
            " moveq #\(27 - probe.into.utf8.count),d2",
            "pclr", " clr.b (a0)+", " dbra d2,pclr"
        ]
        if probe.changeFD { lines.append(" eori.b #1,31(a4)") }
        lines += [
            " moveq #0,d0", " move.w d7,d0", " movea.l a4,a0", " moveq #32,d1",
            " trap #0", " dc.w IWrite", " bcs.s pfail"
        ]
        if probe.holding != nil {
            // the path held open across the rename must still read
            lines += [" moveq #0,d0", " move.w d6,d0", " movea.l a4,a0", " moveq #1,d1",
                      " trap #0", " dc.w IRead", " bcs.s pfail"]
        }
        lines += [
            " moveq #0,d1", " trap #0", " dc.w FExit",
            "pnext", " addi.l #32,d5", " bra.w prd",
            "pfail", " trap #0", " dc.w FExit",
            "pdir dc.b \"/h5\",0",
            "pold \(entryName(probe.from))",
            "pnew \(entryName(probe.into))"
        ]
        if let held = probe.holding { lines.append("pheld dc.b \"/h5/\(held)\",0") }
        lines += [" ends", ""]
        return lines.joined(separator: "\r")
    }

    let probes = [
        RenameProbe(module: "rn01", from: "rnsrc", into: "rndst", expect: 0, why: "a plain rename"),
        RenameProbe(module: "rn02", from: "rndst", into: "RNDST", expect: 0, why: "a case-only rename"),
        RenameProbe(module: "rn03", from: "RNDST", into: "rnother", expect: 218,
                    why: "onto a name another file has"),
        RenameProbe(module: "rn04", from: "RNDST", into: "RNOTHER", expect: 218,
                    why: "onto another file's name in other case"),
        RenameProbe(module: "rn05", from: "rnother", into: "rnfd", changeFD: true, expect: 203,
                    why: "with another FD sector"),
        RenameProbe(module: "rn06", from: "rnother", into: "rnro", mode: 0x81, expect: 203,
                    why: "on a directory opened for read only"),
        RenameProbe(module: "rn07", from: "rnheld", into: "rnheld2", holding: "rnheld", expect: 0,
                    why: "of a file held open, read through afterwards"),
        RenameProbe(module: "rn08", from: "rn_sp", into: "rnsp2", expect: 203,
                    why: "of a host name the entry does not spell (a space)"),
        RenameProbe(module: "rn09", from: "rnother", into: "rn-x", expect: 235,
                    why: "to a name OS-9 cannot hold"),
        RenameProbe(module: "rn10", from: "rnother", into: "rnother", expect: 0,
                    why: "writing the entry back unchanged"),
        RenameProbe(module: "rn11", from: "rnsub", into: "rnsub2", holding: "rnsub", heldMode: 0x81,
                    expect: 0, why: "of a directory held open, as upperdir does, read through afterwards")
    ]

    let name = "fs: a host directory renames by entry write, and refuses the rest"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let hostNames = ["rnsrc", "rndst", "rnother", "rn sp", "rnsp2", "rnfd", "rnro", "rnheld", "rnheld2",
                         "rnsub", "rnsub2", "rn-x"]
        for leftover in hostNames { removeScratchItem(leftover) }
        let seeded = ["rnsrc": "A", "rnother": "B", "rn sp": "C", "rnheld": "H"]
        for (host, text) in seeded {
            try? text.write(toFile: scratchDisk + "/" + host, atomically: false, encoding: .utf8)
        }
        try? FileManager.default.createDirectory(atPath: scratchDisk + "/rnsub",
                                                 withIntermediateDirectories: false)
        try? "S".write(toFile: scratchDisk + "/rnsub/inside", atomically: false, encoding: .utf8)

        var build = ["load /dd/CMDS/r68 /dd/CMDS/l68"]
        for probe in probes {
            try? source(probe).write(toFile: scratchDisk + "/\(probe.module).a",
                                     atomically: true, encoding: .utf8)
            build += ["r68 /h5/\(probe.module).a -o=/h5/\(probe.module).r",
                      "l68 /h5/\(probe.module).r -o=/h5/\(probe.module)"]
        }
        _ = os9(build, timeout: 60)

        var faults: [String] = []
        for probe in probes {
            let out = os9(["/h5/\(probe.module)"], timeout: 20)
            let code = out.range(of: "#000:").flatMap { Int(out[$0.upperBound...].prefix(3)) } ?? 0
            if code != probe.expect {
                faults.append("\(probe.why): \(probe.from) -> \(probe.into) gave \(code), expected \(probe.expect)")
            }
        }

        let listing = Set((try? FileManager.default.contentsOfDirectory(atPath: scratchDisk)) ?? [])
        func text(_ host: String) -> String? {
            try? String(contentsOfFile: scratchDisk + "/" + host, encoding: .utf8)
        }
        if !listing.contains("RNDST") || text("RNDST") != "A" || listing.contains("rnsrc") {
            let seen = listing.filter { $0.lowercased().hasPrefix("rn") && !$0.contains(".") }.sorted()
            faults.append("host after the renames: expected RNDST holding A and no rnsrc, saw \(seen)")
        }
        if text("rnother") != "B" { faults.append("rnother no longer holds B") }
        if text("rn sp") != "C" { faults.append("the host file with a space was changed") }
        if text("rnheld2") != "H" || listing.contains("rnheld") {
            faults.append("the file held open was not renamed to rnheld2")
        }
        if text("rnsub2/inside") != "S" || listing.contains("rnsub") {
            faults.append("the directory held open was not renamed to rnsub2")
        }

        if faults.isEmpty {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            for fault in faults { print("      \(fault)") }
            failed += 1
        }

        for leftover in hostNames + ["RNDST"] { removeScratchItem(leftover) }
        removeScratchItem("rnsub2/inside")
        for probe in probes {
            for suffix in ["", ".a", ".r"] { removeScratchItem(probe.module + suffix) }
        }
    }
}

// ── CPU: NEG and NBCD leave X equal to C, as SUB does ─────────────────────────
// Regression for a flag the core never set. On the 68000, NEG, SUB/SUBI/SUBQ
// and NBCD leave X equal to C. Every NEG and NBCD handler, and the SUB family
// in the 68000 and 68010 tables, set C and left X at whatever the previous
// instruction had made it. Microware's software doubles negate a 64-bit
// mantissa as NEG.L low then NEGX.L high, so a stale X borrowed from the high
// word: 1.0-1.0 came out -2^-20, exp(1) was right to six places, and perl's
// <=> never answered 0 for equal numbers. Each case sets X to the opposite of
// what the instruction must leave, and reads it back with ADDX of two zeros.
do {
    let xflagAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "",
        "F$Exit   equ  $06",
        "I$WritLn equ  $8C",
        "",
        "  psect xflgtst,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,512,start",
        "",
        "* Each case sets X to the opposite of what the instruction must leave,",
        "* runs the instruction, then reads X back with ADDX of two zeros.",
        "start:",
        "  moveq   #0,d7",
        "  subq.l  #8,a7",
        "  movea.l a7,a2",
        "",
        "* Microware's software double add: a 64-bit negate of a zero low word",
        "* must leave no borrow for the high word",
        "  ori.b   #$10,ccr",
        "  moveq   #0,d1",
        "  move.l  #$00100000,d0",
        "  neg.l   d1",
        "  negx.l  d0",
        "  cmpi.l  #$FFF00000,d0",
        "  beq     c1",
        "  addq.l  #1,d7",
        "  lea     f0(pc),a0",
        "  moveq   #f0l,d1",
        "  moveq   #1,d0",
        "  OS9     I$WritLn",
        "c1:",
        "  ori.b   #$10,ccr",
        "  moveq   #0,d1",
        "  neg.l   d1",
        "  moveq   #0,d0",
        "  addx.l  d0,d0",
        "  moveq   #0,d2",
        "  lea     f1(pc),a0",
        "  moveq   #f1l,d1",
        "  bsr     chk",
        "",
        "  andi.b  #$EF,ccr",
        "  moveq   #5,d1",
        "  neg.b   d1",
        "  moveq   #0,d0",
        "  addx.l  d0,d0",
        "  moveq   #1,d2",
        "  lea     f2(pc),a0",
        "  moveq   #f2l,d1",
        "  bsr     chk",
        "",
        "  andi.b  #$EF,ccr",
        "  clr.l   (a2)",
        "  moveq   #1,d3",
        "  sub.l   d3,(a2)",
        "  moveq   #0,d0",
        "  addx.l  d0,d0",
        "  moveq   #1,d2",
        "  lea     f3(pc),a0",
        "  moveq   #f3l,d1",
        "  bsr     chk",
        "",
        "* not #1..#8: r68 assembles those as SUBQ, which never lacked X",
        "  andi.b  #$EF,ccr",
        "  clr.l   (a2)",
        "  subi.l  #$100,(a2)+",
        "  moveq   #0,d0",
        "  addx.l  d0,d0",
        "  subq.l  #4,a2",
        "  moveq   #1,d2",
        "  lea     f4(pc),a0",
        "  moveq   #f4l,d1",
        "  bsr     chk",
        "",
        "  ori.b   #$10,ccr",
        "  move.l  #9,(a2)",
        "  subq.l  #1,(a2)",
        "  moveq   #0,d0",
        "  addx.l  d0,d0",
        "  moveq   #0,d2",
        "  lea     f5(pc),a0",
        "  moveq   #f5l,d1",
        "  bsr     chk",
        "",
        "  andi.b  #$EF,ccr",
        "  moveq   #1,d1",
        "  nbcd    d1",
        "  moveq   #0,d0",
        "  addx.l  d0,d0",
        "  moveq   #1,d2",
        "  lea     f6(pc),a0",
        "  moveq   #f6l,d1",
        "  bsr     chk",
        "",
        "  tst.l   d7",
        "  bne     done",
        "  lea     mall(pc),a0",
        "  moveq   #malll,d1",
        "  moveq   #1,d0",
        "  OS9     I$WritLn",
        "done:",
        "  moveq   #0,d1",
        "  OS9     F$Exit",
        "",
        "* d0 = X as read, d2 = X required, a0/d1 = the failure line",
        "chk:",
        "  cmp.l   d2,d0",
        "  beq     chkok",
        "  addq.l  #1,d7",
        "  moveq   #1,d0",
        "  OS9     I$WritLn",
        "chkok:",
        "  rts",
        "",
        "f0:   dc.b  \"FAIL: NEG.L 0 then NEGX.L borrowed from a stale X\",$0D",
        "f0l   equ   *-f0",
        "f1:   dc.b  \"FAIL: NEG.L of zero left X set\",$0D",
        "f1l   equ   *-f1",
        "f2:   dc.b  \"FAIL: NEG.B of nonzero left X clear\",$0D",
        "f2l   equ   *-f2",
        "f3:   dc.b  \"FAIL: SUB.L Dn,(An) with a borrow left X clear\",$0D",
        "f3l   equ   *-f3",
        "f4:   dc.b  \"FAIL: SUBI.L #$100,(An)+ with a borrow left X clear\",$0D",
        "f4l   equ   *-f4",
        "f5:   dc.b  \"FAIL: SUBQ.L #1,(An) with no borrow left X set\",$0D",
        "f5l   equ   *-f5",
        "f6:   dc.b  \"FAIL: NBCD of 1 with a borrow left X clear\",$0D",
        "f6l   equ   *-f6",
        "mall: dc.b  \"ALL SEVEN X-FLAG CASES HOLD\",$0D",
        "malll equ   *-mall",
        "",
        "  ends",
        ""
    ].joined(separator: "\r")

    let asmPath = scratchDisk + "/xflgtst.a"
    try? xflagAsm.write(toFile: asmPath, atomically: true, encoding: .utf8)

    let name = "cpu: NEG, SUB and NBCD leave X equal to C"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let out = os9([
            "load /dd/CMDS/r68 /dd/CMDS/l68",
            "r68 /h5/xflgtst.a -o=/h5/xflgtst.r",
            "l68 /h5/xflgtst.r -o=/h5/xflgtst",
            "/h5/xflgtst"
        ], timeout: 30)
        if out.contains("ALL SEVEN X-FLAG CASES HOLD") && !out.contains("FAIL:") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            print("      [every case must leave X equal to the carry it produced]")
            // OS-9 ends lines with CR, and the shell's prompt can lead the first
            // one, so a prefix match on LF-split lines found nothing to show.
            let preview = out.split(whereSeparator: \.isNewline)
                .filter { $0.contains("FAIL:") || $0.contains("Error") }
                .prefix(8).joined(separator: " | ")
            print("      output: \(preview)")
            failed += 1
        }
    }

    for leftover in ["xflgtst.a", "xflgtst.r", "xflgtst"] {
        try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
    }
}

// ── F$STrap: exception-handler dispatch across a run of vectors ───────────────
// Regression for the BASIC09 REAL/0 crash family.  Installs ONE F$STrap handler
// over vectors 4/5/6/7 and fires illegal / zero-divide / CHK / TRAPV in turn,
// re-entering the handler each time.  Guards the whole set of fixes: the
// init-table byte-swap (little-endian handler install), the handler-offset base
// (itab+2), A7=A5 handler entry, and the handled-exception dump gating.  Before
// those, a caught arithmetic trap crashed or hung the process instead of
// reaching its handler.  Tools are preloaded (memory-resident) so they fork by
// name without a chx into /dd/CMDS.
do {
    let strapAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "",
        "F$Exit   equ  $06",
        "F$STrap  equ  $0E",
        "I$WritLn equ  $8C",
        "",
        "  psect strptst,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,512,start",
        "",
        "start:",
        "  lea     itab(pc),a1",
        "  suba.l  a0,a0",
        "  OS9     F$STrap",
        "  ori.b   #2,ccr",
        "  trapv",
        "t6:",
        "  moveq   #-1,d0",
        "  chk     #0,d0",
        "t5:",
        "  moveq   #1,d0",
        "  divu    #0,d0",
        "t4:",
        "  dc.w    $4AFC",
        "tdone:",
        "  lea     mdone(pc),a0",
        "  moveq   #mdonel,d1",
        "  moveq   #1,d0",
        "  OS9     I$WritLn",
        "  moveq   #0,d1",
        "  OS9     F$Exit",
        "itab:",
        "  dc.w    $0010",
        "  dc.w    handler-p4",
        "p4:",
        "  dc.w    $0014",
        "  dc.w    handler-p5",
        "p5:",
        "  dc.w    $0018",
        "  dc.w    handler-p6",
        "p6:",
        "  dc.w    $001C",
        "  dc.w    handler-p7",
        "p7:",
        "  dc.w    $FFFF",
        "handler:",
        "  move.l  a1,a7",
        "  move.w  d7,d0",
        "  cmpi.w  #$1C,d0",
        "  beq     h7",
        "  cmpi.w  #$18,d0",
        "  beq     h6",
        "  cmpi.w  #$14,d0",
        "  beq     h5",
        "  cmpi.w  #$10,d0",
        "  beq     h4",
        "  bra     tdone",
        "h7:",
        "  lea     m7(pc),a0",
        "  moveq   #m7l,d1",
        "  bsr     wr",
        "  bra     t6",
        "h6:",
        "  lea     m6(pc),a0",
        "  moveq   #m6l,d1",
        "  bsr     wr",
        "  bra     t5",
        "h5:",
        "  lea     m5(pc),a0",
        "  moveq   #m5l,d1",
        "  bsr     wr",
        "  bra     t4",
        "h4:",
        "  lea     m4(pc),a0",
        "  moveq   #m4l,d1",
        "  bsr     wr",
        "  bra     tdone",
        "wr:",
        "  moveq   #1,d0",
        "  OS9     I$WritLn",
        "  rts",
        "m7:  dc.b  \"vector 7 (TRAPV) handler reached\",$0D",
        "m7l  equ   *-m7",
        "m6:  dc.b  \"vector 6 (CHK) handler reached\",$0D",
        "m6l  equ   *-m6",
        "m5:  dc.b  \"vector 5 (zero divide) handler reached\",$0D",
        "m5l  equ   *-m5",
        "m4:  dc.b  \"vector 4 (illegal) handler reached\",$0D",
        "m4l  equ   *-m4",
        "mdone: dc.b \"ALL FOUR EXCEPTION HANDLERS REACHED\",$0D",
        "mdonel equ  *-mdone",
        "",
        "  ends",
        ""
    ].joined(separator: "\r")

    let asmPath = scratchDisk + "/strptst.a"
    try? strapAsm.write(toFile: asmPath, atomically: true, encoding: .utf8)

    let name = "f$strap: one handler catches four exceptions in a row (TRAPV/CHK/div0/illegal)"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let out = os9([
            "load /dd/CMDS/r68 /dd/CMDS/l68",
            "r68 /h5/strptst.a -o=/h5/strptst.r",
            "l68 /h5/strptst.r -o=/h5/strptst",
            "/h5/strptst"
        ], timeout: 30)
        let reached = out.contains("vector 7 (TRAPV) handler reached")
            && out.contains("vector 6 (CHK) handler reached")
            && out.contains("vector 5 (zero divide) handler reached")
            && out.contains("vector 4 (illegal) handler reached")
            && out.contains("ALL FOUR EXCEPTION HANDLERS REACHED")
        if reached {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            print("      [each of the four vectors must reach the handler]")
            let preview = out.split(separator: "\n")
                .filter { !$0.hasPrefix("#") && $0 != "$" && !$0.isEmpty }
                .prefix(8).joined(separator: " | ")
            print("      output: \(preview)")
            failed += 1
        }
    }

    for leftover in ["strptst.a", "strptst.r", "strptst"] {
        try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
    }
}

// ── F$STrap: a handler that RESUMES the interrupted program (not just diverts) ──
// The sibling test above only exercises handlers that abandon the faulting flow.
// This one exercises the resume-in-place path: the handler restores the saved
// register block and returns to the interrupted code via R$pc, and the program
// runs on to a normal exit.  Regression for the spurious `oldpc+2` that os9exec
// added to R$pc on the UAE path (os9_uae.c): +2 landed R$pc two bytes past the
// real per-exception PC -- mid-instruction -- so any resuming handler ran garbage.
// Covers both PC conventions UAE hands us: TRAPV leaves R$pc at the NEXT
// instruction (the op pre-advances), so the handler resumes directly; DIVU/CHK
// leave R$pc AT the faulting instruction, so the handler must step R$pc past it
// (here +4, the width of `divu #0,dn`) to skip the divide.  The register block is
// D0-D7 / A0-A6 / callers-A7($3C) / SR($40) / PC($42), and the handler resumes in
// USER state (RTE is privileged) by pushing R$pc onto the caller's own stack and
// RTS'ing to it.
do {
    let resumeAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "",
        "F$Exit   equ  $06",
        "F$STrap  equ  $0E",
        "I$WritLn equ  $8C",
        "",
        "  psect rsmtst,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,512,start",
        "",
        "start:",
        "  lea     itab(pc),a1",
        "  suba.l  a0,a0",
        "  OS9     F$STrap",
        "  ori.b   #2,ccr",
        "  trapv",                          // vector 7: R$pc already = next insn
        "  lea     m7(pc),a0",
        "  moveq   #m7l,d1",
        "  moveq   #1,d0",
        "  OS9     I$WritLn",
        "  moveq   #1,d0",
        "  divu    #0,d0",                  // vector 5: R$pc = this insn; handler steps it
        "  lea     m5(pc),a0",
        "  moveq   #m5l,d1",
        "  moveq   #1,d0",
        "  OS9     I$WritLn",
        "  moveq   #0,d1",
        "  OS9     F$Exit",
        "itab:",
        "  dc.w    $001C",                  // vector 7 (TRAPV)
        "  dc.w    handler-p7",
        "p7:",
        "  dc.w    $0014",                  // vector 5 (zero divide)
        "  dc.w    handler-p5",
        "p5:",
        "  dc.w    $FFFF",
        "handler:",
        "  cmpi.w  #$14,d7",               // zero-divide? R$pc points AT the divu
        "  bne     hgo",
        "  addq.l  #4,$42(a7)",            //   step R$pc past the 4-byte divu
        "hgo:",
        "  move.l  $42(a7),-(a1)",         // push R$pc onto caller's own stack
        "  move.l  a1,$3C(a7)",            // record the new caller SP in the block
        "  movem.l (a7)+,d0-d7/a0-a6",     // restore the interrupted registers
        "  movea.l (a7),a7",               // A7 = caller SP (points at pushed R$pc)
        "  rts",                           // resume the interrupted program
        "m7:  dc.b  \"RESUMED PAST TRAPV\",$0D",
        "m7l  equ   *-m7",
        "m5:  dc.b  \"RESUMED PAST DIVU0\",$0D",
        "m5l  equ   *-m5",
        "",
        "  ends",
        ""
    ].joined(separator: "\r")

    let asmPath = scratchDisk + "/rsmtst.a"
    try? resumeAsm.write(toFile: asmPath, atomically: true, encoding: .utf8)

    let name = "f$strap: a handler resumes the interrupted program (TRAPV next-pc + div0 step-pc)"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let out = os9([
            "load /dd/CMDS/r68 /dd/CMDS/l68",
            "r68 /h5/rsmtst.a -o=/h5/rsmtst.r",
            "l68 /h5/rsmtst.r -o=/h5/rsmtst",
            "/h5/rsmtst"
        ], timeout: 30)
        let reached = out.contains("RESUMED PAST TRAPV")
            && out.contains("RESUMED PAST DIVU0")
        if reached {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            print("      [both handlers must resume past the fault, not divert or crash]")
            let preview = out.split(separator: "\n")
                .filter { !$0.hasPrefix("#") && $0 != "$" && !$0.isEmpty }
                .prefix(8).joined(separator: " | ")
            print("      output: \(preview)")
            failed += 1
        }
    }

    for leftover in ["rsmtst.a", "rsmtst.r", "rsmtst"] {
        try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
    }
}

// ── Bus error: an out-of-arena access raises a catchable 68k bus error ─────────
// The 68k RAM arena is the guest's entire address space; a wild pointer (here a
// jump to $80000000) lands outside it.  os9exec now raises a real bus error
// (vector 2) instead of silently clamping the address to the arena base -- so a
// wild access is catchable via F$STrap, exactly as on real hardware, and closes
// the last F$STrap coverage gap (vector 2 was previously unreachable from guest
// code).  The handler installs over vector 2, the program jumps to $80000000,
// and the handler must run.  An UNhandled wild access aborting with E_BUSERR is
// exercised in the wild by pwrstat (see its note above).
do {
    let busAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "",
        "F$Exit   equ  $06",
        "F$STrap  equ  $0E",
        "I$WritLn equ  $8C",
        "",
        "  psect bustst,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,512,start",
        "",
        "start:",
        "  lea     itab(pc),a1",
        "  suba.l  a0,a0",
        "  OS9     F$STrap",
        "  move.l  #$80000000,a0",       // a wild, out-of-arena address
        "  jmp     (a0)",                 // -> bus error (vector 2)
        "itab:",
        "  dc.w    $0008",                // vector 2 (bus error)
        "  dc.w    handler-p2",
        "p2:",
        "  dc.w    $FFFF",
        "handler:",
        "  move.l  a1,a7",                // run the handler on the caller stack
        "  lea     mok(pc),a0",
        "  moveq   #mokl,d1",
        "  moveq   #1,d0",
        "  OS9     I$WritLn",
        "  moveq   #0,d1",
        "  OS9     F$Exit",
        "mok:  dc.b  \"BUS ERROR (vector 2) CAUGHT\",$0D",
        "mokl  equ   *-mok",
        "",
        "  ends",
        ""
    ].joined(separator: "\r")

    let asmPath = scratchDisk + "/bustst.a"
    try? busAsm.write(toFile: asmPath, atomically: true, encoding: .utf8)

    let name = "f$strap: an out-of-arena access raises a catchable bus error (vector 2)"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let out = os9([
            "load /dd/CMDS/r68 /dd/CMDS/l68",
            "r68 /h5/bustst.a -o=/h5/bustst.r",
            "l68 /h5/bustst.r -o=/h5/bustst",
            "/h5/bustst"
        ], timeout: 30)
        if out.contains("BUS ERROR (vector 2) CAUGHT") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            print("      [the wild jump must raise a bus error the handler catches]")
            let preview = out.split(separator: "\n")
                .filter { !$0.hasPrefix("#") && $0 != "$" && !$0.isEmpty }
                .prefix(8).joined(separator: " | ")
            print("      output: \(preview)")
            failed += 1
        }
    }

    for leftover in ["bustst.a", "bustst.r", "bustst"] {
        try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
    }
}

// ── F$SigMask: the level stops at 255 ────────────────────────────────────────
// "The signal masking level is an eight bit quantity; the system takes steps to
// insure that it does not wrap around in either direction" (Microware, OS-9
// Intermediate training). os9exec counted up without limit, so after 300
// increments 255 decrements still left the process masked (found by the skills
// session). Here a signal sent to ourselves after 300 up and 255 down must reach
// the intercept handler at once.
do {
    let maskAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit equ $06", "F$Send equ $08", "F$Icpt equ $09", "F$ID equ $0C", "F$RTE equ $1E",
        "F$SigMask equ $57", "I$WritLn equ $8C",
        "  psect mcap,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start", "  vsect", "scr: ds.b 4096", "  ends",
        "start:",
        "  clr.b   scr(a6)",
        "  lea     handler(pc),a0",
        "  OS9     F$Icpt",
        "  move.w  #299,d4",
        "up:",
        "  moveq   #0,d0", "  moveq   #1,d1", "  OS9     F$SigMask", "  dbra    d4,up",
        "  move.w  #254,d4",
        "down:",
        "  moveq   #0,d0", "  moveq   #-1,d1", "  OS9     F$SigMask", "  dbra    d4,down",
        "  OS9     F$ID",
        "  move.w  #200,d1",
        "  OS9     F$Send",
        "  OS9     F$ID",               // one more call, for delivery on the way out
        "  tst.b   scr(a6)",
        "  beq.s   masked",
        "  lea     mok(pc),a0", "  moveq   #mokl,d1", "  bra.s   say",
        "masked:",
        "  lea     mbad(pc),a0", "  moveq   #mbadl,d1",
        "say:",
        "  moveq   #1,d0", "  OS9     I$WritLn",
        "  moveq   #0,d0", "  moveq   #0,d1", "  OS9     F$SigMask",
        "  moveq   #0,d1", "  OS9     F$Exit",
        "handler:",
        "  move.b  #1,scr(a6)",
        "  OS9     F$RTE",
        "mok:  dc.b  \"SIGMASK CAPPED AT 255\",$0D",
        "mokl  equ   *-mok",
        "mbad: dc.b  \"SIGMASK STILL MASKED\",$0D",
        "mbadl equ   *-mbad",
        "  ends", ""
    ].joined(separator: "\r")

    let name = "f$sigmask: the mask level stops at 255, so 255 decrements undo any number of increments"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? maskAsm.write(toFile: scratchDisk + "/mcap.a", atomically: true, encoding: .utf8)
        let out = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                       "r68 /h5/mcap.a -o=/h5/mcap.r", "l68 /h5/mcap.r -o=/h5/mcap",
                       "/h5/mcap"], timeout: 30)
        if out.contains("SIGMASK CAPPED AT 255") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = out.split(whereSeparator: \.isNewline).filter { $0.contains("SIGMASK") || $0.contains("Error") }
            print("      saw: \(seen.joined(separator: " | "))")
            failed += 1
        }
        for leftover in ["mcap.a", "mcap.r", "mcap"] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
        }
    }
}

// ── a pty pair name too long for a path's name is refused ─────────────────────
// A /pty open copied its name into the path's 29-byte name, and then into a
// 29-byte buffer on os9exec's own stack. "/pty1" followed by 60 more letters
// is still a pty path by its prefix, and overran both. Found by review.
do {
    let ptyAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit equ $06", "I$Open equ $84", "I$WritLn equ $8C",
        "  psect mptyl,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  lea pname(pc),a0", "  moveq #3,d0", "  OS9 I$Open", "  bcc.s wrong",
        "  cmpi.w #215,d1", "  bne.s wrong",
        "  lea mok(pc),a0", "  moveq #mokl,d1", "  bra.s say",
        "wrong:", "  lea mbad(pc),a0", "  moveq #mbadl,d1",
        "say:", "  moveq #1,d0", "  OS9 I$WritLn", "  moveq #0,d1", "  OS9 F$Exit",
        "pname: dc.b \"/pty1" + String(repeating: "a", count: 60) + "\",0",
        "mok:  dc.b \"LONG PTY NAME REFUSED\",$0D", "mokl equ *-mok",
        "mbad: dc.b \"LONG PTY NAME ACCEPTED\",$0D", "mbadl equ *-mbad",
        "  ends", ""
    ].joined(separator: "\r")

    let name = "pty: a pair name too long for a path is refused, not copied past its end"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? ptyAsm.write(toFile: scratchDisk + "/mptyl.a", atomically: true, encoding: .utf8)
        let out = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                       "r68 /h5/mptyl.a -o=/h5/mptyl.r", "l68 /h5/mptyl.r -o=/h5/mptyl",
                       "/h5/mptyl"], timeout: 30)
        if out.contains("LONG PTY NAME REFUSED") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = out.split(whereSeparator: \.isNewline).filter { $0.contains("PTY") || $0.contains("Error") }
            print("      saw: \(seen.joined(separator: " | "))")
            failed += 1
        }
        for leftover in ["mptyl.a", "mptyl.r", "mptyl"] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
        }
    }
}

// ── F$Alarm: an absolute alarm dated decades ago is sent at once ─────────────
// A date in the past is already due. For one far enough back the day count
// times 86400 overflowed 32 bits, undefined in C, and came out as an alarm
// weeks in the future. Julian day 0, a signal to our own intercept routine,
// and a short sleep: the signal must have arrived. Found by review.
do {
    let pastAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit equ $06", "F$Icpt equ $09", "F$Sleep equ $0A", "F$RTE equ $1E", "F$Alarm equ $56",
        "I$WritLn equ $8C",
        "  psect mpast,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,512,start", "  vsect", "scr: ds.b 4096", "  ends",
        "start:",
        "  clr.b scr(a6)", "  lea handler(pc),a0", "  OS9 F$Icpt",
        "  moveq #0,d0", "  move.w #4,d1", "  move.w #200,d2", "  moveq #0,d3", "  moveq #0,d4",
        "  OS9 F$Alarm", "  bcs.s fail",
        "  moveq #20,d0", "  OS9 F$Sleep",              // a fifth of a second is plenty
        "  tst.b scr(a6)", "  beq.s notyet",
        "  lea mok(pc),a0", "  moveq #mokl,d1", "  bra.s say",
        "notyet:", "  lea mbad(pc),a0", "  moveq #mbadl,d1",
        "say:", "  moveq #1,d0", "  OS9 I$WritLn", "  moveq #0,d1",
        "fail:", "  OS9 F$Exit",
        "handler:", "  move.b #1,scr(a6)", "  OS9 F$RTE",
        "mok: dc.b \"PAST ALARM WAS SENT AT ONCE\",$0D", "mokl equ *-mok",
        "mbad: dc.b \"PAST ALARM NOT SENT\",$0D", "mbadl equ *-mbad",
        "  ends", ""
    ].joined(separator: "\r")

    let name = "f$alarm: an A$AtJul alarm for Julian day 0 is sent at once, not weeks later"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? pastAsm.write(toFile: scratchDisk + "/mpast.a", atomically: true, encoding: .utf8)
        _ = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                 "r68 /h5/mpast.a -o=/h5/mpast.r", "l68 /h5/mpast.r -o=/h5/mpast"], timeout: 60)
        let out = os9(["/h5/mpast"], timeout: 15)
        if out.contains("PAST ALARM WAS SENT AT ONCE") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = out.split(whereSeparator: \.isNewline).filter { $0.contains("ALARM") || $0.contains("Error") }
            print("      saw: \(seen.joined(separator: " | "))")
            failed += 1
        }
        for leftover in ["mpast.a", "mpast.r", "mpast"] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
        }
    }
}

// ── F$SetSys: os9exec's note about an unknown offset is not the program's output ─
// An offset os9exec does not know answers 0, and says so -- but it said so with
// upe_printf, which writes to the CALLING PROGRAM's stderr path. The program's
// stderr is redirected to a file here (">>"), and that file must stay empty.
// Found by review.
do {
    let ssAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit equ $06", "F$SetSys equ $27",
        "  psect mssq,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,512,start",
        "start:",
        "  move.w #$7FF0,d0", "  move.l #$80000004,d1", "  OS9 F$SetSys",
        "  moveq #0,d1", "  OS9 F$Exit",
        "  ends", ""
    ].joined(separator: "\r")

    let name = "f$setsys: the note about an unknown offset stays out of the program's stderr"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? ssAsm.write(toFile: scratchDisk + "/mssq.a", atomically: true, encoding: .utf8)
        try? FileManager.default.removeItem(atPath: scratchDisk + "/mssq.err")
        _ = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                 "r68 /h5/mssq.a -o=/h5/mssq.r", "l68 /h5/mssq.r -o=/h5/mssq"], timeout: 60)
        _ = os9(["/h5/mssq >>/h5/mssq.err"], timeout: 20)
        let err = (try? String(contentsOfFile: scratchDisk + "/mssq.err", encoding: .isoLatin1)) ?? "<none>"
        if err.isEmpty {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            print("      program's stderr: \(err.debugDescription.prefix(120))")
            failed += 1
        }
        for leftover in ["mssq.a", "mssq.r", "mssq", "mssq.err"] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
        }
    }
}

// ── os9exec does not end while a waiting process has an alarm to come ────────
// os9exec ends once the launch process is gone and every process left is only
// waiting for input. A process with an alarm armed is not only waiting: the
// alarm is how a program aborts its own wait. Here a background child blocks
// reading an empty pipe with an alarm 30 ticks away whose handler writes a
// marker file; the shell exits at once. Found by review.
do {
    let alarmAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit equ $06", "F$Icpt equ $09", "F$Alarm equ $56", "I$Dup equ $82", "I$Create equ $83",
        "I$Open equ $84", "I$ReadLn equ $8B", "I$Close equ $8F",
        "  psect mawait,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start", "  vsect", "scr: ds.b 4096", "  ends",
        "start:",
        "  lea handler(pc),a0", "  OS9 F$Icpt",
        "  moveq #0,d0", "  moveq #1,d1", "  move.w #200,d2", "  moveq #30,d3", "  OS9 F$Alarm",
        "  lea pipe(pc),a0", "  moveq #3,d0", "  OS9 I$Open", "  bcs.s fail",
        "  move.w d0,d7", "  OS9 I$Dup",                             // a second holder: a writer
        "  move.w d7,d0", "  lea scr(a6),a0", "  moveq #32,d1", "  OS9 I$ReadLn",  // nobody writes: parked
        "  moveq #0,d1",
        "fail:", "  OS9 F$Exit",
        "handler:",
        "  lea mark(pc),a0", "  moveq #3,d0", "  moveq #3,d1", "  OS9 I$Create", "  bcs.s out",
        "  OS9 I$Close",
        "out:", "  moveq #0,d1", "  OS9 F$Exit",
        "pipe: dc.b \"/pipe\",0", "mark: dc.b \"/h5/alarmmark\",0",
        "  ends", ""
    ].joined(separator: "\r")

    let name = "shutdown: os9exec waits for an alarm a parked process has armed"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? alarmAsm.write(toFile: scratchDisk + "/mawait.a", atomically: true, encoding: .utf8)
        try? FileManager.default.removeItem(atPath: scratchDisk + "/alarmmark")
        _ = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                 "r68 /h5/mawait.a -o=/h5/mawait.r", "l68 /h5/mawait.r -o=/h5/mawait"], timeout: 60)
        _ = os9(["/h5/mawait &"], timeout: 20)
        let marked = FileManager.default.fileExists(atPath: scratchDisk + "/alarmmark")
        if marked {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            print("      the alarm's handler never ran: os9exec ended first")
            failed += 1
        }
        for leftover in ["mawait.a", "mawait.r", "mawait", "alarmmark"] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
        }
    }
}

// ── F$RTE: an intercept that waits on a pipe of its own ──────────────────────
// A read parks on an empty pipe; a signal's handler then waits on a second
// pipe (a named one, fed a second later by msigw) and returns. F$RTE has
// to go back to the FIRST read. It went back to the handler's instead -- the
// parked request was remembered by state alone, and the handler's wait had
// overwritten which request that was -- so the program's own read came back
// E$EOF off a pipe it never read. Here a second alarm, below 32, cuts the
// right read short with the signal as its error (found by the pre-release
// kernel review). Writing this test found the handler's wait froze the whole
// emulator first: a masked process parked on a pipe never gave up the CPU.
do {
    let nestAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit equ $06", "F$Icpt equ $09", "F$RTE equ $1E", "F$Alarm equ $56", "I$Dup equ $82",
        "I$Create equ $83", "I$Open equ $84", "I$ReadLn equ $8B", "I$WritLn equ $8C",
        "  psect msigp,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start", "  vsect", "scr: ds.b 256", "  ends",
        "start:",
        "  lea handler(pc),a0", "  OS9 F$Icpt",
        "  moveq #0,d0", "  moveq #1,d1", "  move.w #200,d2", "  moveq #30,d3", "  OS9 F$Alarm",
        "  moveq #0,d0", "  moveq #1,d1", "  moveq #2,d2", "  move.w #500,d3", "  OS9 F$Alarm",
        "  lea pipe(pc),a0", "  moveq #3,d0", "  OS9 I$Open", "  bcs.s fail",
        "  move.w d0,d7", "  OS9 I$Dup",                             // a second holder: a writer
        "  move.w d7,d0", "  lea scr(a6),a0", "  moveq #32,d1", "  OS9 I$ReadLn",  // parked on pipe A
        "  bcc.s wrong", "  cmpi.w #2,d1", "  bne.s wrong",
        "  lea right(pc),a0", "  bra.s say",
        "wrong:", "  lea bad(pc),a0",
        "say:", "  moveq #1,d0", "  moveq #64,d1", "  OS9 I$WritLn",
        "  moveq #0,d1",
        "fail:", "  OS9 F$Exit",
        "handler:",
        "  cmpi.w #200,d1", "  bne.s back",                           // the second alarm: nothing to do
        "  lea named(pc),a0", "  moveq #3,d0", "  moveq #3,d1", "  OS9 I$Create", "  bcs.s back",
        "  move.w d0,d6", "  OS9 I$Dup",                             // held open: a real wait
        "  move.w d6,d0", "  lea scr+128(a6),a0", "  moveq #32,d1", "  OS9 I$ReadLn",  // parked on pipe B
        "back:", "  OS9 F$RTE",
        "pipe: dc.b \"/pipe\",0", "named: dc.b \"/pipe/sigb\",0",
        "right: dc.b \"THE PARKED READ WAS THE ONE CUT SHORT\",13",
        "bad: dc.b \"ANOTHER REQUEST CAME BACK\",13",
        "  ends", ""
    ].joined(separator: "\r")
    // the feeder: a named pipe that exists is OPENED (creating it again is E$CEF, so the shell's > cannot)
    let feedAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit equ $06", "I$Open equ $84", "I$WritLn equ $8C",
        "  psect msigw,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  lea named(pc),a0", "  moveq #2,d0", "  OS9 I$Open", "  bcs.s fail",
        "  lea line(pc),a0", "  moveq #3,d1", "  OS9 I$WritLn", "  bcs.s fail",
        "  moveq #0,d1",
        "fail:", "  OS9 F$Exit",
        "named: dc.b \"/pipe/sigb\",0", "line: dc.b \"hi\",13",
        "  ends", ""
    ].joined(separator: "\r")

    let name = "signal: F$RTE goes back to the read the signal found, not the handler's own pipe wait"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? nestAsm.write(toFile: scratchDisk + "/msigp.a", atomically: true, encoding: .utf8)
        try? feedAsm.write(toFile: scratchDisk + "/msigw.a", atomically: true, encoding: .utf8)
        _ = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                 "r68 /h5/msigp.a -o=/h5/msigp.r", "l68 /h5/msigp.r -o=/h5/msigp",
                 "r68 /h5/msigw.a -o=/h5/msigw.r", "l68 /h5/msigw.r -o=/h5/msigw"], timeout: 60)
        let output = os9(["/h5/msigp &", "sleep -s 1", "/h5/msigw", "sleep -s 6"], timeout: 30)
        if output.contains("THE PARKED READ WAS THE ONE CUT SHORT") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            print("      output: \(output.suffix(300))")
            failed += 1
        }
        for leftover in ["msigp.a", "msigp.r", "msigp", "msigw.a", "msigw.r", "msigw"] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
        }
    }
}

// ── a signal ends a write parked on the terminal, with the signal as its error ─
// "Signal values less than 32 usually cause the current I/O operation to
// terminate with an error status equal to the signal value" (F$Send). F$RTE did
// that for a parked read and a pipe request, but a write parked on a paced
// terminal (pWaitWrite) was simply made active: its I$Write came back carry
// clear, with whatever count it had reached (found by the pre-release
// character-I/O review).
do {
    let parkAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit equ $06", "F$Icpt equ $09", "F$RTE equ $1E", "F$Alarm equ $56", "I$Write equ $8A",
        "I$WritLn equ $8C", "F$SRqMem equ $28",
        "  psect mwsig,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  lea handler(pc),a0", "  OS9 F$Icpt",
        "  move.l #8000,d0", "  OS9 F$SRqMem", "  bcs.w fail", "  movea.l a2,a3",
        "  move.w #7999,d2",
        "fill:", "  move.b #'x',(a2)+", "  dbra d2,fill",
        "  moveq #0,d0", "  moveq #1,d1", "  moveq #2,d2", "  moveq #20,d3", "  OS9 F$Alarm",
        "  movea.l a3,a0", "  moveq #1,d0", "  move.l #8000,d1", "  OS9 I$Write",
        "  bcc.s nocarry", "  cmpi.w #2,d1", "  bne.s other",
        "  lea sigm(pc),a0", "  bra.s tell",
        "nocarry:", "  cmpi.l #8000,d1", "  beq.s whole", "  lea shortm(pc),a0", "  bra.s tell",
        "whole:", "  lea wholem(pc),a0", "  bra.s tell",
        "other:", "  lea otherm(pc),a0",
        "tell:", "  moveq #2,d0", "  moveq #64,d1", "  OS9 I$WritLn",
        "  moveq #0,d1",
        "fail:", "  OS9 F$Exit",
        "handler:", "  OS9 F$RTE",
        "sigm: dc.b \"WRITE ENDED BY THE SIGNAL\",13",
        "shortm: dc.b \"WRITE RETURNED SHORT WITHOUT AN ERROR\",13",
        "wholem: dc.b \"WRITE COMPLETED BEFORE THE SIGNAL\",13",
        "otherm: dc.b \"WRITE ENDED WITH ANOTHER ERROR\",13",
        "  ends", ""
    ].joined(separator: "\r")

    let name = "signal: a write parked on a paced terminal ends with the signal as its error"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? parkAsm.write(toFile: scratchDisk + "/mwsig.a", atomically: true, encoding: .utf8)
        _ = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                 "r68 /h5/mwsig.a -o=/h5/mwsig.r", "l68 /h5/mwsig.r -o=/h5/mwsig"], timeout: 60)
        let output = os9(["/h5/mwsig"], timeout: 60, paced: true)
        if output.contains("WRITE ENDED BY THE SIGNAL") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = output.split(whereSeparator: \.isNewline).filter { $0.contains("WRITE") }
            print("      saw: \(seen)")
            failed += 1
        }
        for leftover in ["mwsig.a", "mwsig.r", "mwsig"] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
        }
    }
}

// ── a line with the most padding SCF allows still goes out when paced ─────────
// PD_NUL asks for up to 255 NULs after each CR. With its auto-LF that is 257
// bytes queued as one unit, and the paced output queue held 256: the write
// waited for room that could never exist (found by the pre-release review).
// Set through SS_Opt, as `tmode null=` cannot store 255.
do {
    let nulAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit equ $06", "I$GetStt equ $8D", "I$SetStt equ $8E", "I$WritLn equ $8C",
        "  psect mnul,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "  vsect", "opt: ds.b 128", "  ends",
        "start:",
        "  moveq #1,d0", "  moveq #0,d1", "  lea opt(a6),a0", "  OS9 I$GetStt", "  bcs.s fail",
        "  move.b #255,opt+6(a6)", "  move.b #1,opt+5(a6)",         // PD_NUL 255, PD_ALF on
        "  moveq #1,d0", "  moveq #0,d1", "  lea opt(a6),a0", "  OS9 I$SetStt", "  bcs.s fail",
        "  lea line(pc),a0", "  moveq #1,d0", "  moveq #3,d1", "  OS9 I$WritLn", "  bcs.s fail",
        "  clr.b opt+6(a6)",
        "  moveq #1,d0", "  moveq #0,d1", "  lea opt(a6),a0", "  OS9 I$SetStt",
        "  lea done(pc),a0", "  moveq #2,d0", "  moveq #40,d1", "  OS9 I$WritLn",
        "  moveq #0,d1",
        "fail:", "  OS9 F$Exit",
        "line: dc.b \"HI\",13",
        "done: dc.b \"PADDED LINE WRITTEN\",13",
        "  ends", ""
    ].joined(separator: "\r")

    let name = "console: a paced line padded with 255 NULs is written, not held for ever"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? nulAsm.write(toFile: scratchDisk + "/mnul.a", atomically: true, encoding: .utf8)
        _ = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                 "r68 /h5/mnul.a -o=/h5/mnul.r", "l68 /h5/mnul.r -o=/h5/mnul"], timeout: 60)
        let output = os9(["/h5/mnul"], timeout: 30, paced: true)
        if output.contains("PADDED LINE WRITTEN") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            print("      output: \(output.suffix(160))")
            failed += 1
        }
        for leftover in ["mnul.a", "mnul.r", "mnul"] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
        }
    }
}

// ── rbf: a path created on an image reports the new file's attributes ────────
// The path kept the attributes of the directory searched to reach the new
// file, so SS_Opt's PD_ATT on a freshly created file answered the directory's
// (directory bit included), and single-user sharing was judged by them too
// (found by the pre-release RBF review).
do {
    let attAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit equ $06", "I$Create equ $83", "I$Delete equ $87", "I$GetStt equ $8D",
        "I$WritLn equ $8C", "I$Close equ $8F",
        "  psect mratt,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "  vsect", "opt: ds.b 128", "  ends",
        "start:",
        "  lea fname(pc),a0", "  moveq #2,d0", "  OS9 I$Delete",
        "  lea fname(pc),a0", "  moveq #3,d0", "  moveq #3,d1", "  OS9 I$Create", "  bcs.s fail",
        "  move.w d0,d7",
        "  moveq #0,d1", "  lea opt(a6),a0", "  OS9 I$GetStt", "  bcs.s fail",
        "  move.w d7,d0", "  OS9 I$Close",
        "  cmpi.b #3,opt+$35(a6)", "  bne.s wrong",
        "  lea filem(pc),a0", "  bra.s tell",
        "wrong:", "  lea dirm(pc),a0",
        "tell:", "  moveq #1,d0", "  moveq #40,d1", "  OS9 I$WritLn",
        "  moveq #0,d1",
        "fail:", "  OS9 F$Exit",
        "fname: dc.b \"/h9/attfile\",0",
        "filem: dc.b \"ATTRIBUTES ARE THE NEW FILE'S\",13",
        "dirm: dc.b \"ATTRIBUTES ARE NOT THE NEW FILE'S\",13",
        "  ends", ""
    ].joined(separator: "\r")

    let name = "rbf: a file just created on an image reports its own attributes in SS_Opt"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? attAsm.write(toFile: scratchDisk + "/mratt.a", atomically: true, encoding: .utf8)
        _ = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                 "r68 /h5/mratt.a -o=/h5/mratt.r", "l68 /h5/mratt.r -o=/h5/mratt"], timeout: 60)
        let output = os9(["mount -k=300K \(scratchDevice)", "/h5/mratt"], timeout: 60)
        if output.contains("ATTRIBUTES ARE THE NEW FILE'S") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = output.split(whereSeparator: \.isNewline)
                .filter { $0.contains("ATTRIBUTES") || $0.contains("Error") }
            print("      saw: \(seen)")
            failed += 1
        }
        for leftover in ["mratt.a", "mratt.r", "mratt"] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
        }
    }
}

// ── scf: I$WritLn to a terminal ends the record on its PD_EOR, not a CR ──────
// I$WritLn cut every record at the first CR before the file manager saw it, so
// after `tmode eor=0A` a record ending in LF was split at a CR inside it. The
// terminal ends a record on PD_EOR; disk files and pipes still end on CR
// (found by the pre-release character-I/O review).
do {
    let eorAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit equ $06", "I$WritLn equ $8C",
        "  psect mweor,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  lea rec(pc),a0", "  moveq #1,d0", "  moveq #6,d1", "  OS9 I$WritLn", "  bcs.s fail",
        "  cmpi.l #6,d1", "  bne.s cut",
        "  lea wholem(pc),a0", "  bra.s tell",
        "cut:", "  lea cutm(pc),a0",
        "tell:", "  moveq #2,d0", "  moveq #40,d1", "  OS9 I$WritLn",
        "  moveq #0,d1",
        "fail:", "  OS9 F$Exit",
        "rec: dc.b \"AB\",13,\"CD\",10",
        "wholem: dc.b \"THE WHOLE RECORD WAS WRITTEN\",10",
        "cutm: dc.b \"THE RECORD WAS CUT AT ITS CR\",10",
        "  ends", ""
    ].joined(separator: "\r")

    let name = "scf: I$WritLn to a terminal with eor=0A writes a record through an embedded CR"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? eorAsm.write(toFile: scratchDisk + "/mweor.a", atomically: true, encoding: .utf8)
        _ = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                 "r68 /h5/mweor.a -o=/h5/mweor.r", "l68 /h5/mweor.r -o=/h5/mweor"], timeout: 60)
        let output = os9(["tmode eor=0A", "/h5/mweor", "tmode eor=0D"], timeout: 60)
        if output.contains("THE WHOLE RECORD WAS WRITTEN") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = output.split(whereSeparator: \.isNewline).filter { $0.contains("RECORD") }
            print("      saw: \(seen)")
            failed += 1
        }
        for leftover in ["mweor.a", "mweor.r", "mweor"] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
        }
    }
}

// ── F$Fork and F$Load need the read permission F$Link needs ──────────────────
// "If the module's access word does not give the process read permission, the
// link call fails" (F$Link) -- and F$Fork ("the module is linked and executed")
// and F$Load ("the first module read is linked") end in that link. Only F$Link
// looked, so a program readable only by its owner ran for anyone (found by the
// freeware session's M$Accs scan: TOP's mmon is owner-only). The module here is
// user 1.1's, owner-read only; user 5.5 may neither run it nor load it, and the
// same module opened to everyone still runs.
do {
    let target = [
        "  use /dd/DEFS/oskdefs.d", "F$Exit equ $06",
        "  psect mpriv,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:", "  moveq #0,d1", "  OS9 F$Exit", "  ends", ""
    ].joined(separator: "\r")
    let caller = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit equ $06", "F$Fork equ $03", "F$Wait equ $04", "F$Load equ $01", "F$SUser equ $1C",
        "I$WritLn equ $8C",
        "  psect mprun,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  move.l #$00050005,d1", "  OS9 F$SUser", "  bcs.w fail",
        "  lea pname(pc),a0", "  lea cparm(pc),a1", "  moveq #0,d0", "  moveq #1,d1", "  moveq #0,d2",
        "  moveq #3,d3", "  moveq #0,d4", "  OS9 F$Fork",
        "  bcc.s forked", "  cmpi.w #164,d1", "  bne.s fother",
        "  lea frefm(pc),a0", "  bsr.s say", "  bra.s load",
        "forked:", "  OS9 F$Wait", "  lea fokm(pc),a0", "  bsr.s say", "  bra.s load",
        "fother:", "  lea fothm(pc),a0", "  bsr.s say",
        "load:", "  lea pname(pc),a0", "  moveq #0,d0", "  OS9 F$Load",
        "  bcc.s loaded", "  cmpi.w #164,d1", "  bne.s lother",
        "  lea lrefm(pc),a0", "  bsr.s say", "  bra.s out",
        "loaded:", "  lea lokm(pc),a0", "  bsr.s say", "  bra.s out",
        "lother:", "  lea lothm(pc),a0", "  bsr.s say",
        "out:", "  moveq #0,d1",
        "fail:", "  OS9 F$Exit",
        "say:", "  moveq #1,d0", "  moveq #40,d1", "  OS9 I$WritLn", "  rts",
        "pname: dc.b \"/h5/mpriv\",0", "cparm: dc.b 13",
        "frefm: dc.b \"FORK REFUSED 164\",13", "fokm: dc.b \"FORK RAN\",13",
        "fothm: dc.b \"FORK OTHER ERROR\",13",
        "lrefm: dc.b \"LOAD REFUSED 164\",13", "lokm: dc.b \"LOAD ALLOWED\",13",
        "lothm: dc.b \"LOAD OTHER ERROR\",13",
        "  ends", ""
    ].joined(separator: "\r")

    let name = "module: F$Fork and F$Load refuse a module the caller has no read permission for"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? target.write(toFile: scratchDisk + "/mpriv.a", atomically: true, encoding: .utf8)
        try? caller.write(toFile: scratchDisk + "/mprun.a", atomically: true, encoding: .utf8)
        _ = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                 "r68 /h5/mpriv.a -o=/h5/mpriv.r", "l68 /h5/mpriv.r -o=/h5/mpriv",
                 "r68 /h5/mprun.a -o=/h5/mprun.r", "l68 /h5/mprun.r -o=/h5/mprun"], timeout: 60)
        let closed = os9(["fixmod -uo=1.1 -up=005 /h5/mpriv", "/h5/mprun"], timeout: 60)
        let opened = os9(["fixmod -uo=1.1 -up=555 /h5/mpriv", "/h5/mprun"], timeout: 60)
        let refused = closed.contains("FORK REFUSED 164") && closed.contains("LOAD REFUSED 164")
        let allowed = opened.contains("FORK RAN") && opened.contains("LOAD ALLOWED")
        if refused && allowed {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = (closed + opened).split(whereSeparator: \.isNewline)
                .filter { $0.contains("FORK") || $0.contains("LOAD") || $0.contains("fixmod") }
            print("      owner-only refused: \(refused), opened allowed: \(allowed); saw: \(seen)")
            failed += 1
        }
        for leftover in ["mpriv.a", "mpriv.r", "mpriv", "mprun.a", "mprun.r", "mprun"] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
        }
    }
}

// ── 68881: seven readings the pre-release CPU/FPU review found wrong ─────────
// Each check leaves a digit; the line printed is the seven of them, 1 where the
// FPU gave the M68000 PRM's answer. In order: FMOVE.B #5 read the high byte of
// its extension word (gave 0); FSNGE was NAN or (Z and N) where the PRM's table
// 3-23 is NAN or (N and not Z), wrong both for -5 < 3 and for -5 = -5; FSCALE
// #3 of 1.0 gave 7.999999999999998; FINT ignored FPCR's rounding mode (2.7 gave
// 3.0 toward zero); FGETEXP of 0 gave -1, not 0; FMOD never set FPSR's quotient
// byte (7 mod 2 has quotient 3); FScc (An)+ stored at An and never moved it.
// The instructions are hand-encoded: r68 has no 68881 mnemonics.
do {
    let fpuAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit equ $06", "I$WritLn equ $8C",
        "  psect mfpu,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "  vsect", "res: ds.b 8", "buf: ds.b 4", "  ends",
        "start:",
        "  lea res(a6),a2", "  moveq #6,d0",
        "clr:", "  move.b #'0',(a2,d0.w)", "  dbra d0,clr",
        // 1: FMOVE.B #5,FP0 ; FMOVE.L FP0,D0
        "  dc.w $F23C,$5800,$0005", "  dc.w $F200,$6000",
        "  cmpi.l #5,d0", "  bne.s t2", "  move.b #'1',0(a2)",
        // 2: -5 FCMP 3 -> NGE true ; -5 FCMP -5 -> NGE false
        "t2:", "  dc.w $F23C,$4000", "  dc.l -5", "  dc.w $F23C,$4038", "  dc.l 3",
        "  dc.w $F241,$001C",
        "  dc.w $F23C,$4000", "  dc.l -5", "  dc.w $F23C,$4038", "  dc.l -5",
        "  dc.w $F242,$001C",
        "  cmpi.b #$FF,d1", "  bne.s t3", "  tst.b d2", "  bne.s t3", "  move.b #'1',1(a2)",
        // 3: 1.0 FSCALE.W #3 must be exactly 8
        "t3:", "  dc.w $F23C,$4000", "  dc.l 1", "  dc.w $F23C,$5026,$0003",
        "  dc.w $F23C,$4038", "  dc.l 8", "  dc.w $F243,$0001",
        "  cmpi.b #$FF,d3", "  bne.s t4", "  move.b #'1',2(a2)",
        // 4: FPCR round-toward-zero, FINT 2.7 must be 2
        "t4:", "  dc.w $F23C,$9000", "  dc.l $10",
        "  dc.w $F23C,$4000", "  dc.l 27", "  dc.w $F23C,$4020", "  dc.l 10", "  dc.w $F200,$0001",
        "  dc.w $F23C,$9000", "  dc.l 0",
        "  dc.w $F23C,$4038", "  dc.l 2", "  dc.w $F244,$0001",
        "  cmpi.b #$FF,d4", "  bne.s t5", "  move.b #'1',3(a2)",
        // 5: FGETEXP of 0 is 0
        "t5:", "  dc.w $F23C,$4000", "  dc.l 0", "  dc.w $F200,$009E", "  dc.w $F200,$043A",
        "  dc.w $F245,$0001",
        "  cmpi.b #$FF,d5", "  bne.s t6", "  move.b #'1',4(a2)",
        // 6: 7 FMOD 2 leaves quotient 3 in FPSR's quotient byte
        "t6:", "  dc.w $F23C,$4000", "  dc.l 7", "  dc.w $F23C,$4021", "  dc.l 2",
        "  dc.w $F206,$A800", "  swap d6", "  andi.w #$FF,d6",
        "  cmpi.w #3,d6", "  bne.s t7", "  move.b #'1',5(a2)",
        // 7: FSEQ (A0)+ moves A0 on by one
        "t7:", "  lea buf(a6),a0", "  move.l a0,d7", "  addq.l #1,d7",
        "  dc.w $F258,$0001",
        "  cmpa.l d7,a0", "  bne.s tell", "  move.b #'1',6(a2)",
        "tell:", "  move.b #13,7(a2)",
        "  movea.l a2,a0", "  moveq #1,d0", "  moveq #8,d1", "  OS9 I$WritLn",
        "  moveq #0,d1", "  OS9 F$Exit",
        "  ends", ""
    ].joined(separator: "\r")

    let name = "68881: byte immediates, NGE, FSCALE, FINT's rounding mode, FGETEXP 0, FMOD's quotient, FScc (An)+"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? fpuAsm.write(toFile: scratchDisk + "/mfpu.a", atomically: true, encoding: .utf8)
        _ = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                 "r68 /h5/mfpu.a -o=/h5/mfpu.r", "l68 /h5/mfpu.r -o=/h5/mfpu"], timeout: 60)
        let output = os9(["/h5/mfpu"], timeout: 30)
        if output.contains("1111111") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = output.split(whereSeparator: \.isNewline)
                .filter { $0.count == 7 && $0.allSatisfy { "01".contains($0) } }
            print("      digits (want 1111111): \(seen)")
            failed += 1
        }
        for leftover in ["mfpu.a", "mfpu.r", "mfpu"] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
        }
    }
}

// ── a bus error hands its F$STrap handler the flags the program had ────────────
// The CPU keeps its flags apart from SR until something asks for SR, and the
// out-of-memory bus error path never asked: the register image an F$STrap
// handler got (R$sr) carried a stale condition code (found by the pre-release
// CPU review). Here X, N and C are set ($19) just before the faulting read.
do {
    let busAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit equ $06", "F$STrap equ $0E", "I$WritLn equ $8C",
        "  psect mbusf,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  moveq #0,d0", "  movea.l d0,a0", "  lea exctbl(pc),a1", "  OS9 F$STrap", "  bcs.s fail",
        "  moveq #0,d1", "  subq.l #1,d1",                      // X, N and C set
        "  move.l $F0000000,d0",                                 // far past memory: a bus error
        "  lea nobus(pc),a0", "  bra.s tell",
        "exctbl: dc.w $08,handler-*-4", "  dc.w -1",
        "handler:", "  move.w $40(a5),d6", "  andi.w #$1F,d6", "  cmpi.w #$19,d6", "  bne.s lost",
        "  lea keptm(pc),a0", "  bra.s tell",
        "lost:", "  lea lostm(pc),a0",
        "tell:", "  moveq #1,d0", "  moveq #40,d1", "  OS9 I$WritLn",
        "  moveq #0,d1",
        "fail:", "  OS9 F$Exit",
        "keptm: dc.b \"BUS ERROR KEPT THE FLAGS\",13",
        "lostm: dc.b \"BUS ERROR LOST THE FLAGS\",13",
        "nobus: dc.b \"NO BUS ERROR\",13",
        "  ends", ""
    ].joined(separator: "\r")

    let name = "cpu: an F$STrap handler for a bus error sees the flags the program had"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? busAsm.write(toFile: scratchDisk + "/mbusf.a", atomically: true, encoding: .utf8)
        _ = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                 "r68 /h5/mbusf.a -o=/h5/mbusf.r", "l68 /h5/mbusf.r -o=/h5/mbusf"], timeout: 60)
        let output = os9(["/h5/mbusf"], timeout: 30)
        if output.contains("BUS ERROR KEPT THE FLAGS") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = output.split(whereSeparator: \.isNewline)
                .filter { $0.contains("BUS ERROR") || $0.contains("Error") }
            print("      saw: \(seen)")
            failed += 1
        }
        for leftover in ["mbusf.a", "mbusf.r", "mbusf"] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
        }
    }
}

// ── debugger: k, n and i leave the emulator whole ─────────────────────────────
// Three debugger commands the pre-release review found harmful: `k60000` wrote
// far past the process table and faulted the host; `nshell` set the trigger to
// "shel" (a CR already gone was cut again) and ran on into a register dump; a
// listing (`i`) in trace mode moved the live PC, so `g` resumed the program at
// the end of the listing and the shell died on an illegal instruction.
do {
    let name = "debugger: k<pid> past the table, n<name>, and i in trace mode leave the emulator whole"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let kill = os9(["idbg", "k60000", "g", "echo AFTER-KILL"], timeout: 30)
        let trigger = os9(["idbg", "nshell", "g"], timeout: 30)
        let listing = os9(["idbg", "t", "i1000", "g", "echo AFTER-LISTING"], timeout: 30)
        // the host fault was caught and turned into a bus error for the
        // process running idbg, so "the shell went on" alone is not enough
        let killOK = kill.contains("no such process") && !kill.contains("E_BUSERR")
        let triggerOK = trigger.contains("trigger='shell'") && !trigger.contains("trigger='shel'")
        let listingOK = listing.contains("AFTER-LISTING")
        if killOK && triggerOK && listingOK {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            print("      k60000 survived: \(killOK), trigger kept whole: \(triggerOK), listing left PC: \(listingOK)")
            failed += 1
        }
    }
}

// ── -d tracing does not starve a pipeline's terminal writer ───────────────────
// Trace lines ("narration") used to go through the paced output queue and wait
// for room in it. A pipeline's first process traces every call, so the queue
// was refilled the moment it had room, while the second process's parked
// write was retried only every thirtieth round: under -d 0x0002, `dir -e
// /dd/CMDS ! list` held list's first line back for 26 seconds, until dir was
// done. Narration now goes straight to the terminal, after whatever the program
// had queued there (consio.c, "who may write"), and list writes at once.
// Over a real pty and paced, as a person would see it.
do {
    let name = "trace: under -d, a pipeline's second process writes without waiting for the first"
    if (filter.isEmpty || name.localizedCaseInsensitiveContains(filter)) && !containerized,
       let (controller, device, _) = makePTY() {
        let process = Process()
        process.executableURL       = execURL
        process.arguments           = ["-d", "0x0002", shellArg]
        process.currentDirectoryURL = URL(fileURLWithPath: scratchDisk)
        process.environment         = ["OS9DISK": diskPath].merging(inheritedByChildren) { mine, _ in mine }
        let deviceHandle = FileHandle(fileDescriptor: device, closeOnDealloc: false)
        process.standardInput  = deviceHandle
        process.standardOutput = deviceHandle
        process.standardError  = deviceHandle
        var waited = -1.0
        if (try? process.run()) != nil {
            let marker = Array("you must specify".utf8)          // list's own first line
            var got = [UInt8]()
            var buf = [UInt8](repeating: 0, count: 65536)
            func drain(_ seconds: Double, until wanted: [UInt8]? = nil) -> Bool {
                let end = Date().addingTimeInterval(seconds)
                while Date() < end {
                    var fds = pollfd(fd: controller, events: Int16(POLLIN), revents: 0)
                    if poll(&fds, 1, 100) > 0 {
                        let count = read(controller, &buf, buf.count)
                        if count <= 0 { return false }
                        got += buf[0..<count]
                        if let wanted, got.suffix(70000).firstRange(of: wanted) != nil { return true }
                    }
                }
                return false
            }
            _ = drain(8)
            got.removeAll()
            let command = Array("dir -e /dd/CMDS ! list\n".utf8)
            let began = Date()
            _ = command.withUnsafeBufferPointer { write(controller, $0.baseAddress, command.count) }
            if drain(40, until: marker) { waited = Date().timeIntervalSince(began) }
            _ = drain(40, until: Array("\n$ ".utf8))              // let the pipeline finish
            let quit = Array("\u{1B}\n".utf8)
            _ = quit.withUnsafeBufferPointer { write(controller, $0.baseAddress, quit.count) }
            usleep(500_000)
            if process.isRunning { process.terminate() }
            process.waitUntilExit()
        }
        close(controller); close(device)
        if waited >= 0 && waited < 8 {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let took = waited < 0 ? "more than 40" : String(format: "%.1f", waited)
            print("      list's first line after \(took) s (want < 8)")
            failed += 1
        }
    }
}

// ── an error message a program asks for is paced like its other output ────────
// F$PErr's text, and any notice written to a program's own stderr from host
// code, was taken for emulator narration, which goes straight to the screen:
// at 300 baud a load error's ~80 characters arrived in well under a second
// instead of about 2.7 (found by the pre-release review of the console model).
do {
    let name = "console: at 300 baud a program's error message is paced, not dumped at once"
    if (filter.isEmpty || name.localizedCaseInsensitiveContains(filter)) && !containerized,
       let (controller, device, _) = makePTY() {
        let process = Process()
        process.executableURL       = execURL
        process.arguments           = [shellArg]
        process.currentDirectoryURL = URL(fileURLWithPath: scratchDisk)
        process.environment         = ["OS9DISK": diskPath].merging(inheritedByChildren) { mine, _ in mine }
        let deviceHandle = FileHandle(fileDescriptor: device, closeOnDealloc: false)
        process.standardInput  = deviceHandle
        process.standardOutput = deviceHandle
        process.standardError  = deviceHandle
        var took = -1.0
        if (try? process.run()) != nil {
            var got = [UInt8]()
            var buf = [UInt8](repeating: 0, count: 65536)
            func drain(_ seconds: Double, until wanted: [UInt8]? = nil) -> Bool {
                let end = Date().addingTimeInterval(seconds)
                while Date() < end {
                    var fds = pollfd(fd: controller, events: Int16(POLLIN), revents: 0)
                    if poll(&fds, 1, 50) > 0 {
                        let count = read(controller, &buf, buf.count)
                        if count <= 0 { return false }
                        got += buf[0..<count]
                        if let wanted, got.firstRange(of: wanted) != nil { return true }
                    }
                }
                return false
            }
            func send(_ text: String) {
                let bytes = Array(text.utf8)
                _ = bytes.withUnsafeBufferPointer { write(controller, $0.baseAddress, bytes.count) }
            }
            _ = drain(3)
            send("tmode baud=300\n")
            _ = drain(3)
            got.removeAll()
            let began = Date()
            send("load /dd/nosuch\n")
            if drain(20, until: Array("Path Name Not Found".utf8)) { took = Date().timeIntervalSince(began) }
            send("tmode baud=19200\n")
            _ = drain(3)
            send("\u{1B}\n")
            usleep(500_000)
            if process.isRunning { process.terminate() }
            process.waitUntilExit()
        }
        close(controller); close(device)
        if took >= 2.0 {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let after = String(format: "%.2f", took)
            print("      the message was complete after \(after) s (want at least 2 at 300 baud)")
            failed += 1
        }
    }
}

// ── a trace line does not release output that XOFF is holding ─────────────────
// Before a trace line goes out, whatever the program had queued is sent, so
// lines keep their order -- but not while XOFF holds the terminal: that output
// must stay held. It was flushed anyway: with -d on, ^S, then `mdir`, the
// echoed `mdir` appeared during the hold (pre-release review).
do {
    let name = "trace: a trace line does not flush output that XOFF is holding"
    if (filter.isEmpty || name.localizedCaseInsensitiveContains(filter)) && !containerized,
       let (controller, device, _) = makePTY() {
        let process = Process()
        process.executableURL       = execURL
        process.arguments           = ["-d", "0x0008", shellArg]
        process.currentDirectoryURL = URL(fileURLWithPath: scratchDisk)
        process.environment         = ["OS9DISK": diskPath].merging(inheritedByChildren) { mine, _ in mine }
        let deviceHandle = FileHandle(fileDescriptor: device, closeOnDealloc: false)
        process.standardInput  = deviceHandle
        process.standardOutput = deviceHandle
        process.standardError  = deviceHandle
        var duringHold = [UInt8](), afterRelease = [UInt8]()
        if (try? process.run()) != nil {
            var buf = [UInt8](repeating: 0, count: 65536)
            func drain(_ seconds: Double) -> [UInt8] {
                var got = [UInt8]()
                let end = Date().addingTimeInterval(seconds)
                while Date() < end {
                    var fds = pollfd(fd: controller, events: Int16(POLLIN), revents: 0)
                    if poll(&fds, 1, 50) > 0 {
                        let count = read(controller, &buf, buf.count)
                        if count <= 0 { break }
                        got += buf[0..<count]
                    }
                }
                return got
            }
            func send(_ text: String) {
                let bytes = Array(text.utf8)
                _ = bytes.withUnsafeBufferPointer { write(controller, $0.baseAddress, bytes.count) }
            }
            _ = drain(4)
            send("\u{13}")                     // ^S
            _ = drain(0.5)
            send("mdir\n")
            duringHold = drain(3)
            send("\u{11}")                     // ^Q
            afterRelease = drain(3)
            send("\u{1B}\n")
            usleep(500_000)
            if process.isRunning { process.terminate() }
            process.waitUntilExit()
        }
        close(controller); close(device)
        let echo = Array("mdir".utf8)
        let heldBack = duringHold.firstRange(of: echo) == nil
        let released = afterRelease.firstRange(of: echo) != nil
        if heldBack && released {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            print("      echo held during ^S: \(heldBack), shown after ^Q: \(released)")
            failed += 1
        }
    }
}

// ── an intercept that writes does not move its parked write's place ───────────
// A write parked on a full paced terminal keeps its place (the count it had
// reached, a line ending's tail, the terminal it holds). An intercept routine
// whose own write parked overwrote that place, and after F$RTE the outer write
// resumed at the handler's count -- bytes repeated or lost (pre-release review
// of the console model). Signal 200 is not an error, so the write goes on.
do {
    let placeAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit equ $06", "F$Icpt equ $09", "F$RTE equ $1E", "F$Alarm equ $56", "I$Write equ $8A",
        "I$WritLn equ $8C", "F$SRqMem equ $28",
        "  psect mwplc,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  lea handler(pc),a0", "  OS9 F$Icpt",
        "  move.l #8000,d0", "  OS9 F$SRqMem", "  bcs.s fail", "  movea.l a2,a3",
        "  move.w #7999,d2",
        "fill:", "  move.b #'~',(a2)+", "  dbra d2,fill",
        "  moveq #0,d0", "  moveq #1,d1", "  move.w #200,d2", "  moveq #20,d3", "  OS9 F$Alarm",
        "  movea.l a3,a0", "  moveq #1,d0", "  move.l #8000,d1", "  OS9 I$Write",
        "  moveq #0,d1",
        "fail:", "  OS9 F$Exit",
        "handler:", "  lea hline(pc),a0", "  moveq #1,d0", "  moveq #20,d1", "  OS9 I$WritLn",
        "  OS9 F$RTE",
        "hline: dc.b \"HANDLER-LINE\",13",
        "  ends", ""
    ].joined(separator: "\r")

    let name = "signal: an intercept routine that writes leaves its parked write's place alone"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? placeAsm.write(toFile: scratchDisk + "/mwplc.a", atomically: true, encoding: .utf8)
        _ = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                 "r68 /h5/mwplc.a -o=/h5/mwplc.r", "l68 /h5/mwplc.r -o=/h5/mwplc"], timeout: 60)
        let output = os9(["/h5/mwplc"], timeout: 60, paced: true)
        let letters = output.filter { $0 == "~" }.count   // a character nothing else prints
        let handled = output.components(separatedBy: "HANDLER-LINE").count - 1
        if letters == 8000 && handled == 1 {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            print("      ~ written: \(letters) (want 8000), handler lines: \(handled) (want 1)")
            failed += 1
        }
        for leftover in ["mwplc.a", "mwplc.r", "mwplc"] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
        }
    }
}

// ── F$RTE does not take the terminal from a write that parked meanwhile ───────
// While A's intercept routine runs, A is not waiting on its write, so B's
// write goes ahead and parks part way, holding the terminal. F$RTE handed the
// terminal back to A regardless, and A's rest landed in the middle of B's
// record (pre-release review of the console model). A resumes behind B now.
do {
    let header = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Fork equ $03", "F$Wait equ $04", "F$Exit equ $06", "F$Icpt equ $09", "F$Sleep equ $0A",
        "F$RTE equ $1E", "F$SRqMem equ $28", "F$Alarm equ $56", "I$Write equ $8A"
    ]
    func fill(_ count: Int, _ char: String) -> [String] {
        ["  move.l #\(count),d0", "  OS9 F$SRqMem", "  bcs.w fail", "  movea.l a2,a3",
         "  move.w #\(count - 1),d2", "fill:", "  move.b #'\(char)',(a2)+", "  dbra d2,fill"]
    }
    let first = header + ["  psect mrtea,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start", "start:",
        "  lea handler(pc),a0", "  OS9 F$Icpt"] + fill(8000, "~") + [
        "  lea bname(pc),a0", "  lea bparm(pc),a1", "  moveq #0,d0", "  moveq #1,d1", "  moveq #0,d2",
        "  moveq #3,d3", "  moveq #0,d4", "  OS9 F$Fork", "  bcs.s fail",
        "  moveq #0,d0", "  moveq #1,d1", "  move.w #200,d2", "  moveq #20,d3", "  OS9 F$Alarm",
        "  movea.l a3,a0", "  moveq #1,d0", "  move.l #8000,d1", "  OS9 I$Write",
        "  OS9 F$Wait", "  moveq #0,d1",
        "fail:", "  OS9 F$Exit",
        "handler:", "  moveq #15,d0", "  OS9 F$Sleep", "  OS9 F$RTE",
        "bname: dc.b \"/h5/mrteb\",0", "bparm: dc.b $0D", "  ends", ""]
    let second = header + ["  psect mrteb,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start", "start:",
        "  moveq #5,d0", "  OS9 F$Sleep"] + fill(4000, "^") + [
        "  movea.l a3,a0", "  moveq #1,d0", "  move.l #4000,d1", "  OS9 I$Write", "  moveq #0,d1",
        "fail:", "  OS9 F$Exit", "  ends", ""]
    let modules = ["mrtea": first, "mrteb": second]

    let name = "signal: after F$RTE a write resumes behind one that parked during its intercept"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        var build = ["load /dd/CMDS/r68 /dd/CMDS/l68"]
        for (module, lines) in modules {
            try? lines.joined(separator: "\r").write(toFile: scratchDisk + "/\(module).a",
                                                      atomically: true, encoding: .utf8)
            build += ["r68 /h5/\(module).a -o=/h5/\(module).r", "l68 /h5/\(module).r -o=/h5/\(module)"]
        }
        _ = os9(build, timeout: 60)
        let output = os9(["/h5/mrtea"], timeout: 60, paced: true)
        let marks  = output.filter { $0 == "~" || $0 == "^" }   // characters nothing else prints
        let tildes = marks.filter { $0 == "~" }.count
        let hashes = marks.filter { $0 == "^" }.count
        var whole  = false
        if let from = marks.firstIndex(of: "^"), let upTo = marks.lastIndex(of: "^") {
            whole = !marks[from...upTo].contains("~")
        }
        if tildes == 8000 && hashes == 4000 && whole {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            print("      ~ \(tildes) (want 8000), ^ \(hashes) (want 4000), ^ in one run: \(whole)")
            failed += 1
        }
        for module in modules.keys {
            for suffix in [".a", ".r", ""] { removeScratchItem(module + suffix) }
        }
    }
}

// ── a process's queued signals die with it, not with the next process ────────
// Signals sent to a masked process wait in one global queue, taken one per
// system call. A process that ended masked left its entries there, and they
// went to the next process given its pid: `echo` after it was killed by an old
// alarm's signal (found by the kernel review). Here a masked process computes
// while a one-tick cyclic alarm piles signals up, and exits; the command after
// it, given the same pid (the lowest free one), must simply run.
do {
    let leftAsm = [
        "F$Exit equ $06", "F$Icpt equ $09", "F$Sleep equ $0A", "F$SigMask equ $0B", "F$RTE equ $1E",
        "F$Alarm equ $56",
        " psect msigleft,$0101,$8001,0,1024,start",
        "start",
        " lea handler(pc),a0", " trap #0", " dc.w F$Icpt",
        " moveq #0,d0", " moveq #1,d1", " trap #0", " dc.w F$SigMask",
        " moveq #0,d0", " move.w #2,d1", " move.l #300,d2", " moveq #1,d3", " trap #0", " dc.w F$Alarm",
        // computing, not sleeping: a masked F$Sleep still ends at the first
        // signal, and one queued signal was not enough to show the fault
        " move.l #60000000,d0", "spin", " subq.l #1,d0", " bne.s spin",
        " moveq #0,d1", " trap #0", " dc.w F$Exit",
        "handler", " trap #0", " dc.w F$RTE",
        " ends", ""
    ].joined(separator: "\r")

    let name = "signal: signals queued for a process that exits masked do not reach the next one"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? leftAsm.write(toFile: scratchDisk + "/msigleft.a", atomically: true, encoding: .utf8)
        _ = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                 "r68 /h5/msigleft.a -o=/h5/msigleft.r", "l68 /h5/msigleft.r -o=/h5/msigleft"], timeout: 60)
        let out = os9(["/h5/msigleft", "echo NEXT-RAN", "echo AND-THE-ONE-AFTER"], timeout: 30)
        let lines = out.replacingOccurrences(of: "\r", with: "\n").split(separator: "\n")
        let ran = lines.contains { $0 == "NEXT-RAN" } && lines.contains { $0 == "AND-THE-ONE-AFTER" }
        if ran {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            print("      saw: \(lines.filter { $0.contains("RAN") || $0.contains("AFTER") || $0.contains("rror") })")
            failed += 1
        }
        for item in ["msigleft.a", "msigleft.r", "msigleft"] { removeScratchItem(item) }
    }
}

// ── debugger listings go to the operator, not where idbg's output is sent ─────
// The debugger's P, M, F and V list through the same routine internal commands
// print with, so run as `idbg >file` their listings went into the file. What
// the debugger says belongs to the operator, like the rest of its output
// (found by the pre-release CPU review).
do {
    let name = "debugger: its P listing goes to the operator even when idbg's output is redirected"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let file = scratchDisk + "/dbgout"
        try? FileManager.default.removeItem(atPath: file)
        let out = os9(["idbg >/\(scratchDev)/dbgout", "p", "g"], timeout: 30)
        let inFile = (try? String(contentsOfFile: file, encoding: .isoLatin1)) ?? ""
        if out.contains("Last Syscall") && !inFile.contains("Last Syscall") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let shown = out.contains("Last Syscall"), filed = inFile.contains("Last Syscall")
            print("      listing on the terminal: \(shown), in the file: \(filed)")
            failed += 1
        }
        try? FileManager.default.removeItem(atPath: file)
    }
}

// ── 68881 arithmetic rounds as FPCR says ─────────────────────────────────────
// FPCR's rounding mode governed only a float stored as an integer and FINT;
// arithmetic always rounded to nearest. 2/3 shows it: it is inexact and to
// nearest rounds it down, so rounding toward plus infinity gives a result one
// unit in the last place higher. (Not in the browser build: WebAssembly has no
// rounding modes.)
do {
    let roundAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit equ $06", "I$WritLn equ $8C",
        "  psect mfprnd,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "  vsect", "near: ds.l 2", "up: ds.l 2", "  ends",
        "start:",
        "  dc.w $F23C,$4000", "  dc.l 2", "  dc.w $F23C,$4020", "  dc.l 3",
        "  lea near(a6),a0", "  dc.w $F210,$7400",
        "  dc.w $F23C,$9000", "  dc.l $30",                     // FPCR: toward plus infinity
        "  dc.w $F23C,$4000", "  dc.l 2", "  dc.w $F23C,$4020", "  dc.l 3",
        "  lea up(a6),a0", "  dc.w $F210,$7400",
        "  dc.w $F23C,$9000", "  dc.l 0",
        "  move.l near(a6),d0", "  cmp.l up(a6),d0", "  bne.s same",
        "  move.l up+4(a6),d0", "  sub.l near+4(a6),d0", "  cmpi.l #1,d0", "  bne.s same",
        "  lea okm(pc),a0", "  bra.s tell",
        "same:", "  lea sam(pc),a0",
        "tell:", "  moveq #1,d0", "  moveq #40,d1", "  OS9 I$WritLn",
        "  moveq #0,d1", "  OS9 F$Exit",
        "okm: dc.b \"FPCR ROUNDING HONOURED\",13",
        "sam: dc.b \"FPCR ROUNDING IGNORED\",13",
        "  ends", ""
    ].joined(separator: "\r")

    let name = "68881: arithmetic rounds as FPCR says (2/3 rounded up is one ulp above to nearest)"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? roundAsm.write(toFile: scratchDisk + "/mfprnd.a", atomically: true, encoding: .utf8)
        _ = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                 "r68 /h5/mfprnd.a -o=/h5/mfprnd.r", "l68 /h5/mfprnd.r -o=/h5/mfprnd"], timeout: 60)
        let output = os9(["/h5/mfprnd"], timeout: 30)
        if output.contains("FPCR ROUNDING HONOURED") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            print("      saw: \(output.split(whereSeparator: \.isNewline).filter { $0.contains("FPCR") })")
            failed += 1
        }
        for leftover in ["mfprnd.a", "mfprnd.r", "mfprnd"] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
        }
    }
}

// ── F$Event: Ev$Wait answers the value that satisfied it ──────────────────────
// "returns with the value of the event causing the process to wake" (Microware,
// OS-9 Intermediate training, _os9_ev_wait) -- the value BEFORE the wait
// auto-increment, as the signal search already reported it for a queued
// waiter. An event already in range answered the incremented value instead,
// and TOP's os9lib takes a mutex with `while (_ev_wait(id,0,0) != 0)`: it got
// 1, went round, and waited forever on the lock it had just taken
// (osk-freeware, 2026-09-23: MNews hung in info_lock).
do {
    let evAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "",
        "F$Exit   equ  $06",
        "F$Event  equ  $53",
        "I$WritLn equ  $8C",
        "",
        "  psect evpre,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,512,start",
        "",
        "start:",
        "  lea     evname(pc),a0",
        "  moveq   #0,d0",          // initial value 0: the lock is free
        "  move.w  #2,d1",          // Ev$Creat
        "  move.w  #1,d2",          // wait increment +1: waiting takes it
        "  move.w  #-1,d3",         // signal increment -1: signalling frees it
        "  OS9     F$Event",
        "  bcs     done",
        "  move.l  d0,d7",
        "  move.w  #4,d1",          // Ev$Wait on [0,0], in range at once
        "  moveq   #0,d2",
        "  moveq   #0,d3",
        "  OS9     F$Event",
        "  bcs     done",
        "  move.l  d1,d6",          // what it answered
        "  move.l  d7,d0",
        "  move.w  #6,d1",          // Ev$Read: the increment must still be applied
        "  OS9     F$Event",
        "  bcs     done",
        "  tst.l   d6",
        "  bne.s   after",
        "  cmpi.l  #1,d1",
        "  bne.s   after",
        "  lea     mok(pc),a0",
        "  moveq   #mokl,d1",
        "  bra.s   say",
        "after:",
        "  lea     mbad(pc),a0",
        "  moveq   #mbadl,d1",
        "say:",
        "  moveq   #1,d0",
        "  OS9     I$WritLn",
        "  move.l  d7,d0",
        "  move.w  #1,d1",          // Ev$UnLnk, then Ev$Delet
        "  OS9     F$Event",
        "  lea     evname(pc),a0",
        "  move.w  #3,d1",
        "  OS9     F$Event",
        "  moveq   #0,d1",
        "done:",
        "  OS9     F$Exit",
        "evname: dc.b  \"EvPre\",0",
        "mok:  dc.b  \"EVWAIT ANSWERED 0, EVENT NOW 1\",$0D",
        "mokl  equ   *-mok",
        "mbad:  dc.b  \"EVWAIT ANSWERED THE INCREMENTED VALUE\",$0D",
        "mbadl  equ   *-mbad",
        "",
        "  ends",
        ""
    ].joined(separator: "\r")

    let name = "f$event: Ev$Wait answers the value that satisfied it, before the wait increment"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? evAsm.write(toFile: scratchDisk + "/evpre.a", atomically: true, encoding: .utf8)
        let out = os9([
            "load /dd/CMDS/r68 /dd/CMDS/l68",
            "r68 /h5/evpre.a -o=/h5/evpre.r",
            "l68 /h5/evpre.r -o=/h5/evpre",
            "/h5/evpre"
        ], timeout: 20)
        if out.contains("EVWAIT ANSWERED 0, EVENT NOW 1") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let preview = out.split(separator: "\n")
                .filter { $0.contains("EVWAIT") || $0.contains("Error") }
                .prefix(4).joined(separator: " | ")
            print("      output: \(preview)")
            failed += 1
        }
        for leftover in ["evpre.a", "evpre.r", "evpre"] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
        }
    }
}

// ── F$Event: a bad event ID errors immediately instead of hanging forever ──────
// evWait() (events.c) used to return E_EVNTID for BOTH "no such event" and
// "value not yet in range" -- the exact same code the polling dispatch loop in
// fcalls.c's OS9_F_Event treats as "not ready yet, park and retry". A
// genuinely bad ID can never satisfy the range check, so the process parked
// forever instead of getting an error back -- confirmed hanging past a 20s
// timeout before the fix (EV_NOTYET, a distinct internal-only sentinel, now
// separates "keep waiting" from "this ID was never valid").
do {
    let evAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "",
        "F$Exit   equ  $06",
        "F$Event  equ  $53",
        "I$WritLn equ  $8C",
        "",
        "  psect evwtst,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,512,start",
        "",
        "start:",
        "  moveq   #1,d0",          // bogus event ID -- never created by anyone
        "  move.w  #4,d1",          // Ev_Wait
        "  moveq   #0,d2",          // minV
        "  move.l  #999,d3",        // maxV
        "  OS9     F$Event",
        "  bcs     gotErr",
        "  lea     nofail(pc),a0",
        "  moveq   #nofaill,d1",
        "  moveq   #1,d0",
        "  OS9     I$WritLn",
        "  bra     done",
        "gotErr:",
        "  lea     mok(pc),a0",
        "  moveq   #mokl,d1",
        "  moveq   #1,d0",
        "  OS9     I$WritLn",
        "done:",
        "  moveq   #0,d1",
        "  OS9     F$Exit",
        "mok:  dc.b  \"EVWAIT BAD ID RETURNED ERROR\",$0D",
        "mokl  equ   *-mok",
        "nofail:  dc.b  \"EVWAIT BAD ID DID NOT ERROR\",$0D",
        "nofaill  equ   *-nofail",
        "",
        "  ends",
        ""
    ].joined(separator: "\r")

    let asmPath = scratchDisk + "/evwtst.a"
    try? evAsm.write(toFile: asmPath, atomically: true, encoding: .utf8)

    let name = "f$event: Ev_Wait on a bad event ID errors immediately, doesn't hang"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let out = os9([
            "load /dd/CMDS/r68 /dd/CMDS/l68",
            "r68 /h5/evwtst.a -o=/h5/evwtst.r",
            "l68 /h5/evwtst.r -o=/h5/evwtst",
            "/h5/evwtst"
        ], timeout: 20)
        if out.contains("EVWAIT BAD ID RETURNED ERROR") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            print("      [a bad event ID must error immediately, not park forever]")
            let preview = out.split(separator: "\n")
                .filter { !$0.hasPrefix("#") && $0 != "$" && !$0.isEmpty }
                .prefix(8).joined(separator: " | ")
            print("      output: \(preview)")
            failed += 1
        }
    }

    for leftover in ["evwtst.a", "evwtst.r", "evwtst"] {
        try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
    }
}

// ── F$Event: Creat/Wait/Signl/Wait/Delet lifecycle round-trip ──────────────────
// The Event Manager had zero automated coverage before this (not even manually
// Live-verified per 68k/syscall-reference.md -- "Manual, name-level only").
// Initial value is chosen already inside the wait range so this single process
// never blocks: a genuinely-blocking wait (a second process signalling a first
// process's parked wait) is a separate, harder test not attempted here.
// Each wait answers the value that satisfied it, before its increment (see
// "Ev$Wait answers the value that satisfied it"); this test expected the
// incremented one until 2026-09-23, which was the emulator's answer, not OS-9's.
do {
    let evAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "",
        "F$Exit   equ  $06",
        "F$Event  equ  $53",
        "I$WritLn equ  $8C",
        "",
        "  psect evlife,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,512,start",
        "",
        "start:",
        "  lea     evname(pc),a0",
        "  moveq   #5,d0",           // initial value 5 -- already inside [1,999]
        "  move.w  #2,d1",           // Ev_Creat
        "  moveq   #1,d2",           // wIncr
        "  moveq   #1,d3",           // sIncr
        "  OS9     F$Event",
        "  bcs     fail",
        "  lea     evId(pc),a1",
        "  move.l  d0,(a1)",
        "",
        "  lea     evId(pc),a1",     // Ev_Wait #1: 5 is already in range -> answers 5,
        "  move.l  (a1),d0",         // the value that satisfied it; the event becomes 6
        "  move.w  #4,d1",
        "  moveq   #1,d2",
        "  move.l  #999,d3",
        "  OS9     F$Event",
        "  bcs     fail",
        "  cmp.l   #5,d1",
        "  bne     fail",
        "",
        "  lea     evId(pc),a1",     // Ev_Signl: value 6+1=7
        "  move.l  (a1),d0",
        "  move.w  #8,d1",
        "  OS9     F$Event",
        "  bcs     fail",
        "",
        "  lea     evId(pc),a1",     // Ev_Wait #2: 7 is in range -> answers 7, becomes 8
        "  move.l  (a1),d0",
        "  move.w  #4,d1",
        "  moveq   #1,d2",
        "  move.l  #999,d3",
        "  OS9     F$Event",
        "  bcs     fail",
        "  cmp.l   #7,d1",
        "  bne     fail",
        "",
        "  lea     evId(pc),a1",     // Ev_UnLnk: the creator holds the one link
        "  move.l  (a1),d0",         // Ev_Creat gave it, and Ev_Delet refuses
        "  move.w  #1,d1",           // while the use count is not zero
        "  OS9     F$Event",
        "  bcs     fail",
        "",
        "  lea     evname(pc),a0",   // Ev_Delet: by name, not by ID
        "  move.w  #3,d1",
        "  OS9     F$Event",
        "  bcs     fail",
        "",
        "  lea     okmsg(pc),a0",
        "  moveq   #okmsgl,d1",
        "  moveq   #1,d0",
        "  OS9     I$WritLn",
        "  bra     done",
        "fail:",
        "  lea     failmsg(pc),a0",
        "  moveq   #failmsgl,d1",
        "  moveq   #1,d0",
        "  OS9     I$WritLn",
        "done:",
        "  moveq   #0,d1",
        "  OS9     F$Exit",
        "evname:   dc.b  \"evlftst1\",0",
        "evId:     dc.l  0",
        "okmsg:    dc.b  \"EVENT LIFECYCLE OK\",$0D",
        "okmsgl    equ   *-okmsg",
        "failmsg:  dc.b  \"EVENT LIFECYCLE FAILED\",$0D",
        "failmsgl  equ   *-failmsg",
        "",
        "  ends",
        ""
    ].joined(separator: "\r")

    let asmPath = scratchDisk + "/evlife.a"
    try? evAsm.write(toFile: asmPath, atomically: true, encoding: .utf8)

    let name = "f$event: Ev_Creat/Ev_Wait/Ev_Signl/Ev_Wait/Ev_Delet round-trip"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let out = os9([
            "load /dd/CMDS/r68 /dd/CMDS/l68",
            "r68 /h5/evlife.a -o=/h5/evlife.r",
            "l68 /h5/evlife.r -o=/h5/evlife",
            "/h5/evlife"
        ], timeout: 20)
        if out.contains("EVENT LIFECYCLE OK") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            print("      [Creat->Wait->Signl->Wait->Delet must all succeed with the expected values]")
            let preview = out.split(separator: "\n")
                .filter { !$0.hasPrefix("#") && $0 != "$" && !$0.isEmpty }
                .prefix(8).joined(separator: " | ")
            print("      output: \(preview)")
            failed += 1
        }
    }

    for leftover in ["evlife.a", "evlife.r", "evlife"] {
        try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
    }
}

// ── F$Event: a blocking Ev_Wait is woken by another process's Ev_Signl ─────────
// The lifecycle test above deliberately avoided blocking (its initial value was
// already in range). This is the harder cross-process question its own comment
// flagged as not attempted: process A parks on an OUT-of-range Ev_Wait, and a
// separate backgrounded process B links the same event by name and signals it
// into range. A green here proves that a signal from one process actually wakes
// a waiter blocked in another, not just that a single process whose value is
// already in range falls through.
//
// The mechanism underneath changed on 2026-08-04 and this comment used to
// describe the old one. Ev_Signl no longer merely bumps a counter and leave
// A's parked wait to be served by the poll-retry re-dispatch of a pWaitRead
// process: events.c now keeps the FIFO wait queue the manual describes, and
// the signal search picks A out of it and records the value it is to return.
// The retry re-dispatch is still how A gets scheduled to collect that answer,
// so what this test demands of the system is unchanged -- which is exactly why
// it was worth keeping as written while the mechanism under it was replaced.
// Verified non-vacuous 2026-07-22: a control signaler that links
// the event but never signals it leaves the waiter parked forever (no "WAITER
// WOKEN", run hangs to the timeout) -- so the wake is caused by the signal, not
// by the mere existence of a second process. First automated coverage of a
// genuinely-blocking OS-9 event wait at all.
do {
    let waiterAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "",
        "F$Exit   equ  $06",
        "F$Event  equ  $53",
        "I$WritLn equ  $8C",
        "",
        "  psect evwait,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,512,start",
        "",
        "start:",
        "  lea     evname(pc),a0",
        "  moveq   #0,d0",              // initial value 0 -- OUTSIDE the wait range [3,999]
        "  move.w  #2,d1",              // Ev_Creat
        "  moveq   #1,d2",              // wIncr
        "  moveq   #1,d3",              // sIncr
        "  OS9     F$Event",
        "  bcs     fail",
        "  lea     evId(pc),a1",
        "  move.l  d0,(a1)",            // save evId
        "",
        "  lea     parkmsg(pc),a0",     // announce created + about to block
        "  moveq   #parkmsgl,d1",
        "  moveq   #1,d0",
        "  OS9     I$WritLn",
        "",
        "  lea     evId(pc),a1",        // Ev_Wait for [3,999]; value 0 -> PARK
        "  move.l  (a1),d0",
        "  move.w  #4,d1",
        "  moveq   #3,d2",
        "  move.l  #999,d3",
        "  OS9     F$Event",
        "  bcs     fail",
        "",
        "  lea     okmsg(pc),a0",       // only reached if the parked wait was woken
        "  moveq   #okmsgl,d1",
        "  moveq   #1,d0",
        "  OS9     I$WritLn",
        "  bra     done",
        "fail:",
        "  lea     failmsg(pc),a0",
        "  moveq   #failmsgl,d1",
        "  moveq   #1,d0",
        "  OS9     I$WritLn",
        "done:",
        "  moveq   #0,d1",
        "  OS9     F$Exit",
        "",
        "evname:   dc.b  \"evblkw\",0",
        "evId:     dc.l  0",
        "parkmsg:  dc.b  \"WAITER PARKED\",$0D",
        "parkmsgl  equ   *-parkmsg",
        "okmsg:    dc.b  \"WAITER WOKEN\",$0D",
        "okmsgl    equ   *-okmsg",
        "failmsg:  dc.b  \"WAITER FAILED\",$0D",
        "failmsgl  equ   *-failmsg",
        "",
        "  ends",
        ""
    ].joined(separator: "\r")

    let sigAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "",
        "F$Exit   equ  $06",
        "F$Event  equ  $53",
        "F$Sleep  equ  $0A",
        "I$WritLn equ  $8C",
        "",
        "  psect evsig,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,512,start",
        "",
        "start:",
        "  lea     tries(pc),a2",       // retry Ev_Link until the waiter has created it
        "  move.l  #20,(a2)",
        "linkloop:",
        "  lea     evname(pc),a0",
        "  move.w  #0,d1",              // Ev_Link (by name)
        "  OS9     F$Event",
        "  bcc     linked",
        "  moveq   #5,d0",              // not there yet -- nap 5 ticks and retry
        "  OS9     F$Sleep",
        "  lea     tries(pc),a2",
        "  subq.l  #1,(a2)",
        "  bne     linkloop",
        "  bra     fail",
        "linked:",
        "  lea     evId(pc),a1",
        "  move.l  d0,(a1)",            // evId from the link
        "  lea     cnt(pc),a2",
        "  move.l  #3,(a2)",            // signal 3 times: value 0 -> 3, into range
        "sigloop:",
        "  lea     evId(pc),a1",
        "  move.l  (a1),d0",
        "  move.w  #8,d1",              // Ev_Signl
        "  OS9     F$Event",
        "  bcs     fail",
        "  lea     cnt(pc),a2",
        "  subq.l  #1,(a2)",
        "  bne     sigloop",
        "",
        "  move.l  #60,d0",             // give the woken waiter time to print
        "  OS9     F$Sleep",
        "",
        "  lea     okmsg(pc),a0",
        "  moveq   #okmsgl,d1",
        "  moveq   #1,d0",
        "  OS9     I$WritLn",
        "  bra     done",
        "fail:",
        "  lea     failmsg(pc),a0",
        "  moveq   #failmsgl,d1",
        "  moveq   #1,d0",
        "  OS9     I$WritLn",
        "done:",
        "  moveq   #0,d1",
        "  OS9     F$Exit",
        "",
        "evname:   dc.b  \"evblkw\",0",
        "evId:     dc.l  0",
        "tries:    dc.l  0",
        "cnt:      dc.l  0",
        "okmsg:    dc.b  \"SIGNALER DONE\",$0D",
        "okmsgl    equ   *-okmsg",
        "failmsg:  dc.b  \"SIGNALER FAILED\",$0D",
        "failmsgl  equ   *-failmsg",
        "",
        "  ends",
        ""
    ].joined(separator: "\r")

    try? waiterAsm.write(toFile: scratchDisk + "/evwait.a", atomically: true, encoding: .utf8)
    try? sigAsm.write(toFile: scratchDisk + "/evsig.a", atomically: true, encoding: .utf8)

    let name = "f$event: a blocking Ev_Wait is woken by another process's Ev_Signl"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let out = os9([
            "load /dd/CMDS/r68 /dd/CMDS/l68",
            "r68 /h5/evwait.a -o=/h5/evwait.r",
            "l68 /h5/evwait.r -o=/h5/evwait",
            "r68 /h5/evsig.a -o=/h5/evsig.r",
            "l68 /h5/evsig.r -o=/h5/evsig",
            "/h5/evwait &",             // parks on an out-of-range Ev_Wait
            "/h5/evsig"                 // links + signals it into range
        ], timeout: 30)
        if out.contains("WAITER WOKEN") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            print("      [a parked Ev_Wait must be woken when a separate process signals the event into range]")
            let preview = out.split(separator: "\n")
                .filter { !$0.hasPrefix("#") && $0 != "$" && !$0.isEmpty }
                .prefix(10).joined(separator: " | ")
            print("      output: \(preview)")
            failed += 1
        }
    }

    for leftover in ["evwait.a", "evwait.r", "evwait", "evsig.a", "evsig.r", "evsig"] {
        try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
    }
}

// ── icopy must not report success for bytes it did not deliver ───────────────
// An internal command is host C run to completion: it never returns to the
// scheduler. When a pipe fills, the pipe manager queues a system task to finish
// the write later and returns 0 -- correct for a 68k program, which gets
// resumed, but for an internal command that task never runs. `icopy` was told
// "all bytes written" and believed it: a 10000-byte file copied into a pipe
// delivered 4096 and reported success.
//
// Two halves: the pipe manager now reports the count it actually wrote when the
// caller cannot park, and icopy checks the count instead of assuming it got
// what it asked for. The copy still cannot complete -- that would need icopy to
// be parkable -- but it fails loudly instead of losing data quietly.
//
// file-to-file and file-to-SCF are unaffected and were measured so: a full disk
// already reported E$FULL, and /term took all 10000 bytes.
do {
    let big = String(repeating: "X", count: 10000)
    try? big.write(toFile: scratchDisk + "/icbig", atomically: true, encoding: .utf8)

    check("icopy: a destination that cannot take it all reports an error",
        contains: "245",
        "icopy /h5/icbig /pipe/icp")

    check("icopy: file to file still copies whole",
        contains: "10000",
        "icopy /h5/icbig /h5/iccopy", "dir -e /h5")

    for leftover in ["icbig", "iccopy"] {
        try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
    }
}

// ── F$SRqMem at the block limit reports E$MemFul, not E$NoRAM ────────────────
// E$MemFul (207), v2.4 Technical Manual: "MEMORY FULL - The process will not
// execute because there is not enough contiguous RAM free. This can ALSO occur
// if a process has already been allocated the maximum number of blocks
// permitted by the system." E$NoRAM (237) is the other one: "no free RAM, or
// not enough contiguous memory".
//
// os9malloc has always known which of the two it hit -- get_mem failing is one,
// install_memblock running past MAXMEMBLOCKS is the other -- but it returned
// NULL for both, so F$SRqMem answered E$NoRAM either way and told a program the
// machine was out of memory when it had really hit its own block limit.
//
// The module asks for 16-byte blocks in a loop, so it exhausts MAXMEMBLOCKS
// (512) long before it exhausts the arena; whichever error comes back is the
// block-limit one by construction.
do {
    let memAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "",
        "F$Exit   equ  $06",
        "F$SRqMem equ  $28",
        "I$WritLn equ  $8C",
        "E_MEMFUL equ  207",
        "",
        "  psect memful,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "",
        "start:",
        "grab:",
        "  moveq   #16,d0",
        "  OS9     F$SRqMem",
        "  bcc     grab",              // got one, keep going
        "  cmpi.w  #E_MEMFUL,d1",
        "  beq     ismemful",
        "  lea     wrongmsg(pc),a0",
        "  moveq   #wrongmsgl,d1",
        "  bra     say",
        "ismemful:",
        "  lea     okmsg(pc),a0",
        "  moveq   #okmsgl,d1",
        "say:",
        "  moveq   #1,d0",
        "  OS9     I$WritLn",
        "  moveq   #0,d1",
        "  OS9     F$Exit",
        "",
        "okmsg:     dc.b  \"BLOCK-LIMIT-IS-MEMFUL\",$0D",
        "okmsgl     equ   *-okmsg",
        "wrongmsg:  dc.b  \"BLOCK-LIMIT-WRONG-ERROR\",$0D",
        "wrongmsgl  equ   *-wrongmsg",
        "",
        "  ends",
        ""
    ].joined(separator: "\r")

    try? memAsm.write(toFile: scratchDisk + "/memful.a", atomically: true, encoding: .utf8)

    run("f$srqmem: a process at its block limit reports E$MemFul, not E$NoRAM",
        expectation: "contains: BLOCK-LIMIT-IS-MEMFUL",
        commands: [
            "load /dd/CMDS/r68 /dd/CMDS/l68",
            "r68 /h5/memful.a -o=/h5/memful.r",
            "l68 /h5/memful.r -o=/h5/memful",
            "/h5/memful"
        ], timeout: 30) { $0.contains("BLOCK-LIMIT-IS-MEMFUL") }

    for leftover in ["memful.a", "memful.r", "memful"] {
        try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
    }
}

// ── a mode-0 open on a host directory answers getstats instead of faulting ──
// OS-9 lets a path be opened with access mode 0 -- neither read nor write -- to
// ask about a file rather than read it. On a host-directory device pFopen opens
// no host stream for that (so attr can reach a file whose content permissions are
// cleared), and every handler that touched the stream afterwards faulted the HOST:
// fileno(NULL) inside SS_Size, which segv_handler hands to the guest as E$BusErr.
// zip, zipinfo, unzip, mv and texidx all died that way on a host-directory /dd
// while passing on an RBF image. The module opens a 1234-byte file with mode 0,
// asks SS_Size (must be 1234), SS_Pos and SS_EOF, seeks, and closes; any failure
// exits with its error, so the shell prints "Error #" -- #000:102 before the fix.
do {
    let modeZeroName = "file: a mode-0 open on a host directory answers SS_Size, SS_Pos, SS_EOF and seek"
    if filter.isEmpty || modeZeroName.localizedCaseInsensitiveContains(filter) {
        let asm = [
            "  use /dd/DEFS/oskdefs.d",
            "",
            "F$Exit   equ  $06",
            "I$Open   equ  $84",
            "I$Seek   equ  $88",
            "I$GetStt equ  $8D",
            "I$Close  equ  $8F",
            "",
            "  psect modezero,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
            "",
            "start:",
            "  lea     fname(pc),a0",
            "  moveq   #0,d0",
            "  OS9     I$Open",
            "  bcs     fail",
            "  move.w  d0,d7",
            "  moveq   #2,d1",
            "  OS9     I$GetStt",
            "  bcs     fail",
            "  cmpi.l  #1234,d2",
            "  bne     wrong",
            "  move.w  d7,d0",
            "  moveq   #5,d1",
            "  OS9     I$GetStt",
            "  bcs     fail",
            "  move.w  d7,d0",
            "  moveq   #6,d1",
            "  OS9     I$GetStt",
            "  bcs     fail",
            "  move.w  d7,d0",
            "  moveq   #10,d1",
            "  OS9     I$Seek",
            "  bcs     fail",
            "  move.w  d7,d0",
            "  OS9     I$Close",
            "  moveq   #0,d1",
            "  OS9     F$Exit",
            "wrong:",
            "  moveq   #1,d1",
            "fail:",
            "  OS9     F$Exit",
            "fname:",
            "  dc.b    \"/h5/modezero.dat\",0",
            "",
            "  ends",
            ""
        ].joined(separator: "\r")
        try? asm.write(toFile: scratchDisk + "/modezero.a", atomically: true, encoding: .utf8)
        try? Data(repeating: 0x41, count: 1234).write(to: URL(fileURLWithPath: scratchDisk + "/modezero.dat"))

        let out = os9([
            "load /dd/CMDS/r68 /dd/CMDS/l68",
            "r68 /h5/modezero.a -o=/h5/modezero.r",
            "l68 /h5/modezero.r -o=/h5/modezero",
            "/h5/modezero",
            "echo MODEZERO-END"
        ], timeout: 30)
        let built = FileManager.default.fileExists(atPath: scratchDisk + "/modezero")
        let clean = out.contains("MODEZERO-END") && !out.contains("Error #")
        if built && clean {
            print("PASS: \(modeZeroName)")
            passed += 1
        } else {
            print("FAIL: \(modeZeroName)")
            if !built { print("      the module was never built, so this proves nothing") }
            let errors = out.replacingOccurrences(of: "\r", with: "\n")
                .split(separator: "\n").filter { $0.contains("Error #") }
            for line in errors.prefix(3) { print("      | \(line.trimmingCharacters(in: .whitespaces))") }
            failed += 1
        }
        for leftover in ["modezero.a", "modezero.r", "modezero", "modezero.dat"] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
        }
    }
}

// ── PD_DUP replays the CALLER's buffer, whatever is in it ──
// Technical I/O Manual v2.4, PD_DUP: "If this character is input, SCF
// (I$ReadLn) duplicates whatever is in the input buffer through the first
// PD_EOR character. Normally, this is the previous line typed." The hedge is
// the whole point: the line is not kept anywhere private, so what comes back is
// whatever THIS caller's buffer holds. A program that seeds its own buffer and
// then reads a Ctrl-A gets its own text back, not the line typed at the shell
// before it. Nothing tested this, and "fixing" the replay to use a buffer of
// SCF's own would look tidier and would be wrong.
do {
    let dupAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "",
        "F$Exit   equ  $06",
        "I$ReadLn equ  $8B",
        "I$WritLn equ  $8C",
        "",
        "  psect dupbuf,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "",
        "start:",
        "  sub.l   #64,a7",
        "  movea.l a7,a4",            // our own buffer, on the stack
        "  lea     seed(pc),a1",
        "  movea.l a4,a0",
        "  moveq   #8,d2",            // "DUPTEXT" and the CR
        "seedloop:",
        "  move.b  (a1)+,(a0)+",
        "  subq.l  #1,d2",
        "  bne.s   seedloop",
        "  clr.b   (a0)",             // NUL right after the CR
        "  movea.l a4,a0",
        "  moveq   #32,d1",
        "  moveq   #0,d0",            // path 0: the terminal
        "  OS9     I$ReadLn",
        "  bcs.s   failed",
        "  movea.l a4,a0",            // d1 = what the read returned
        "  moveq   #1,d0",
        "  OS9     I$WritLn",
        "  bra.s   done",
        "failed:",
        "  lea     msg(pc),a0",
        "  moveq   #msgl,d1",
        "  moveq   #1,d0",
        "  OS9     I$WritLn",
        "done:",
        "  moveq   #0,d1",
        "  OS9     F$Exit",
        "",
        "seed: dc.b \"DUPTEXT\",$0D",
        "msg:  dc.b \"READ FAILED\",$0D",
        "msgl  equ  *-msg",
        "",
        "  ends",
        ""
    ].joined(separator: "\r")
    try? dupAsm.write(toFile: scratchDisk + "/dupbuf.a", atomically: true, encoding: .utf8)

    run("scf: PD_DUP replays the caller's own buffer, not a line SCF kept",
        expectation: "Ctrl-A gives back the text the program seeded, DUPTEXT",
        commands: ["load /dd/CMDS/r68 /dd/CMDS/l68",
                   "r68 /h5/dupbuf.a -o=/h5/dupbuf.r", "l68 /h5/dupbuf.r -o=/h5/dupbuf",
                   "/h5/dupbuf", "\u{01}"], timeout: 30) { out in
        let printed = out.replacingOccurrences(of: "\r", with: "\n").split(separator: "\n")
                         .filter { !$0.hasPrefix("$ ") }
        return printed.contains { $0.contains("DUPTEXT") } && !out.contains("READ FAILED")
    }
    for leftover in ["dupbuf.a", "dupbuf.r", "dupbuf"] {
        try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
    }
}

// ── the emulator's own options: -i, -ih, -dh, -p ──
// Four of os9exec's command-line options, none of which any test passed. -i is
// the one with teeth: it turns the internal commands off, so `pwd` (os9exec's
// own, not OS-9's) stops being found -- the switch for a site that wants
// nothing but real OS-9 modules. The other three only have to say something
// true, but each one used to be a page of code no test entered.
do {
    struct OptionCase {
        let name: String
        let flags: [String]
        let commands: [String]
        let pass: (String) -> Bool
    }
    let cases = [
        OptionCase(name: "options: internal commands run by default", flags: [],
                   commands: ["pwd"]) { !$0.contains("can't execute") },
        OptionCase(name: "options: -i turns the internal commands off", flags: ["-i"],
                   commands: ["pwd"]) { $0.contains("can't execute \"pwd\"") },
        OptionCase(name: "options: -ih lists the internal commands", flags: ["-ih"],
                   commands: ["echo done"]) { $0.contains("mount") && $0.contains("iprocs") },
        OptionCase(name: "options: -dh lists the debug masks", flags: ["-dh"],
                   commands: ["echo done"]) { $0.contains("dbgFiles") && $0.contains("0x0200") },
        OptionCase(name: "internal: dch is accepted and does nothing", flags: [],
                   commands: ["dch", "echo STILLHERE"]) {
            $0.contains("STILLHERE") && !$0.contains("Error #") && !$0.contains("can't execute")
        },
        OptionCase(name: "options: -p sets the first process's priority", flags: ["-p", "200"],
                   commands: ["procs"]) { out in
            // procs prints one row per process, priority in its own column
            out.replacingOccurrences(of: "\r", with: "\n").split(separator: "\n")
               .contains { $0.contains(" shell ") && $0.contains("200") }
        },
    ]
    for c in cases where filter.isEmpty || c.name.localizedCaseInsensitiveContains(filter) {
        let out = os9(c.commands, flags: c.flags)
        if c.pass(out) {
            print("PASS: \(c.name)"); passed += 1
        } else {
            print("FAIL: \(c.name)")
            for line in out.replacingOccurrences(of: "\r", with: "\n")
                           .split(separator: "\n").prefix(6) { print("      | \(line)") }
            failed += 1
        }
    }
}

// ── a failed allocation is the program's error, and nobody else's business ──
// OS-9 refuses a memory request silently: the caller gets E$NoRAM and decides.
// os9exec used to narrate it too, on the program's own stderr -- a line from the
// Mac original, where it meant the HOST had run out. In practice it announced a
// program asking for nonsense, mixed into that program's output (one runaway
// allocator: 439,689 copies).
//
// Two programs, because the two failures are different people's business:
//   memflood asks for a gigabyte forty times. No -M could satisfy that, so it is
//     purely the program's: the error comes back and NOTHING is printed.
//   memfill takes the arena a megabyte at a time until it is gone. That one is
//     the operator's -- the arena really is too small -- so os9exec says so ONCE,
//     on its own console, naming -M, and never on the program's stderr (which is
//     redirected into a file here to prove it).
// Both exit with the last error they got, so the shell's "Error #000:237" is
// the proof the program itself was told.
do {
    func requester(_ name: String, bytes: String, times: Int) -> String {
        [
            "  use /dd/DEFS/oskdefs.d",
            "",
            "F$Exit   equ  $06",
            "F$SRqMem equ  $28",
            "",
            "  psect \(name),(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
            "",
            "start:",
            "  moveq   #0,d4",
            "  moveq   #\(times),d2",
            "askagain:",
            "  move.l  #\(bytes),d0",
            "  OS9     F$SRqMem",
            "  bcc     granted",
            "  move.l  d1,d4",             // remember the refusal
            "granted:",
            "  subq.l  #1,d2",
            "  bne     askagain",
            "  move.l  d4,d1",
            "  OS9     F$Exit",
            "",
            "  ends",
            ""
        ].joined(separator: "\r")
    }
    try? requester("memflood", bytes: "$40000000", times: 40)     // 1 GB: never satisfiable
        .write(toFile: scratchDisk + "/memflood.a", atomically: true, encoding: .utf8)
    try? requester("memfill", bytes: "$00100000", times: 60)      // 1 MB x 60: fills 32 MB
        .write(toFile: scratchDisk + "/memfill.a", atomically: true, encoding: .utf8)

    let floodName = "memory: a refused allocation is the program's error, and os9exec says nothing"
    let fillName  = "memory: an exhausted arena is said once, to the operator, naming -M"
    let wanted = [floodName, fillName].contains { filter.isEmpty || $0.localizedCaseInsensitiveContains(filter) }
    if wanted {
        let build = [
            "load /dd/CMDS/r68 /dd/CMDS/l68",
            "r68 /h5/memflood.a -o=/h5/memflood.r",
            "l68 /h5/memflood.r -o=/h5/memflood",
            "r68 /h5/memfill.a -o=/h5/memfill.r",
            "l68 /h5/memfill.r -o=/h5/memfill"
        ]
        func lines(_ out: String, _ needle: String) -> [Substring] {
            // Split on CR as well as LF: OS-9 ends a line with CR.
            out.replacingOccurrences(of: "\r", with: "\n").split(separator: "\n").filter { $0.contains(needle) }
        }
        let refused = "Error #000:237"
        let hint    = "arena is full"

        // Built in a call of its own, as every other test here builds: assembling
        // two programs inside the same 30s budget the run itself has left a cold
        // or loaded container short of time, and a run cut off by its timeout
        // failed BOTH tests at once -- seen once in the x64 leg under load 5.
        _ = os9(build, timeout: 120)
        let errFile = scratchDisk + "/memfill.err"
        let out     = os9(["/h5/memflood", "/h5/memfill >>>/h5/memfill.err"], timeout: 30)
        let guestErr = (try? String(contentsOfFile: errFile, encoding: .isoLatin1)) ?? "<missing>"
        removeScratchItem("memfill.err")   // the shell will not redirect onto an existing file
        let paced   = os9(["/h5/memflood", "/h5/memfill >>>/h5/memfill.err"], timeout: 60, paced: true)

        // memflood's own stretch of the run: from its command line to memfill's.
        // Sliced on the command lines, which name each program once.
        let floodPart = out.components(separatedBy: "/h5/memflood\n").last?
                           .components(separatedBy: "/h5/memfill >>>").first ?? ""
        let floodSeen = floodPart.contains(refused)
        let floodSilent = floodSeen && lines(floodPart, "memory").isEmpty && lines(floodPart, hint).isEmpty
        let floodTold   = lines(out, refused).count == 2 && lines(paced, refused).count == 2
        if filter.isEmpty || floodName.localizedCaseInsensitiveContains(filter) {
            if floodSilent && floodTold {
                print("PASS: \(floodName)"); passed += 1
            } else {
                print("FAIL: \(floodName)")
                if !floodSilent { for l in lines(floodPart, "memory").prefix(3) { print("      printed: \(l)") } }
                if !floodSeen { print("      could not find memflood's part of the run, so this proves nothing") }
                if !floodTold { print("      expected two \(refused) (one per program), saw \(lines(out, refused).count)") }
                failed += 1
            }
        }

        let saidOnce   = lines(out, hint).count == 1 && lines(paced, hint).count == 1
        let namesM     = lines(out, hint).allSatisfy { $0.contains("-M") }
        let notInGuest = guestErr != "<missing>" && !guestErr.contains(hint) && !guestErr.contains("memory")
        if filter.isEmpty || fillName.localizedCaseInsensitiveContains(filter) {
            if saidOnce && namesM && notInGuest {
                print("PASS: \(fillName)"); passed += 1
            } else {
                print("FAIL: \(fillName)")
                print("      hint lines: \(lines(out, hint).count) unpaced, \(lines(paced, hint).count) paced (want 1 each)")
                let tail = paced.replacingOccurrences(of: "\r", with: "|").replacingOccurrences(of: "\n", with: "|")
                print("      paced run ended: \(tail.suffix(240))")
                if !namesM { print("      the hint does not name -M") }
                if !notInGuest { print("      program's stderr file: \(guestErr.prefix(200))") }
                failed += 1
            }
        }
    }

    for leftover in ["memflood.a", "memflood.r", "memflood", "memfill.a", "memfill.r", "memfill", "memfill.err"] {
        try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
    }
}

// ── module revision: a higher revision supersedes the resident module ─────────
// M$Revs, v2.4 Technical Manual: "If two modules with the same name and type
// are found in the memory search or loaded into memory, only the module with
// the highest revision level is kept. This enables easy substitution of modules
// for update or correction."
//
// Until 2026-08-24 os9exec kept whatever was already resident and discarded the
// module it had just loaded, revision unread -- so rebuilding a module and
// loading it did nothing, with no way to displace the old one. Both revisions
// stay in memory on purpose: a process already running holds a link to the old
// one and has to keep working. Only which one a SEARCH finds changes.
//
// The two modules must differ in revision and be otherwise interchangeable, so
// they are the same source assembled twice, and each prints its own revision --
// the assertion is which one RUNS, not what mdir lists. They are linked into
// separate directories because the module name comes from l68's -o=, not from
// the psect, so linking both as "revmod" is the only way to make the names
// collide.
do {
    func revSource(_ rev: Int, _ tag: String) -> String {
        [ "  use /dd/DEFS/oskdefs.d",
          "",
          "F$Exit   equ  $06",
          "I$WritLn equ  $8C",
          "",
          "  psect revmod,(Prgrm<<8)+Objct,(ReEnt<<8)+\(rev),1,512,start",
          "",
          "start:",
          "  lea     msg(pc),a0",
          "  moveq   #msgl,d1",
          "  moveq   #1,d0",
          "  OS9     I$WritLn",
          "  moveq   #0,d1",
          "  OS9     F$Exit",
          "",
          "msg:  dc.b  \"\(tag)\",$0D",
          "msgl  equ   *-msg",
          "",
          "  ends",
          "" ].joined(separator: "\r")
    }
    try? FileManager.default.createDirectory(atPath: scratchDisk + "/reva",
                                             withIntermediateDirectories: true)
    try? FileManager.default.createDirectory(atPath: scratchDisk + "/revb",
                                             withIntermediateDirectories: true)
    try? revSource(1, "THIS-IS-REV1").write(toFile: scratchDisk + "/rev1.a",
                                            atomically: true, encoding: .utf8)
    try? revSource(2, "THIS-IS-REV2").write(toFile: scratchDisk + "/rev2.a",
                                            atomically: true, encoding: .utf8)

    let build = [
        "load /dd/CMDS/r68 /dd/CMDS/l68",
        "r68 /h5/rev1.a -o=/h5/rev1.r",
        "r68 /h5/rev2.a -o=/h5/rev2.r",
        "l68 /h5/rev1.r -o=/h5/reva/revmod",
        "l68 /h5/rev2.r -o=/h5/revb/revmod",
    ]

    run("module: a higher revision supersedes the resident module",
        expectation: "contains: THIS-IS-REV2",
        commands: build + ["load /h5/reva/revmod", "load /h5/revb/revmod", "revmod"],
        timeout: 30) { $0.contains("THIS-IS-REV2") }

    // The companion, and it has to assert what the DISCARD branch controls, not
    // what the search does. Asserting "revmod still prints REV2" would be
    // vacuous: find_mod_id returns the highest revision either way, so that
    // passes even if the loader keeps every module it is handed -- verified by
    // sabotage. What the discard actually decides is whether a second copy
    // stays in memory, so count the entries: two after a higher revision is
    // loaded, still one after a lower one is refused.
    // Count only inside mdir's listing: the shell echoes every command, and the
    // build lines carry "revmod" in their -o= paths, so counting the whole
    // transcript counts those too.
    func mdirEntries(_ out: String) -> Int {
        guard let listing = out.range(of: "Module Directory", options: .backwards)
        else { return -1 }
        return out[listing.upperBound...].components(separatedBy: "revmod").count - 1
    }

    run("module: a superseding revision leaves both in memory",
        expectation: "mdir lists revmod twice",
        commands: build + ["load /h5/reva/revmod", "load /h5/revb/revmod", "mdir"],
        timeout: 30) { mdirEntries($0) == 2 }

    run("module: a lower revision is not kept at all",
        expectation: "mdir lists revmod once",
        commands: build + ["load /h5/revb/revmod", "load /h5/reva/revmod", "mdir"],
        timeout: 30) { mdirEntries($0) == 1 }

    for leftover in ["rev1.a", "rev2.a", "rev1.r", "rev2.r", "reva", "revb"] {
        try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
    }
}

// ── F$Alarm: a fired alarm kills an active process (no F$Icpt handler) ─────────
// 68k/syscall-reference.md flags this explicitly: A$Set's register contract and
// A$Delete were Live-verified, but "actual signal delivery on firing not
// exercised". F$Icpt (how a program would normally catch a delivered signal) is
// itself documented non-functional on os9exec, so a program with no real
// handler installed should be KILLED when an alarm fires (send_signal's
// documented no-handler fallback, confirmed by reading procstuff.c's
// send_signal()). Zero interval -- the check right after the very F$Alarm
// syscall that creates it sees it already due, so this needs no sleep/wait
// and isolates the fire-and-kill mechanism from any scheduling question.
do {
    let alAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "",
        "F$Exit   equ  $06",
        "F$Alarm  equ  $56",
        "I$WritLn equ  $8C",
        "",
        "  psect alfire1,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,512,start",
        "",
        "start:",
        "  clr.l   d0",
        "  move.w  #1,d1",           // A$Set
        "  move.w  #7,d2",           // sig=7, ordinary interceptable, no special name
        "  clr.l   d3",              // interval=0 -- due immediately
        "  OS9     F$Alarm",
        "  bcs     setfail",
        "  lea     nofiremsg(pc),a0",
        "  moveq   #nofiremsgl,d1",
        "  moveq   #1,d0",
        "  OS9     I$WritLn",
        "  bra     done",
        "setfail:",
        "  lea     setfailmsg(pc),a0",
        "  moveq   #setfailmsgl,d1",
        "  moveq   #1,d0",
        "  OS9     I$WritLn",
        "done:",
        "  moveq   #0,d1",
        "  OS9     F$Exit",
        "nofiremsg:   dc.b  \"ALARM DID NOT FIRE\",$0D",
        "nofiremsgl   equ   *-nofiremsg",
        "setfailmsg:  dc.b  \"A$SET FAILED\",$0D",
        "setfailmsgl  equ   *-setfailmsg",
        "",
        "  ends",
        ""
    ].joined(separator: "\r")

    let asmPath = scratchDisk + "/alfire1.a"
    try? alAsm.write(toFile: asmPath, atomically: true, encoding: .utf8)

    let name = "f$alarm: a fired alarm kills the owning process (no F$Icpt handler)"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let out = os9([
            "load /dd/CMDS/r68 /dd/CMDS/l68",
            "r68 /h5/alfire1.a -o=/h5/alfire1.r",
            "l68 /h5/alfire1.r -o=/h5/alfire1",
            "/h5/alfire1"
        ], timeout: 15)
        if !out.contains("ALARM DID NOT FIRE") && !out.contains("A$SET FAILED") && out != "(timeout)" {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            print("      [an alarm with a zero interval must fire and kill the process immediately]")
            let preview = out.split(separator: "\n")
                .filter { !$0.hasPrefix("#") && $0 != "$" && !$0.isEmpty }
                .prefix(8).joined(separator: " | ")
            print("      output: \(preview)")
            failed += 1
        }
    }

    for leftover in ["alfire1.a", "alfire1.r", "alfire1"] {
        try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
    }
}

// ── F$Alarm: a fired alarm interrupts a FINITE F$Sleep ─────────────────────────
// The actual bug this pair of tests found and this fix addresses: while every
// process in the system is asleep/blocked, os9exec_loop's own dispatch loop
// is not what's iterating -- do_arbitrate() (procstuff.c) blocks inside its
// own retry loop, calling DoWait() repeatedly until something's wakeUpTick
// expires, and control doesn't return to os9exec_loop (where the alarm queue
// used to be checked, only after an actual syscall dispatch) until then.
// Confirmed live before the fix: a 1-second alarm did not interrupt a
// 10-second F$Sleep -- the signal only arrived once the sleep expired
// naturally and the process made its own next syscall. Fixed by also checking
// CheckAlarms() inside DoWait() itself (alongside the existing CheckInputBuffers()
// call there, added for the identical reason on a different symptom -- see
// DoWait()'s own comment, procstuff.c).
do {
    let alAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "",
        "F$Exit   equ  $06",
        "F$Alarm  equ  $56",
        "F$Sleep  equ  $0A",
        "I$WritLn equ  $8C",
        "",
        "  psect alfire2,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,512,start",
        "",
        "start:",
        "  clr.l   d0",
        "  move.w  #1,d1",           // A$Set
        "  move.w  #7,d2",           // sig=7
        "  move.l  #100,d3",         // interval=100 ticks = 1 real second
        "  OS9     F$Alarm",
        "  bcs     setfail",
        "  move.l  #1000,d0",        // F$Sleep(1000) -- finite, ~10 real seconds
        "  OS9     F$Sleep",
        "  lea     nofiremsg(pc),a0",
        "  moveq   #nofiremsgl,d1",
        "  moveq   #1,d0",
        "  OS9     I$WritLn",
        "  bra     done",
        "setfail:",
        "  lea     setfailmsg(pc),a0",
        "  moveq   #setfailmsgl,d1",
        "  moveq   #1,d0",
        "  OS9     I$WritLn",
        "done:",
        "  moveq   #0,d1",
        "  OS9     F$Exit",
        "nofiremsg:   dc.b  \"ALARM DID NOT INTERRUPT FINITE SLEEP\",$0D",
        "nofiremsgl   equ   *-nofiremsg",
        "setfailmsg:  dc.b  \"A$SET FAILED\",$0D",
        "setfailmsgl  equ   *-setfailmsg",
        "",
        "  ends",
        ""
    ].joined(separator: "\r")

    let asmPath = scratchDisk + "/alfire2.a"
    try? alAsm.write(toFile: asmPath, atomically: true, encoding: .utf8)

    let name = "f$alarm: a fired alarm interrupts a finite F$Sleep (does not wait it out)"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let out = os9([
            "load /dd/CMDS/r68 /dd/CMDS/l68",
            "r68 /h5/alfire2.a -o=/h5/alfire2.r",
            "l68 /h5/alfire2.r -o=/h5/alfire2",
            "/h5/alfire2"
        ], timeout: 15)
        if !out.contains("ALARM DID NOT INTERRUPT FINITE SLEEP") && !out.contains("A$SET FAILED") && out != "(timeout)" {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            print("      [a 1-second alarm must interrupt a 10-second sleep, not wait it out]")
            let preview = out.split(separator: "\n")
                .filter { !$0.hasPrefix("#") && $0 != "$" && !$0.isEmpty }
                .prefix(8).joined(separator: " | ")
            print("      output: \(preview)")
            failed += 1
        }
    }

    for leftover in ["alfire2.a", "alfire2.r", "alfire2"] {
        try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
    }
}

// ── F$Alarm: an interval with the high bit set is 256ths of a second ──────────
// Technical Manual, F$Alarm (User-state System Calls 1-1): "If the high order
// bit is set, the low 31 bits are interpreted as 256ths of a second. NOTE: All
// times are rounded up to the nearest clock tick." A_Make stored d3 as raw
// ticks, so $80000100 (one second) was due about 2^31 ticks away and never
// fired. Every C program's alarm() takes this path: unix.l shifts the seconds
// left 8 and sets bit 31 (osk-freeware's atc froze on it). Same shape as the
// finite-sleep test above: no F$Icpt handler, so the alarm firing kills the
// process before the 10-second sleep ends and the message never prints.
do {
    for (funcCode, label) in [(1, "A$Set"), (2, "A$Cycle")] {
        let module = "al256\(funcCode)"
        let alAsm = [
            "  use /dd/DEFS/oskdefs.d",
            "",
            "F$Exit   equ  $06",
            "F$Alarm  equ  $56",
            "F$Sleep  equ  $0A",
            "I$WritLn equ  $8C",
            "",
            "  psect \(module),(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,512,start",
            "",
            "start:",
            "  clr.l   d0",
            "  move.w  #\(funcCode),d1",
            "  move.w  #7,d2",
            "  move.l  #$80000100,d3",   // one second, in 256ths
            "  OS9     F$Alarm",
            "  bcs     setfail",
            "  lea     armedmsg(pc),a0",
            "  moveq   #armedmsgl,d1",
            "  moveq   #1,d0",
            "  OS9     I$WritLn",
            "  move.l  #1000,d0",        // F$Sleep(1000) -- ~10 real seconds
            "  OS9     F$Sleep",
            "  lea     nofiremsg(pc),a0",
            "  moveq   #nofiremsgl,d1",
            "  moveq   #1,d0",
            "  OS9     I$WritLn",
            "  bra     done",
            "setfail:",
            "  lea     setfailmsg(pc),a0",
            "  moveq   #setfailmsgl,d1",
            "  moveq   #1,d0",
            "  OS9     I$WritLn",
            "done:",
            "  moveq   #0,d1",
            "  OS9     F$Exit",
            "armedmsg:    dc.b  \"256THS ALARM ARMED\",$0D",
            "armedmsgl    equ   *-armedmsg",
            "nofiremsg:   dc.b  \"256THS ALARM DID NOT FIRE\",$0D",
            "nofiremsgl   equ   *-nofiremsg",
            "setfailmsg:  dc.b  \"ALARM SET FAILED\",$0D",
            "setfailmsgl  equ   *-setfailmsg",
            "",
            "  ends",
            ""
        ].joined(separator: "\r")

        try? alAsm.write(toFile: scratchDisk + "/\(module).a", atomically: true, encoding: .utf8)

        let name = "f$alarm: \(label) with the high bit set counts 256ths of a second"
        if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
            let out = os9([
                "load /dd/CMDS/r68 /dd/CMDS/l68",
                "r68 /h5/\(module).a -o=/h5/\(module).r",
                "l68 /h5/\(module).r -o=/h5/\(module)",
                "/h5/\(module)"
            ], timeout: 30)
            // ARMED is required, not just the failure lines absent: a module
            // that never assembled or never ran prints neither failure line.
            if out.contains("256THS ALARM ARMED") && !out.contains("256THS ALARM DID NOT FIRE")
                && !out.contains("ALARM SET FAILED") && out != "(timeout)" {
                print("PASS: \(name)")
                passed += 1
            } else {
                print("FAIL: \(name)")
                print("      [d3=$80000100 is one second; the alarm must end a 10-second sleep]")
                print("      armed=\(out.contains("256THS ALARM ARMED")) "
                      + "notFired=\(out.contains("256THS ALARM DID NOT FIRE")) timeout=\(out == "(timeout)")")
                let preview = out.split(separator: "\n")
                    .filter { !$0.hasPrefix("#") && $0 != "$" && !$0.isEmpty }
                    .prefix(8).joined(separator: " | ")
                print("      output: \(preview)")
                failed += 1
            }
        }

        for suffix in [".a", ".r", ""] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/\(module)" + suffix)
        }
    }
}

// ── F$Alarm: alarm IDs, A$Delete of all, a cyclic alarm's ID, and alarms at exit ──
// Technical Manual, F$Alarm (pp.1-1, 1-2): "A$Delete removes a cyclic alarm, or
// any alarm that has not expired. If zero is passed as the alarm ID, all pending
// alarm requests are removed", and "The system automatically deletes a process's
// pending alarms when the process dies". Found by the 2026-09-15 argument audit,
// each probed live:
//  - the first alarm got ID 0, so it could never be deleted by itself, and
//    A$Delete(0) removed that one alarm instead of all of them;
//  - a cyclic alarm was re-made in a new slot each time it fired, so A$Delete of
//    the ID A$Cycle returned missed it (E$BPAddr) and it kept firing;
//  - A_Kill skipped every second alarm of a dying process, and the survivors
//    fired at the next process to get its ID (Error #001:044, signal 300).
do {
    let header = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit   equ $06", "F$Icpt   equ $09", "F$Sleep  equ $0A", "F$RTE    equ $1E",
        "F$Alarm  equ $56", "I$WritLn equ $8C",
        "CNT      equ -32768"
    ]
    func say(_ label: String) -> [String] {
        ["  lea \(label)(pc),a0", "  moveq #\(label)l,d1", "  moveq #1,d0", "  OS9 I$WritLn"]
    }
    func message(_ label: String, _ text: String) -> [String] {
        ["\(label): dc.b \"\(text)\",$0D", "\(label)l equ *-\(label)"]
    }

    // 1. IDs are never 0; A$Delete(0) removes every pending alarm of the caller.
    let delAll = header + [
        "  psect aldall,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  moveq #0,d0", "  move.w #1,d1", "  move.l #300,d2", "  move.l #10000,d3", "  OS9 F$Alarm",
        "  bcs.w done", "  move.l d0,d5",
        "  moveq #0,d0", "  move.w #1,d1", "  move.l #300,d2", "  move.l #10000,d3", "  OS9 F$Alarm",
        "  bcs.w done", "  move.l d0,d6",
        "  tst.l d5", "  beq.s idzero", "  tst.l d6", "  bne.s idok",
        "idzero:"] + say("mzero") + [
        "idok:",
        "  moveq #0,d0", "  move.w #0,d1", "  OS9 F$Alarm",          // A$Delete(0): all
        "  bcc.s delok"] + say("mdel0") + [
        "delok:",
        "  move.l d6,d0", "  move.w #0,d1", "  OS9 F$Alarm",         // must be gone already
        "  bcs.s gone"] + say("mleft") + [
        "gone:"] + say("mdone") + [
        "done:",
        "  moveq #0,d1", "  OS9 F$Exit"] +
        message("mzero", "ALARM ID ZERO") + message("mdel0", "DELETE ALL FAILED") +
        message("mleft", "DELETE ALL LEFT AN ALARM") + message("mdone", "DELALL DONE") + ["  ends", ""]

    // 2. A cyclic alarm keeps the ID A$Cycle returned, so A$Delete stops it.
    let cyclic = header + [
        "  psect alcdel,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  lea icpt(pc),a0", "  OS9 F$Icpt", "  clr.l CNT(a6)",
        "  moveq #0,d0", "  move.w #2,d1", "  move.l #300,d2", "  moveq #5,d3", "  OS9 F$Alarm",
        "  bcs.w done", "  move.l d0,d5",
        "wait1:", "  moveq #2,d0", "  OS9 F$Sleep", "  cmpi.l #3,CNT(a6)", "  blo.s wait1",
        "  move.l d5,d0", "  move.w #0,d1", "  OS9 F$Alarm",
        "  bcc.s delok"] + say("mfail") + [
        "delok:",
        "  move.l CNT(a6),d4", "  addq.l #1,d4",                     // one in flight is fine
        "  moveq #30,d6",
        "wait2:", "  moveq #2,d0", "  OS9 F$Sleep", "  subq.l #1,d6", "  bne.s wait2",
        "  cmp.l CNT(a6),d4", "  bhs.s quiet"] + say("mfire") + [
        "quiet:"] + say("mdone") + [
        "done:",
        "  moveq #0,d1", "  OS9 F$Exit",
        "icpt:", "  addq.l #1,CNT(a6)", "  OS9 F$RTE"] +
        message("mfail", "CYCLIC DELETE FAILED") + message("mfire", "CYCLIC STILL FIRING") +
        message("mdone", "CYCLIC DONE") + ["  ends", ""]

    // 3. Alarms die with their process: three pending at exit, then the next
    //    process (which gets the same ID) sleeps past all of them.
    let leaver = header + [
        "  psect alleav,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  moveq #0,d0", "  move.w #1,d1", "  move.l #300,d2", "  move.l #150,d3", "  OS9 F$Alarm",
        "  moveq #0,d0", "  move.w #1,d1", "  move.l #300,d2", "  move.l #160,d3", "  OS9 F$Alarm",
        "  moveq #0,d0", "  move.w #1,d1", "  move.l #300,d2", "  move.l #170,d3", "  OS9 F$Alarm",
        "  moveq #0,d1", "  OS9 F$Exit", "  ends", ""]
    let sleeper = header + [
        "  psect alslep,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  move.l #400,d0", "  OS9 F$Sleep"] + say("mdone") + [
        "  moveq #0,d1", "  OS9 F$Exit"] + message("mdone", "SURVIVED") + ["  ends", ""]

    let modules = ["aldall": delAll, "alcdel": cyclic, "alleav": leaver, "alslep": sleeper]
    for (module, lines) in modules {
        try? lines.joined(separator: "\r").write(toFile: scratchDisk + "/\(module).a",
                                                  atomically: true, encoding: .utf8)
    }
    var build = ["load /dd/CMDS/r68 /dd/CMDS/l68"]
    for module in modules.keys.sorted() {
        build += ["r68 /h5/\(module).a -o=/h5/\(module).r", "l68 /h5/\(module).r -o=/h5/\(module)"]
    }

    struct AlarmCase {
        let name: String
        let commands: [String]
        let pass: (String) -> Bool
    }
    let cases = [
        AlarmCase(name: "f$alarm: IDs are never 0, and A$Delete of 0 removes every pending alarm",
                  commands: ["/h5/aldall"]) {
            $0.contains("DELALL DONE") && !$0.contains("ALARM ID ZERO")
                && !$0.contains("DELETE ALL FAILED") && !$0.contains("DELETE ALL LEFT AN ALARM")
        },
        AlarmCase(name: "f$alarm: a cyclic alarm keeps its ID, so A$Delete stops it after it has fired",
                  commands: ["/h5/alcdel"]) {
            $0.contains("CYCLIC DONE") && !$0.contains("CYCLIC DELETE FAILED")
                && !$0.contains("CYCLIC STILL FIRING")
        },
        AlarmCase(name: "f$alarm: every pending alarm dies with its process, none reaches the next",
                  commands: ["/h5/alleav", "/h5/alslep"]) {
            $0.contains("SURVIVED") && !$0.contains("#001:044")
        }
    ]
    let wanted = cases.contains { filter.isEmpty || $0.name.localizedCaseInsensitiveContains(filter) }
    if wanted { _ = os9(build, timeout: 60) }
    for testCase in cases where filter.isEmpty || testCase.name.localizedCaseInsensitiveContains(filter) {
        let out = os9(testCase.commands, timeout: 30)
        if testCase.pass(out) {
            print("PASS: \(testCase.name)")
            passed += 1
        } else {
            print("FAIL: \(testCase.name)")
            let lines = out.split(whereSeparator: \.isNewline).filter {
                !$0.hasPrefix("#") && $0 != "$" && !$0.isEmpty
            }
            print("      saw: \(lines.suffix(8).joined(separator: " | "))")
            failed += 1
        }
    }
    for module in modules.keys {
        for suffix in [".a", ".r", ""] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/\(module)" + suffix)
        }
    }
}

// ── output registers: a0 after I$Delete/I$MakDir/I$ChgDir and Ev$Link; F$STime ──
// Technical Manual: I$Delete, I$MakDir and I$ChgDir return "(a0) = Updated past
// pathlist" (pp.2-7, 2-15, 2-3), Ev$Link returns "(a0) = updated past event name"
// (p.1-19), and "registers not explicitly specified as input or output parameters
// are not altered" (p.ii). Found by the 2026-09-15 argument audit: the three path
// calls left a0 where it was, Ev$Link too, and F$STime handed back d0 and d1
// converted to seconds-since-midnight and a Julian day. The path checks compare
// against I$Open on the same name, which already returns a0 the documented way.
do {
    let header = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit   equ $06", "F$STime  equ $16", "F$Event  equ $53",
        "I$Open   equ $84", "I$Create equ $83", "I$MakDir equ $85", "I$ChgDir equ $86",
        "I$Delete equ $87", "I$Close  equ $8F", "I$WritLn equ $8C"
    ]
    func say(_ label: String) -> [String] {
        ["  lea \(label)(pc),a0", "  moveq #\(label)l,d1", "  moveq #1,d0", "  OS9 I$WritLn"]
    }
    func message(_ label: String, _ text: String) -> [String] {
        ["\(label): dc.b \"\(text)\",$0D", "\(label)l equ *-\(label)"]
    }
    // a0 minus the name's address after the call, into <reg>
    func advance(_ reg: String) -> [String] { ["  move.l a0,\(reg)", "  sub.l a1,\(reg)"] }

    let paths = header + [
        "  psect rgpath,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  lea dname(pc),a1", "  movea.l a1,a0", "  moveq #3,d0", "  moveq #0,d1", "  OS9 I$MakDir",
        "  bcs.w fail"] + advance("d5") + [
        "  lea dname(pc),a1", "  movea.l a1,a0", "  move.w #$81,d0", "  OS9 I$Open",
        "  bcs.w fail"] + advance("d3") + [
        "  OS9 I$Close",
        "  cmp.l d3,d5", "  beq.s mkok"] + say("mmkbad") + ["  bra.s mkdone", "mkok:"] + say("mmkok") + [
        "mkdone:",
        "  lea dname(pc),a1", "  movea.l a1,a0", "  moveq #1,d0", "  OS9 I$ChgDir",
        "  bcs.w fail"] + advance("d5") + [
        "  cmp.l d3,d5", "  beq.s cdok"] + say("mcdbad") + ["  bra.s cddone", "cdok:"] + say("mcdok") + [
        "cddone:",
        "  lea fname(pc),a0", "  moveq #3,d0", "  moveq #$1B,d1", "  OS9 I$Create",
        "  bcs.w fail", "  OS9 I$Close",
        "  lea fname(pc),a1", "  movea.l a1,a0", "  moveq #1,d0", "  OS9 I$Open",
        "  bcs.w fail"] + advance("d3") + [
        "  OS9 I$Close",
        "  lea fname(pc),a1", "  movea.l a1,a0", "  moveq #2,d0", "  OS9 I$Delete",
        "  bcs.w fail"] + advance("d5") + [
        "  cmp.l d3,d5", "  beq.s dlok"] + say("mdlbad") + ["  bra.s dldone", "dlok:"] + say("mdlok") + [
        "dldone:",
        "  moveq #0,d1",
        "fail:", "  OS9 F$Exit",
        "dname: dc.b \"/h5/rgdir\",0",
        "fname: dc.b \"/h5/rgdir/rgf\",0"] +
        message("mmkbad", "MAKDIR A0 NOT ADVANCED") + message("mmkok", "MAKDIR A0 OK") +
        message("mcdbad", "CHGDIR A0 NOT ADVANCED") + message("mcdok", "CHGDIR A0 OK") +
        message("mdlbad", "DELETE A0 NOT ADVANCED") + message("mdlok", "DELETE A0 OK") + ["  ends", ""]

    let stime = header + [
        "  psect rgstim,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  move.l #$00123456,d0", "  move.l #$07EA090F,d1", "  OS9 F$STime",
        "  bcs.s fail",
        "  cmpi.l #$00123456,d0", "  bne.s changed", "  cmpi.l #$07EA090F,d1", "  bne.s changed"] +
        say("mkept") + ["  bra.s done", "changed:"] + say("mchg") + [
        "done:", "  moveq #0,d1",
        "fail:", "  OS9 F$Exit"] +
        message("mkept", "STIME KEPT D0 D1") + message("mchg", "STIME CHANGED D0 D1") + ["  ends", ""]

    let evlink = header + [
        "  psect rgevln,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  lea ename(pc),a0", "  moveq #0,d0", "  move.w #2,d1", "  moveq #0,d2", "  moveq #0,d3",
        "  OS9 F$Event",                                            // Ev$Creat
        "  bcs.s fail",
        "  lea ename(pc),a1", "  movea.l a1,a0", "  move.w #0,d1", "  OS9 F$Event",  // Ev$Link
        "  bcs.s fail"] + advance("d5") + [
        "  move.l d0,d6",
        "  cmpi.l #\(4),d5", "  beq.s lnok"] + say("mlnbad") + ["  bra.s lndone", "lnok:"] + say("mlnok") + [
        "lndone:",
        "  move.l d6,d0", "  move.w #1,d1", "  OS9 F$Event",         // Ev$UnLnk (the link)
        "  move.l d6,d0", "  move.w #1,d1", "  OS9 F$Event",         // Ev$UnLnk (the create)
        "  lea ename(pc),a0", "  move.w #3,d1", "  OS9 F$Event",      // Ev$Delet
        "  moveq #0,d1",
        "fail:", "  OS9 F$Exit",
        "ename: dc.b \"rgev\",0"] +
        message("mlnbad", "EVLINK A0 NOT ADVANCED") + message("mlnok", "EVLINK A0 OK") + ["  ends", ""]

    let modules = ["rgpath": paths, "rgstim": stime, "rgevln": evlink]
    for (module, lines) in modules {
        try? lines.joined(separator: "\r").write(toFile: scratchDisk + "/\(module).a",
                                                  atomically: true, encoding: .utf8)
    }

    struct RegisterCase {
        let name: String
        let module: String
        let want: [String]
    }
    let cases = [
        RegisterCase(name: "io: I$MakDir, I$ChgDir and I$Delete return a0 updated past the pathlist",
                     module: "rgpath", want: ["MAKDIR A0 OK", "CHGDIR A0 OK", "DELETE A0 OK"]),
        RegisterCase(name: "time: F$STime leaves d0 and d1 as they were passed",
                     module: "rgstim", want: ["STIME KEPT D0 D1"]),
        RegisterCase(name: "event: Ev$Link returns a0 updated past the event name",
                     module: "rgevln", want: ["EVLINK A0 OK"])
    ]
    let chosen = cases.filter { filter.isEmpty || $0.name.localizedCaseInsensitiveContains(filter) }
    if !chosen.isEmpty {
        var build = ["load /dd/CMDS/r68 /dd/CMDS/l68"]
        for testCase in chosen {
            build += ["r68 /h5/\(testCase.module).a -o=/h5/\(testCase.module).r",
                      "l68 /h5/\(testCase.module).r -o=/h5/\(testCase.module)"]
        }
        _ = os9(build, timeout: 60)
    }
    for testCase in chosen {
        removeScratchItem("rgdir/rgf")
        removeScratchItem("rgdir")
        let out = os9(["/h5/\(testCase.module)"], timeout: 30)
        if testCase.want.allSatisfy({ out.contains($0) }) {
            print("PASS: \(testCase.name)")
            passed += 1
        } else {
            print("FAIL: \(testCase.name)")
            let lines = out.split(whereSeparator: \.isNewline).filter {
                !$0.hasPrefix("#") && $0 != "$" && !$0.isEmpty
            }
            print("      saw: \(lines.suffix(8).joined(separator: " | "))")
            failed += 1
        }
    }
    removeScratchItem("rgdir/rgf")
    removeScratchItem("rgdir")
    for module in modules.keys {
        for suffix in [".a", ".r", ""] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/\(module)" + suffix)
        }
    }
}

// ── time: F$Gregor keeps 1900 and 2100 out of the leap years ──────────────────
// g_date gave February 29 days whenever the year divided by 4, so 1700, 1800,
// 1900 and 2100 had a 29th of February: F$Gregor turned the Julian day of
// 1900-03-01 into 1900-02-29, and every later day of those years came out one
// day early. Found by the 2026-09-15 argument audit. The Julian numbers are
// checked against values worked out outside the emulator (standard JDN - 1, the
// epoch the manual's weekday formula implies), so the test is not only a round
// trip through os9exec; 2000-03-01 is a control that was right before the fix.
do {
    struct CalendarDate { let label: String; let packed: UInt32; let julian: UInt32 }
    let dates = [
        CalendarDate(label: "1900", packed: 0x076C_0301, julian: 0x24D9E7),
        CalendarDate(label: "2100", packed: 0x0834_0301, julian: 0x25F740),
        CalendarDate(label: "2000", packed: 0x07D0_0301, julian: 0x256894)
    ]
    func hex(_ value: UInt32) -> String { "$" + String(value, radix: 16, uppercase: true) }
    var lines = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit   equ $06", "F$Julian equ $20", "F$Gregor equ $54", "I$WritLn equ $8C",
        "  psect clgreg,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:"
    ]
    func say(_ label: String) -> [String] {
        ["  lea \(label)(pc),a0", "  moveq #\(label)l,d1", "  moveq #1,d0", "  OS9 I$WritLn"]
    }
    for date in dates {
        let tag = date.label
        lines += ["  moveq #0,d0", "  move.l #\(hex(date.packed)),d1", "  OS9 F$Julian", "  bcs.w fail",
                  "  cmpi.l #\(hex(date.julian)),d1", "  beq.s jok\(tag)"] + say("mjb\(tag)") + [
                  "jok\(tag):",
                  "  moveq #0,d0", "  move.l #\(hex(date.julian)),d1", "  OS9 F$Gregor", "  bcs.w fail",
                  "  cmpi.l #\(hex(date.packed)),d1", "  beq.s gok\(tag)"] + say("mgb\(tag)") + [
                  "  bra.s gdn\(tag)", "gok\(tag):"] + say("mgo\(tag)") + ["gdn\(tag):"]
    }
    lines += ["  moveq #0,d1", "fail:", "  OS9 F$Exit"]
    for date in dates {
        let tag = date.label
        for (label, text) in [("mjb\(tag)", "JULIAN \(tag) BAD"), ("mgb\(tag)", "GREGOR \(tag) BAD"),
                              ("mgo\(tag)", "GREGOR \(tag) OK")] {
            lines += ["\(label): dc.b \"\(text)\",$0D", "\(label)l equ *-\(label)"]
        }
    }
    lines += ["  ends", ""]
    try? lines.joined(separator: "\r").write(toFile: scratchDisk + "/clgreg.a", atomically: true, encoding: .utf8)

    let name = "time: F$Gregor keeps 1900 and 2100 out of the leap years"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let out = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                       "r68 /h5/clgreg.a -o=/h5/clgreg.r", "l68 /h5/clgreg.r -o=/h5/clgreg",
                       "/h5/clgreg"], timeout: 60)
        let good = dates.allSatisfy { out.contains("GREGOR \($0.label) OK") } && !out.contains(" BAD")
        if good {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = out.split(whereSeparator: \.isNewline).filter {
                $0.contains("GREGOR") || $0.contains("JULIAN") || $0.contains("Error #")
            }
            print("      saw: \(seen.joined(separator: " | "))")
            failed += 1
        }
    }
    for suffix in [".a", ".r", ""] {
        try? FileManager.default.removeItem(atPath: scratchDisk + "/clgreg" + suffix)
    }
}

// ── F$Link link count on a type refusal, F$Panic, F$SRqMem wrap, I$ChgDir mode 5 ──
// Found by the 2026-09-15 argument audit, each probed live:
//  - F$Link with a type/language the module does not have returned E$MNF after
//    link_module had already counted a link, so each refusal left the module one
//    link higher and it could never be unlinked away;
//  - F$Panic is a system-state call (Technical Manual p.3-16), but from a user
//    program it entered the interactive debugger, which read the rest of stdin;
//  - F$SRqMem rounded $FFFFFFF8 up to 0 and granted a zero-byte block;
//  - I$ChgDir with read and execute changed only the execution directory, where
//    "Both can change simultaneously" (p.2-3).
do {
    let header = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit   equ $06", "F$Link   equ $00", "F$SRqMem equ $28", "F$Panic  equ $5E",
        "I$Open   equ $84", "I$ChgDir equ $86", "I$Close  equ $8F", "I$WritLn equ $8C"
    ]
    func say(_ label: String) -> [String] {
        ["  lea \(label)(pc),a0", "  moveq #\(label)l,d1", "  moveq #1,d0", "  OS9 I$WritLn"]
    }
    func message(_ label: String, _ text: String) -> [String] {
        ["\(label): dc.b \"\(text)\",$0D", "\(label)l equ *-\(label)"]
    }
    let linkRefused = header + [
        "  psect mlrefu,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:", "  moveq #3,d7",
        "again:",
        "  lea mname(pc),a0", "  move.w #$0400,d0", "  OS9 F$Link",   // binex is a program, not data
        "  bcc.s linked"] + say("mref") + ["  bra.s next", "linked:"] + say("macc") + [
        "next:", "  subq.l #1,d7", "  bne.s again",
        "  moveq #0,d1", "  OS9 F$Exit",
        "mname: dc.b \"binex\",0"] + message("mref", "LINK REFUSED") + message("macc", "LINK ACCEPTED") +
        ["  ends", ""]
    let panic = header + [
        "  psect mpanic,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  moveq #0,d0", "  OS9 F$Panic",
        "  bcc.s taken", "  cmpi.w #208,d1", "  bne.s taken"] + say("mref") +
        ["  bra.s done", "taken:"] + say("mtak") + [
        "done:", "  moveq #0,d1", "  OS9 F$Exit"] +
        message("mref", "PANIC REFUSED") + message("mtak", "PANIC NOT REFUSED") + ["  ends", ""]
    let srqmem = header + [
        "  psect msrqwr,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  move.l #$FFFFFFF8,d0", "  OS9 F$SRqMem",
        "  bcs.s refused"] + say("mgrant") + ["  bra.s done", "refused:"] + say("mref") + [
        "done:", "  moveq #0,d1", "  OS9 F$Exit"] +
        message("mgrant", "SRQMEM GRANTED A WRAPPED SIZE") + message("mref", "SRQMEM REFUSED") + ["  ends", ""]
    let chgdir = header + [
        "  psect mcdboth,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  lea dname(pc),a0", "  moveq #5,d0", "  OS9 I$ChgDir", "  bcs.w fail",
        "  lea fname(pc),a0", "  moveq #1,d0", "  OS9 I$Open",           // from the data directory
        "  bcs.s nodata", "  OS9 I$Close"] + say("mdata") + [
        "nodata:",
        "  lea fname(pc),a0", "  moveq #5,d0", "  OS9 I$Open",           // from the execution directory
        "  bcs.s noexec", "  OS9 I$Close"] + say("mexec") + [
        "noexec:", "  moveq #0,d1",
        "fail:", "  OS9 F$Exit",
        "dname: dc.b \"/h5/cdboth\",0",
        "fname: dc.b \"only5\",0"] +
        message("mdata", "DATA DIR CHANGED") + message("mexec", "EXEC DIR CHANGED") + ["  ends", ""]

    // F$Link of an INTERNAL command name (os9exec's own `pwd`, not a module on
    // any disk). The shell links a command before forking it, so this cannot
    // answer E$MNF -- but it used to answer success with a NULL module pointer
    // and entry point, and a caller that read them died: `which pwd` took a bus
    // error. What comes back must be a real module: a2 and a1 set, and $4AFC
    // (MODSYNC) at a2.
    let linkInternal = header + [
        "  psect mlint,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  lea iname(pc),a0", "  moveq #0,d0", "  OS9 F$Link", "  bcs.s refused",
        "  move.l a2,d2", "  beq.s gavenull",
        "  move.l a1,d3", "  beq.s gavenull",
        "  movea.l a2,a0", "  cmpi.w #$4AFC,(a0)", "  bne.s notmod"] + say("mok") + [
        "  bra.s done",
        "gavenull:"] + say("mnull") + ["  bra.s done",
        "notmod:"] + say("mbad") + ["  bra.s done",
        "refused:"] + say("mref") + [
        "done:", "  moveq #0,d1", "  OS9 F$Exit",
        "iname: dc.b \"pwd\",0"] +
        message("mok", "LINK GAVE A MODULE") + message("mnull", "LINK GAVE NULL") +
        message("mbad", "LINK GAVE A NON-MODULE") + message("mref", "LINK REFUSED") + ["  ends", ""]

    let modules = ["mlrefu": linkRefused, "mpanic": panic, "msrqwr": srqmem, "mcdboth": chgdir,
                   "mlint": linkInternal]
    for (module, lines) in modules {
        try? lines.joined(separator: "\r").write(toFile: scratchDisk + "/\(module).a",
                                                  atomically: true, encoding: .utf8)
    }

    struct CallCase {
        let name: String
        let module: String
        let commands: [String]
        let timeout: TimeInterval
        let pass: (String) -> Bool
    }
    let cases = [
        CallCase(name: "module: F$Link refused on type leaves the link count as it was", module: "mlrefu",
                 commands: ["load /dd/CMDS/binex", "/h5/mlrefu", "unlink binex", "mdir -e"],
                 timeout: 30) { out in
            // one unlink after the load must bring binex's link count to 0: a
            // leaked link leaves it at 1. binex is sticky (attr $C0), so at 0 it
            // stays listed; mdir -e's Lnk column is the one before the name.
            return out.contains("LINK REFUSED") && !out.contains("LINK ACCEPTED") &&
                   mdirLinks(of: "binex", in: out) ?? 0 == 0
        },
        CallCase(name: "module: F$Link of an internal command hands back a real module", module: "mlint",
                 commands: ["/h5/mlint", "pwd"], timeout: 20) {
            // and the internal command still runs from the shell, which is why
            // this cannot simply answer E$MNF
            $0.contains("LINK GAVE A MODULE") && !$0.contains("can't execute")
        },
        CallCase(name: "module: F$Panic from a user program is refused, not the debugger", module: "mpanic",
                 commands: ["/h5/mpanic", "echo AFTER-PANIC"], timeout: 20) {
            $0.contains("PANIC REFUSED") && $0.contains("AFTER-PANIC")
        },
        CallCase(name: "memory: F$SRqMem refuses a size whose rounding wraps past zero", module: "msrqwr",
                 commands: ["/h5/msrqwr"], timeout: 30) {
            $0.contains("SRQMEM REFUSED")
        },
        CallCase(name: "io: I$ChgDir with read and execute changes both directories", module: "mcdboth",
                 commands: ["/h5/mcdboth"], timeout: 30) {
            $0.contains("DATA DIR CHANGED") && $0.contains("EXEC DIR CHANGED")
        }
    ]
    let chosen = cases.filter { filter.isEmpty || $0.name.localizedCaseInsensitiveContains(filter) }
    if !chosen.isEmpty {
        var build = ["load /dd/CMDS/r68 /dd/CMDS/l68"]
        for testCase in chosen {
            build += ["r68 /h5/\(testCase.module).a -o=/h5/\(testCase.module).r",
                      "l68 /h5/\(testCase.module).r -o=/h5/\(testCase.module)"]
        }
        _ = os9(build, timeout: 60)
        try? FileManager.default.createDirectory(atPath: scratchDisk + "/cdboth", withIntermediateDirectories: true)
        try? "x\r".write(toFile: scratchDisk + "/cdboth/only5", atomically: true, encoding: .utf8)
    }
    for testCase in chosen {
        let out = os9(testCase.commands, timeout: testCase.timeout)
        if testCase.pass(out) {
            print("PASS: \(testCase.name)")
            passed += 1
        } else {
            print("FAIL: \(testCase.name)")
            let lines = out.split(whereSeparator: \.isNewline).filter {
                !$0.hasPrefix("#") && $0 != "$" && !$0.isEmpty
            }
            let telling = lines.filter {
                $0.contains("LINK") || $0.contains("PANIC") || $0.contains("SRQMEM") || $0.contains("DIR ")
                    || $0.contains("Error") || $0.contains(testCase.module) || $0.contains("binex")
            }
            print("      saw: \(telling.joined(separator: " | "))")
            failed += 1
        }
    }
    removeScratchItem("cdboth")
    for module in modules.keys {
        for suffix in [".a", ".r", ""] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/\(module)" + suffix)
        }
    }
}

// ── GetStat/SetStat bounds: SS_FD's byte count, pipe SS_FDInf, SS_WTrk's track ──
// Found by the 2026-09-15 argument audit, each probed live:
//  - SS_FD / SS_FDInf copy "d2.w = Number of bytes to copy (<=logical sector
//    size of media)" (Technical Manual pp.2-11, 2-12); RBF handed the full
//    32-bit d2 to memcpy, so a stray upper word read past the 2048-byte host FD
//    buffer and wrote over guest memory;
//  - a pipe's SS_FDInf used d3 as an index into the system path table with no
//    bound: d3=$00100000 faulted the host (the guest saw a bus error);
//  - SS_WTrk "formats the entire media only when side 0 of the first accessable
//    track is specified" (p.2-29), but os9exec formatted from any track to the
//    END of the device: track 1 wiped a mount -k image from byte 16384 on.
do {
    let header = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit   equ $06", "I$Open   equ $84", "I$Close  equ $8F", "I$GetStt equ $8D",
        "I$SetStt equ $8E", "I$WritLn equ $8C",
        "BUF      equ -32700", "BUF16    equ -32684"
    ]
    func say(_ label: String) -> [String] {
        ["  lea \(label)(pc),a0", "  moveq #\(label)l,d1", "  moveq #1,d0", "  OS9 I$WritLn"]
    }
    func message(_ label: String, _ text: String) -> [String] {
        ["\(label): dc.b \"\(text)\",$0D", "\(label)l equ *-\(label)"]
    }
    let fdCount = header + [
        "  psect msfdcp,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  lea BUF(a6),a1", "  moveq #31,d2",
        "fill:", "  move.b #$AA,(a1)+", "  dbra d2,fill",
        "  lea fname(pc),a0", "  moveq #1,d0", "  OS9 I$Open", "  bcs.w fail", "  move.w d0,d7",
        "  move.w d7,d0", "  move.w #$0F,d1", "  move.l #$00010010,d2", "  lea BUF(a6),a0",
        "  OS9 I$GetStt", "  bcs.w fail",
        "  lea BUF16(a6),a1", "  moveq #15,d2",
        "check:", "  cmpi.b #$AA,(a1)+", "  bne.s over", "  dbra d2,check"] + say("mkept") + [
        "  bra.s done", "over:"] + say("mover") + [
        "done:", "  moveq #0,d1",
        "fail:", "  OS9 F$Exit",
        "fname: dc.b \"/hq/fdcap\",0"] +
        message("mkept", "SS_FD KEPT TO D2.W") + message("mover", "SS_FD OVERRAN") + ["  ends", ""]
    let pipeInfo = header + [
        "  psect mspipe,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  lea pname(pc),a0", "  moveq #3,d0", "  OS9 I$Open", "  bcs.w fail", "  move.w d0,d7",
        "  move.w d7,d0", "  move.w #$20,d1", "  moveq #16,d2", "  move.l #$00100000,d3", "  lea BUF(a6),a0",
        "  OS9 I$GetStt", "  bcs.s refused"] + say("macc") + ["  bra.s done", "refused:"] + say("mref") + [
        "done:", "  moveq #0,d1",
        "fail:", "  OS9 F$Exit",
        "pname: dc.b \"/pipe\",0"] +
        message("macc", "PIPE FDINF ACCEPTED") + message("mref", "PIPE FDINF REFUSED") + ["  ends", ""]
    let writeTrack = header + [
        "  psect mswtrk,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  lea rname(pc),a0", "  moveq #3,d0", "  OS9 I$Open", "  bcs.w fail", "  move.w d0,d7",
        "  move.w d7,d0", "  move.w #$04,d1", "  moveq #1,d2", "  lea BUF(a6),a0", "  lea BUF(a6),a1",
        "  moveq #0,d3", "  moveq #0,d4",
        "  OS9 I$SetStt",                                     // the result is not the point
        "  move.w d7,d0", "  OS9 I$Close"] + say("mdone") + [
        "  moveq #0,d1",
        "fail:", "  OS9 F$Exit",
        "rname: dc.b \"/hq@\",0"] + message("mdone", "WTRK DONE") + ["  ends", ""]

    let modules = ["msfdcp": fdCount, "mspipe": pipeInfo, "mswtrk": writeTrack]
    for (module, lines) in modules {
        try? lines.joined(separator: "\r").write(toFile: scratchDisk + "/\(module).a",
                                                  atomically: true, encoding: .utf8)
    }
    let names = [
        "rbf: GetStt SS_FD copies d2.w bytes, not the whole d2",
        "pipe: GetStt SS_FDInf refuses a path number past the table",
        "rbf: SetStt SS_WTrk on a later track leaves the media alone"
    ]
    let chosen = names.filter { filter.isEmpty || $0.localizedCaseInsensitiveContains(filter) }
    func report(_ name: String, _ good: Bool, _ out: String) {
        if good {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let lines = out.split(whereSeparator: \.isNewline).filter {
                $0.contains("SS_FD") || $0.contains("FDINF") || $0.contains("WTRK") || $0.contains("Bytes")
                    || $0.contains("Differences") || $0.contains("Error")
            }
            print("      saw: \(lines.joined(separator: " | "))")
            failed += 1
        }
    }
    if !chosen.isEmpty {
        var build = ["load /dd/CMDS/r68 /dd/CMDS/l68"]
        for module in modules.keys.sorted() {
            build += ["r68 /h5/\(module).a -o=/h5/\(module).r", "l68 /h5/\(module).r -o=/h5/\(module)"]
        }
        _ = os9(build, timeout: 60)
    }
    if chosen.contains(names[0]) {
        removeScratchItem("hq")
        let out = os9(["mount -k=1M hq", "echo hi >/hq/fdcap", "/h5/msfdcp"], timeout: 30)
        report(names[0], out.contains("SS_FD KEPT TO D2.W"), out)
    }
    if chosen.contains(names[1]) {
        let out = os9(["/h5/mspipe"], timeout: 30)
        report(names[1], out.contains("PIPE FDINF REFUSED"), out)
    }
    if chosen.contains(names[2]) {
        // three runs, so no sector cache can stand between the format and cmp
        removeScratchItem("hq")
        _ = os9(["mount -k=1M hq", "copy /dd/CMDS/shell /hq/big"], timeout: 30)
        let formatted = os9(["/h5/mswtrk"], timeout: 30)
        let compared = os9(["cmp /dd/CMDS/shell /hq/big"], timeout: 30)
        report(names[2], formatted.contains("WTRK DONE") && compared.contains("Bytes different: 00000000")
                   && !compared.contains("Differences"), formatted + compared)
    }
    removeScratchItem("hq")
    for module in modules.keys {
        for suffix in [".a", ".r", ""] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/\(module)" + suffix)
        }
    }
}

// ── host-dir SS_Ready, F$DatMod's type, F$CCtl's reserved bits ─────────────────
// Found by the 2026-09-15 argument audit, each probed live:
//  - "RBF devices always return carry clear, d1.l=1" (I$GetStt SS_Ready,
//    p.2-13), but a host directory -- which reports itself as RBF -- said E$UnkSvc;
//  - F$DatMod's "d3.w = desired type/language (optional)" (p.1-12) was ignored,
//    always $0400, so F$Link by the requested type got E$MNF. It is optional
//    because bit 15 of d2 asks for it (the OS-9 Guru, 11.5.4): with that bit
//    clear the module is Data whatever d3 holds, which is what the C library's
//    _mkdata_module relies on -- it never sets d3 (osk-freeware, 2026-09-23:
//    TOP's SysInfo module typed with the caller's leftover d3, so MNews could
//    not link it). Both halves are checked;
//  - F$CCtl: "If any reserved bit is set, an E$Param error is returned" (p.1-6),
//    but every value succeeded.
do {
    let header = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit   equ $06", "F$Link   equ $00", "F$DatMod equ $25", "F$CCtl   equ $5A",
        "F$UAcct  equ $59", "F$Protect equ $3B", "F$UnLink equ $02", "F$SRqMem equ $28", "F$SRtMem equ $29",
        "F$ID equ $0C", "F$DExec equ $23", "F$Mem equ $07",
        "I$Open   equ $84", "I$GetStt equ $8D", "I$WritLn equ $8C"
    ]
    func say(_ label: String) -> [String] {
        ["  lea \(label)(pc),a0", "  moveq #\(label)l,d1", "  moveq #1,d0", "  OS9 I$WritLn"]
    }
    func message(_ label: String, _ text: String) -> [String] {
        ["\(label): dc.b \"\(text)\",$0D", "\(label)l equ *-\(label)"]
    }
    let ready = header + [
        "  psect mhrdy,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  lea dname(pc),a0", "  move.w #$81,d0", "  OS9 I$Open", "  bcs.w fail",
        "  move.w #$01,d1", "  OS9 I$GetStt",
        "  bcs.s notrdy", "  cmpi.l #1,d1", "  bne.s notrdy"] + say("mok") + ["  bra.s done", "notrdy:"] +
        say("mbad") + [
        "done:", "  moveq #0,d1",
        "fail:", "  OS9 F$Exit",
        "dname: dc.b \"/h5\",0"] + message("mok", "HOSTDIR READY 1") + message("mbad", "HOSTDIR READY FAILED") +
        ["  ends", ""]
    let datmod = header + [
        "  psect mdmtyp,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  lea mname(pc),a0", "  moveq #16,d0", "  move.w #$8000,d1", "  move.w #$8333,d2", "  move.w #$0401,d3",
        "  OS9 F$DatMod", "  bcs.w fail",
        "  lea mname(pc),a0", "  move.w #$0401,d0", "  OS9 F$Link",
        "  bcs.s lost"] + say("mkept") + ["  bra.s done", "lost:"] + say("mlost") + [
        "done:", "  moveq #0,d1",
        "fail:", "  OS9 F$Exit",
        "mname: dc.b \"dmtyp\",0"] + message("mkept", "DATMOD TYPE KEPT") + message("mlost", "DATMOD TYPE LOST") +
        ["  ends", ""]
    // Bit 15 clear, and d3 holding what a C caller leaves there: a Data module.
    let datdefault = header + [
        "  psect mdmdat,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  lea mname(pc),a0", "  moveq #16,d0", "  move.w #$8001,d1", "  move.w #$0333,d2", "  move.w #$0006,d3",
        "  OS9 F$DatMod", "  bcs.w fail",
        "  cmpi.w #$0400,d0", "  bne.s notdata",
        "  lea mname(pc),a0", "  move.w #$0400,d0", "  OS9 F$Link",
        "  bcs.s notdata"] + say("mdata") + ["  bra.s done", "notdata:"] + say("mnodata") + [
        "done:", "  moveq #0,d1",
        "fail:", "  OS9 F$Exit",
        "mname: dc.b \"dmdat\",0"] + message("mdata", "DATMOD IS DATA") + message("mnodata", "DATMOD NOT DATA") +
        ["  ends", ""]
    let cctl = header + [
        "  psect mcctl,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  move.l #$80,d0", "  OS9 F$CCtl",
        "  bcc.s acc", "  cmpi.w #225,d1", "  bne.s acc"] + say("mref") + ["  bra.s flush", "acc:"] + say("macc") + [
        "flush:",
        "  moveq #0,d0", "  OS9 F$CCtl",
        "  bcs.s done"] + say("mflush") + [
        "done:", "  moveq #0,d1", "  OS9 F$Exit"] +
        message("mref", "CCTL RESERVED REFUSED") + message("macc", "CCTL RESERVED ACCEPTED") +
        message("mflush", "CCTL FLUSH OK") + ["  ends", ""]

    // F$UAcct with no accounting module installed: E$UnkSvc, as on a stock
    // system, and no anomaly line for it. F$Protect succeeds, as F$Permit does
    // (osk-freeware, 2026-09-23: UAC_view makes both).
    let acct = header + [
        "  psect macct,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  moveq #3,d0", "  suba.l a0,a0", "  OS9 F$UAcct",
        "  bcc.s wrong", "  cmpi.w #208,d1", "  bne.s wrong",
        "  move.l #16,d0", "  lea start(pc),a2", "  OS9 F$Protect",
        "  bcs.s wrong"] + say("mstock") + ["  bra.s done", "wrong:"] + say("mnot") + [
        "done:", "  moveq #0,d1", "  OS9 F$Exit"] +
        message("mstock", "UACCT UNKSVC PROTECT OK") + message("mnot", "UACCT OR PROTECT WRONG") +
        ["  ends", ""]

    // A sticky module "is retained in memory when its link count becomes zero"
    // and removed "when its link count becomes -1" (M$Attr bit 6, Technical
    // Manual, Module Header). Found by the skills session: it was freed at 0.
    let sticky = header + [
        "  psect mstky,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  lea sname(pc),a0", "  moveq #16,d0", "  move.w #$C001,d1", "  move.w #$0333,d2",
        "  OS9 F$DatMod", "  bcs.w fail",
        "  OS9 F$UnLink",                                  // link count 1 -> 0: kept
        "  lea sname(pc),a0", "  moveq #0,d0", "  OS9 F$Link",
        "  bcs.s gone"] + [                                 // must still be there
        "  OS9 F$UnLink",                                  // 1 -> 0 again
        "  OS9 F$UnLink",                                  // 0 -> -1: removed
        "  lea sname(pc),a0", "  moveq #0,d0", "  OS9 F$Link",
        "  bcc.s stayed", "  cmpi.w #221,d1", "  bne.s stayed"] + say("mskept") + ["  bra.s done", "gone:"] +
        say("msgone") + ["  bra.s done", "stayed:"] + say("msstay") + [
        "done:", "  moveq #0,d1",
        "fail:", "  OS9 F$Exit",
        "sname: dc.b \"stkymod\",0"] + message("mskept", "STICKY KEPT AT 0 AND GONE AT -1") +
        message("msgone", "STICKY FREED AT 0") + message("msstay", "STICKY NEVER FREED") + ["  ends", ""]

    // A zero-byte F$SRqMem is granted 0 bytes at an address of its own. It
    // used to be recorded as a zero-size block, which the next request could
    // share, and returning it printed "STRANGE BLOCK at <host pointer>" into
    // the program's own output (osk-freeware, 2026-09-23, via _srqmem(0)).
    let zeroBlock = header + [
        "  psect mzero,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  moveq #0,d0", "  OS9 F$SRqMem", "  bcs.w fail",
        "  movea.l a2,a3", "  move.l d0,d7",
        "  moveq #16,d0", "  OS9 F$SRqMem", "  bcs.w fail",
        "  cmpa.l a2,a3", "  beq.s shared"] + say("mapart") + [
        "  moveq #16,d0", "  OS9 F$SRtMem",
        "  move.l d7,d0", "  movea.l a3,a2", "  OS9 F$SRtMem",
        "  bra.s done", "shared:"] + say("mshared") + [
        "done:", "  moveq #0,d1",
        "fail:", "  OS9 F$Exit"] +
        message("mapart", "ZERO BLOCK HAS ITS OWN ADDRESS") + message("mshared", "ZERO BLOCK SHARES AN ADDRESS") +
        ["  ends", ""]

    // A raw open of a device (`/h5@`, as the C library's stat() makes) took a
    // path slot whose last file's name was never cleared, so deleting that file
    // afterwards was refused E$Share as though it were still open (found by the
    // pre-release host-files review).
    let rawDelete = header + [
        "I$Create equ $83", "I$Delete equ $87", "I$Close equ $8F",
        "  psect mrawd,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  lea victim(pc),a0", "  moveq #2,d0", "  OS9 I$Delete",       // a leftover from an earlier run
        "  lea victim(pc),a0", "  moveq #3,d0", "  moveq #3,d1", "  OS9 I$Create", "  bcs.w setup",
        "  OS9 I$Close",
        "  lea raw(pc),a0", "  moveq #1,d0", "  OS9 I$Open", "  bcs.w setup", "  move.w d0,d7",
        "  lea victim(pc),a0", "  moveq #2,d0", "  OS9 I$Delete", "  bcs.s refused"] + say("mrdok") + [
        "  bra.s done", "refused:"] + say("mrdno") + [
        "done:", "  move.w d7,d0", "  OS9 I$Close", "  moveq #0,d1", "  bra.s fail",
        "setup:"] + say("mrdsu") + [
        "fail:", "  OS9 F$Exit",
        "victim: dc.b \"/h5/rawvict\",0", "raw: dc.b \"/h5@\",0"] +
        message("mrdok", "DELETED WITH A RAW PATH OPEN") + message("mrdno", "DELETE REFUSED") +
        message("mrdsu", "SETUP FAILED") +
        ["  ends", ""]

    // A zero-byte block handed back with a size of its own: os9free walked it
    // "in smaller pieces" of zero bytes, on the same address, for ever, and the
    // host's stack overflowed -- two system calls took the emulator down
    // (found by the pre-release kernel review).
    let zeroFree = header + [
        "  psect mzfre,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  moveq #0,d0", "  OS9 F$SRqMem", "  bcs.w fail",
        "  moveq #16,d0", "  OS9 F$SRtMem", "  bcs.w fail"] + say("mzfok") + [
        "  moveq #0,d1",
        "fail:", "  OS9 F$Exit"] +
        message("mzfok", "ZERO BLOCK GIVEN BACK") +
        ["  ends", ""]

    // "If the module's access word does not give the process read permission,
    // the link call fails" (F$Link, page 1-41). The creator's own field is the
    // one checked here -- the super-user group is checked the same way -- so a
    // module made with no permissions at all is refused (E$Permit, 164) and one
    // with owner-read links. os9exec never looked (found by the skills session).
    let permLink = header + [
        "  psect mperm,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  lea pnone(pc),a0", "  moveq #16,d0", "  move.w #$8001,d1", "  move.w #$0000,d2",
        "  OS9 F$DatMod", "  bcs.w fail", "  movea.l a2,a3",
        "  lea pnone(pc),a0", "  moveq #0,d0", "  OS9 F$Link",
        "  bcc.s wrong", "  cmpi.w #164,d1", "  bne.s wrong",
        "  lea pread(pc),a0", "  moveq #16,d0", "  move.w #$8001,d1", "  move.w #$0001,d2",
        "  OS9 F$DatMod", "  bcs.w fail", "  movea.l a2,a4",
        "  lea pread(pc),a0", "  moveq #0,d0", "  OS9 F$Link",
        "  bcs.s wrong", "  OS9 F$UnLink"] + say("mpok") + [
        "  movea.l a4,a2", "  OS9 F$UnLink", "  movea.l a3,a2", "  OS9 F$UnLink",
        "  bra.s done", "wrong:"] + say("mpbad") + [
        "done:", "  moveq #0,d1",
        "fail:", "  OS9 F$Exit",
        "pnone: dc.b \"permnone\",0", "pread: dc.b \"permread\",0"] +
        message("mpok", "LINK NEEDS READ PERMISSION") + message("mpbad", "LINK IGNORED PERMISSION") + ["  ends", ""]

    // Found by review of the fixes above. A request within 64 bytes of 4 GB
    // wrapped to 0 in the rounding and was granted a minimum block while the
    // caller was told it had ~4 GB (E$NoRAM now). F$DExec on a process the
    // caller did not F$DFork was carried out -- and would now load that
    // process's registers from a stale buffer (E$IPrcID now, as F$DExit).
    // FCMP of +inf with +inf took its flags from inf-inf, a NaN, not equal.
    let reviewFixes = header + [
        "  psect mrevw,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  move.l #$FFFFFFE0,d0", "  OS9 F$SRqMem", "  bcc.s wrong", "  cmpi.w #237,d1", "  bne.s wrong",
        "  OS9 F$ID", "  moveq #1,d1", "  moveq #0,d2", "  OS9 F$DExec", "  bcc.s wrong",
        "  cmpi.w #224,d1", "  bne.s wrong",
        "  lea inf(pc),a0", "  dc.w $F210,$5400", "  dc.w $F210,$5438", "  dc.w $F200,$A800",
        "  btst #26,d0", "  beq.s wrong"] + say("mrvok") + ["  bra.s done", "wrong:"] + say("mrvbad") + [
        "done:", "  moveq #0,d1", "  OS9 F$Exit",
        "inf: dc.l $7FF00000,0"] +
        message("mrvok", "REVIEW FIXES HOLD") + message("mrvbad", "REVIEW FIX BROKEN") + ["  ends", ""]

    // F$Mem of $FFFFFFE8: where ulong is 32 bits the rounding wrapped to 0 and
    // freed the data area under the process (review, part 4). Must be E$NoRAM,
    // and an information request after it must still see the area. Only a
    // 32-bit host (the i386 leg) could fail this.
    let memWrap = header + [
        "  psect mmemw,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  move.l #$FFFFFFE8,d0", "  OS9 F$Mem", "  bcc.s mwbad", "  cmpi.w #237,d1", "  bne.s mwbad",
        "  moveq #0,d0", "  OS9 F$Mem", "  bcs.s mwbad", "  tst.l d0", "  beq.s mwbad"] + say("mwok") + [
        "  bra.s mwdone", "mwbad:"] + say("mwno") + [
        "mwdone:", "  moveq #0,d1", "  OS9 F$Exit"] +
        message("mwok", "FMEM HUGE REFUSED, AREA KEPT") + message("mwno", "FMEM HUGE MISHANDLED") + ["  ends", ""]

    // F$Mem giving back 16 bytes and taking them again inside one 64-byte arena
    // unit: the bytes never left the arena, and the growth handed them back
    // holding what was written there (review, part 4). The data area gained is
    // clean, as at fork. A is a multiple of 64 at least 32 below the size; the
    // area goes to A+48, is marked, down to A+32 and back to A+48 -- all inside
    // the unit ending at A+64. The long argument keeps the stack below A+32.
    let memClean = header + [
        "  psect mmemz,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  moveq #0,d0", "  OS9 F$Mem", "  bcs.s mzbad", "  move.l d0,d5",
        "  subi.l #32,d5", "  andi.l #$FFFFFFC0,d5",
        "  move.l d5,d0", "  addi.l #48,d0", "  OS9 F$Mem", "  bcs.s mzbad",
        "  moveq #-1,d1", "  move.l d1,-4(a1)", "  move.l d1,-8(a1)", "  move.l d1,-12(a1)", "  move.l d1,-16(a1)",
        "  move.l d5,d0", "  addi.l #32,d0", "  OS9 F$Mem", "  bcs.s mzbad",
        "  move.l d5,d0", "  addi.l #48,d0", "  OS9 F$Mem", "  bcs.s mzbad",
        "  move.l -4(a1),d1", "  or.l -8(a1),d1", "  or.l -12(a1),d1", "  or.l -16(a1),d1",
        "  bne.s mzbad"] + say("mzok") + [
        "  bra.s mzdone", "mzbad:"] + say("mzno") + [
        "mzdone:", "  moveq #0,d1", "  OS9 F$Exit"] +
        message("mzok", "FMEM REGROWN AREA CLEAN") + message("mzno", "FMEM REGROWN AREA STALE") + ["  ends", ""]

    let modules = ["mhrdy": ready, "mdmtyp": datmod, "mdmdat": datdefault, "mcctl": cctl, "macct": acct,
                   "mstky": sticky, "mzero": zeroBlock, "mzfre": zeroFree, "mrawd": rawDelete,
                   "mperm": permLink, "mrevw": reviewFixes, "mmemw": memWrap,
                   "mmemz": memClean]
    for (module, lines) in modules {
        try? lines.joined(separator: "\r").write(toFile: scratchDisk + "/\(module).a",
                                                  atomically: true, encoding: .utf8)
    }
    struct StatusCase {
        let name: String
        let module: String
        let want: [String]
        var absent: [String] = []
        var args = ""
    }
    let cases = [
        StatusCase(name: "fs: GetStt SS_Ready on a host directory answers ready, d1=1",
                   module: "mhrdy", want: ["HOSTDIR READY 1"]),
        StatusCase(name: "module: F$DatMod keeps the type/language asked for in d3 (d2 bit 15 set)",
                   module: "mdmtyp", want: ["DATMOD TYPE KEPT"]),
        StatusCase(name: "module: F$DatMod makes a Data module when d2 bit 15 is clear, whatever d3 holds",
                   module: "mdmdat", want: ["DATMOD IS DATA"]),
        StatusCase(name: "cache: F$CCtl refuses reserved bits and still flushes on 0",
                   module: "mcctl", want: ["CCTL RESERVED REFUSED", "CCTL FLUSH OK"]),
        StatusCase(name: "system: F$UAcct answers E$UnkSvc quietly, F$Protect succeeds as F$Permit does",
                   module: "macct", want: ["UACCT UNKSVC PROTECT OK"], absent: ["unimplemented"]),
        StatusCase(name: "module: a sticky module stays at link count 0 and goes at -1",
                   module: "mstky", want: ["STICKY KEPT AT 0 AND GONE AT -1"]),
        StatusCase(name: "memory: a zero-byte F$SRqMem gets an address of its own, and says nothing on return",
                   module: "mzero", want: ["ZERO BLOCK HAS ITS OWN ADDRESS"], absent: ["BLOCK at"]),
        StatusCase(name: "fs: a file can be deleted while a raw path to its device is open",
                   module: "mrawd", want: ["DELETED WITH A RAW PATH OPEN"]),
        StatusCase(name: "memory: a zero-byte block given back with a size of 16 frees, and the emulator lives",
                   module: "mzfre", want: ["ZERO BLOCK GIVEN BACK"]),
        StatusCase(name: "module: F$Link refuses a module whose access word gives no read permission",
                   module: "mperm", want: ["LINK NEEDS READ PERMISSION"]),
        StatusCase(name: "system: a 4 GB F$SRqMem, F$DExec of a stranger, FCMP of equal infinities",
                   module: "mrevw", want: ["REVIEW FIXES HOLD"]),
        StatusCase(name: "memory: F$Mem of nearly 4 GB is refused and leaves the data area alone",
                   module: "mmemw", want: ["FMEM HUGE REFUSED, AREA KEPT"]),
        StatusCase(name: "memory: F$Mem hands back a shrunk-and-regrown data area clean",
                   module: "mmemz", want: ["FMEM REGROWN AREA CLEAN"],
                   args: String(repeating: "parameter-area-", count: 8))
    ]
    let chosen = cases.filter { filter.isEmpty || $0.name.localizedCaseInsensitiveContains(filter) }
    if !chosen.isEmpty {
        var build = ["load /dd/CMDS/r68 /dd/CMDS/l68"]
        for testCase in chosen {
            build += ["r68 /h5/\(testCase.module).a -o=/h5/\(testCase.module).r",
                      "l68 /h5/\(testCase.module).r -o=/h5/\(testCase.module)"]
        }
        _ = os9(build, timeout: 60)
    }
    for testCase in chosen {
        let out = os9(["/h5/\(testCase.module) \(testCase.args)"], timeout: 30)
        if testCase.want.allSatisfy({ out.contains($0) }) && !testCase.absent.contains(where: { out.contains($0) }) {
            print("PASS: \(testCase.name)")
            passed += 1
        } else {
            print("FAIL: \(testCase.name)")
            let lines = out.split(whereSeparator: \.isNewline).filter {
                $0.contains("READY") || $0.contains("DATMOD") || $0.contains("CCTL") || $0.contains("Error") ||
                $0.contains("UACCT") || $0.contains("unimplemented") || $0.contains("STICKY") ||
                $0.contains("BLOCK") || $0.contains("LINK ") || $0.contains("REVIEW") || $0.contains("FMEM") ||
                $0.contains("DELETE") || $0.contains("SETUP")
            }
            print("      saw: \(lines.joined(separator: " | "))")
            failed += 1
        }
    }
    for module in modules.keys {
        for suffix in [".a", ".r", ""] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/\(module)" + suffix)
        }
    }
}

// ── process permissions: S$Kill, F$SPrior, F$SetSys, F$DExit ───────────────────
// Technical Manual rules the 2026-09-15 argument audit found unenforced, each
// probed live; rdoggett's decision: enforce them.
//  - "The S$Kill signal may only be sent to processes with the same group ID as
//    the sender. Super users may kill any process." (F$Send, p.1-48)
//  - "A process can only change another process's priority if it has the same
//    user ID", the super user excepted (F$SPrior, p.1-54)
//  - "Only a super-user can change system variables." (F$SetSys, p.1-51)
//  - F$DExit "terminates a suspended child process that was created with the
//    F$DFork system call" (p.1-16); it killed any process.
// The first program forks a sleeping child as the super user, becomes 5.5, and
// tries each call on it. Refusals are E$IPrcID (224) or, for F$SetSys, E$Permit
// (164). The second forks a plain child and tries F$DExit on it.
do {
    let header = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Fork   equ $03", "F$Wait   equ $04", "F$Exit   equ $06", "F$Send   equ $08",
        "F$Sleep  equ $0A", "F$SPrior equ $0D", "F$SUser  equ $1C", "F$DExit  equ $24",
        "F$SetSys equ $27", "I$WritLn equ $8C"
    ]
    func say(_ label: String) -> [String] {
        ["  lea \(label)(pc),a0", "  moveq #\(label)l,d1", "  moveq #1,d0", "  OS9 I$WritLn"]
    }
    func message(_ label: String, _ text: String) -> [String] {
        ["\(label): dc.b \"\(text)\",$0D", "\(label)l equ *-\(label)"]
    }
    // refused when carry is set and d1.w equals <code>
    func refused(_ code: Int, _ refusedLabel: String, _ acceptedLabel: String, _ tag: String) -> [String] {
        ["  bcc.s acc\(tag)", "  cmpi.w #\(code),d1", "  bne.s acc\(tag)"] + say(refusedLabel) +
            ["  bra.s end\(tag)", "acc\(tag):"] + say(acceptedLabel) + ["end\(tag):"]
    }
    let fork = [
        "  lea cname(pc),a0", "  lea cparm(pc),a1", "  moveq #0,d0", "  moveq #1,d1", "  moveq #0,d2",
        "  moveq #3,d3", "  moveq #0,d4", "  OS9 F$Fork"
    ]
    let child = header + [
        "  psect mpchld,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:", "  move.l #300,d0", "  OS9 F$Sleep", "  moveq #0,d1", "  OS9 F$Exit", "  ends", ""]
    let perms = header + [
        "  psect mpperm,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:"] + fork + [
        "  bcs.w fail", "  moveq #0,d5", "  move.w d0,d5",
        "  move.l #$00050005,d1", "  OS9 F$SUser", "  bcc.s asuser"] + say("msufail") + ["  bra.w reap", "asuser:",
        "  move.l d5,d0", "  moveq #0,d1", "  OS9 F$Send"] + refused(224, "mkref", "mkacc", "k") + [
        "  move.l d5,d0", "  move.l #200,d1", "  OS9 F$SPrior"] + refused(224, "mpref", "mpacc", "p") + [
        "  move.l #$28,d0", "  moveq #2,d1", "  moveq #50,d2", "  OS9 F$SetSys"] +
        refused(164, "msref", "msacc", "s") + [
        "reap:", "  OS9 F$Wait",
        "  moveq #0,d1",
        "fail:", "  OS9 F$Exit",
        "cname: dc.b \"/h5/mpchld\",0", "cparm: dc.b $0D", "  align"] +
        message("msufail", "SUSER FAILED") +
        message("mkref", "SKILL REFUSED") + message("mkacc", "SKILL NOT REFUSED") +
        message("mpref", "SPRIOR REFUSED") + message("mpacc", "SPRIOR NOT REFUSED") +
        message("msref", "SETSYS REFUSED") + message("msacc", "SETSYS NOT REFUSED") + ["  ends", ""]
    let dexit = header + [
        "  psect mpdext,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:"] + fork + [
        "  bcs.w fail", "  moveq #0,d5", "  move.w d0,d5",
        "  move.l d5,d0", "  OS9 F$DExit"] + refused(224, "mdref", "mdacc", "d") + [
        "  OS9 F$Wait",
        "  moveq #0,d1",
        "fail:", "  OS9 F$Exit",
        "cname: dc.b \"/h5/mpchld\",0", "cparm: dc.b $0D", "  align"] +
        message("mdref", "DEXIT REFUSED") + message("mdacc", "DEXIT NOT REFUSED") + ["  ends", ""]

    let modules = ["mpchld": child, "mpperm": perms, "mpdext": dexit]
    for (module, lines) in modules {
        try? lines.joined(separator: "\r").write(toFile: scratchDisk + "/\(module).a",
                                                  atomically: true, encoding: .utf8)
    }
    struct PermCase {
        let name: String
        let module: String
        let want: [String]
    }
    let cases = [
        PermCase(name: "process: a non-super user may not S$Kill, F$SPrior or F$SetSys outside its reach",
                 module: "mpperm", want: ["SKILL REFUSED", "SPRIOR REFUSED", "SETSYS REFUSED"]),
        PermCase(name: "process: F$DExit refuses a child that was not made by F$DFork",
                 module: "mpdext", want: ["DEXIT REFUSED"])
    ]
    let chosen = cases.filter { filter.isEmpty || $0.name.localizedCaseInsensitiveContains(filter) }
    if !chosen.isEmpty {
        var build = ["load /dd/CMDS/r68 /dd/CMDS/l68"]
        for module in modules.keys.sorted() {
            build += ["r68 /h5/\(module).a -o=/h5/\(module).r", "l68 /h5/\(module).r -o=/h5/\(module)"]
        }
        _ = os9(build, timeout: 60)
    }
    for testCase in chosen {
        let out = os9(["/h5/\(testCase.module)"], timeout: 30)
        if testCase.want.allSatisfy({ out.contains($0) }) && !out.contains("SUSER FAILED") {
            print("PASS: \(testCase.name)")
            passed += 1
        } else {
            print("FAIL: \(testCase.name)")
            let lines = out.split(whereSeparator: \.isNewline).filter {
                $0.contains("REFUSED") || $0.contains("SUSER") || $0.contains("Error")
            }
            print("      saw: \(lines.joined(separator: " | "))")
            failed += 1
        }
    }
    for module in modules.keys {
        for suffix in [".a", ".r", ""] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/\(module)" + suffix)
        }
    }
}

// ── RBF permissions: a directory's mode bits, and SS_FDInf for the super group ──
// Rules the 2026-09-15 argument audit found unenforced; rdoggett's decision:
// enforce them.
//  - I$ChgDir: "the caller must have access permission for the specified mode"
//    (p.2-3), and the shell's chd uses update. A directory granting the public
//    read only was still entered by a non-owner, because a directory at the end
//    of a path had its read permission checked and nothing else.
//  - SS_FDInf: "If SS_FDInf is called in user state, the caller must be a
//    super-group user" (p.2-12). It reads any sector of the device by number.
do {
    let fdinf = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit   equ $06", "I$Open   equ $84", "I$GetStt equ $8D", "I$WritLn equ $8C", "BUF equ -32700",
        "  psect mfdinf,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  lea fname(pc),a0", "  moveq #1,d0", "  OS9 I$Open", "  bcs.s fail",
        "  move.w #$20,d1", "  moveq #16,d2", "  moveq #0,d3", "  lea BUF(a6),a0", "  OS9 I$GetStt",
        "  bcc.s allowed", "  cmpi.w #164,d1", "  bne.s allowed",
        "  lea mref(pc),a0", "  moveq #mrefl,d1", "  bra.s write",
        "allowed:", "  lea macc(pc),a0", "  moveq #maccl,d1",
        "write:", "  moveq #1,d0", "  OS9 I$WritLn",
        "  moveq #0,d1",
        "fail:", "  OS9 F$Exit",
        "fname: dc.b \"/hq/one\",0",
        "mref: dc.b \"FDINF REFUSED\",$0D", "mrefl equ *-mref",
        "macc: dc.b \"FDINF ALLOWED\",$0D", "maccl equ *-macc",
        "  ends", ""
    ]
    try? fdinf.joined(separator: "\r").write(toFile: scratchDisk + "/mfdinf.a", atomically: true, encoding: .utf8)

    let dirName = "rbf: a non-owner may not chd into a directory that grants it read only"
    if filter.isEmpty || dirName.localizedCaseInsensitiveContains(filter) {
        removeScratchItem("hq")
        let out = os9(["mount -k=1M hq", "makdir /hq/pd", "attr /hq/pd -nw -npw -ne -npe",
                       "login claude", "dir /hq/pd", "chd /hq/pd", "logout"], timeout: 30)
        // the read-only open (dir) still works; the update-mode chd is E$FNA
        if out.contains("Directory of /hq/pd") && out.contains("#000:214") {
            print("PASS: \(dirName)")
            passed += 1
        } else {
            print("FAIL: \(dirName)")
            let lines = out.split(whereSeparator: \.isNewline).filter {
                $0.contains("chd") || $0.contains("Directory of") || $0.contains("Error")
            }
            print("      saw: \(lines.joined(separator: " | "))")
            failed += 1
        }
    }

    let infoName = "rbf: SS_FDInf is refused to a non-super user and allowed to the super user"
    if filter.isEmpty || infoName.localizedCaseInsensitiveContains(filter) {
        removeScratchItem("hq")
        _ = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                 "r68 /h5/mfdinf.a -o=/h5/mfdinf.r", "l68 /h5/mfdinf.r -o=/h5/mfdinf"], timeout: 60)
        // public read, or the non-super open fails before SS_FDInf is ever asked
        let out = os9(["mount -k=1M hq", "echo hi >/hq/one", "attr /hq/one -pr", "/h5/mfdinf",
                       "login claude", "/h5/mfdinf", "logout"], timeout: 30)
        let allowedAt = out.range(of: "FDINF ALLOWED")
        let refusedAt = out.range(of: "FDINF REFUSED")
        if let allowed = allowedAt, let refused = refusedAt, allowed.lowerBound < refused.lowerBound {
            print("PASS: \(infoName)")
            passed += 1
        } else {
            print("FAIL: \(infoName)")
            let lines = out.split(whereSeparator: \.isNewline).filter {
                $0.contains("FDINF") || $0.contains("Error")
            }
            print("      saw: \(lines.joined(separator: " | "))")
            failed += 1
        }
    }
    removeScratchItem("hq")
    for suffix in [".a", ".r", ""] {
        try? FileManager.default.removeItem(atPath: scratchDisk + "/mfdinf" + suffix)
    }
}

// ── RBF: create's dir bit, the S attribute, SS_Ticks, SS_FD writes, SS_Attr ────
// Found by the 2026-09-15 argument audit, each probed live on an RBF image:
//  - I$Create stored attribute bit 7 and made an empty "directory" (p.2-5: "You
//    cannot use I$Create to make directory files");
//  - the file's own single-user attribute was ignored, only the open's mode bit
//    counted (p.7-9: "only one process may open the file at a time");
//  - SS_Ticks kept the low word of d2 as raw ticks and ignored the 256ths bit
//    (p.2-28), so $00010001 gave up after one tick;
//  - SS_FD SetStt wrote all 16 bytes through any path (p.2-24: "The path must be
//    open for write ... You can only change FD_OWN, FD_DAT, and FD_Creat");
//  - SS_Attr set the dir bit on a plain file (p.2-22: "It is not permitted").
do {
    let header = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit   equ $06", "F$Sleep  equ $0A", "I$Create equ $83", "I$Open   equ $84", "I$Read   equ $89",
        "I$GetStt equ $8D", "I$SetStt equ $8E", "I$Close  equ $8F", "I$WritLn equ $8C",
        "BUF equ -32700", "BUF2 equ -32600"
    ]
    func say(_ label: String) -> [String] {
        ["  lea \(label)(pc),a0", "  moveq #\(label)l,d1", "  moveq #1,d0", "  OS9 I$WritLn"]
    }
    func message(_ label: String, _ text: String) -> [String] {
        ["\(label): dc.b \"\(text)\",$0D", "\(label)l equ *-\(label)"]
    }
    func program(_ name: String, _ body: [String], _ data: [String]) -> [String] {
        header + ["  psect \(name),(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start", "start:"] + body +
            ["  moveq #0,d1", "fail:", "  OS9 F$Exit"] + data + ["  ends", ""]
    }
    let createDir = program("mcrdir", [
        "  lea fname(pc),a0", "  moveq #3,d0", "  move.w #$FF,d1", "  OS9 I$Create", "  bcs.w fail",
        "  OS9 I$Close"], ["fname: dc.b \"/hq/c80\",0"])
    let holder = program("mshold", [
        "  lea fname(pc),a0", "  moveq #1,d0", "  OS9 I$Open", "  bcs.w fail",
        "  move.l #300,d0", "  OS9 F$Sleep"], ["fname: dc.b \"/hq/s6\",0"])
    let second = program("msopen", [
        "  moveq #60,d0", "  OS9 F$Sleep",
        "  lea fname(pc),a0", "  moveq #1,d0", "  OS9 I$Open",
        "  bcc.s allowed", "  cmpi.w #253,d1", "  bne.s allowed"] + say("mref") + ["  bra.s done", "allowed:"] +
        say("macc") + ["done:"],
        ["fname: dc.b \"/hq/s6\",0"] + message("mref", "SINGLE ATTR REFUSED") + message("macc", "SINGLE ATTR ALLOWED"))
    let lockHolder = program("mtkhld", [
        "  lea fname(pc),a0", "  moveq #3,d0", "  OS9 I$Open", "  bcs.w fail",
        "  move.w #$11,d1", "  moveq #-1,d2", "  OS9 I$SetStt", "  bcs.w fail",
        "  move.l #300,d0", "  OS9 F$Sleep"], ["fname: dc.b \"/hq/tk\",0"])
    let ticksReader = program("mtkrd", [
        "  moveq #60,d0", "  OS9 F$Sleep",
        "  lea fname(pc),a0", "  moveq #3,d0", "  OS9 I$Open", "  bcs.w fail", "  move.w d0,d7",
        "  move.w #$10,d1", "  move.l #$00010001,d2", "  OS9 I$SetStt", "  bcs.w fail",
        "  move.w d7,d0", "  moveq #1,d1", "  lea BUF(a6),a0", "  OS9 I$Read",
        "  bcs.s rderr"] + say("mread") + ["  bra.s done", "rderr:"] + say("merr") + ["done:"],
        ["fname: dc.b \"/hq/tk\",0"] + message("mread", "TICKS WAITED AND READ") + message("merr", "TICKS READ ERROR"))
    let setFD = program("msfdw", [
        "  lea fname(pc),a0", "  moveq #1,d0", "  OS9 I$Open", "  bcs.w fail", "  move.w d0,d7",
        "  move.w d7,d0", "  move.w #$0F,d1", "  moveq #16,d2", "  lea BUF(a6),a0", "  OS9 I$GetStt", "  bcs.w fail",
        "  move.l BUF+9(a6),d6",
        "  move.b #5,BUF+8(a6)",
        "  move.w d7,d0", "  move.w #$0F,d1", "  lea BUF(a6),a0", "  OS9 I$SetStt",
        "  bcc.s rdacc", "  cmpi.w #203,d1", "  bne.s rdacc"] + say("mrdref") + ["  bra.s rddone", "rdacc:"] +
        say("mrdacc") + ["rddone:",
        "  move.w d7,d0", "  OS9 I$Close",
        "  lea fname(pc),a0", "  moveq #3,d0", "  OS9 I$Open", "  bcs.w fail", "  move.w d0,d7",
        "  move.w d7,d0", "  move.w #$0F,d1", "  moveq #16,d2", "  lea BUF(a6),a0", "  OS9 I$GetStt", "  bcs.w fail",
        "  move.b #5,BUF+8(a6)", "  move.l #$1000,BUF+9(a6)",
        "  move.w d7,d0", "  move.w #$0F,d1", "  lea BUF(a6),a0", "  OS9 I$SetStt", "  bcs.w fail",
        "  move.w d7,d0", "  move.w #$0F,d1", "  moveq #16,d2", "  lea BUF2(a6),a0", "  OS9 I$GetStt", "  bcs.w fail",
        "  cmpi.b #1,BUF2+8(a6)", "  bne.s changed", "  cmp.l BUF2+9(a6),d6", "  bne.s changed"] +
        say("mkept") + ["  bra.s done", "changed:"] + say("mchg") + ["done:"],
        ["fname: dc.b \"/hq/fdw\",0"] + message("mrdref", "SETFD READ PATH REFUSED") +
        message("mrdacc", "SETFD READ PATH ALLOWED") + message("mkept", "SETFD KEPT LNK SIZ") +
        message("mchg", "SETFD CHANGED LNK SIZ"))
    let dirBit = program("madirb", [
        "  lea fname(pc),a0", "  moveq #3,d0", "  OS9 I$Open", "  bcs.w fail",
        "  move.w #$1C,d1", "  move.l #$9B,d2", "  OS9 I$SetStt",
        "  bcc.s acc", "  cmpi.w #214,d1", "  bne.s acc"] + say("mref") + ["  bra.s done", "acc:"] + say("macc") +
        ["done:"],
        ["fname: dc.b \"/hq/ad\",0"] + message("mref", "ATTR DIR BIT REFUSED") + message("macc",
            "ATTR DIR BIT ALLOWED"))

    let modules = ["mcrdir": createDir, "mshold": holder, "msopen": second, "mtkhld": lockHolder,
                   "mtkrd": ticksReader, "msfdw": setFD, "madirb": dirBit]
    for (module, lines) in modules {
        try? lines.joined(separator: "\r").write(toFile: scratchDisk + "/\(module).a",
                                                  atomically: true, encoding: .utf8)
    }
    struct RBFCase {
        let name: String
        let commands: [String]
        let pass: (String) -> Bool
    }
    let cases = [
        RBFCase(name: "rbf: I$Create with attribute bit 7 makes a file, not a directory",
                commands: ["mount -k=1M hq", "/h5/mcrdir", "attr /hq/c80"]) { out in
            out.split(whereSeparator: \.isNewline).contains {
                $0.contains("/hq/c80") && !$0.hasPrefix("$") && !$0.trimmingCharacters(in: .whitespaces).hasPrefix("d")
            }
        },
        RBFCase(name: "rbf: a file's own single-user attribute refuses a second process",
                commands: ["mount -k=1M hq", "echo hi >/hq/s6", "attr /hq/s6 -s -pr", "/h5/mshold &",
                           "/h5/msopen", "w"]) { $0.contains("SINGLE ATTR REFUSED") },
        RBFCase(name: "rbf: SS_Ticks keeps all of d2, so $00010001 waits out a lock",
                commands: ["mount -k=1M hq", "echo data >/hq/tk", "/h5/mtkhld &", "/h5/mtkrd", "w"]) {
            $0.contains("TICKS WAITED AND READ")
        },
        RBFCase(name: "rbf: SetStt SS_FD needs a write path and changes only owner and dates",
                commands: ["mount -k=1M hq", "echo hello >/hq/fdw", "/h5/msfdw"]) {
            $0.contains("SETFD READ PATH REFUSED") && $0.contains("SETFD KEPT LNK SIZ")
        },
        RBFCase(name: "rbf: SetStt SS_Attr will not set the dir bit on a plain file",
                commands: ["mount -k=1M hq", "echo hi >/hq/ad", "/h5/madirb"]) { $0.contains("ATTR DIR BIT REFUSED") }
    ]
    let chosen = cases.filter { filter.isEmpty || $0.name.localizedCaseInsensitiveContains(filter) }
    if !chosen.isEmpty {
        var build = ["load /dd/CMDS/r68 /dd/CMDS/l68"]
        for module in modules.keys.sorted() {
            build += ["r68 /h5/\(module).a -o=/h5/\(module).r", "l68 /h5/\(module).r -o=/h5/\(module)"]
        }
        _ = os9(build, timeout: 90)
    }
    for testCase in chosen {
        removeScratchItem("hq")
        let out = os9(testCase.commands, timeout: 40)
        if testCase.pass(out) {
            print("PASS: \(testCase.name)")
            passed += 1
        } else {
            print("FAIL: \(testCase.name)")
            let lines = out.split(whereSeparator: \.isNewline).filter {
                $0.contains("/hq/c80") || $0.contains("SINGLE") || $0.contains("TICKS") || $0.contains("SETFD")
                    || $0.contains("ATTR DIR") || $0.contains("Error")
            }
            print("      saw: \(lines.joined(separator: " | "))")
            failed += 1
        }
    }
    removeScratchItem("hq")
    for module in modules.keys {
        for suffix in [".a", ".r", ""] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/\(module)" + suffix)
        }
    }
}

// ── RBF: I$Delete refuses a file another path has open, readers included ──────
// "The caller must have non-sharable write access to the file (the file may not
// already be open) or an error results." (Technical Manual, I$Delete, p.2-7).
// Only another writer was refused (E$Share); a file open for READING was deleted
// out from under its reader, which went on reading freed sectors. Found by the
// 2026-09-15 argument audit, probed live. A holder opens the file for read and
// sleeps; a second process deletes it; the file must still be there afterwards.
do {
    let header = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit   equ $06", "F$Sleep  equ $0A", "I$Open   equ $84", "I$Delete equ $87", "I$WritLn equ $8C"
    ]
    let holder = header + [
        "  psect mrdhld,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  lea fname(pc),a0", "  moveq #1,d0", "  OS9 I$Open", "  bcs.s fail",
        "  move.l #300,d0", "  OS9 F$Sleep",
        "  moveq #0,d1",
        "fail:", "  OS9 F$Exit",
        "fname: dc.b \"/hq/rd\",0", "  ends", ""
    ]
    let deleter = header + [
        "  psect mrddel,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  moveq #60,d0", "  OS9 F$Sleep",
        "  lea fname(pc),a0", "  moveq #2,d0", "  OS9 I$Delete",
        "  bcc.s gone", "  cmpi.w #253,d1", "  bne.s gone",
        "  lea mref(pc),a0", "  moveq #mrefl,d1", "  bra.s write",
        "gone:", "  lea mdel(pc),a0", "  moveq #mdell,d1",
        "write:", "  moveq #1,d0", "  OS9 I$WritLn",
        "  moveq #0,d1", "  OS9 F$Exit",
        "fname: dc.b \"/hq/rd\",0",
        "mref: dc.b \"DELETE REFUSED WHILE OPEN\",$0D", "mrefl equ *-mref",
        "mdel: dc.b \"DELETE ALLOWED WHILE OPEN\",$0D", "mdell equ *-mdel",
        "  ends", ""
    ]
    for (module, lines) in ["mrdhld": holder, "mrddel": deleter] {
        try? lines.joined(separator: "\r").write(toFile: scratchDisk + "/\(module).a",
                                                  atomically: true, encoding: .utf8)
    }
    let name = "rbf: I$Delete refuses a file another process has open for reading"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        _ = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                 "r68 /h5/mrdhld.a -o=/h5/mrdhld.r", "l68 /h5/mrdhld.r -o=/h5/mrdhld",
                 "r68 /h5/mrddel.a -o=/h5/mrddel.r", "l68 /h5/mrddel.r -o=/h5/mrddel"], timeout: 60)
        removeScratchItem("hq")
        let out = os9(["mount -k=1M hq", "echo KEEPTHIS >/hq/rd", "/h5/mrdhld &", "/h5/mrddel", "w",
                       "list /hq/rd"], timeout: 40)
        let survived = out.split(whereSeparator: \.isNewline).contains {
            !$0.hasPrefix("$") && $0.trimmingCharacters(in: .whitespaces) == "KEEPTHIS"
        }
        if out.contains("DELETE REFUSED WHILE OPEN") && survived {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let lines = out.split(whereSeparator: \.isNewline).filter {
                $0.contains("DELETE") || $0.contains("KEEPTHIS") || $0.contains("Error")
            }
            print("      saw: \(lines.joined(separator: " | "))")
            failed += 1
        }
        removeScratchItem("hq")
    }
    for module in ["mrdhld", "mrddel"] {
        for suffix in [".a", ".r", ""] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/\(module)" + suffix)
        }
    }
}

// ── host dir: I$Delete refuses a file held open in mode 0 as well ──────────────
// A host directory refuses to delete a file this emulator holds open (I$Delete:
// "the file may not already be open"), but the check skipped opens without a
// host stream -- mode 0, opened for its attributes or status only. Found by
// review. The program holds the file in mode 0, deletes it by name (E$Share),
// closes, and deletes it again (gone).
do {
    let lines = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit equ $06", "I$Open equ $84", "I$Delete equ $87", "I$WritLn equ $8C", "I$Close equ $8F",
        "  psect mzdel,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  lea fname(pc),a0", "  moveq #0,d0", "  OS9 I$Open", "  bcs.s bad", "  move.w d0,d7",
        "  lea fname(pc),a0", "  moveq #2,d0", "  OS9 I$Delete", "  bcc.s bad",
        "  cmpi.w #253,d1", "  bne.s bad",
        "  move.w d7,d0", "  OS9 I$Close",
        "  lea fname(pc),a0", "  moveq #2,d0", "  OS9 I$Delete", "  bcs.s bad",
        "  lea mok(pc),a0", "  moveq #mokl,d1", "  bra.s say",
        "bad:", "  lea mbad(pc),a0", "  moveq #mbadl,d1",
        "say:", "  moveq #1,d0", "  OS9 I$WritLn", "  moveq #0,d1", "  OS9 F$Exit",
        "fname: dc.b \"/h5/mzdelf\",0",
        "mok: dc.b \"MODE 0 OPEN KEPT THE FILE\",$0D", "mokl equ *-mok",
        "mbad: dc.b \"MODE 0 OPEN DID NOT COUNT\",$0D", "mbadl equ *-mbad",
        "  ends", ""
    ]
    try? lines.joined(separator: "\r").write(toFile: scratchDisk + "/mzdel.a", atomically: true, encoding: .utf8)
    let name = "host dir: I$Delete refuses a file held open in mode 0, and deletes it once closed"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        FileManager.default.createFile(atPath: scratchDisk + "/mzdelf", contents: Data("held\r".utf8))
        let out = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                       "r68 /h5/mzdel.a -o=/h5/mzdel.r", "l68 /h5/mzdel.r -o=/h5/mzdel",
                       "/h5/mzdel"], timeout: 60)
        if out.contains("MODE 0 OPEN KEPT THE FILE") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = out.split(whereSeparator: \.isNewline).filter { $0.contains("MODE 0") || $0.contains("Error") }
            print("      saw: \(seen.joined(separator: " | "))")
            failed += 1
        }
    }
    for leftover in ["mzdel.a", "mzdel.r", "mzdel", "mzdelf"] {
        try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
    }
}

// ── module: F$SetCRC refuses an image whose size field is too small ───────────
// "The module must have correct size and sync bytes; other parts of the module
// are not checked." (Technical Manual, F$SetCRC, p.1-50), E$BMID. Only the sync
// word was checked; a size of 0 made the CRC run over some 4 GB and killed the
// caller with a bus error. Found by the 2026-09-15 argument audit, probed live.
do {
    let lines = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit   equ $06", "F$SetCRC equ $26", "I$WritLn equ $8C", "BUF equ -32700",
        "  psect msetcrc,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  lea BUF(a6),a1", "  moveq #63,d2",
        "zero:", "  clr.b (a1)+", "  dbra d2,zero",
        "  move.w #$4AFC,BUF(a6)", "  clr.l BUF+4(a6)",
        "  lea BUF(a6),a0", "  OS9 F$SetCRC",
        "  bcc.s accepted", "  cmpi.w #205,d1", "  bne.s accepted",
        "  lea mref(pc),a0", "  moveq #mrefl,d1", "  bra.s write",
        "accepted:", "  lea macc(pc),a0", "  moveq #maccl,d1",
        "write:", "  moveq #1,d0", "  OS9 I$WritLn",
        "  moveq #0,d1", "  OS9 F$Exit",
        "mref: dc.b \"SETCRC SIZE REFUSED\",$0D", "mrefl equ *-mref",
        "macc: dc.b \"SETCRC SIZE ACCEPTED\",$0D", "maccl equ *-macc",
        "  ends", ""
    ]
    try? lines.joined(separator: "\r").write(toFile: scratchDisk + "/msetcrc.a", atomically: true, encoding: .utf8)
    let name = "module: F$SetCRC refuses an image whose size field is too small"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let out = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                       "r68 /h5/msetcrc.a -o=/h5/msetcrc.r", "l68 /h5/msetcrc.r -o=/h5/msetcrc",
                       "/h5/msetcrc"], timeout: 60)
        if out.contains("SETCRC SIZE REFUSED") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = out.split(whereSeparator: \.isNewline).filter { $0.contains("SETCRC") || $0.contains("Error") }
            print("      saw: \(seen.joined(separator: " | "))")
            failed += 1
        }
    }
    for suffix in [".a", ".r", ""] {
        try? FileManager.default.removeItem(atPath: scratchDisk + "/msetcrc" + suffix)
    }
}

// ── RBF I$MakDir: the permissions in d1, and the execution bit ────────────────
// I$MakDir (Technical Manual p.2-15): "The remaining attributes are specified by
// the bytes passed in register d1.w", and "If the execution bit is set, OS-9
// begins searching for the file in the working execution directory". On an RBF
// image the attributes were forced to $BF and the execution bit dropped. Found
// by the 2026-09-15 argument audit, probed live.
do {
    func program(_ name: String, _ mode: String, _ attr: String, _ path: String) -> [String] {
        ["  use /dd/DEFS/oskdefs.d", "F$Exit equ $06", "I$MakDir equ $85",
         "  psect \(name),(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
         "start:", "  lea dname(pc),a0", "  moveq #\(mode),d0", "  move.w #\(attr),d1",
         "  OS9 I$MakDir", "  bcs.s fail", "  moveq #0,d1", "fail:", "  OS9 F$Exit",
         "dname: dc.b \"\(path)\",0", "  ends", ""]
    }
    let modules = ["mmkatt": program("mmkatt", "$01", "$0003", "/hq/md3"),
                   "mmkexe": program("mmkexe", "$05", "$003F", "mdx")]
    for (module, lines) in modules {
        try? lines.joined(separator: "\r").write(toFile: scratchDisk + "/\(module).a",
                                                  atomically: true, encoding: .utf8)
    }
    let attrName = "rbf: I$MakDir gives a new directory the permissions asked for in d1"
    let execName = "rbf: I$MakDir with the execution bit makes a relative directory in the exec directory"
    let chosen = [attrName, execName].filter { filter.isEmpty || $0.localizedCaseInsensitiveContains(filter) }
    if !chosen.isEmpty {
        var build = ["load /dd/CMDS/r68 /dd/CMDS/l68"]
        for module in modules.keys.sorted() {
            build += ["r68 /h5/\(module).a -o=/h5/\(module).r", "l68 /h5/\(module).r -o=/h5/\(module)"]
        }
        _ = os9(build, timeout: 60)
    }
    func report(_ name: String, _ good: Bool, _ out: String) {
        if good {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let lines = out.split(whereSeparator: \.isNewline).filter {
                $0.contains("md3") || $0.contains("mdx") || $0.contains("Directory of") || $0.contains("Error")
            }
            print("      saw: \(lines.joined(separator: " | "))")
            failed += 1
        }
    }
    if chosen.contains(attrName) {
        removeScratchItem("hq")
        let out = os9(["mount -k=1M hq", "/h5/mmkatt", "attr /hq/md3"], timeout: 30)
        let good = out.split(whereSeparator: \.isNewline).contains {
            !$0.hasPrefix("$") && $0.contains("/hq/md3")
                && $0.trimmingCharacters(in: .whitespaces).hasPrefix("d-----wr")
        }
        report(attrName, good, out)
    }
    if chosen.contains(execName) {
        removeScratchItem("hq")
        removeScratchItem("mdx")
        let out = os9(["mount -k=1M hq", "makdir /hq/X", "chd /h5", "chx /hq/X", "/h5/mmkexe",
                       "chx /dd/CMDS", "dir /hq/X"], timeout: 30)
        let listing = out.components(separatedBy: "Directory of /hq/X").dropFirst().joined()
        report(execName, listing.contains("mdx"), out)
        removeScratchItem("mdx")
    }
    removeScratchItem("hq")
    for module in modules.keys {
        for suffix in [".a", ".r", ""] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/\(module)" + suffix)
        }
    }
}

// ── error: F$PErr prints the message for the error from the path it is given ──
// F$PErr (Technical Manual p.1-44): "If an error path number is specified, the
// path is searched for a text description of the error ... If the error number
// matches the first seven characters in a line (that is, 000:215), the rest of
// the line is printed along with the error number", continued on lines that begin
// with a space. d0.w was ignored and the built-in text always printed. Found by
// the 2026-09-15 argument audit, probed live.
do {
    let messages = "000:216 CUSTOM-MESSAGE-216\r    continued-line-216\r000:217 OTHER-MESSAGE-217\r"
    try? messages.write(toFile: scratchDisk + "/errmsgs.txt", atomically: true, encoding: .utf8)
    let lines = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit   equ $06", "F$PErr   equ $0F", "I$Open   equ $84",
        "  psect mperr,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  lea fname(pc),a0", "  moveq #1,d0", "  OS9 I$Open", "  bcs.s fail",
        "  move.w #216,d1", "  OS9 F$PErr",
        "  moveq #0,d1",
        "fail:", "  OS9 F$Exit",
        "fname: dc.b \"/h5/errmsgs.txt\",0",
        "  ends", ""
    ]
    try? lines.joined(separator: "\r").write(toFile: scratchDisk + "/mperr.a", atomically: true, encoding: .utf8)
    let name = "error: F$PErr prints the message for the error from the path it is given"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let out = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                       "r68 /h5/mperr.a -o=/h5/mperr.r", "l68 /h5/mperr.r -o=/h5/mperr",
                       "/h5/mperr"], timeout: 60)
        if out.contains("CUSTOM-MESSAGE-216") && out.contains("continued-line-216")
            && !out.contains("OTHER-MESSAGE-217") && !out.contains("Path Name Not Found") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = out.split(whereSeparator: \.isNewline).filter {
                $0.contains("216") || $0.contains("217") || $0.contains("Error")
            }
            print("      saw: \(seen.joined(separator: " | "))")
            failed += 1
        }
    }
    for item in ["mperr.a", "mperr.r", "mperr", "errmsgs.txt"] {
        try? FileManager.default.removeItem(atPath: scratchDisk + "/" + item)
    }
}

// ── I$Delete of a directory on a host directory device ──────────────────────
// Deleting a directory without the directory bit in the mode is E$FNA on RBF,
// and deldir relies on it: it tries I$Delete on every entry, and E$FNA is its
// cue to descend and empty that directory first. The host device let remove()
// answer instead -- an empty directory vanished whatever the mode, a full one
// gave E$DNE -- so `deldir -q` of any tree with a non-empty subdirectory failed
// on a host directory and deleted nothing.
//
// And after descending, deldir re-opens the parent and seeks past the slot it
// left. RBF keeps a deleted entry's slot, so the entries after it stay where
// they were; a host listing closed up, the seek landed one entry too far, and
// every entry after a subdirectory was left behind (then E$DNE). The tree
// mixes files and subdirectories so that some file follows a subdirectory in
// whatever order the host lists them.
do {
    let tree = "t_deltree"
    removeScratchItem(tree)
    let treeCommands = ["makdir \(scratch)/\(tree)"]
        + ["inner", "second"].flatMap { dir in
            ["makdir \(scratch)/\(tree)/\(dir)", "echo x >\(scratch)/\(tree)/\(dir)/g"]
        }
        + ["f1", "f2", "f3", "f4"].map { "echo x >\(scratch)/\(tree)/\($0)" }
    run("fs: deldir -q removes a tree of files and non-empty subdirectories on a host directory",
        expectation: "the tree, its subdirectories and every file are all gone",
        commands: treeCommands + ["deldir -q \(scratch)/\(tree)"]) { _ in
        !FileManager.default.fileExists(atPath: scratchDisk + "/" + tree)
    }
    removeScratchItem(tree)

    let plainDir = "t_delplaindir"
    removeScratchItem(plainDir)
    run("fs: del of an empty directory on a host directory is refused with E$FNA, as on RBF",
        expectation: "Error #000:214, and the directory is still there",
        commands: ["makdir \(scratch)/\(plainDir)", "del \(scratch)/\(plainDir)"]) { out in
        out.contains("#000:214") && FileManager.default.fileExists(atPath: scratchDisk + "/" + plainDir)
    }
    removeScratchItem(plainDir)

    // A directory link inside the device: deldir empties the directory the link
    // names, then clears the link's directory bit through SS_Attr, which removes
    // the link. On macOS that removal was rmdir(), which refuses a symlink
    // (ENOTDIR, E$PNNF): deldir failed and the link stayed. Linux's remove()
    // already took the link away. The directory it named stays, empty.
    let linkTarget = "t_dellinktarget"
    let dirLink = "t_dellink"
    removeScratchItem(dirLink)
    removeScratchItem(linkTarget)
    try? FileManager.default.createDirectory(atPath: scratchDisk + "/" + linkTarget,
                                             withIntermediateDirectories: false)
    try? "x\r".write(toFile: scratchDisk + "/" + linkTarget + "/f1", atomically: true, encoding: .utf8)
    try? FileManager.default.createSymbolicLink(atPath: scratchDisk + "/" + dirLink,
                                                withDestinationPath: linkTarget)
    run("fs: deldir -q of a directory link on a host directory removes the link and empties its directory",
        expectation: "the link is gone; the directory it named is still there, and empty",
        commands: ["deldir -q \(scratch)/\(dirLink)"]) { _ in
        let fileManager = FileManager.default
        let linkGone = (try? fileManager.destinationOfSymbolicLink(atPath: scratchDisk + "/" + dirLink)) == nil
        return linkGone && (try? fileManager.contentsOfDirectory(atPath: scratchDisk + "/" + linkTarget)) == []
    }
    removeScratchItem(dirLink)
    removeScratchItem(linkTarget)
}

// ── F$Event: an empty event name is E$BNam ──────────────────────────────────
// "E$BNam  Name is syntactically incorrect or longer than 11 characters"
// (Ev$Link, Ev$Creat, Ev$Delet). The manual gives event names no syntax of
// their own, so only the length was checked: Ev$Creat of "" made an event
// with no name, and Ev$Link of "" answered E$EvNF. Whatever the syntax is, an
// empty name is not in it -- F$PrsNam calls a null name a bad name.
do {
    let evAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "",
        "F$Exit   equ  $06",
        "F$Event  equ  $53",
        "I$WritLn equ  $8C",
        "",
        "  psect evbnam,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,512,start",
        "",
        "start:",
        "  lea     empty(pc),a0",
        "  moveq   #0,d0",
        "  move.w  #2,d1",           // Ev_Creat
        "  moveq   #0,d2",
        "  moveq   #0,d3",
        "  OS9     F$Event",
        "  bcc     fail",
        "  cmp.w   #235,d1",
        "  bne     fail",
        "  lea     empty(pc),a0",
        "  move.w  #0,d1",           // Ev_Link
        "  OS9     F$Event",
        "  bcc     fail",
        "  cmp.w   #235,d1",
        "  bne     fail",
        "  lea     okmsg(pc),a0",
        "  moveq   #okmsgl,d1",
        "  moveq   #1,d0",
        "  OS9     I$WritLn",
        "  bra     done",
        "fail:",
        "  lea     failmsg(pc),a0",
        "  moveq   #failmsgl,d1",
        "  moveq   #1,d0",
        "  OS9     I$WritLn",
        "done:",
        "  moveq   #0,d1",
        "  OS9     F$Exit",
        "empty:    dc.b  0",
        "okmsg:    dc.b  \"EVENT EMPTY NAME REFUSED\",$0D",
        "okmsgl    equ   *-okmsg",
        "failmsg:  dc.b  \"EVENT EMPTY NAME TAKEN\",$0D",
        "failmsgl  equ   *-failmsg",
        "",
        "  ends",
        ""
    ].joined(separator: "\r")

    try? evAsm.write(toFile: scratchDisk + "/evbnam.a", atomically: true, encoding: .utf8)

    let name = "f$event: Ev_Creat and Ev_Link of an empty name are E$BNam"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let out = os9([
            "load /dd/CMDS/r68 /dd/CMDS/l68",
            "r68 /h5/evbnam.a -o=/h5/evbnam.r",
            "l68 /h5/evbnam.r -o=/h5/evbnam",
            "/h5/evbnam"
        ], timeout: 20)
        if out.contains("EVENT EMPTY NAME REFUSED") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = out.split(whereSeparator: \.isNewline).filter {
                $0.contains("EVENT EMPTY") || $0.contains("Error")
            }
            print("      saw: \(seen.joined(separator: " | "))")
            failed += 1
        }
    }
    for item in ["evbnam.a", "evbnam.r", "evbnam"] {
        try? FileManager.default.removeItem(atPath: scratchDisk + "/" + item)
    }
}

// ── F$DExec: its outputs, and a child that terminates ─────────────────────────
// F$DExec (p.1-14) returns "d1.l = remaining count not executed" and "d2.w =
// exception occurred, if non-zero"; os9exec set d0 alone, so d1 and d2 came
// back as the caller's own count and breakpoint count, which reads as an
// exception on every stop. "If the child process terminates for any reason,
// the carry bit is set and returned", and "A F$DExit call must be made to
// return the debugged process's resources": the parent was woken with no
// carry, and F$DExit then refused the child it had forked (E$IPrcID).
do {
    let header = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit   equ $06", "F$DFork  equ $22", "F$DExec  equ $23", "F$DExit  equ $24", "I$WritLn equ $8C",
        "REGS     equ -32700"
    ]
    func say(_ label: String) -> [String] {
        ["  lea \(label)(pc),a0", "  moveq #\(label)l,d1", "  moveq #1,d0", "  OS9 I$WritLn"]
    }
    func message(_ label: String, _ text: String) -> [String] {
        ["\(label): dc.b \"\(text)\",$0D", "\(label)l equ *-\(label)"]
    }
    let child = header + [
        "  psect mdxchd,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:", "  nop", "  nop", "  nop", "  nop", "  moveq #0,d1", "  OS9 F$Exit", "  ends", ""]
    let parent = header + [
        "  psect mdxpar,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  lea cname(pc),a0", "  lea cparm(pc),a1", "  lea REGS(a6),a2", "  moveq #0,d0", "  moveq #0,d1",
        "  moveq #1,d2", "  moveq #3,d3", "  moveq #0,d4", "  OS9 F$DFork", "  bcs.w fail",
        "  moveq #0,d5", "  move.w d0,d5",
        // two instructions, one breakpoint that is never reached
        "  move.l d5,d0", "  moveq #2,d1", "  moveq #1,d2", "  lea bkpt(pc),a0", "  OS9 F$DExec",
        "  bcs.s stepbad", "  tst.l d1", "  bne.s stepbad", "  tst.w d2", "  bne.s stepbad"] +
        say("mstepok") + ["  bra.s run", "stepbad:"] + say("mstepbad") + [
        "run:",
        "  move.l d5,d0", "  moveq #0,d1", "  moveq #0,d2", "  OS9 F$DExec",
        "  bcc.s exitbad", "  cmpi.w #228,d1", "  bne.s exitbad"] +
        say("mexitok") + ["  bra.s dexit", "exitbad:"] + say("mexitbad") + [
        "dexit:",
        "  move.l d5,d0", "  OS9 F$DExit", "  bcs.s dxbad"] +
        say("mdxok") + ["  bra.s done", "dxbad:"] + say("mdxbad") + [
        "done:", "  moveq #0,d1",
        "fail:", "  OS9 F$Exit",
        "cname: dc.b \"/h5/mdxchd\",0", "cparm: dc.b $0D", "  align",
        "bkpt: dc.l 0"] +
        message("mstepok", "DEXEC STEP OUTPUTS OK") + message("mstepbad", "DEXEC STEP OUTPUTS WRONG") +
        message("mexitok", "DEXEC EXIT REPORTED") + message("mexitbad", "DEXEC EXIT NOT REPORTED") +
        message("mdxok", "DEXIT AFTER EXIT OK") + message("mdxbad", "DEXIT AFTER EXIT REFUSED") + ["  ends", ""]

    let modules = ["mdxchd": child, "mdxpar": parent]
    for (module, lines) in modules {
        try? lines.joined(separator: "\r").write(toFile: scratchDisk + "/\(module).a",
                                                  atomically: true, encoding: .utf8)
    }
    let name = "process: F$DExec returns its remaining count and no exception, and reports a child's exit"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        var build = ["load /dd/CMDS/r68 /dd/CMDS/l68"]
        for module in modules.keys.sorted() {
            build += ["r68 /h5/\(module).a -o=/h5/\(module).r", "l68 /h5/\(module).r -o=/h5/\(module)"]
        }
        _ = os9(build, timeout: 60)
        let out = os9(["/h5/mdxpar"], timeout: 30)
        let want = ["DEXEC STEP OUTPUTS OK", "DEXEC EXIT REPORTED", "DEXIT AFTER EXIT OK"]
        if want.allSatisfy({ out.contains($0) }) {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let lines = out.split(whereSeparator: \.isNewline).filter {
                $0.contains("DEXEC") || $0.contains("DEXIT") || $0.contains("Error")
            }
            print("      saw: \(lines.joined(separator: " | "))")
            failed += 1
        }
    }
    for module in modules.keys {
        for suffix in [".a", ".r", ""] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/\(module)" + suffix)
        }
    }
}

// ── F$DExec steps its child and nobody else ───────────────────────────────────
// The one-instruction step is the CPU's, and F$DExec armed it for whichever
// process ran next. With the debugged child parked in a terminal read, that was
// a bystander: it ran one instruction per trip through the scheduler until its
// next system call -- a 60-million-iteration loop took 48s instead of under 2
// (found by the pre-release review; measured before the fix). A pipe read parks
// differently and never showed it, which is why the child reads the terminal.
do {
    let header = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit equ $06", "F$Sleep equ $0A", "F$DFork equ $22", "F$DExec equ $23", "F$DExit equ $24",
        "I$ReadLn equ $8B", "I$WritLn equ $8C", "REGS equ -32700"
    ]
    let child = header + ["  psect mdxkid,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "  vsect", "buf: ds.b 32", "  ends", "start:",
        "  moveq #0,d0", "  lea buf(a6),a0", "  moveq #32,d1", "  OS9 I$ReadLn", "  moveq #0,d1", "  OS9 F$Exit",
        "  ends", ""]
    let debugger = header + ["  psect mdxdbg,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start", "start:",
        "  lea cname(pc),a0", "  lea cparm(pc),a1", "  lea REGS(a6),a2", "  moveq #0,d0", "  moveq #0,d1",
        "  moveq #1,d2", "  moveq #3,d3", "  moveq #0,d4", "  OS9 F$DFork", "  bcs.s fail",
        "  moveq #0,d5", "  move.w d0,d5",
        "  move.l d5,d0", "  moveq #0,d1", "  moveq #0,d2", "  OS9 F$DExec",
        "  move.l d5,d0", "  OS9 F$DExit",
        "  lea donem(pc),a0", "  moveq #2,d0", "  moveq #20,d1", "  OS9 I$WritLn", "  moveq #0,d1",
        "fail:", "  OS9 F$Exit",
        "cname: dc.b \"/h5/mdxkid\",0", "cparm: dc.b $0D", "donem: dc.b \"DEBUGGER DONE\",13", "  ends", ""]
    let bystander = header + ["  psect mdxby,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start", "start:",
        "  moveq #30,d0", "  OS9 F$Sleep",
        "  move.l #60000000,d0", "spin:", "  subq.l #1,d0", "  bne.s spin",
        "  lea donem(pc),a0", "  moveq #2,d0", "  moveq #20,d1", "  OS9 I$WritLn", "  moveq #0,d1", "  OS9 F$Exit",
        "donem: dc.b \"BYSTANDER DONE\",13", "  ends", ""]
    let modules = ["mdxkid": child, "mdxdbg": debugger, "mdxby": bystander]

    let name = "process: F$DExec steps its own child, not a bystander, while the child waits"
    if (filter.isEmpty || name.localizedCaseInsensitiveContains(filter)) && !containerized {
        var build = ["load /dd/CMDS/r68 /dd/CMDS/l68"]
        for (module, lines) in modules {
            try? lines.joined(separator: "\r").write(toFile: scratchDisk + "/\(module).a",
                                                      atomically: true, encoding: .utf8)
            build += ["r68 /h5/\(module).a -o=/h5/\(module).r", "l68 /h5/\(module).r -o=/h5/\(module)"]
        }
        _ = os9(build, timeout: 60)

        var bystanderDone = false
        var debuggerDone  = false
        var shown         = ""
        if let (ptyMain, ptyTerminal, _) = makePTY() {
            let process = Process()
            process.executableURL       = execURL
            process.arguments           = ["-r", shellArg]
            process.currentDirectoryURL = URL(fileURLWithPath: scratchDisk)
            let resolved: String = {                   // one spelling, as os9() gives it
                guard let path = realpath(scratchDisk, nil) else { return scratchDisk }
                defer { free(path) }
                return String(cString: path)
            }()
            process.environment         = ["OS9DISK": diskPath, "OS9STOP": "1",
                                           "OS9H\(scratchDev.dropFirst())": resolved]
                                          .merging(inheritedByChildren) { mine, _ in mine }
            let terminalHandle = FileHandle(fileDescriptor: ptyTerminal, closeOnDealloc: false)
            process.standardInput  = terminalHandle
            process.standardOutput = terminalHandle
            process.standardError  = terminalHandle

            if (try? process.run()) != nil {
                var seen = Data()
                func send(_ keys: String) { var bytes = Array(keys.utf8); _ = write(ptyMain, &bytes, bytes.count) }
                func wait(for text: String, _ seconds: Double) -> Bool {
                    let end = Date().addingTimeInterval(seconds)
                    var buf = [UInt8](repeating: 0, count: 65536)
                    while Date() < end {
                        if seen.range(of: Data(text.utf8)) != nil { return true }
                        var fds = pollfd(fd: ptyMain, events: Int16(POLLIN), revents: 0)
                        if poll(&fds, 1, 200) > 0 {
                            let count = read(ptyMain, &buf, buf.count)
                            if count <= 0 { break }
                            seen.append(contentsOf: buf[0..<count])
                        }
                    }
                    return seen.range(of: Data(text.utf8)) != nil
                }
                _ = wait(for: "$ ", 5)
                send("/h5/mdxby >/nil&\n")
                usleep(200_000)
                send("/h5/mdxdbg\n")
                bystanderDone = wait(for: "BYSTANDER DONE", 10)
                send("go\n")                             // the child's line: now it can finish
                debuggerDone = wait(for: "DEBUGGER DONE", 60)
                shown = String(bytes: seen.suffix(300), encoding: .utf8) ?? ""
                send("\u{1B}\n\u{04}\n")
                usleep(500_000)
                if process.isRunning { process.terminate() }
                process.waitUntilExit()
            }
            close(ptyMain); close(ptyTerminal)
        }
        if bystanderDone && debuggerDone {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            print("      bystander done within 10s: \(bystanderDone), debugger done after the line: \(debuggerDone)")
            let oneLine = shown.replacingOccurrences(of: "\r", with: "|").replacingOccurrences(of: "\n", with: "")
            print("      last shown: \(oneLine)")
            failed += 1
        }
        for module in modules.keys {
            for suffix in [".a", ".r", ""] { removeScratchItem(module + suffix) }
        }
    }
}

// ── F$DExec takes the child's registers from the buffer ─────────────────────
// F$DExec's input includes "register buffer contains child register image"
// (p.1-16), so a register a debugger changes there is what the child runs with;
// os9exec only ever wrote the buffer, so the child resumed with its own. And
// F$DFork's child "is created with the trace bit of its status register set"
// (p.1-15), which is the SR the image should show; it showed $0000. Both found
// by the skills session. The child's first instruction copies d5 to d6: after
// one step with d5 set to $12345678 in the buffer, d6 there must be the same.
do {
    let header = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit   equ $06", "F$DFork  equ $22", "F$DExec  equ $23", "F$DExit  equ $24", "I$WritLn equ $8C",
        "REGS     equ -32700"
    ]
    func say(_ label: String) -> [String] {
        ["  lea \(label)(pc),a0", "  moveq #\(label)l,d1", "  moveq #1,d0", "  OS9 I$WritLn"]
    }
    func message(_ label: String, _ text: String) -> [String] {
        ["\(label): dc.b \"\(text)\",$0D", "\(label)l equ *-\(label)"]
    }
    let child = header + [
        "  psect mdrchd,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:", "  move.l d5,d6", "  moveq #0,d1", "  OS9 F$Exit", "  ends", ""]
    let parent = header + [
        "  psect mdrpar,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  lea cname(pc),a0", "  lea cparm(pc),a1", "  lea REGS(a6),a2", "  moveq #0,d0", "  moveq #0,d1",
        "  moveq #1,d2", "  moveq #3,d3", "  moveq #0,d4", "  OS9 F$DFork", "  bcs.w fail",
        "  moveq #0,d7", "  move.w d0,d7",
        "  move.w REGS+$40(a6),d0", "  btst #15,d0", "  beq.s notrace"] + say("mtrace") + [
        "  bra.s edit", "notrace:"] + say("mnotrace") + [
        "edit:",
        "  move.l #$12345678,REGS+$14(a6)",          // d5 in the buffer
        "  move.l d7,d0", "  moveq #1,d1", "  moveq #0,d2", "  OS9 F$DExec", "  bcs.s regbad",
        "  cmpi.l #$12345678,REGS+$18(a6)",          // d6 in the buffer
        "  bne.s regbad"] + say("mregok") + ["  bra.s dexit", "regbad:"] + say("mregbad") + [
        "dexit:",
        "  move.l d7,d0", "  OS9 F$DExit",
        "  moveq #0,d1",
        "fail:", "  OS9 F$Exit",
        "cname: dc.b \"/h5/mdrchd\",0", "cparm: dc.b $0D", "  align"] +
        message("mtrace", "DFORK IMAGE HAS TRACE SET") + message("mnotrace", "DFORK IMAGE HAS NO TRACE") +
        message("mregok", "DEXEC USED THE BUFFER") + message("mregbad", "DEXEC IGNORED THE BUFFER") + ["  ends", ""]

    let modules = ["mdrchd": child, "mdrpar": parent]
    for (module, lines) in modules {
        try? lines.joined(separator: "\r").write(toFile: scratchDisk + "/\(module).a",
                                                  atomically: true, encoding: .utf8)
    }
    let name = "process: F$DExec resumes the child from its register buffer, whose SR shows the trace bit"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        var build = ["load /dd/CMDS/r68 /dd/CMDS/l68"]
        for module in modules.keys.sorted() {
            build += ["r68 /h5/\(module).a -o=/h5/\(module).r", "l68 /h5/\(module).r -o=/h5/\(module)"]
        }
        _ = os9(build, timeout: 60)
        let out = os9(["/h5/mdrpar"], timeout: 30)
        if out.contains("DFORK IMAGE HAS TRACE SET") && out.contains("DEXEC USED THE BUFFER") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let lines = out.split(whereSeparator: \.isNewline).filter {
                $0.contains("DEXEC") || $0.contains("DFORK") || $0.contains("Error")
            }
            print("      saw: \(lines.joined(separator: " | "))")
            failed += 1
        }
    }
    for module in modules.keys {
        for suffix in [".a", ".r", ""] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/\(module)" + suffix)
        }
    }
}

// ── 68881: a double result is stored exactly, and x/0 is an infinity ──────────
// The FPU emulation (UAE's fpp.c) rebuilt a double with frexp and "rounded" it by
// adding half an ULP to a value that already had exactly 53 bits; that add rounded
// to even, so every odd mantissa was stored one ULP high: 3/10 as ...334, 1/3 as
// ...556. An infinity went through frexp as well and came out as garbage
// ($3FFFFFFFFFFFFFFF, which BASIC09 under math881 printed as 2.). Found by the
// skills session. The FPU instructions are written as words so that the test
// does not depend on the assembler knowing them: fmove.d (a0),fp0 / fdiv.d
// (a1),fp0 / fmove.d fp0,(a2).
do {
    func divide(_ num: String, _ den: String) -> [String] {
        ["  lea \(num)(pc),a0", "  dc.w $F210,$5400", "  lea \(den)(pc),a1", "  dc.w $F211,$5420",
         "  lea scr(a6),a2", "  dc.w $F212,$7400"]
    }
    let fpuAsm = ([
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit equ $06", "I$WritLn equ $8C",
        "  psect mfdiv,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start", "  vsect", "scr: ds.b 4096", "  ends",
        "start:"] + divide("three", "ten") + [
        "  cmpi.l #$3FD33333,(a2)", "  bne.s wrong", "  cmpi.l #$33333333,4(a2)", "  bne.s wrong"] +
        divide("one", "three") + [
        "  cmpi.l #$3FD55555,(a2)", "  bne.s wrong", "  cmpi.l #$55555555,4(a2)", "  bne.s wrong"] +
        divide("five", "zero") + [
        "  cmpi.l #$7FF00000,(a2)", "  bne.s wrong", "  tst.l 4(a2)", "  bne.s wrong",
        "  lea mok(pc),a0", "  moveq #mokl,d1", "  bra.s say",
        "wrong:", "  lea mbad(pc),a0", "  moveq #mbadl,d1",
        "say:", "  moveq #1,d0", "  OS9 I$WritLn", "  moveq #0,d1", "  OS9 F$Exit",
        "one:   dc.l $3FF00000,0", "three: dc.l $40080000,0", "five:  dc.l $40140000,0",
        "ten:   dc.l $40240000,0", "zero:  dc.l 0,0",
        "mok:  dc.b \"FDIV STORED EXACTLY\",$0D", "mokl equ *-mok",
        "mbad: dc.b \"FDIV STORED WRONG\",$0D", "mbadl equ *-mbad",
        "  ends", ""
    ]).joined(separator: "\r")

    let name = "fpu: a 68881 double is stored exactly (3/10, 1/3) and 5/0 stores as an infinity"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? fpuAsm.write(toFile: scratchDisk + "/mfdiv.a", atomically: true, encoding: .utf8)
        let out = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                       "r68 /h5/mfdiv.a -o=/h5/mfdiv.r", "l68 /h5/mfdiv.r -o=/h5/mfdiv",
                       "/h5/mfdiv"], timeout: 30)
        if out.contains("FDIV STORED EXACTLY") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = out.split(whereSeparator: \.isNewline).filter { $0.contains("FDIV") || $0.contains("Error") }
            print("      saw: \(seen.joined(separator: " | "))")
            failed += 1
        }
        for leftover in ["mfdiv.a", "mfdiv.r", "mfdiv"] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
        }
    }
}

// ── 68881: FINT, FINTRZ, FMOD and FREM keep their results floating ────────────
// All four went through a C (int): FINT(-2.3) truncated to -1 and FINT(2.5) came
// out 3 where the 68881 rounds to nearest even (-2, 2); FINTRZ(1e10) and
// FMOD(1e10,3) overflowed the int, which is undefined in C and a wrong answer on
// every host; FREM(-7,2), whose quotient rounds to nearest (-4), gave -1 for 1.
// Found by review. Written as words, like the FDIV test: fmove.d (a0),fp0 /
// <op>.d (a1),fp0 / fmove.d fp0,(a2).
do {
    func apply(_ opword: String, _ dst: String, _ src: String, _ want: String) -> [String] {
        ["  lea \(dst)(pc),a0", "  dc.w $F210,$5400", "  lea \(src)(pc),a1", "  dc.w $F211,\(opword)",
         "  lea scr(a6),a2", "  dc.w $F212,$7400", "  lea \(want)(pc),a3",
         "  cmpm.l (a3)+,(a2)+", "  bne.w wrong", "  cmpm.l (a3)+,(a2)+", "  bne.w wrong"]
    }
    let fpuAsm = ([
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit equ $06", "I$WritLn equ $8C",
        "  psect mfint,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start", "  vsect", "scr: ds.b 4096", "  ends",
        "start:"] +
        apply("$5401", "one", "mtwo3", "mtwo") +      // FINT(-2.3)    = -2
        apply("$5401", "one", "twohalf", "two") +     // FINT(2.5)     = 2
        apply("$5403", "one", "e10", "e10") +         // FINTRZ(1e10)  = 1e10
        apply("$5421", "e10", "three", "one") +       // FMOD(1e10,3)  = 1
        apply("$5425", "mseven", "two", "one") + [    // FREM(-7,2)    = 1
        "  lea mok(pc),a0", "  moveq #mokl,d1", "  bra.s say",
        "wrong:", "  lea mbad(pc),a0", "  moveq #mbadl,d1",
        "say:", "  moveq #1,d0", "  OS9 I$WritLn", "  moveq #0,d1", "  OS9 F$Exit",
        "one:     dc.l $3FF00000,0", "two:     dc.l $40000000,0", "mtwo:    dc.l $C0000000,0",
        "mtwo3:   dc.l $C0026666,$66666666", "twohalf: dc.l $40040000,0",
        "three:   dc.l $40080000,0", "mseven:  dc.l $C01C0000,0", "e10:     dc.l $4202A05F,$20000000",
        "mok:  dc.b \"FINT FAMILY EXACT\",$0D", "mokl equ *-mok",
        "mbad: dc.b \"FINT FAMILY WRONG\",$0D", "mbadl equ *-mbad",
        "  ends", ""
    ]).joined(separator: "\r")

    let name = "fpu: 68881 FINT rounds to nearest even, and FINTRZ, FMOD and FREM stay exact past 2^31"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? fpuAsm.write(toFile: scratchDisk + "/mfint.a", atomically: true, encoding: .utf8)
        let out = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                       "r68 /h5/mfint.a -o=/h5/mfint.r", "l68 /h5/mfint.r -o=/h5/mfint",
                       "/h5/mfint"], timeout: 30)
        if out.contains("FINT FAMILY EXACT") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = out.split(whereSeparator: \.isNewline).filter { $0.contains("FINT") || $0.contains("Error") }
            print("      saw: \(seen.joined(separator: " | "))")
            failed += 1
        }
        for leftover in ["mfint.a", "mfint.r", "mfint"] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
        }
    }
}

// ── 68881: a float stored as an integer rounds by FPCR and saturates ──────────
// FMOVE to a byte, word or long was a C cast: it truncated whatever FPCR's
// rounding mode said, and past the format's range was undefined behaviour (the
// host decided what came out). The 68881 rounds by FPCR -- to nearest even by
// default -- and stores the largest integer of the sign for a value it cannot
// hold. Found by review. Words as in the FDIV test: fmove.d (a0),fp0 /
// fmove.l fp0,d0 ($6000; .b is $7800) / fmove.l #n,fpcr.
do {
    func store(_ value: String, _ format: String = "$6000") -> [String] {
        ["  lea \(value)(pc),a0", "  dc.w $F210,$5400", "  moveq #0,d0", "  dc.w $F200,\(format)"]
    }
    let fpuAsm = ([
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit equ $06", "I$WritLn equ $8C",
        "  psect mfmovl,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:"] +
        store("twoseven") + ["  cmpi.l #3,d0", "  bne.w wrong"] +             // nearest: 3
        store("mtwohalf") + ["  cmpi.l #-2,d0", "  bne.w wrong"] +            // nearest even: -2
        store("threeg") + ["  cmpi.l #$7FFFFFFF,d0", "  bne.w wrong"] +       // too big: largest
        store("mthreeg") + ["  cmpi.l #$80000000,d0", "  bne.w wrong"] +      // too small: smallest
        store("threehundred", "$7800") + ["  cmpi.b #$7F,d0", "  bne.w wrong"] + [ // byte: 127
        "  dc.w $F23C,$9000", "  dc.l $00000010"] +                             // FPCR: toward zero
        store("twoseven") + ["  cmpi.l #2,d0", "  bne.w wrong"] + [
        "  dc.w $F23C,$9000", "  dc.l 0",
        "  lea mok(pc),a0", "  moveq #mokl,d1", "  bra.s say",
        "wrong:", "  dc.w $F23C,$9000", "  dc.l 0", "  lea mbad(pc),a0", "  moveq #mbadl,d1",
        "say:", "  moveq #1,d0", "  OS9 I$WritLn", "  moveq #0,d1", "  OS9 F$Exit",
        "twoseven:     dc.l $40059999,$9999999A", "mtwohalf:     dc.l $C0040000,0",
        "threeg:       dc.l $41E65A0B,$C0000000", "mthreeg:      dc.l $C1E65A0B,$C0000000",
        "threehundred: dc.l $4072C000,0",
        "mok:  dc.b \"FMOVE INTEGER ROUNDED\",$0D", "mokl equ *-mok",
        "mbad: dc.b \"FMOVE INTEGER WRONG\",$0D", "mbadl equ *-mbad",
        "  ends", ""
    ]).joined(separator: "\r")

    let name = "fpu: a 68881 float stored as an integer rounds by FPCR and saturates past the range"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? fpuAsm.write(toFile: scratchDisk + "/mfmovl.a", atomically: true, encoding: .utf8)
        let out = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                       "r68 /h5/mfmovl.a -o=/h5/mfmovl.r", "l68 /h5/mfmovl.r -o=/h5/mfmovl",
                       "/h5/mfmovl"], timeout: 30)
        if out.contains("FMOVE INTEGER ROUNDED") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = out.split(whereSeparator: \.isNewline).filter { $0.contains("FMOVE") || $0.contains("Error") }
            print("      saw: \(seen.joined(separator: " | "))")
            failed += 1
        }
        for leftover in ["mfmovl.a", "mfmovl.r", "mfmovl"] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
        }
    }
}

// ── F$DFork: a debugged child goes with its debugger ─────────────────────────
// A debugger that exits without F$DExit left its child asleep for ever, and the
// child kept the debugger's pid as its own: whoever got that pid next passed
// F$DExec's and F$DExit's parent checks and could drive it. It now ends with
// its debugger, as F$DExit would have ended it. Found by review.
do {
    let header = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit   equ $06", "F$DFork  equ $22",
        "REGS     equ -32700"
    ]
    let child = header + [
        "  psect mdgc,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:", "  moveq #0,d1", "  OS9 F$Exit", "  ends", ""]
    let parent = header + [
        "  psect mdgp,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  lea cname(pc),a0", "  lea cparm(pc),a1", "  lea REGS(a6),a2", "  moveq #0,d0", "  moveq #0,d1",
        "  moveq #1,d2", "  moveq #3,d3", "  moveq #0,d4", "  OS9 F$DFork",
        "  moveq #0,d1", "  OS9 F$Exit",                           // no F$DExit
        "cname: dc.b \"/h5/mdgc\",0", "cparm: dc.b $0D", "  ends", ""]
    let modules = ["mdgc": child, "mdgp": parent]
    for (module, lines) in modules {
        try? lines.joined(separator: "\r").write(toFile: scratchDisk + "/\(module).a",
                                                  atomically: true, encoding: .utf8)
    }
    let name = "process: a child forked by F$DFork ends when its debugger exits without F$DExit"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        var build = ["load /dd/CMDS/r68 /dd/CMDS/l68"]
        for module in modules.keys.sorted() {
            build += ["r68 /h5/\(module).a -o=/h5/\(module).r", "l68 /h5/\(module).r -o=/h5/\(module)"]
        }
        _ = os9(build, timeout: 60)
        let out = os9(["/h5/mdgp", "procs"], timeout: 30)
        let listed = out.split(whereSeparator: \.isNewline).contains { !$0.hasPrefix("$") && $0.contains("mdgc") }
        if !listed && out.contains("procs") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = out.split(whereSeparator: \.isNewline).filter { $0.contains("mdgc") || $0.contains("Error") }
            print("      saw: \(seen.joined(separator: " | "))")
            failed += 1
        }
    }
    for module in modules.keys {
        for suffix in [".a", ".r", ""] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/\(module)" + suffix)
        }
    }
}

// ── F$SRqMem with -1 allocates the largest free block ─────────────────────────
// "If -1 is passed in d0.l, the largest block of free memory is allocated to
// the calling process" (p.1-56). os9exec granted a fixed 8 MB however much was
// free. The program takes the -1 block and, still holding it, asks for 64 bytes
// more than it was given: if that was the largest block, there is none bigger.
// (Asked after giving it back, the shell's own frees can merge with it first.)
do {
    let largestAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit   equ $06", "F$SRqMem equ $28", "F$SRtMem equ $29", "I$WritLn equ $8C",
        "  psect mlargest,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  moveq #-1,d0", "  OS9 F$SRqMem", "  bcs.s nomem",
        "  move.l d0,d5", "  movea.l a2,a3",
        "  addi.l #64,d0", "  OS9 F$SRqMem", "  bcc.s bigger",
        "  lea mok(pc),a4", "  moveq #mokl,d6", "  bra.s giveback",
        "bigger:", "  OS9 F$SRtMem",                             // d0 and a2 name the larger block
        "  lea mbig(pc),a4", "  moveq #mbigl,d6",
        "giveback:", "  move.l d5,d0", "  movea.l a3,a2", "  OS9 F$SRtMem",
        "  movea.l a4,a0", "  move.l d6,d1", "  bra.s say",
        "nomem:", "  lea mfail(pc),a0", "  moveq #mfaill,d1",
        "say:", "  moveq #1,d0", "  OS9 I$WritLn", "  moveq #0,d1", "  OS9 F$Exit",
        "mok: dc.b \"SRQMEM LARGEST OK\",$0D", "mokl equ *-mok",
        "mbig: dc.b \"SRQMEM LARGER BLOCK GRANTED\",$0D", "mbigl equ *-mbig",
        "mfail: dc.b \"SRQMEM -1 FAILED\",$0D", "mfaill equ *-mfail",
        "  ends", ""
    ].joined(separator: "\r")

    try? largestAsm.write(toFile: scratchDisk + "/mlargest.a", atomically: true, encoding: .utf8)

    let name = "f$srqmem: -1 allocates the largest free block"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let out = os9([
            "load /dd/CMDS/r68 /dd/CMDS/l68",
            "r68 /h5/mlargest.a -o=/h5/mlargest.r",
            "l68 /h5/mlargest.r -o=/h5/mlargest",
            "/h5/mlargest"
        ], timeout: 30)
        if out.contains("SRQMEM LARGEST OK") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = out.split(whereSeparator: \.isNewline).filter {
                $0.contains("SRQMEM") || $0.contains("Error")
            }
            print("      saw: \(seen.joined(separator: " | "))")
            failed += 1
        }
    }
    for item in ["mlargest.a", "mlargest.r", "mlargest"] {
        try? FileManager.default.removeItem(atPath: scratchDisk + "/" + item)
    }
}

// ── F$GBlkMp reports the free memory there is ──────────────────────────────────
// F$GBlkMp (p.1-32) returns "d1.l = Number of memory fragments", "d2.l = Total
// RAM found by system at startup", "d3.l = Current total free RAM available",
// and the address and size of each free block in the buffer, ended by 0.
// os9exec reported no fragments, an empty map, and as free RAM only what sat on
// its free list (mfree: 0.06 K free of 117 K) -- none of the 32 MB arena it had
// yet to carve. The program asks for the map in a 256-byte buffer: there must be
// a fragment, over a megabyte free, no more free than at startup, and when every
// fragment fits in the buffer, sizes that add up to the free total.
do {
    let mapAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit   equ $06", "F$GBlkMp equ $19", "I$WritLn equ $8C", "BUF equ -32700",
        "  psect mblkmap,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  moveq #0,d0", "  move.l #256,d1", "  lea BUF(a6),a0", "  OS9 F$GBlkMp", "  bcs.s bad",
        "  tst.l d1", "  beq.s bad",
        "  cmpi.l #$100000,d3", "  bls.s bad",
        "  cmp.l d3,d2", "  bcs.s bad",
        "  cmpi.l #31,d1", "  bhi.s good",                   // 31 pairs and the 0 fill 252 of 256 bytes
        "  lea BUF(a6),a1", "  moveq #0,d4",
        "sum:", "  move.l (a1)+,d5", "  beq.s summed", "  add.l (a1)+,d4", "  bra.s sum",
        "summed:", "  cmp.l d3,d4", "  bne.s bad",
        "good:", "  lea mok(pc),a0", "  moveq #mokl,d1", "  bra.s say",
        "bad:", "  lea mbad(pc),a0", "  moveq #mbadl,d1",
        "say:", "  moveq #1,d0", "  OS9 I$WritLn", "  moveq #0,d1", "  OS9 F$Exit",
        "mok: dc.b \"GBLKMP MAP OK\",$0D", "mokl equ *-mok",
        "mbad: dc.b \"GBLKMP MAP WRONG\",$0D", "mbadl equ *-mbad",
        "  ends", ""
    ].joined(separator: "\r")

    try? mapAsm.write(toFile: scratchDisk + "/mblkmap.a", atomically: true, encoding: .utf8)

    let name = "f$gblkmp: reports the free fragments, the RAM at startup and the free total"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let out = os9([
            "load /dd/CMDS/r68 /dd/CMDS/l68",
            "r68 /h5/mblkmap.a -o=/h5/mblkmap.r",
            "l68 /h5/mblkmap.r -o=/h5/mblkmap",
            "/h5/mblkmap"
        ], timeout: 30)
        if out.contains("GBLKMP MAP OK") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = out.split(whereSeparator: \.isNewline).filter {
                $0.contains("GBLKMP") || $0.contains("Error")
            }
            print("      saw: \(seen.joined(separator: " | "))")
            failed += 1
        }
    }
    for item in ["mblkmap.a", "mblkmap.r", "mblkmap"] {
        try? FileManager.default.removeItem(atPath: scratchDisk + "/" + item)
    }
}

// ── F$Load of a two-module file links the first, and the pair goes together ────
// "All modules that are loaded are added to the system module directory, and
// the first module read is linked" (F$Load, p.1-41); "When several modules are
// loaded together as a group, modules are only removed when the link count of
// all modules in the group have zero link counts" (F$UnLink, p.1-69). os9exec
// linked every module of the file, so the second one stayed in the directory,
// link count 1, after the first had been unlinked away.
do {
    func tinyModule(_ name: String) -> String {
        [
            "  use /dd/DEFS/oskdefs.d", "F$Exit equ $06",
            "  psect \(name),(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,512,start",
            "start:", "  moveq #0,d1", "  OS9 F$Exit", "  ends", ""
        ].joined(separator: "\r")
    }
    let parts = ["mgrpa", "mgrpb"]
    for part in parts {
        try? tinyModule(part).write(toFile: scratchDisk + "/\(part).a", atomically: true, encoding: .utf8)
    }
    let name = "module: F$Load of a two-module file links the first only, and unlinking it removes both"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        var build = ["load /dd/CMDS/r68 /dd/CMDS/l68"]
        for part in parts {
            build += ["r68 /h5/\(part).a -o=/h5/\(part).r", "l68 /h5/\(part).r -o=/h5/\(part)"]
        }
        _ = os9(build, timeout: 60)
        var pair = Data()
        for part in parts {
            if let bytes = FileManager.default.contents(atPath: scratchDisk + "/" + part) {
                pair.append(bytes)
            }
        }
        FileManager.default.createFile(atPath: scratchDisk + "/mgrpab", contents: pair)

        let out = os9(["load /h5/mgrpab", "mdir -e", "unlink mgrpa", "echo AFTER-UNLINK", "mdir -e"], timeout: 30)
        let lines = out.split(whereSeparator: \.isNewline).map { String($0) }
        let marker = lines.firstIndex { $0.trimmingCharacters(in: .whitespaces) == "AFTER-UNLINK" } ?? lines.count
        // mdir -e rows end "<link count> <module name>"; the shell's "$ ..." echoes are not rows
        func linkCount(of module: String, in rows: ArraySlice<String>) -> String? {
            for row in rows where !row.hasPrefix("$") {
                let fields = row.split(separator: " ")
                if fields.count >= 2, fields[fields.count - 1] == Substring(module) {
                    return String(fields[fields.count - 2])
                }
            }
            return nil
        }
        let loaded = lines[..<marker]
        let unlinked = lines[marker...]
        if linkCount(of: "mgrpa", in: loaded) == "1" && linkCount(of: "mgrpb", in: loaded) == "0"
            && linkCount(of: "mgrpa", in: unlinked) == nil && linkCount(of: "mgrpb", in: unlinked) == nil {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = lines.filter { $0.hasSuffix(" mgrpa") || $0.hasSuffix(" mgrpb") || $0.contains("AFTER-UNLINK") }
            print("      saw: \(seen.joined(separator: " | "))")
            failed += 1
        }
    }

    // The module directory's second word is the group pointer: "the module group
    // base" (F$VModul takes it in d0). It pointed every module at itself, so the
    // pair looked like two groups of one. The checker copies the directory with
    // F$GModDr and wants exactly one entry whose group is another module, and
    // that module in the directory too.
    let groupName = "module: the module directory points a file's second module at its first as the group"
    if filter.isEmpty || groupName.localizedCaseInsensitiveContains(filter) {
        let checkAsm = [
            "  use /dd/DEFS/oskdefs.d", "F$Exit equ $06", "F$GModDr equ $1A", "F$SRqMem equ $28",
            "I$WritLn equ $8C",
            "  psect mgrpchk,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,512,start",
            "start:",
            "  move.l #16384,d0", "  OS9 F$SRqMem", "  bcs.s bad", "  movea.l a2,a4",
            "  movea.l a2,a0", "  move.l d0,d1", "  OS9 F$GModDr", "  bcs.s bad",
            "  lsr.l #4,d1", "  beq.s bad",
            "  moveq #0,d6", "  movea.l a4,a3", "  move.l d1,d7",
            "scan:", "  move.l (a3),d2", "  beq.s next", "  cmp.l 4(a3),d2", "  beq.s next",
            "  addq.l #1,d6", "  move.l 4(a3),d4",
            "next:", "  lea 16(a3),a3", "  subq.l #1,d7", "  bne.s scan",
            "  cmpi.l #1,d6", "  bne.s bad",
            "  movea.l a4,a3", "  move.l d1,d7",
            "find:", "  cmp.l (a3),d4", "  beq.s good", "  lea 16(a3),a3", "  subq.l #1,d7", "  bne.s find",
            "bad:", "  lea mbad(pc),a0", "  moveq #mbadl,d1", "  bra.s say",
            "good:", "  lea mok(pc),a0", "  moveq #mokl,d1",
            "say:", "  moveq #1,d0", "  OS9 I$WritLn", "  moveq #0,d1", "  OS9 F$Exit",
            "mok:  dc.b \"GROUP POINTS AT THE FIRST\",$0D", "mokl equ *-mok",
            "mbad: dc.b \"GROUP POINTER WRONG\",$0D", "mbadl equ *-mbad",
            "  ends", ""
        ].joined(separator: "\r")
        try? checkAsm.write(toFile: scratchDisk + "/mgrpchk.a", atomically: true, encoding: .utf8)
        var build = ["load /dd/CMDS/r68 /dd/CMDS/l68",
                     "r68 /h5/mgrpchk.a -o=/h5/mgrpchk.r", "l68 /h5/mgrpchk.r -o=/h5/mgrpchk"]
        if !FileManager.default.fileExists(atPath: scratchDisk + "/mgrpab") {
            for part in parts {
                build += ["r68 /h5/\(part).a -o=/h5/\(part).r", "l68 /h5/\(part).r -o=/h5/\(part)"]
            }
        }
        _ = os9(build, timeout: 60)
        if !FileManager.default.fileExists(atPath: scratchDisk + "/mgrpab") {
            var pair = Data()
            for part in parts {
                if let bytes = FileManager.default.contents(atPath: scratchDisk + "/" + part) {
                    pair.append(bytes)
                }
            }
            FileManager.default.createFile(atPath: scratchDisk + "/mgrpab", contents: pair)
        }
        let out = os9(["load /h5/mgrpab", "/h5/mgrpchk"], timeout: 30)
        if out.contains("GROUP POINTS AT THE FIRST") {
            print("PASS: \(groupName)")
            passed += 1
        } else {
            print("FAIL: \(groupName)")
            let seen = out.split(whereSeparator: \.isNewline).filter { $0.contains("GROUP") || $0.contains("Error") }
            print("      saw: \(seen.joined(separator: " | "))")
            failed += 1
        }
    }
    for item in ["mgrpa.a", "mgrpa.r", "mgrpa", "mgrpb.a", "mgrpb.r", "mgrpb", "mgrpab",
                 "mgrpchk.a", "mgrpchk.r", "mgrpchk"] {
        try? FileManager.default.removeItem(atPath: scratchDisk + "/" + item)
    }
}

// ── Module lookup: the established module wins a tie, and type is part of the name ─
// "If a module with the same name and type exists, the one with the highest
// revision level is retained in the module directory. Ties are broken in favor
// of the established module" (F$Load). The search broke ties by LOWEST SLOT, and
// slots are reused: with two slots freed below a resident module, a file loaded
// next puts its second module -- same name, same revision -- below it, and that
// one answered from then on. The search also ignored type, so a Data module made
// with F$DatMod under a program's name answered F$Link for the program (E$MNF
// from the type check), and F$UnLoad of the program found the Data module and
// refused. Found by review.
do {
    func tinyProgram(_ name: String) -> String {
        [
            "  use /dd/DEFS/oskdefs.d", "F$Exit equ $06",
            "  psect \(name),(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,512,start",
            "start:", "  moveq #0,d1", "  OS9 F$Exit", "  ends", ""
        ].joined(separator: "\r")
    }
    let tiny = ["mtfa", "mtfb", "mtfx", "mtie", "mshad"]
    let checkAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Link equ $00", "F$Load equ $01", "F$UnLink equ $02", "F$Exit equ $06", "F$UnLoad equ $1D",
        "F$DatMod equ $25", "I$WritLn equ $8C",
        "  psect mlkchk,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        // two modules, then the one that will be established, then free the two slots below it
        "  lea pa(pc),a0", "  moveq #0,d0", "  OS9 F$Load", "  bcs.w bad", "  movea.l a2,a5",
        "  lea pb(pc),a0", "  moveq #0,d0", "  OS9 F$Load", "  bcs.w bad", "  movea.l a2,a4",
        "  lea pt(pc),a0", "  moveq #0,d0", "  OS9 F$Load", "  bcs.w bad", "  move.l a2,d7",
        "  movea.l a5,a2", "  OS9 F$UnLink", "  bcs.w bad",
        "  movea.l a4,a2", "  OS9 F$UnLink", "  bcs.w bad",
        // a file whose second module is mtie again, landing in a lower slot
        "  lea pg(pc),a0", "  moveq #0,d0", "  OS9 F$Load", "  bcs.w bad",
        "  lea nt(pc),a0", "  moveq #0,d0", "  OS9 F$Link", "  bcs.w bad",
        "  cmp.l a2,d7", "  bne.w bad",
        // a Data module under a program's name, then the program
        "  lea ns(pc),a0", "  moveq #64,d0", "  moveq #0,d1", "  move.w #$0333,d2", "  OS9 F$DatMod",
        "  bcs.w bad",
        "  lea ps(pc),a0", "  moveq #0,d0", "  OS9 F$Load", "  bcs.w bad", "  move.l a2,d6",
        "  lea ns(pc),a0", "  move.w #$0101,d0", "  OS9 F$Link", "  bcs.w bad",
        "  cmp.l a2,d6", "  bne.w bad",
        "  lea ns(pc),a0", "  move.w #$0100,d0", "  OS9 F$UnLoad", "  bcs.w bad",
        "  lea mok(pc),a0", "  moveq #mokl,d1", "  bra.s say",
        "bad:", "  lea mbad(pc),a0", "  moveq #mbadl,d1",
        "say:", "  moveq #1,d0", "  OS9 I$WritLn", "  moveq #0,d1", "  OS9 F$Exit",
        "pa: dc.b \"/h5/mtfa\",0", "pb: dc.b \"/h5/mtfb\",0", "pt: dc.b \"/h5/mtie\",0",
        "pg: dc.b \"/h5/mtgrp\",0", "ps: dc.b \"/h5/mshad\",0", "nt: dc.b \"mtie\",0", "ns: dc.b \"mshad\",0",
        "mok:  dc.b \"LOOKUP KEEPS THE ESTABLISHED AND THE TYPE\",$0D", "mokl equ *-mok",
        "mbad: dc.b \"LOOKUP FOUND THE WRONG MODULE\",$0D", "mbadl equ *-mbad",
        "  ends", ""
    ].joined(separator: "\r")

    let name = "module: of equal revisions the established module answers, and only a module of the type asked"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        var build = ["load /dd/CMDS/r68 /dd/CMDS/l68"]
        for module in tiny + ["mlkchk"] {
            let source = module == "mlkchk" ? checkAsm : tinyProgram(module)
            try? source.write(toFile: scratchDisk + "/\(module).a", atomically: true, encoding: .utf8)
            build += ["r68 /h5/\(module).a -o=/h5/\(module).r", "l68 /h5/\(module).r -o=/h5/\(module)"]
        }
        _ = os9(build, timeout: 90)
        var group = Data()
        for part in ["mtfx", "mtie"] {
            if let bytes = FileManager.default.contents(atPath: scratchDisk + "/" + part) {
                group.append(bytes)
            }
        }
        FileManager.default.createFile(atPath: scratchDisk + "/mtgrp", contents: group)
        let out = os9(["/h5/mlkchk"], timeout: 30)
        if out.contains("LOOKUP KEEPS THE ESTABLISHED AND THE TYPE") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = out.split(whereSeparator: \.isNewline).filter { $0.contains("LOOKUP") || $0.contains("Error") }
            print("      saw: \(seen.joined(separator: " | "))")
            failed += 1
        }
    }
    for module in tiny + ["mlkchk"] {
        for suffix in [".a", ".r", ""] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/\(module)" + suffix)
        }
    }
    try? FileManager.default.removeItem(atPath: scratchDisk + "/mtgrp")
}

// ── RBF: SS_Size allocates the space it gives a file ───────────────────────────
// "The SETSTAT call (SS_Size) explicitly allocates file space" (I$Create,
// p.2-5). On an RBF image SS_Size only wrote the new size into the FD: no
// sector was allocated, so a read inside the new size found nothing there and
// answered E$EOF. The program creates a file, sets its size to 3000, and reads
// 16 bytes at 2500.
do {
    let sizeAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit equ $06", "I$Create equ $83", "I$Seek equ $88", "I$Read equ $89",
        "I$WritLn equ $8C", "I$SetStt equ $8E", "BUF equ -32700",
        "  psect mszalloc,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  lea fname(pc),a0", "  moveq #3,d0", "  moveq #$1B,d1", "  OS9 I$Create", "  bcs.s bad",
        "  moveq #0,d5", "  move.w d0,d5",
        "  move.l d5,d0", "  moveq #2,d1", "  move.l #3000,d2", "  OS9 I$SetStt", "  bcs.s bad",   // SS_Size
        "  move.l d5,d0", "  move.l #2500,d1", "  OS9 I$Seek", "  bcs.s bad",
        "  move.l d5,d0", "  moveq #16,d1", "  lea BUF(a6),a0", "  OS9 I$Read", "  bcs.s bad",
        "  cmpi.l #16,d1", "  bne.s bad",
        "  lea mok(pc),a0", "  moveq #mokl,d1", "  bra.s say",
        "bad:", "  lea mbad(pc),a0", "  moveq #mbadl,d1",
        "say:", "  moveq #1,d0", "  OS9 I$WritLn", "  moveq #0,d1", "  OS9 F$Exit",
        "fname: dc.b \"/hq/szalloc\",0",
        "mok: dc.b \"SS_SIZE SPACE READABLE\",$0D", "mokl equ *-mok",
        "mbad: dc.b \"SS_SIZE SPACE NOT THERE\",$0D", "mbadl equ *-mbad",
        "  ends", ""
    ].joined(separator: "\r")

    try? sizeAsm.write(toFile: scratchDisk + "/mszalloc.a", atomically: true, encoding: .utf8)

    let name = "rbf: SS_Size allocates the space, so a read inside the new size succeeds"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        removeScratchItem("hq")
        let out = os9([
            "load /dd/CMDS/r68 /dd/CMDS/l68",
            "r68 /h5/mszalloc.a -o=/h5/mszalloc.r",
            "l68 /h5/mszalloc.r -o=/h5/mszalloc",
            "mount -k=1M hq",
            "/h5/mszalloc"
        ], timeout: 30)
        if out.contains("SS_SIZE SPACE READABLE") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = out.split(whereSeparator: \.isNewline).filter {
                $0.contains("SS_SIZE") || $0.contains("Error")
            }
            print("      saw: \(seen.joined(separator: " | "))")
            failed += 1
        }
        removeScratchItem("hq")
    }
    for item in ["mszalloc.a", "mszalloc.r", "mszalloc"] {
        try? FileManager.default.removeItem(atPath: scratchDisk + "/" + item)
    }
}

// ── RBF: SS_Attr will not clear the directory bit of a directory with files ───
// SS_Attr: "It is not permitted to set the dir bit of a non-directory file, or
// to clear the dir bit of a non-empty directory" (p.2-22), and E$DNE is
// "DIRECTORY NOT EMPTY - An attempt was made to remove the directory attribute
// from a directory that is not empty". On an RBF image `attr -nd` of a
// directory holding a file turned it into a plain file, and the file inside
// was left with no directory entry leading to it. deldir, which empties a
// directory before clearing the bit, must still work.
do {
    let name = "rbf: attr -nd of a directory with a file in it is E$DNE, and deldir still removes it"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        removeScratchItem("hq")
        let out = os9(["mount -k=1M hq", "makdir /hq/keepdir9", "echo x >/hq/keepdir9/insidef9",
                       "attr -nd /hq/keepdir9", "dir /hq/keepdir9",
                       "deldir -q /hq/keepdir9", "dir -e /hq/keepdir9"], timeout: 30)
        let lines = out.split(whereSeparator: \.isNewline)
        let listed = lines.contains { !$0.hasPrefix("$") && $0.contains("insidef9") }
        // the last dir, after deldir, must find nothing to list
        let gone = out.range(of: "Error #000:216", options: .backwards) != nil
        if out.contains("#000:238") && out.contains("Directory of /hq/keepdir9") && listed && gone {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = lines.filter { $0.contains("Error") || $0.contains("Directory of") || $0.contains("insidef9") }
            print("      saw: \(seen.joined(separator: " | "))")
            failed += 1
        }
        removeScratchItem("hq")
    }
}

// ── SS_Attr: the directory bit on a plain host file is refused, as on RBF ──────
// "It is not permitted to set the dir bit of a non-directory file" (I$SetStt
// SS_Attr, p.2-22). RBF answers E$FNA (0d43a2e); on a host directory the bit
// was dropped and the call reported success. (The attr utility refuses -d by
// itself, so the program makes the call.)
do {
    let attrAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit equ $06", "I$Create equ $83", "I$WritLn equ $8C", "I$SetStt equ $8E",
        "  psect mattrdir,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,512,start",
        "start:",
        "  lea fname(pc),a0", "  moveq #3,d0", "  moveq #$1B,d1", "  OS9 I$Create", "  bcs.s bad",
        "  moveq #$1C,d1", "  move.l #$9B,d2", "  OS9 I$SetStt", "  bcc.s bad",       // SS_Attr, dir bit
        "  cmpi.w #214,d1", "  bne.s bad",
        "  lea mok(pc),a0", "  moveq #mokl,d1", "  bra.s say",
        "bad:", "  lea mbad(pc),a0", "  moveq #mbadl,d1",
        "say:", "  moveq #1,d0", "  OS9 I$WritLn", "  moveq #0,d1", "  OS9 F$Exit",
        "fname: dc.b \"/h5/t_attrdirbit\",0",
        "mok: dc.b \"HOST DIR BIT REFUSED\",$0D", "mokl equ *-mok",
        "mbad: dc.b \"HOST DIR BIT ACCEPTED\",$0D", "mbadl equ *-mbad",
        "  ends", ""
    ].joined(separator: "\r")

    try? attrAsm.write(toFile: scratchDisk + "/mattrdir.a", atomically: true, encoding: .utf8)

    let name = "fs: SS_Attr setting the dir bit of a plain host file is E$FNA, as on RBF"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        removeScratchItem("t_attrdirbit")
        let out = os9([
            "load /dd/CMDS/r68 /dd/CMDS/l68",
            "r68 /h5/mattrdir.a -o=/h5/mattrdir.r",
            "l68 /h5/mattrdir.r -o=/h5/mattrdir",
            "/h5/mattrdir"
        ], timeout: 30)
        if out.contains("HOST DIR BIT REFUSED") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = out.split(whereSeparator: \.isNewline).filter { $0.contains("HOST DIR") || $0.contains("Error") }
            print("      saw: \(seen.joined(separator: " | "))")
            failed += 1
        }
        removeScratchItem("t_attrdirbit")
    }
    for item in ["mattrdir.a", "mattrdir.r", "mattrdir"] {
        try? FileManager.default.removeItem(atPath: scratchDisk + "/" + item)
    }
}

// ── SS_SSig: a read while the signal is armed is refused ─────────────────────
// SS_SSig (I$SetStt, p.2-24): "The device or pipe is considered busy and returns
// an error if any read request arrives before the signal is sent." E$DevBsy is
// the manual's "DEVICE BUSY". os9exec let the read go ahead and then sent the
// armed signal, which kills a program with no intercept routine. The program
// arms SS_SSig on an empty pipe of its own and reads it.
do {
    let ssigAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit equ $06", "I$Open equ $84", "I$Read equ $89", "I$WritLn equ $8C", "I$SetStt equ $8E",
        "BUF equ -32700",
        "  psect mssigrd,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  lea pname(pc),a0", "  moveq #3,d0", "  OS9 I$Open", "  bcs.s bad",
        "  moveq #0,d5", "  move.w d0,d5",
        "  move.l d5,d0", "  moveq #$1A,d1", "  moveq #$40,d2", "  OS9 I$SetStt", "  bcs.s bad",  // SS_SSig
        "  move.l d5,d0", "  moveq #1,d1", "  lea BUF(a6),a0", "  OS9 I$Read", "  bcc.s bad",
        "  cmpi.w #250,d1", "  bne.s bad",
        "  move.l d5,d0", "  moveq #$1B,d1", "  OS9 I$SetStt",                                     // SS_Relea
        "  lea mok(pc),a0", "  moveq #mokl,d1", "  bra.s say",
        "bad:", "  lea mbad(pc),a0", "  moveq #mbadl,d1",
        "say:", "  moveq #1,d0", "  OS9 I$WritLn", "  moveq #0,d1", "  OS9 F$Exit",
        "pname: dc.b \"/pipe\",0",
        "mok: dc.b \"SSIG READ BUSY\",$0D", "mokl equ *-mok",
        "mbad: dc.b \"SSIG READ NOT REFUSED\",$0D", "mbadl equ *-mbad",
        "  ends", ""
    ].joined(separator: "\r")

    try? ssigAsm.write(toFile: scratchDisk + "/mssigrd.a", atomically: true, encoding: .utf8)

    let name = "io: a read on a path with SS_SSig armed is E$DevBsy"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let out = os9([
            "load /dd/CMDS/r68 /dd/CMDS/l68",
            "r68 /h5/mssigrd.a -o=/h5/mssigrd.r",
            "l68 /h5/mssigrd.r -o=/h5/mssigrd",
            "/h5/mssigrd"
        ], timeout: 30)
        if out.contains("SSIG READ BUSY") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = out.split(whereSeparator: \.isNewline).filter { $0.contains("SSIG") || $0.contains("Error") }
            print("      saw: \(seen.joined(separator: " | "))")
            failed += 1
        }
    }
    for item in ["mssigrd.a", "mssigrd.r", "mssigrd"] {
        try? FileManager.default.removeItem(atPath: scratchDisk + "/" + item)
    }
}

// ── Pipes: SS_Size(0) leaves a pipe with a waiting writer alone ────────────────
// "For pipe files, you can use SS_Size to reset the pipe path (d2.l=0), provided
// the pipe has no active readers or writers" (I$SetStt SS_Size, p.2-24). The
// reset happened regardless. Here `list` fills the pipe and parks waiting for
// room; the program at the other end lets it, resets its stdin, and counts what
// it can still read. Every byte of the file must arrive.
do {
    let resetAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit equ $06", "F$Sleep equ $0A", "I$Read equ $89", "I$WritLn equ $8C", "I$SetStt equ $8E",
        "BUF equ -32700",
        "  psect mpiperst,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  moveq #30,d0", "  OS9 F$Sleep",
        "  moveq #0,d0", "  moveq #2,d1", "  moveq #0,d2", "  OS9 I$SetStt",          // SS_Size 0 on stdin
        "  moveq #0,d4",
        "rd:", "  moveq #0,d0", "  move.l #256,d1", "  lea BUF(a6),a0", "  OS9 I$Read", "  bcs.s done",
        "  add.l d1,d4", "  bra.s rd",
        "done:", "  cmpi.w #211,d1", "  bne.s bad",
        "  cmpi.l #12000,d4", "  bne.s bad",
        "  lea mok(pc),a0", "  moveq #mokl,d1", "  bra.s say",
        "bad:", "  lea mbad(pc),a0", "  moveq #mbadl,d1",
        "say:", "  moveq #1,d0", "  OS9 I$WritLn", "  moveq #0,d1", "  OS9 F$Exit",
        "mok: dc.b \"PIPE RESET LEFT THE WRITER ALONE\",$0D", "mokl equ *-mok",
        "mbad: dc.b \"PIPE RESET DROPPED DATA\",$0D", "mbadl equ *-mbad",
        "  ends", ""
    ].joined(separator: "\r")

    try? resetAsm.write(toFile: scratchDisk + "/mpiperst.a", atomically: true, encoding: .utf8)
    // 12000 bytes of 20-byte lines: three times the pipe's 4096-byte buffer
    let line = String(repeating: "p", count: 19) + "\r"
    try? String(repeating: line, count: 600).write(toFile: scratchDisk + "/t_piperst", atomically: true,
                                                    encoding: .utf8)

    let name = "pipe: SS_Size(0) is ignored while a writer is waiting on the pipe"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let out = os9([
            "load /dd/CMDS/r68 /dd/CMDS/l68",
            "r68 /h5/mpiperst.a -o=/h5/mpiperst.r",
            "l68 /h5/mpiperst.r -o=/h5/mpiperst",
            "list /h5/t_piperst ! /h5/mpiperst"
        ], timeout: 30)
        if out.contains("PIPE RESET LEFT THE WRITER ALONE") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = out.split(whereSeparator: \.isNewline).filter {
                $0.contains("PIPE RESET") || $0.contains("Error")
            }
            print("      saw: \(seen.joined(separator: " | "))")
            failed += 1
        }
    }
    for item in ["mpiperst.a", "mpiperst.r", "mpiperst", "t_piperst"] {
        try? FileManager.default.removeItem(atPath: scratchDisk + "/" + item)
    }
}

// ── time: F$Julian and F$Gregor switch calendars on 1582-10-15 ─────────────────
// "The algorithm used by OS-9 makes this adjustment on October 15, 1582"
// (F$Julian, F$Gregor, CAVEATS): earlier days are Julian-calendar dates. Both
// calls were Gregorian for every date, so 1582-10-04, the day before the switch,
// came out ten days short of it, and 1500-02-29, a Julian leap day, did not
// exist. Day numbers worked out outside the emulator (astronomical JDN - 1, the
// epoch of the manual's weekday formula); 1582-10-15 is a control that was right.
do {
    struct CalendarDate { let label: String; let packed: UInt32; let julian: UInt32 }
    let dates = [
        CalendarDate(label: "oct4", packed: 0x062E_0A04, julian: 0x231517),
        CalendarDate(label: "oct15", packed: 0x062E_0A0F, julian: 0x231518),
        CalendarDate(label: "feb29", packed: 0x05DC_021D, julian: 0x229F3F)
    ]
    func hex(_ value: UInt32) -> String { "$" + String(value, radix: 16, uppercase: true) }
    func say(_ label: String) -> [String] {
        ["  lea \(label)(pc),a0", "  moveq #\(label)l,d1", "  moveq #1,d0", "  OS9 I$WritLn"]
    }
    var lines = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit   equ $06", "F$Julian equ $20", "F$Gregor equ $54", "I$WritLn equ $8C",
        "  psect cl1582,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:"
    ]
    for date in dates {
        let tag = date.label
        lines += ["  moveq #0,d0", "  move.l #\(hex(date.packed)),d1", "  OS9 F$Julian", "  bcs.w fail",
                  "  cmpi.l #\(hex(date.julian)),d1", "  beq.s jok\(tag)"] + say("mjb\(tag)") + [
                  "jok\(tag):",
                  "  moveq #0,d0", "  move.l #\(hex(date.julian)),d1", "  OS9 F$Gregor", "  bcs.w fail",
                  "  cmpi.l #\(hex(date.packed)),d1", "  beq.s gok\(tag)"] + say("mgb\(tag)") + [
                  "  bra.s gdn\(tag)", "gok\(tag):"] + say("mgo\(tag)") + ["gdn\(tag):"]
    }
    lines += ["  moveq #0,d1", "fail:", "  OS9 F$Exit"]
    for date in dates {
        let tag = date.label
        for (label, text) in [("mjb\(tag)", "JULIAN \(tag) BAD"), ("mgb\(tag)", "GREGOR \(tag) BAD"),
                              ("mgo\(tag)", "GREGOR \(tag) OK")] {
            lines += ["\(label): dc.b \"\(text)\",$0D", "\(label)l equ *-\(label)"]
        }
    }
    lines += ["  ends", ""]
    try? lines.joined(separator: "\r").write(toFile: scratchDisk + "/cl1582.a", atomically: true, encoding: .utf8)

    let name = "time: F$Julian and F$Gregor use the Julian calendar before 1582-10-15"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let out = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                       "r68 /h5/cl1582.a -o=/h5/cl1582.r", "l68 /h5/cl1582.r -o=/h5/cl1582",
                       "/h5/cl1582"], timeout: 60)
        let good = dates.allSatisfy { out.contains("GREGOR \($0.label) OK") } && !out.contains(" BAD")
        if good {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = out.split(whereSeparator: \.isNewline).filter {
                $0.contains("GREGOR") || $0.contains("JULIAN") || $0.contains("Error #")
            }
            print("      saw: \(seen.joined(separator: " | "))")
            failed += 1
        }
    }
    for suffix in [".a", ".r", ""] {
        try? FileManager.default.removeItem(atPath: scratchDisk + "/cl1582" + suffix)
    }
}

// ── F$UnLoad matches the module type/language it is given ─────────────────────
// F$UnLoad (p.1-70) takes "d0.w = Module type/language" with the name. os9exec
// ignored it, so asking to unload a data module named binex unloaded the
// program binex. Matched now as F$Link matches: type and language each, 0 being
// any. The program asks for a data module ($0400) first -- refused, 221 -- and
// then for a program of any language ($0100), which does unload it.
do {
    let unloadAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit equ $06", "F$UnLoad equ $1D", "I$WritLn equ $8C",
        "  psect munload,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,512,start",
        "start:",
        "  lea mname(pc),a0", "  move.w #$0400,d0", "  OS9 F$UnLoad", "  bcc.s bad",
        "  cmpi.w #221,d1", "  bne.s bad",
        "  lea mref(pc),a0", "  moveq #mrefl,d1", "  moveq #1,d0", "  OS9 I$WritLn",
        "  lea mname(pc),a0", "  move.w #$0100,d0", "  OS9 F$UnLoad", "  bcs.s bad",
        "  lea mok(pc),a0", "  moveq #mokl,d1", "  bra.s say",
        "bad:", "  lea mbad(pc),a0", "  moveq #mbadl,d1",
        "say:", "  moveq #1,d0", "  OS9 I$WritLn", "  moveq #0,d1", "  OS9 F$Exit",
        "mname: dc.b \"binex\",0",
        "mref: dc.b \"UNLOAD WRONG TYPE REFUSED\",$0D", "mrefl equ *-mref",
        "mok: dc.b \"UNLOAD MATCHING TYPE DONE\",$0D", "mokl equ *-mok",
        "mbad: dc.b \"UNLOAD TYPE NOT HONOURED\",$0D", "mbadl equ *-mbad",
        "  ends", ""
    ].joined(separator: "\r")

    try? unloadAsm.write(toFile: scratchDisk + "/munload.a", atomically: true, encoding: .utf8)

    let name = "module: F$UnLoad refuses a name of the wrong type and unloads the matching one"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        _ = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                 "r68 /h5/munload.a -o=/h5/munload.r", "l68 /h5/munload.r -o=/h5/munload"], timeout: 60)
        let out = os9(["load /dd/CMDS/binex", "/h5/munload", "mdir -e"], timeout: 30)
        // unloaded: gone, or -- binex being sticky -- kept with no links
        let links = mdirLinks(of: "binex", in: out) ?? 0
        if out.contains("UNLOAD WRONG TYPE REFUSED") && out.contains("UNLOAD MATCHING TYPE DONE") && links == 0 {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = out.split(whereSeparator: \.isNewline).filter {
                $0.contains("UNLOAD") || $0.hasSuffix(" binex") || $0.contains("Error")
            }
            print("      saw: \(seen.joined(separator: " | "))")
            failed += 1
        }
    }
    for item in ["munload.a", "munload.r", "munload"] {
        try? FileManager.default.removeItem(atPath: scratchDisk + "/" + item)
    }
}

// ── F$Load: super-user modules only from a file the super user owns ─────────────
// "If any of the modules loaded belong to the super-user, the file must also be
// owned by the super-user. This prevents normal users from executing privileged
// service requests" (F$Load, p.1-41); the file security section adds "If not, the
// modules contained within the file are not loaded", and E$Permit is "The process
// or module must be owned by the super-user to perform the requested function".
// It matters because F$SUser lets a program take its module's owner ID: without
// the rule, any user could stamp 0.0 into a module and become the super user.
// A module built here is owned 0.0; one copy of it on an RBF image is given to
// 1.7 and must not load, the other, still the super user's, must.
do {
    let ownAsm = [
        "  use /dd/DEFS/oskdefs.d", "F$Exit equ $06",
        "  psect mownmod,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,512,start",
        "start:", "  moveq #0,d1", "  OS9 F$Exit", "  ends", ""
    ].joined(separator: "\r")
    try? ownAsm.write(toFile: scratchDisk + "/mownmod.a", atomically: true, encoding: .utf8)

    let name = "module: F$Load refuses a super-user module from a file a user owns, with E$Permit"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        removeScratchItem("hq")
        let out = os9([
            "load /dd/CMDS/r68 /dd/CMDS/l68",
            "r68 /h5/mownmod.a -o=/h5/mownmod.r", "l68 /h5/mownmod.r -o=/h5/mownmod",
            "mount -k=1M hq",
            "copy /h5/mownmod /hq/usermod", "copy /h5/mownmod /hq/supermod", "chown 1.7 /hq/usermod",
            "load /hq/usermod", "echo AFTER-USER-LOAD", "mdir",
            "load /hq/supermod", "echo AFTER-SUPER-LOAD", "mdir"
        ], timeout: 60)
        let lines = out.split(whereSeparator: \.isNewline).map { String($0) }
        let userMark = lines.firstIndex { $0.trimmingCharacters(in: .whitespaces) == "AFTER-USER-LOAD" } ?? 0
        let superMark = lines.firstIndex { $0.trimmingCharacters(in: .whitespaces) == "AFTER-SUPER-LOAD" }
            ?? lines.count
        // mdir lists names in columns; the shell's "$ ..." echoes are not the listing
        func listed(_ rows: ArraySlice<String>) -> Bool {
            rows.contains { !$0.hasPrefix("$") && $0.split(separator: " ").contains("mownmod") }
        }
        let refused = out.contains("#000:164") && !listed(lines[userMark..<superMark])
        let loaded = listed(lines[superMark...])
        if refused && loaded {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = lines.filter { $0.contains("Error") || $0.contains("AFTER-") || $0.contains("mownmod") }
            print("      saw: \(seen.joined(separator: " | "))")
            failed += 1
        }
        removeScratchItem("hq")
    }
    for item in ["mownmod.a", "mownmod.r", "mownmod"] {
        try? FileManager.default.removeItem(atPath: scratchDisk + "/" + item)
    }
}

// ── F$Load: a header claiming nearly 4 GB ends the owner walk ─────────────────
// Before entering any module of a file a user owns, F$Load walks every header to
// check its owner, adding each module's size to the offset. A size the file
// cannot hold wrapped that offset where ulong is 32 bits (i386, wasm32, mingw):
// a second header claiming $FFFFFFE0 after a 32-byte first one brought it back to
// 0, and the walk went round for ever. Neither header is a module, so the load is
// refused either way; what matters is that it answers. Found by review.
do {
    let name = "module: F$Load of a file whose second header claims nearly 4 GB answers, not loops"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        removeScratchItem("hq")
        func header(size: UInt32) -> [UInt8] {
            let sizeBytes = (0..<4).map { UInt8(truncatingIfNeeded: size >> (24 - 8 * $0)) }
            // M$ID, M$SysRev, M$Size, M$Owner 1.7, then the rest of a 48-byte header
            return [0x4A, 0xFC, 0x00, 0x01] + sizeBytes + [0x00, 0x01, 0x00, 0x07] + [UInt8](repeating: 0, count: 36)
        }
        let first = Array(header(size: 32).prefix(32))
        let bytes = first + header(size: 0xFFFF_FFE0)
        FileManager.default.createFile(atPath: scratchDisk + "/mwrapf", contents: Data(bytes))
        let out = os9([
            "mount -k=1M hq", "copy /h5/mwrapf /hq/wrapf", "chown 1.7 /hq/wrapf",
            "load /hq/wrapf", "echo AFTER-WRAP-LOAD"
        ], timeout: 30)
        let answered = out.split(whereSeparator: \.isNewline).contains { $0.hasPrefix("AFTER-WRAP-LOAD") }
        if answered && out.contains("Error") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = out.split(whereSeparator: \.isNewline).filter { $0.contains("Error") || $0.contains("AFTER-") }
            print("      saw: \(seen.joined(separator: " | "))")
            failed += 1
        }
        removeScratchItem("hq")
    }
    try? FileManager.default.removeItem(atPath: scratchDisk + "/mwrapf")
}

// ── accounting: a process that computes without system calls is charged for it ─
// The C library's clock() reads the process's user ticks (P$UTicks, through
// F$GPrDsc). They were counted only from one system call to the next, and a
// process the system tick pre-empted had its time booked to the arbitrator, so
// a program computing without calls saw clock() stand still: the Whetstone
// benchmark divided by zero. Found by the osk-freeware session. The program
// reads P$UTicks around a loop with no calls in it and must have been charged
// at least 10 ticks for it. Not measured against the wall clock: F$Time's tick
// is not aligned with its seconds, so seconds*100+tick jumps by up to a second.
do {
    let ticksAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "F$ID equ $0C", "F$Exit equ $06", "F$GPrDsc equ $18", "I$WritLn equ $8C",
        "  psect mutick,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,8192,start", "  vsect", "scr: ds.b 4096", "  ends",
        "start:",
        "  bsr.s uticks", "  move.l d0,d6",
        "  move.l #30000000,d5",
        "spin:", "  subq.l #1,d5", "  bne.s spin",
        "  bsr.s uticks", "  sub.l d6,d0", "  move.l d0,d6",
        "  cmpi.l #10,d6", "  blt.s bad",       // 40-80 here; the bug gave 0 or 1
        "  lea mok(pc),a0", "  moveq #mokl,d1", "  bra.s say",
        "bad:", "  lea mbad(pc),a0", "  moveq #mbadl,d1",
        "say:", "  moveq #1,d0", "  OS9 I$WritLn", "  moveq #0,d1", "  OS9 F$Exit",
        // d0 = this process's P$UTicks
        "uticks:", "  OS9 F$ID", "  move.w #$800,d1", "  lea scr(a6),a0", "  OS9 F$GPrDsc",
        "  move.l scr+$2B4(a6),d0", "  rts",
        "mok:  dc.b \"USER TICKS COUNTED\",$0D", "mokl equ *-mok",
        "mbad: dc.b \"USER TICKS MISSING\",$0D", "mbadl equ *-mbad",
        "  ends", ""
    ].joined(separator: "\r")

    let name = "accounting: a process computing without system calls gets its user ticks (clock())"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        try? ticksAsm.write(toFile: scratchDisk + "/mutick.a", atomically: true, encoding: .utf8)
        let out = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                       "r68 /h5/mutick.a -o=/h5/mutick.r", "l68 /h5/mutick.r -o=/h5/mutick",
                       "/h5/mutick"], timeout: 120)
        if out.contains("USER TICKS COUNTED") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = out.split(whereSeparator: \.isNewline).filter { $0.contains("TICKS") || $0.contains("Error") }
            print("      saw: \(seen.joined(separator: " | "))")
            failed += 1
        }
        for leftover in ["mutick.a", "mutick.r", "mutick"] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
        }
    }
}

// ── accounting: another process sees a computing process's ticks as they grow ──
// The ticks a process runs before the system tick pre-empts it were held back
// until its next system call. A process that computes without calls then never
// had its P$UTicks move, so anything reading its descriptor from outside (procs,
// a profiler) saw no CPU time at all. Found reviewing the fix above. A child
// spins with no calls; its parent sleeps a second, reads the child's P$UTicks
// through F$GPrDsc and must see at least 10, then kills it. Needs the tick: with
// it off nothing pre-empts the child and the parent never runs again.
do {
    let spinAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "  psect mspin,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,512,start", "  vsect", "scr: ds.b 4096", "  ends",
        "start:", "spin:", "  bra.s spin", "  ends", ""
    ].joined(separator: "\r")
    let watchAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Fork equ $03", "F$Wait equ $04", "F$Exit equ $06", "F$Send equ $08", "F$Sleep equ $0A",
        "F$GPrDsc equ $18", "I$WritLn equ $8C",
        "  psect mwatch,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,8192,start", "  vsect", "scr: ds.b 4096", "  ends",
        "start:",
        "  lea child(pc),a0", "  lea parm(pc),a1", "  moveq #0,d0", "  moveq #0,d1", "  moveq #1,d2",
        "  moveq #3,d3", "  moveq #0,d4", "  OS9 F$Fork", "  bcs.s bad", "  move.w d0,d7",
        "  moveq #100,d0", "  OS9 F$Sleep",
        "  move.w d7,d0", "  move.w #$800,d1", "  lea scr(a6),a0", "  OS9 F$GPrDsc", "  bcs.s bad",
        "  move.l scr+$2B4(a6),d6",
        "  move.w d7,d0", "  moveq #0,d1", "  OS9 F$Send", "  OS9 F$Wait",
        "  cmpi.l #10,d6", "  blt.s bad",
        "  lea mok(pc),a0", "  moveq #mokl,d1", "  bra.s say",
        "bad:", "  lea mbad(pc),a0", "  moveq #mbadl,d1",
        "say:", "  moveq #1,d0", "  OS9 I$WritLn", "  moveq #0,d1", "  OS9 F$Exit",
        "child: dc.b \"/h5/mspin\",0", "parm: dc.b $0D",
        "mok:  dc.b \"OBSERVER SEES THE TICKS\",$0D", "mokl equ *-mok",
        "mbad: dc.b \"OBSERVER SEES NO TICKS\",$0D", "mbadl equ *-mbad",
        "  ends", ""
    ].joined(separator: "\r")

    let name = "accounting: another process reads a computing process's user ticks as they grow"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        if (ProcessInfo.processInfo.environment["OS9_FLAGS"] ?? "").contains("-q") {
            print("SKIP: \(name) (the system tick is off, so nothing pre-empts the child)")
        } else {
            try? spinAsm.write(toFile: scratchDisk + "/mspin.a", atomically: true, encoding: .utf8)
            try? watchAsm.write(toFile: scratchDisk + "/mwatch.a", atomically: true, encoding: .utf8)
            let out = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                           "r68 /h5/mspin.a -o=/h5/mspin.r", "l68 /h5/mspin.r -o=/h5/mspin",
                           "r68 /h5/mwatch.a -o=/h5/mwatch.r", "l68 /h5/mwatch.r -o=/h5/mwatch",
                           "/h5/mwatch"], timeout: 60)
            if out.contains("OBSERVER SEES THE TICKS") {
                print("PASS: \(name)")
                passed += 1
            } else {
                print("FAIL: \(name)")
                let seen = out.split(whereSeparator: \.isNewline)
                    .filter { $0.contains("OBSERVER") || $0.contains("Error") }
                print("      saw: \(seen.joined(separator: " | "))")
                failed += 1
            }
        }
        for leftover in ["mspin.a", "mspin.r", "mspin", "mwatch.a", "mwatch.r", "mwatch"] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
        }
    }
}

// ── idle: a writer waiting on a full pipe does not keep a core busy ─────────────
// A pipe request parked as a system task was tried again on every pass of the
// scheduler, so a writer waiting for a slow reader to make room spun the host
// at 100% for as long as it waited (4.98 s of CPU in 5.03 s, measured; v4.0.0
// the same). Now a parked request that moved nothing waits for its pipe to
// change. The reader sleeps 3 s before draining 13K that `list` writes; the
// emulator's own CPU time for the whole run must stay under a second. Local
// only: a container's CPU is not the host's to count.
do {
    let name = "idle: a writer parked on a full pipe for 3 s costs under a second of CPU"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        if containerized {
            print("SKIP: \(name) (a container's CPU time is not counted here)")
        } else {
            let slowAsm = [
                "  use /dd/DEFS/oskdefs.d", "F$Exit equ $06", "F$Sleep equ $0A", "I$Read equ $89",
                "  psect mslowrd,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
                "  vsect", "buf: ds.b 512", "  ends",
                "start:", "  move.l #300,d0", "  OS9 F$Sleep",
                "rd:", "  moveq #0,d0", "  lea buf(a6),a0", "  move.l #512,d1", "  OS9 I$Read", "  bcc.s rd",
                "  moveq #0,d1", "  OS9 F$Exit", "  ends", ""
            ].joined(separator: "\r")
            try? slowAsm.write(toFile: scratchDisk + "/mslowrd.a", atomically: true, encoding: .utf8)
            _ = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                     "r68 /h5/mslowrd.a -o=/h5/mslowrd.r", "l68 /h5/mslowrd.r -o=/h5/mslowrd"], timeout: 60)
            func childCPU() -> Double {
                var usage = rusage()
                getrusage(RUSAGE_CHILDREN, &usage)
                return Double(usage.ru_utime.tv_sec) + Double(usage.ru_utime.tv_usec) / 1e6
                     + Double(usage.ru_stime.tv_sec) + Double(usage.ru_stime.tv_usec) / 1e6
            }
            let before = childCPU()
            let started = Date()
            let out = os9(["list /dd/SYS/errmsg ! /h5/mslowrd", "echo PIPE DONE"], timeout: 60)
            let spent = childCPU() - before
            let wall = Date().timeIntervalSince(started)
            if out.contains("PIPE DONE") && wall >= 3 && spent < 1.0 {
                print("PASS: \(name)")
                passed += 1
            } else {
                print("FAIL: \(name)")
                print("      cpu \(String(format: "%.2f", spent)) s in \(String(format: "%.2f", wall)) s")
                failed += 1
            }
        }
        for leftover in ["mslowrd.a", "mslowrd.r", "mslowrd"] {
            try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
        }
    }
}

// ── F$Sleep: a few 256ths of a second still sleep ──────────────────────────────
// "If the high order bit of d0.l is set, the low 31 bits are converted from
// 256ths of a second into ticks" (F$Sleep, p.1-58); F$Alarm, for the same
// encoding, rounds "up to the nearest clock tick". os9exec truncated, so at 100
// ticks/s 1/256 was 0 ticks and returned at once. The program sleeps 1/256 twenty
// times and measures ticks with F$Time format 3 (seconds since midnight and the
// current tick): each sleep must reach a tick boundary, so at least 10 ticks.
do {
    let sleepAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit equ $06", "F$Sleep equ $0A", "F$Time equ $15", "I$WritLn equ $8C",
        "  psect msleep256,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,512,start",
        "start:",
        "  bsr.s now", "  move.l d4,d7",
        "  moveq #19,d2",
        "nap:", "  move.l #$80000001,d0", "  OS9 F$Sleep", "  dbra d2,nap",
        "  bsr.s now", "  sub.l d7,d4",
        "  cmpi.l #10,d4", "  blt.s bad",
        "  lea mok(pc),a0", "  moveq #mokl,d1", "  bra.s say",
        "bad:", "  lea mbad(pc),a0", "  moveq #mbadl,d1",
        "say:", "  moveq #1,d0", "  OS9 I$WritLn", "  moveq #0,d1", "  OS9 F$Exit",
        // d4 = seconds since midnight * 100 + current tick
        "now:", "  moveq #3,d0", "  OS9 F$Time",
        "  move.l d0,d4", "  move.l d0,d5", "  move.l d0,d6",
        "  lsl.l #6,d4", "  lsl.l #5,d5", "  lsl.l #2,d6", "  add.l d5,d4", "  add.l d6,d4",
        "  moveq #0,d5", "  move.w d3,d5", "  add.l d5,d4", "  rts",
        "mok: dc.b \"SLEEP 256THS WAITED\",$0D", "mokl equ *-mok",
        "mbad: dc.b \"SLEEP 256THS DID NOT WAIT\",$0D", "mbadl equ *-mbad",
        "  ends", ""
    ].joined(separator: "\r")

    try? sleepAsm.write(toFile: scratchDisk + "/msleep256.a", atomically: true, encoding: .utf8)

    let name = "time: F$Sleep of 1/256 second sleeps at least to the next tick"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let out = os9([
            "load /dd/CMDS/r68 /dd/CMDS/l68",
            "r68 /h5/msleep256.a -o=/h5/msleep256.r",
            "l68 /h5/msleep256.r -o=/h5/msleep256",
            "/h5/msleep256"
        ], timeout: 30)
        if out.contains("SLEEP 256THS WAITED") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            let seen = out.split(whereSeparator: \.isNewline).filter { $0.contains("SLEEP") || $0.contains("Error") }
            print("      saw: \(seen.joined(separator: " | "))")
            failed += 1
        }
    }
    for item in ["msleep256.a", "msleep256.r", "msleep256"] {
        try? FileManager.default.removeItem(atPath: scratchDisk + "/" + item)
    }
}

// SOCK_STREAM is Int32 on Darwin and an enum on Glibc; socket() wants Int32.
#if canImport(Darwin)
let streamSocketType = SOCK_STREAM
#else
let streamSocketType = Int32(SOCK_STREAM.rawValue)
#endif

// ── SPF sockets: an OS-9 program reaches the host network ─────────────────────
// The networking programs on the system disk open a path like "/ip0#1/tcp0" and
// drive it with one setstat whose parameter block says what to do; os9exec had
// no such device, so every one of them stopped at its socket call (E$MNF).
// spfsock.c gives those paths host sockets. Here the harness listens on the port
// tcpsend uses, the OS-9 side sends a file, and every byte must arrive.
// Skipped under a container: os9exec is then inside it and cannot reach this
// listener on the host's loopback.
do {
    let name = "net: tcpsend sends a file over TCP through an /ip0 socket path"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        if containerized {
            print("SKIP: \(name) (the container cannot reach the host's loopback)")
        } else {
            let sendFile = "/dd/SYS/errmsg"
            let port: UInt16 = 27000          // the port tcpsend connects to
            let listenFd = socket(AF_INET, streamSocketType, 0)
            var yes: Int32 = 1
            setsockopt(listenFd, SOL_SOCKET, SO_REUSEADDR, &yes, socklen_t(MemoryLayout<Int32>.size))
            var addr = sockaddr_in()
            addr.sin_family = sa_family_t(AF_INET)
            addr.sin_port = port.bigEndian
            addr.sin_addr.s_addr = INADDR_LOOPBACK.bigEndian
            let bound = withUnsafePointer(to: &addr) {
                $0.withMemoryRebound(to: sockaddr.self, capacity: 1) {
                    bind(listenFd, $0, socklen_t(MemoryLayout<sockaddr_in>.size))
                }
            }
            if listenFd < 0 || bound != 0 || listen(listenFd, 1) != 0 {
                if listenFd >= 0 { close(listenFd) }
                print("SKIP: \(name) (port \(port) is not available here)")
            } else {
                // Count what arrives, on a background thread, until the sender
                // closes. Every step records WHY it stopped: this test failed 3
                // of 16 runs under load on 2026-09-18 and has not been seen
                // since in 70+ runs, and "sent=N received=M" alone never said
                // which end went wrong. A rare failure is only worth having if
                // the one time it happens is decisive.
                var received = 0
                var accepted = false
                var readErrno: Int32 = 0
                var lastRead = 0
                let done = DispatchSemaphore(value: 0)
                DispatchQueue.global().async {
                    let conn = accept(listenFd, nil, nil)
                    if conn >= 0 {
                        accepted = true
                        var buf = [UInt8](repeating: 0, count: 4096)
                        while true {
                            let got = read(conn, &buf, buf.count)
                            if got <= 0 {
                                lastRead = got
                                if got < 0 { readErrno = errno }
                                break
                            }
                            received += got
                        }
                        close(conn)
                    }
                    done.signal()
                }

                let began = Date()
                let out = os9(["load /dd/CMDS/BOOTOBJS/SPF/inetdb",
                               "load /dd/CMDS/BOOTOBJS/SPF/netdb_local",
                               "tcpsend localhost \(sendFile)"], timeout: 45)
                let ranFor = Date().timeIntervalSince(began)
                // .timedOut means the reader is STILL RUNNING, so `received` is
                // being written as it is read here -- the count is not just
                // short, it is unsynchronised, and a failure reported from it
                // would be the harness's fault rather than the emulator's.
                let drained = done.wait(timeout: .now() + 20) == .success
                close(listenFd)

                // tcpsend reports what it sent; the host must have got exactly that
                let sent = out.split(whereSeparator: \.isNewline)
                    .first { $0.contains("sent ") && $0.contains(" bytes") }
                    .flatMap { $0.split(separator: " ").dropFirst().first.map(String.init) }
                    .flatMap { Int($0) }
                if let sent, sent > 0, sent == received {
                    print("PASS: \(name)")
                    passed += 1
                } else {
                    print("FAIL: \(name)")
                    print("      saw: sent=\(sent.map(String.init) ?? "-") received=\(received)")
                    print("      how: accepted=\(accepted) drained=\(drained) " +
                          "lastRead=\(lastRead)\(readErrno != 0 ? " errno=\(readErrno)" : "") " +
                          "emulator ran \(String(format: "%.1f", ranFor))s of a 45s budget")
                    if !drained {
                        print("      NOTE: the reader had not finished, so received= is unsynchronised")
                    }
                    let seen = out.split(whereSeparator: \.isNewline).filter {
                        $0.contains("socket") || $0.contains("Error") || $0.contains("sent")
                    }
                    print("      out: \(seen.joined(separator: " | "))")
                    failed += 1
                }
            }
        }
    }
}

// ── sockets: a peer that stops reading must not stop the EMULATOR ──
// Every SPF socket is O_NONBLOCK (pSopen sets it so a read never blocks the
// emulator), so a send() whose host buffer is full returns EAGAIN. pSwrite
// used to retry that in place, which spun inside the syscall with the whole
// emulator stopped: no other OS-9 process ran and no alarm came due until the
// peer drained. A reader that stopped for good hung everything. consio.c had
// made the same mistake for the console and fixed it by parking the writer.
//
// The check has to be careful not to be vacuous. The shell would reach the
// marker long BEFORE tcpsend fills the buffer, so the marker would appear on
// a frozen emulator too. The guest therefore sleeps first: the marker can only
// be written if the emulator went on scheduling processes while the socket sat
// unread, which is the whole property. The peer reads nothing for `stall`
// seconds, watches for the marker, and only then drains so the run can end.
do {
    let name = "net: a socket write whose peer stops reading does not freeze the emulator"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        if containerized {
            print("SKIP: \(name) (the container cannot reach the host's loopback)")
        } else {
            let port: UInt16 = 27000     // tcpsend's own port, as the test above notes
            let stall = 6.0, guestSleep = 2
            let big    = scratchDisk + "/BIGSEND"
            let marker = scratchDisk + "/SPFALIVE"
            try? FileManager.default.removeItem(atPath: marker)
            // larger than any plausible host send buffer, so a peer that does
            // not read is guaranteed to make send() return EAGAIN partway
            FileManager.default.createFile(atPath: big,
                contents: Data(repeating: 0x78, count: 4 * 1024 * 1024))

            let listenFd = socket(AF_INET, streamSocketType, 0)
            var yes: Int32 = 1
            setsockopt(listenFd, SOL_SOCKET, SO_REUSEADDR, &yes, socklen_t(MemoryLayout<Int32>.size))
            var addr = sockaddr_in()
            addr.sin_family = sa_family_t(AF_INET)
            addr.sin_port = port.bigEndian
            addr.sin_addr.s_addr = INADDR_LOOPBACK.bigEndian
            let bound = withUnsafePointer(to: &addr) {
                $0.withMemoryRebound(to: sockaddr.self, capacity: 1) {
                    bind(listenFd, $0, socklen_t(MemoryLayout<sockaddr_in>.size))
                }
            }
            if listenFd < 0 || bound != 0 || listen(listenFd, 1) != 0 {
                if listenFd >= 0 { close(listenFd) }
                print("SKIP: \(name) (port \(port) is not available here)")
            } else {
                var aliveAt: Double? = nil
                let done = DispatchSemaphore(value: 0)
                DispatchQueue.global().async {
                    let conn = accept(listenFd, nil, nil)
                    if conn >= 0 {
                        let t0 = Date()
                        while Date().timeIntervalSince(t0) < stall {
                            if aliveAt == nil,
                               FileManager.default.fileExists(atPath: marker) {
                                aliveAt = Date().timeIntervalSince(t0)
                            }
                            usleep(20_000)
                        }
                        var buf = [UInt8](repeating: 0, count: 65536)
                        while read(conn, &buf, buf.count) > 0 {}
                        close(conn)
                    }
                    done.signal()
                }

                let out = os9(["load /dd/CMDS/BOOTOBJS/SPF/inetdb",
                         "load /dd/CMDS/BOOTOBJS/SPF/netdb_local",
                         "tcpsend localhost \(scratch)/BIGSEND >/nil&",
                         "sleep \(guestSleep)",
                         "echo alive >\(scratch)/SPFALIVE"], timeout: 90)
                _ = done.wait(timeout: .now() + stall + 30)
                close(listenFd)

                if aliveAt != nil {
                    print("PASS: \(name)")
                    passed += 1
                } else {
                    print("FAIL: \(name)")
                    print("      the guest never reached its marker during a \(stall)s unread")
                    print("      socket, so nothing else was scheduled while the write waited")
                    print("      out: \(out.split(whereSeparator: \.isNewline).suffix(6).joined(separator: " | "))")
                    failed += 1
                }
                try? FileManager.default.removeItem(atPath: big)
            }
        }
    }
}

// ── sockets: a listening socket is ready when a connection is waiting ─────────
// A server may poll its listening path with SS_Ready before accepting, as boa
// (the OSK web server, written for ISP) does. The answer was always E$NotRdy on
// a socket that was not connected, so such a server logged "starting server"
// and never answered anyone. Found by the osk-freeware session. The guest opens
// "/socket", binds loopback and listens; the host connects; the guest must see
// SS_Ready succeed within a few seconds.
do {
    let name = "net: SS_Ready on a listening socket answers ready once a connection waits"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        if containerized {
            print("SKIP: \(name) (the container cannot reach the host's loopback)")
        } else {
            let port: UInt16 = 27123
            let readyAsm = [
                "  use /dd/DEFS/oskdefs.d",
                "F$Exit equ $06", "F$Sleep equ $0A", "I$Open equ $84", "I$WritLn equ $8C",
                "I$GetStt equ $8D", "I$SetStt equ $8E",
                "  psect mlsnrdy,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
                "start:",
                "  lea sname(pc),a0", "  moveq #3,d0", "  OS9 I$Open", "  bcs.w bad", "  move.w d0,d7",
                "  lea sargs(pc),a0", "  moveq #12,d2", "  move.w #$6F,d1", "  OS9 I$SetStt", "  bcs.w bad",
                "  move.w d7,d0", "  lea saddr(pc),a0", "  moveq #16,d2", "  move.w #$6C,d1",
                "  OS9 I$SetStt", "  bcs.w bad",
                "  move.w d7,d0", "  moveq #1,d2", "  move.w #$6D,d1", "  OS9 I$SetStt", "  bcs.w bad",
                "  move.w #400,d6",
                "poll:", "  move.w d7,d0", "  moveq #1,d1", "  OS9 I$GetStt", "  bcc.s ready",
                "  moveq #2,d0", "  OS9 F$Sleep", "  dbra d6,poll",
                "bad:", "  lea mbad(pc),a0", "  moveq #mbadl,d1", "  bra.s say",
                "ready:", "  lea mok(pc),a0", "  moveq #mokl,d1",
                "say:", "  moveq #1,d0", "  OS9 I$WritLn", "  moveq #0,d1", "  OS9 F$Exit",
                "sargs: dc.l 2,1,0",
                "saddr: dc.w 2,\(port)", "  dc.l $7F000001,0,0",
                "sname: dc.b \"/socket\",0",
                "mok:  dc.b \"LISTENING SOCKET READY\",$0D", "mokl equ *-mok",
                "mbad: dc.b \"LISTENING SOCKET NEVER READY\",$0D", "mbadl equ *-mbad",
                "  ends", ""
            ].joined(separator: "\r")
            try? readyAsm.write(toFile: scratchDisk + "/mlsnrdy.a", atomically: true, encoding: .utf8)
            _ = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                     "r68 /h5/mlsnrdy.a -o=/h5/mlsnrdy.r", "l68 /h5/mlsnrdy.r -o=/h5/mlsnrdy"], timeout: 60)

            // keep trying until the guest listens, then hold the connection open
            var connected = false
            let done = DispatchSemaphore(value: 0)
            DispatchQueue.global().async {
                let started = Date()
                while Date().timeIntervalSince(started) < 20 && !connected {
                    let client = socket(AF_INET, streamSocketType, 0)
                    var addr = sockaddr_in()
                    addr.sin_family = sa_family_t(AF_INET)
                    addr.sin_port = port.bigEndian
                    addr.sin_addr.s_addr = INADDR_LOOPBACK.bigEndian
                    let result = withUnsafePointer(to: &addr) {
                        $0.withMemoryRebound(to: sockaddr.self, capacity: 1) {
                            connect(client, $0, socklen_t(MemoryLayout<sockaddr_in>.size))
                        }
                    }
                    if result == 0 {
                        connected = true
                        usleep(3_000_000)
                    } else {
                        usleep(50_000)
                    }
                    close(client)
                }
                done.signal()
            }
            let out = os9(["/h5/mlsnrdy"], timeout: 60)
            _ = done.wait(timeout: .now() + 30)
            if out.contains("LISTENING SOCKET READY") {
                print("PASS: \(name)")
                passed += 1
            } else {
                print("FAIL: \(name)")
                let seen = out.split(whereSeparator: \.isNewline)
                    .filter { $0.contains("LISTENING") || $0.contains("Error") }
                print("      saw (host connected: \(connected)): \(seen.joined(separator: " | "))")
                failed += 1
            }
            for leftover in ["mlsnrdy.a", "mlsnrdy.r", "mlsnrdy"] {
                try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
            }
        }
    }
}

// ── sockets: a dropped connection is a write error, not the emulator's death ──
// A write to a connection the far end has dropped raises SIGPIPE, whose default
// action ended os9exec itself -- every OS-9 process with it, exit 141, from one
// tcpsend. The listener here accepts and at once resets the connection, so
// tcpsend's first write meets a dead socket; it must get a write error and the
// shell must still be there to run the next command.
do {
    let name = "net: a write to a dropped connection fails in the guest, the emulator lives"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        if containerized {
            print("SKIP: \(name) (the container cannot reach the host's loopback)")
        } else {
            let port: UInt16 = 27000          // the port tcpsend connects to
            let listenFd = socket(AF_INET, streamSocketType, 0)
            var yes: Int32 = 1
            setsockopt(listenFd, SOL_SOCKET, SO_REUSEADDR, &yes, socklen_t(MemoryLayout<Int32>.size))
            var addr = sockaddr_in()
            addr.sin_family = sa_family_t(AF_INET)
            addr.sin_port = port.bigEndian
            addr.sin_addr.s_addr = INADDR_LOOPBACK.bigEndian
            let bound = withUnsafePointer(to: &addr) {
                $0.withMemoryRebound(to: sockaddr.self, capacity: 1) {
                    bind(listenFd, $0, socklen_t(MemoryLayout<sockaddr_in>.size))
                }
            }
            if listenFd < 0 || bound != 0 || listen(listenFd, 1) != 0 {
                if listenFd >= 0 { close(listenFd) }
                print("SKIP: \(name) (port \(port) is not available here)")
            } else {
                // accept, then reset: a close that sends RST instead of FIN
                let done = DispatchSemaphore(value: 0)
                DispatchQueue.global().async {
                    let conn = accept(listenFd, nil, nil)
                    if conn >= 0 {
                        var hard = linger(l_onoff: 1, l_linger: 0)
                        setsockopt(conn, SOL_SOCKET, SO_LINGER, &hard, socklen_t(MemoryLayout<linger>.size))
                        close(conn)
                    }
                    done.signal()
                }

                let out = os9(["load /dd/CMDS/BOOTOBJS/SPF/inetdb",
                               "load /dd/CMDS/BOOTOBJS/SPF/netdb_local",
                               "tcpsend localhost /dd/SYS/errmsg",
                               "echo EMULATOR-STILL-HERE"], timeout: 30)
                _ = done.wait(timeout: .now() + 10)
                close(listenFd)

                if out.contains("EMULATOR-STILL-HERE") {
                    print("PASS: \(name)")
                    passed += 1
                } else {
                    print("FAIL: \(name)")
                    let seen = out.split(whereSeparator: \.isNewline).filter {
                        $0.contains("tcpsend") || $0.contains("rror") || $0.contains("Sending")
                    }
                    print("      out: \(seen.joined(separator: " | "))")
                    failed += 1
                }
            }
        }
    }
}

// ── sockets: a slow connect parks its caller and nobody else ─────────────────
// connect() ran blocking: every OS-9 process stood still for the whole
// handshake, and the system tick's signal cut it short anyway (connect is not
// restarted), so a connection that took longer than a tick failed at once.
// 192.0.2.1 (TEST-NET-1) is never routed, so a connect to it stays in progress:
// tcpsend must still be waiting two seconds later while procs runs. Skipped
// where this network answers that address at once, which the harness checks.
do {
    let name = "net: a connect still in progress leaves the other processes running"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        var pending = false
        let probe = socket(AF_INET, streamSocketType, 0)
        if probe >= 0 {
            _ = fcntl(probe, F_SETFL, fcntl(probe, F_GETFL, 0) | O_NONBLOCK)
            var far = sockaddr_in()
            far.sin_family = sa_family_t(AF_INET)
            far.sin_port = UInt16(9).bigEndian
            far.sin_addr.s_addr = UInt32(0xC000_0201).bigEndian      // 192.0.2.1
            let r = withUnsafePointer(to: &far) {
                $0.withMemoryRebound(to: sockaddr.self, capacity: 1) {
                    connect(probe, $0, socklen_t(MemoryLayout<sockaddr_in>.size))
                }
            }
            if r != 0 && errno == EINPROGRESS {
                var pf = pollfd(fd: probe, events: Int16(POLLOUT), revents: 0)
                pending = poll(&pf, 1, 2500) == 0                     // still no answer
            }
            close(probe)
        }
        if containerized {
            print("SKIP: \(name) (the container's network is not this host's)")
        } else if !pending {
            print("SKIP: \(name) (this network answers 192.0.2.1 at once)")
        } else {
            let out = os9(["load /dd/CMDS/BOOTOBJS/SPF/inetdb",
                           "load /dd/CMDS/BOOTOBJS/SPF/netdb_local",
                           "tcpsend 192.0.2.1 /dd/SYS/errmsg &",
                           "sleep -s 2",
                           "procs",
                           "kill 3"], timeout: 30)   // never connects; see the multicast test
            let waiting = out.split(whereSeparator: \.isNewline).contains {
                $0.contains("tcpsend") && $0.contains(">>>")
            }
            if waiting {
                print("PASS: \(name)")
                passed += 1
            } else {
                print("FAIL: \(name)")
                let seen = out.split(whereSeparator: \.isNewline).filter {
                    $0.contains("tcpsend") || $0.contains("rror") || $0.contains("procs")
                }
                print("      out: \(seen.joined(separator: " | "))")
                failed += 1
            }
        }
    }
}

// ── tftpd: a host fetches a file over UDP ────────────────────────────────────
// tftpd binds UDP port 69, reads each request with the sender's address and
// answers it with send-to, through the forked tftpdc -- the datagram half of
// the socket manager, which no TCP program touches. The harness is the TFTP
// client: a read request, then an ACK for every block (RFC 1350), and the file
// must arrive byte for byte. Skipped where UDP port 69 cannot be bound.
do {
    let name = "net: tftpd serves a file to a host TFTP client over UDP"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let dgram = Int32(SOCK_DGRAM)
        func udpAddr(_ port: UInt16, _ host: UInt32) -> sockaddr_in {
            var a = sockaddr_in()
            a.sin_family = sa_family_t(AF_INET)
            a.sin_port = port.bigEndian
            a.sin_addr.s_addr = host.bigEndian
            return a
        }
        var probeAddr = udpAddr(69, INADDR_ANY)
        let probe = socket(AF_INET, dgram, 0)
        let probed = probe >= 0 && withUnsafePointer(to: &probeAddr) {
            $0.withMemoryRebound(to: sockaddr.self, capacity: 1) {
                bind(probe, $0, socklen_t(MemoryLayout<sockaddr_in>.size))
            }
        } == 0
        if probe >= 0 { close(probe) }

        if containerized {
            print("SKIP: \(name) (the container cannot reach the host's loopback)")
        } else if !probed {
            print("SKIP: \(name) (UDP port 69 is not available to this user)")
        } else {
            var blob = [UInt8](repeating: 0, count: 3000)          // six blocks, the last short
            for i in blob.indices { blob[i] = UInt8((i * 7 + 3) & 0xFF) }
            FileManager.default.createFile(atPath: scratchDisk + "/tftpblob", contents: Data(blob))

            var got = [UInt8]()
            let done = DispatchSemaphore(value: 0)
            DispatchQueue.global().async {
                sleep(4)                                         // tftpd's bind, after its loads
                let fd = socket(AF_INET, dgram, 0)
                var quiet = timeval(tv_sec: 2, tv_usec: 0)
                setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &quiet, socklen_t(MemoryLayout<timeval>.size))
                var server = udpAddr(69, INADDR_LOOPBACK)
                func sendTo(_ bytes: [UInt8], _ to: inout sockaddr_in) {
                    _ = withUnsafePointer(to: &to) {
                        $0.withMemoryRebound(to: sockaddr.self, capacity: 1) {
                            sendto(fd, bytes, bytes.count, 0, $0, socklen_t(MemoryLayout<sockaddr_in>.size))
                        }
                    }
                }
                sendTo([0, 1] + Array("tftpblob".utf8) + [0] + Array("octet".utf8) + [0], &server)
                var buf = [UInt8](repeating: 0, count: 600)
                var from = sockaddr_in()
                var fromLen = socklen_t(MemoryLayout<sockaddr_in>.size)
                while true {
                    let n = withUnsafeMutablePointer(to: &from) {
                        $0.withMemoryRebound(to: sockaddr.self, capacity: 1) {
                            recvfrom(fd, &buf, buf.count, 0, $0, &fromLen)
                        }
                    }
                    if n < 4 || buf[1] != 3 { break }             // not a DATA packet
                    got += buf[4..<n]
                    sendTo([0, 4, buf[2], buf[3]], &from)         // ACK that block, to tftpdc's port
                    if n < 516 { break }                          // the short block is the last
                }
                close(fd)
                done.signal()
            }

            let out = os9(["load /dd/CMDS/BOOTOBJS/SPF/inetdb",
                           "load /dd/CMDS/BOOTOBJS/SPF/netdb_local",
                           "tftpd /\(scratchDev) &",
                           "sleep -s 10",
                           "kill 3"], timeout: 30)   // a daemon listens until killed; see the multicast test
            _ = done.wait(timeout: .now() + 15)

            if got == blob {
                print("PASS: \(name)")
                passed += 1
            } else {
                print("FAIL: \(name)")
                print("      saw: \(got.count) of \(blob.count) bytes")
                let seen = out.split(whereSeparator: \.isNewline).filter { $0.contains("tftp") || $0.contains("rror") }
                print("      out: \(seen.joined(separator: " | "))")
                failed += 1
            }
            removeScratchItem("tftpblob")
        }
    }
}

// ── shutdown: a daemon waiting for input does not hold os9exec open ─────────
// Once the shell os9exec was started with has exited, os9exec ends when every
// process left is only waiting for input (rdoggett, 2026-09-19: end and let the
// connections close). Before this it depended on a scheduling counter: with a
// daemon parked on a socket, about one run in twelve never ended at all. mrecv
// listens until killed, so it is that daemon here, NOT killed at the end. Six
// runs, because one run passed the old build eleven times in twelve; with the
// tick off (-q), which is where the old race showed.
do {
    let name = "shutdown: a daemon waiting for input does not keep os9exec open after the shell"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        if containerized {
            print("SKIP: \(name) (Linux loopback in the container carries no multicast)")
        } else {
            var stuck = 0
            for _ in 0..<6 {
                let out = os9(["load /dd/CMDS/BOOTOBJS/SPF/inetdb",
                               "load /dd/CMDS/BOOTOBJS/SPF/netdb_local",
                               "mrecv -v -i 127.0.0.1 &",
                               "sleep -s 1"], timeout: 20, flags: ["-q"])
                if out.contains("(timeout)") || !out.contains("Waiting for incoming multicasts") { stuck += 1 }
            }
            if stuck == 0 {
                print("PASS: \(name)"); passed += 1
            } else {
                print("FAIL: \(name)")
                print("      [\(stuck) of 6 runs did not end, or never started the daemon]")
                failed += 1
            }
        }
    }
}

// The deterministic half of the same rule. A process blocked in a PIPE read is
// parked as a system task, which the scheduler used to count as runnable: with
// the shell gone and only such a reader left, os9exec never ended, every time.
// pipewt opens an unnamed pipe, keeps a second path on it (so the read is not
// end of file), says it is ready and reads -- forever.
do {
    let name = "shutdown: a process blocked on a pipe read does not keep os9exec open after the shell"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let pipewtAsm = [
            "  use /dd/DEFS/oskdefs.d",
            "",
            "F$Exit   equ  $06",
            "I$Dup    equ  $82",
            "I$Create equ  $83",
            "I$Read   equ  $89",
            "I$WritLn equ  $8C",
            "",
            "  psect pipewt,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,512,start",
            "",
            "start:",
            "  lea     pname(pc),a0",
            "  moveq   #3,d0",
            "  moveq   #0,d1",
            "  moveq   #0,d2",
            "  OS9     I$Create",
            "  bcs.s   done",
            "  move.w  d0,d7",
            "  OS9     I$Dup",
            "  lea     msg(pc),a0",
            "  moveq   #msgl,d1",
            "  moveq   #1,d0",
            "  OS9     I$WritLn",
            "  sub.l   #16,a7",
            "  movea.l a7,a0",
            "  moveq   #10,d1",
            "  moveq   #0,d0",
            "  move.w  d7,d0",
            "  OS9     I$Read",
            "done:",
            "  moveq   #0,d1",
            "  OS9     F$Exit",
            "pname: dc.b \"/pipe\",0",
            "msg:   dc.b \"PIPEWAIT READY\",$0D",
            "msgl   equ  *-msg",
            "",
            "  ends",
            ""
        ].joined(separator: "\r")
        try? pipewtAsm.write(toFile: scratchDisk + "/pipewt.a", atomically: true, encoding: .utf8)
        let out = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                       "r68 /h5/pipewt.a -o=/h5/pipewt.r",
                       "l68 /h5/pipewt.r -o=/h5/pipewt",
                       "/h5/pipewt &",
                       "sleep -s 1"], timeout: 30)
        if !out.contains("(timeout)") && out.contains("PIPEWAIT READY") {
            print("PASS: \(name)"); passed += 1
        } else {
            print("FAIL: \(name)")
            print("      [os9exec must end once only the pipe reader is left; timed out=\(out.contains("(timeout)"))]")
            failed += 1
        }
        removeScratchItem("pipewt.a"); removeScratchItem("pipewt.r"); removeScratchItem("pipewt")
    }
}

// ── multicast: msend reaches mrecv through a group ───────────────────────────
// Socket options were accepted and never applied, so mrecv's group join did
// nothing and msend's datagram reached nobody. They are applied now, by their
// BSD numbers translated to the host's. Both are pinned to the loopback
// interface so nothing leaves this machine. Skipped in the container, whose
// Linux loopback does not usually carry multicast.
do {
    let name = "net: msend reaches mrecv through a multicast group on the loopback"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        if containerized {
            print("SKIP: \(name) (Linux loopback in the container carries no multicast)")
        } else {
            let out = os9(["load /dd/CMDS/BOOTOBJS/SPF/inetdb",
                           "load /dd/CMDS/BOOTOBJS/SPF/netdb_local",
                           "mrecv -v -i 127.0.0.1 &",
                           "sleep -s 1",
                           "msend -l -i 127.0.0.1 -m group-delivered",
                           "sleep -s 2",
                           // mrecv listens until killed. Left running, it decided
                           // by a scheduler race whether the emulator ended after
                           // the shell or waited on it forever (about 1 run in 12).
                           "kill 3"], timeout: 30)
            if out.contains("[group-delivered]") {
                print("PASS: \(name)")
                passed += 1
            } else {
                print("FAIL: \(name)")
                let seen = out.split(whereSeparator: \.isNewline).filter {
                    $0.contains("msend") || $0.contains("mrecv") || $0.contains("Received") || $0.contains("rror")
                }
                print("      out: \(seen.joined(separator: " | "))")
                failed += 1
            }
        }
    }
}

// ── telnet: data that arrives later still wakes the client ───────────────────
// The telnet client arms SS_SSig on its socket and sleeps until data comes.
// The signal was sent only if data was already there when it was armed, so a
// server that spoke first and at once worked, and anything that arrived later
// never woke it. Sockets are now checked with the terminals. And when the
// server closed, a socket with nothing pending said "not ready" even though a
// read would have met the end of file, so the client never left. Here the host
// server waits 2.5 s, sends one line, and closes: the line must arrive and the
// client must go, letting the shell run the next command.
do {
    let name = "net: telnet is woken by data that arrives later, and leaves when the server closes"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        if containerized {
            print("SKIP: \(name) (the container cannot reach the host's loopback)")
        } else {
            let port: UInt16 = 27023
            let listenFd = socket(AF_INET, streamSocketType, 0)
            var yes: Int32 = 1
            setsockopt(listenFd, SOL_SOCKET, SO_REUSEADDR, &yes, socklen_t(MemoryLayout<Int32>.size))
            var addr = sockaddr_in()
            addr.sin_family = sa_family_t(AF_INET)
            addr.sin_port = port.bigEndian
            addr.sin_addr.s_addr = INADDR_LOOPBACK.bigEndian
            let bound = withUnsafePointer(to: &addr) {
                $0.withMemoryRebound(to: sockaddr.self, capacity: 1) {
                    bind(listenFd, $0, socklen_t(MemoryLayout<sockaddr_in>.size))
                }
            }
            if listenFd < 0 || bound != 0 || listen(listenFd, 1) != 0 {
                if listenFd >= 0 { close(listenFd) }
                print("SKIP: \(name) (port \(port) is not available here)")
            } else {
                let done = DispatchSemaphore(value: 0)
                DispatchQueue.global().async {
                    let conn = accept(listenFd, nil, nil)
                    if conn >= 0 {
                        usleep(2_500_000)
                        let line = "late-line-from-host\r\n"
                        _ = write(conn, line, line.utf8.count)
                        sleep(1)
                        close(conn)
                    }
                    done.signal()
                }
                let out = os9(["load /dd/CMDS/BOOTOBJS/SPF/inetdb",
                               "load /dd/CMDS/BOOTOBJS/SPF/netdb_local",
                               "telnet 127.0.0.1 \(port) </nil",
                               "echo TELNET-HAS-LEFT"], timeout: 20)
                _ = done.wait(timeout: .now() + 10)
                close(listenFd)
                if out.contains("late-line-from-host") && out.contains("TELNET-HAS-LEFT") {
                    print("PASS: \(name)")
                    passed += 1
                } else {
                    print("FAIL: \(name)")
                    print("      out: \(out.split(whereSeparator: \.isNewline).suffix(8).joined(separator: " | "))")
                    failed += 1
                }
            }
        }
    }
}

// ── ftp put: a masked, waiting process still gives up the CPU ───────────────
// The OS-9 ftp client masks signals and then waits for the server's reply.
// os9exec never switched away from a process with signals masked -- even one
// parked waiting to read -- so ftpd, which had to run to answer, never got a
// turn: the upload hung and the emulator spun at 100% CPU. Here the guest's
// own ftp client uploads 70,001 bytes to the guest's ftpd, all in /h5.
do {
    let name = "net: the ftp client uploads to ftpd (a masked waiting process yields)"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        var probeAddr = sockaddr_in()
        probeAddr.sin_family = sa_family_t(AF_INET)
        probeAddr.sin_port = UInt16(21).bigEndian
        probeAddr.sin_addr.s_addr = INADDR_ANY
        let probe = socket(AF_INET, streamSocketType, 0)
        let probed = probe >= 0 && withUnsafePointer(to: &probeAddr) {
            $0.withMemoryRebound(to: sockaddr.self, capacity: 1) {
                bind(probe, $0, socklen_t(MemoryLayout<sockaddr_in>.size))
            }
        } == 0
        if probe >= 0 { close(probe) }
        if !probed && !containerized {
            print("SKIP: \(name) (port 21 is not available to this user)")
        } else {
            var blob = [UInt8](repeating: 0, count: 70001)
            for i in blob.indices { blob[i] = UInt8((i * 13 + 7) & 0xFF) }
            FileManager.default.createFile(atPath: scratchDisk + "/putsrc", contents: Data(blob))
            let script = "user dog\r\rbinary\rput /\(scratchDev)/putsrc /\(scratchDev)/putdst\rbye\r"
            try? script.write(toFile: scratchDisk + "/putcmds", atomically: true, encoding: .utf8)
            _ = os9(["load /dd/CMDS/BOOTOBJS/SPF/inetdb",
                     "load /dd/CMDS/BOOTOBJS/SPF/netdb_local",
                     "ftpd &",
                     "sleep -s 2",
                     "ftp -n localhost </\(scratchDev)/putcmds",
                     "kill 3"], timeout: 40)   // a daemon listens until killed; see the multicast test
            let got = FileManager.default.contents(atPath: scratchDisk + "/putdst") ?? Data()
            if got == Data(blob) {
                print("PASS: \(name)")
                passed += 1
            } else {
                print("FAIL: \(name)")
                print("      saw: \(got.count) of \(blob.count) bytes uploaded")
                failed += 1
            }
            for leftover in ["putsrc", "putdst", "putcmds"] { removeScratchItem(leftover) }
        }
    }
}

// ── RPC: portmap, a registered server, and a client that finds it ────────────
// Sun RPC over the socket manager: portmap on port 111, sortd registering with
// it, and rsort asking portmap where sortd is and having it sort three words.
// macOS's own rpcbind holds port 111, so this runs where the port is free --
// the Linux container, typically -- and is skipped elsewhere.
do {
    let name = "net: rsort finds sortd through portmap and gets its words back sorted"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        var pa = sockaddr_in()
        pa.sin_family = sa_family_t(AF_INET)
        pa.sin_port = UInt16(111).bigEndian
        pa.sin_addr.s_addr = INADDR_ANY
        let probe = socket(AF_INET, Int32(SOCK_DGRAM), 0)
        let free = probe >= 0 && withUnsafePointer(to: &pa) {
            $0.withMemoryRebound(to: sockaddr.self, capacity: 1) {
                bind(probe, $0, socklen_t(MemoryLayout<sockaddr_in>.size))
            }
        } == 0
        if probe >= 0 { close(probe) }
        if !free && !containerized {
            print("SKIP: \(name) (port 111 is taken on this host -- macOS runs its own rpcbind)")
        } else {
            let out = os9(["load /dd/CMDS/BOOTOBJS/SPF/inetdb",
                           "load /dd/CMDS/BOOTOBJS/SPF/inetdb2",
                           "load /dd/CMDS/BOOTOBJS/SPF/netdb_local",
                           "load /dd/CMDS/BOOTOBJS/SPF/rpcdb",
                           "portmap &", "sleep -s 3",
                           "sortd &", "sleep -s 3",
                           "rsort localhost pear apple fig",
                           // the daemons never exit, and the emulator waits for every
                           // process: portmap and sortd are 3 and 4 (each load has exited)
                           "kill 3", "kill 4"], timeout: 60)
            let words = out.split(whereSeparator: \.isNewline).map { $0.trimmingCharacters(in: .whitespaces) }
                .filter { ["apple", "fig", "pear"].contains($0) || $0.hasSuffix(" apple") }
                .map { $0.split(separator: " ").last.map(String.init) ?? $0 }
            if words == ["apple", "fig", "pear"] {
                print("PASS: \(name)")
                passed += 1
            } else {
                print("FAIL: \(name)")
                print("      saw words: \(words); tail: \(out.split(whereSeparator: \.isNewline).suffix(5).joined(separator: " | "))")
                failed += 1
            }
        }
    }
}

// ── telnetd: a host telnet client logs in to OS-9 ─────────────────────────────
// telnetd accepts the connection, and its telnetdc child opens /pk, takes a
// pty/tty pair from it and forks login on the tty. Three things stopped it: a
// second open of /pk was refused as busy, the socket could not carry the event
// telnetdc waits on, and a tty took os9exec's own host-stdin EOF as its own --
// so login gave up before a key was typed. Here a host client logs in as dog
// and runs procs; the listing proves the shell ran with its I/O on the tty.
// telnetd serves port 23 and has no option to move it, so the test skips where
// this user cannot bind that port, or another run already holds it.
do {
    let name = "net: a telnet client logs in through telnetd and runs a command"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let port: UInt16 = 23                 // telnet/tcp, telnetd's default
        let probeFd = socket(AF_INET, streamSocketType, 0)
        var addr = sockaddr_in()
        addr.sin_family = sa_family_t(AF_INET)
        addr.sin_port = port.bigEndian
        addr.sin_addr.s_addr = INADDR_ANY
        let probed = probeFd >= 0 && withUnsafePointer(to: &addr) {
            $0.withMemoryRebound(to: sockaddr.self, capacity: 1) {
                bind(probeFd, $0, socklen_t(MemoryLayout<sockaddr_in>.size))
            }
        } == 0
        if probeFd >= 0 { close(probeFd) }

        if containerized {
            print("SKIP: \(name) (the container cannot reach the host's loopback)")
        } else if !probed {
            print("SKIP: \(name) (port \(port) is not available to this user)")
        } else {
            // the client: connect once telnetd listens, type, and keep all it hears
            var heard = [UInt8]()
            let done = DispatchSemaphore(value: 0)
            DispatchQueue.global().async {
                var loopback = addr
                loopback.sin_addr.s_addr = INADDR_LOOPBACK.bigEndian
                var conn: Int32 = -1
                for _ in 0..<40 where conn < 0 {
                    let fd = socket(AF_INET, streamSocketType, 0)
                    let ok = withUnsafePointer(to: &loopback) {
                        $0.withMemoryRebound(to: sockaddr.self, capacity: 1) {
                            connect(fd, $0, socklen_t(MemoryLayout<sockaddr_in>.size))
                        }
                    } == 0
                    if ok { conn = fd } else { close(fd); usleep(150_000) }
                }
                if conn >= 0 {
                    var quiet = timeval(tv_sec: 0, tv_usec: 300_000)
                    setsockopt(conn, SOL_SOCKET, SO_RCVTIMEO, &quiet, socklen_t(MemoryLayout<timeval>.size))
                    var buf = [UInt8](repeating: 0, count: 4096)
                    func gather(for seconds: Double) {
                        let end = Date().addingTimeInterval(seconds)
                        while Date() < end {
                            let got = read(conn, &buf, buf.count)
                            if got == 0 { break }
                            if got > 0 { heard += buf[0..<got] }
                        }
                    }
                    for line in ["", "dog\r", "procs\r", "logout\r"] {
                        if !line.isEmpty { _ = write(conn, line, line.utf8.count) }
                        gather(for: 1.0)
                    }
                    close(conn)
                }
                done.signal()
            }

            let out = os9(["load /dd/CMDS/BOOTOBJS/SPF/inetdb",
                           "load /dd/CMDS/BOOTOBJS/SPF/netdb_local",
                           "load /dd/CMDS/BOOTOBJS/SPF/pkman",
                           "load /dd/CMDS/BOOTOBJS/SPF/pk",
                           "telnetd &",
                           "sleep -s 8",
                           "kill 3"], timeout: 30)   // a daemon listens until killed; see the multicast test
            _ = done.wait(timeout: .now() + 10)

            let session = String(decoding: heard, as: UTF8.self)
                .split(whereSeparator: { $0 == "\r" || $0 == "\n" })
            let loggedOn = session.contains { $0.contains("logged on") }
            let procsOnTty = session.contains { $0.contains("procs") && $0.contains("tty") }
            if loggedOn && procsOnTty {
                print("PASS: \(name)")
                passed += 1
            } else {
                print("FAIL: \(name)")
                print("      saw: logged on=\(loggedOn) procs on a tty=\(procsOnTty)")
                print("      client: \(session.suffix(6).joined(separator: " | "))")
                let seen = out.split(whereSeparator: \.isNewline).filter { $0.contains("Error") }
                print("      out: \(seen.joined(separator: " | "))")
                failed += 1
            }
        }
    }
}

// ── ftpd: a host FTP client logs in and fetches a file ────────────────────────
// ftpdc, the per-connection child, would not run: it wants its socket path to
// report the device type it checks for, and asks the socket for both ends'
// addresses. Then an active-mode transfer failed: ftpd binds its data socket
// to port 20 on 127.0.0.1, which macOS keeps for the super user on one address
// but not on all. Here a client logs in as dog and fetches /dd/SYS/errmsg over
// a data connection it listens for (PORT); every byte must match the disk.
// ftpd serves port 21 and cannot be moved, so this skips where that port
// cannot be bound, or another run already holds it.
do {
    let name = "net: an FTP client logs in to ftpd and fetches a file in active mode"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        func tcpSocket(port: UInt16, address: UInt32) -> (Int32, sockaddr_in) {
            var sa = sockaddr_in()
            sa.sin_family = sa_family_t(AF_INET)
            sa.sin_port = port.bigEndian
            sa.sin_addr.s_addr = address.bigEndian
            return (socket(AF_INET, streamSocketType, 0), sa)
        }
        func bindTo(_ fd: Int32, _ sa: inout sockaddr_in) -> Bool {
            withUnsafePointer(to: &sa) {
                $0.withMemoryRebound(to: sockaddr.self, capacity: 1) {
                    bind(fd, $0, socklen_t(MemoryLayout<sockaddr_in>.size))
                }
            } == 0
        }
        var (probeFd, probeAddr) = tcpSocket(port: 21, address: INADDR_ANY)
        let probed = probeFd >= 0 && bindTo(probeFd, &probeAddr)
        if probeFd >= 0 { close(probeFd) }
        let expected = FileManager.default.contents(atPath: diskPath + "/SYS/errmsg") ?? Data()

        if containerized {
            print("SKIP: \(name) (the container cannot reach the host's loopback)")
        } else if !probed {
            print("SKIP: \(name) (port 21 is not available to this user)")
        } else {
            var replies = ""
            var fetched = Data()
            let done = DispatchSemaphore(value: 0)
            DispatchQueue.global().async {
                var (ctl, ctlAddr) = tcpSocket(port: 21, address: INADDR_LOOPBACK)
                var linked = false
                for _ in 0..<40 where !linked {
                    linked = withUnsafePointer(to: &ctlAddr) {
                        $0.withMemoryRebound(to: sockaddr.self, capacity: 1) {
                            connect(ctl, $0, socklen_t(MemoryLayout<sockaddr_in>.size))
                        }
                    } == 0
                    if !linked { close(ctl); usleep(150_000); ctl = socket(AF_INET, streamSocketType, 0) }
                }
                guard linked else { close(ctl); done.signal(); return }
                var quiet = timeval(tv_sec: 0, tv_usec: 300_000)
                setsockopt(ctl, SOL_SOCKET, SO_RCVTIMEO, &quiet, socklen_t(MemoryLayout<timeval>.size))
                var buf = [UInt8](repeating: 0, count: 4096)
                func gather(for seconds: Double) {
                    let end = Date().addingTimeInterval(seconds)
                    while Date() < end {
                        let got = read(ctl, &buf, buf.count)
                        if got == 0 { break }
                        if got > 0 { replies += String(decoding: buf[0..<got], as: UTF8.self) }
                    }
                }
                func say(_ line: String) { _ = write(ctl, line + "\r\n", line.utf8.count + 2); gather(for: 1.0) }

                // the data connection: we listen, ftpd connects to us
                var (data, dataAddr) = tcpSocket(port: 0, address: INADDR_LOOPBACK)
                var dataLen = socklen_t(MemoryLayout<sockaddr_in>.size)
                if bindTo(data, &dataAddr) && listen(data, 1) == 0 {
                    withUnsafeMutablePointer(to: &dataAddr) {
                        $0.withMemoryRebound(to: sockaddr.self, capacity: 1) { _ = getsockname(data, $0, &dataLen) }
                    }
                    let dataPort = UInt16(bigEndian: dataAddr.sin_port)
                    gather(for: 1.0)
                    say("USER dog")
                    say("PASS ")
                    say("TYPE I")
                    say("PORT 127,0,0,1,\(dataPort >> 8),\(dataPort & 0xFF)")
                    let retr = "RETR /dd/SYS/errmsg\r\n"   // answered on the data connection
                    _ = write(ctl, retr, retr.utf8.count)
                    let conn = accept(data, nil, nil)
                    if conn >= 0 {
                        var chunk = [UInt8](repeating: 0, count: 4096)
                        while true {
                            let got = read(conn, &chunk, chunk.count)
                            if got <= 0 { break }
                            fetched.append(contentsOf: chunk[0..<got])
                        }
                        close(conn)
                    }
                    gather(for: 1.0)
                    say("QUIT")
                }
                close(data)
                close(ctl)
                done.signal()
            }

            let out = os9(["load /dd/CMDS/BOOTOBJS/SPF/inetdb",
                           "load /dd/CMDS/BOOTOBJS/SPF/netdb_local",
                           "ftpd &",
                           "sleep -s 10",
                           "kill 3"], timeout: 30)   // a daemon listens until killed; see the multicast test
            _ = done.wait(timeout: .now() + 10)

            let loggedIn = replies.contains("230 ")
            if loggedIn && !expected.isEmpty && fetched == expected {
                print("PASS: \(name)")
                passed += 1
            } else {
                print("FAIL: \(name)")
                print("      saw: logged in=\(loggedIn) fetched=\(fetched.count) of \(expected.count) bytes")
                let codes = replies.split(whereSeparator: { $0 == "\r" || $0 == "\n" })
                print("      server: \(codes.suffix(6).joined(separator: " | "))")
                let seen = out.split(whereSeparator: \.isNewline).filter { $0.contains("ftpd") || $0.contains("Error") }
                print("      out: \(seen.joined(separator: " | "))")
                failed += 1
            }
        }
    }
}

// ── ping: an echo request goes out and its reply comes back ─────────────────
// ping opens a raw socket and sends with an address given per datagram, then
// receives with the sender's address; neither was there, so it stopped after
// "PING ...". A raw socket is the host's ICMP datagram socket, which needs no
// super user; Linux's gives replies without the IP header and with its own
// echo identifier, so those are put back. Under a container os9exec pings the
// container's own loopback, which Docker lets an ordinary user do.
do {
    let name = "net: ping gets an echo reply from the loopback"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let icmp = socket(AF_INET, Int32(SOCK_DGRAM), Int32(IPPROTO_ICMP))
        if icmp >= 0 { close(icmp) }
        if !containerized && icmp < 0 {
            print("SKIP: \(name) (this host gives no ICMP socket to this user)")
        } else {
            let out = os9(["load /dd/CMDS/BOOTOBJS/SPF/inetdb",
                           "load /dd/CMDS/BOOTOBJS/SPF/netdb_local",
                           "ping 127.0.0.1"], timeout: 20)
            if out.contains("bytes from 127.0.0.1") {
                print("PASS: \(name)")
                passed += 1
            } else {
                print("FAIL: \(name)")
                let seen = out.split(whereSeparator: \.isNewline).filter { $0.contains("ping") || $0.contains("PING") }
                print("      out: \(seen.joined(separator: " | "))")
                failed += 1
            }
        }
    }
}

// ── /socket: the older socket library's calls, one setstat per BSD call ──────
// Programs built with the earlier Microware socket library (ttcp, the BIND 4.8.3
// tools, WN's inetd) open plain "/socket" rather than an "/ip0" path, and make
// each socket call a setstat of its own -- socket, bind, listen, connect and
// accept -- where the SPF library puts an operation inside one SS_SPF block.
// os9exec's original authors served those calls in network.c; it was retired in
// 2026 as unused, and "/socket" then answered E$MNF, so every such program
// stopped at its first socket call. spfsock.c serves them again over the same
// host sockets. These programs make the calls directly, as that library does,
// so the tests need nothing from any networking package.
do {
    /// A TCP socket on the host's loopback, bound to a port the host picked.
    func loopbackSocket(listening: Bool) -> (fd: Int32, port: UInt16)? {
        let sock = socket(AF_INET, streamSocketType, 0)
        guard sock >= 0 else { return nil }
        var addr = sockaddr_in()
        addr.sin_family = sa_family_t(AF_INET)
        addr.sin_addr.s_addr = INADDR_LOOPBACK.bigEndian
        var len = socklen_t(MemoryLayout<sockaddr_in>.size)
        let bound = withUnsafeMutablePointer(to: &addr) {
            $0.withMemoryRebound(to: sockaddr.self, capacity: 1) {
                bind(sock, $0, len) == 0 && getsockname(sock, $0, &len) == 0
            }
        }
        guard bound, !listening || listen(sock, 1) == 0 else { close(sock); return nil }
        return (sock, UInt16(bigEndian: addr.sin_port))
    }

    /// An assembler source whose `start:` is <body>, with the data every one of
    /// these programs uses: the device name, socket()'s three arguments
    /// (Internet, stream, default protocol) and 127.0.0.1:<port> laid out as a
    /// BSD socket address.
    func socketProgram(_ module: String, port: UInt16, _ body: [String]) -> String {
        ([
            "  use /dd/DEFS/oskdefs.d",
            "",
            "F$Exit   equ  $06",
            "I$Open   equ  $84",
            "I$Write  equ  $8A",
            "I$SetStt equ  $8E",
            "I$Close  equ  $8F",
            "SSBind   equ  $6C",
            "SSListen equ  $6D",
            "SSConn   equ  $6E",
            "SSResv   equ  $6F",
            "SSAccept equ  $70",
            "",
            "  psect \(module),(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
            "",
            "start:"
        ] + body + [
            "fail:",
            "  OS9     F$Exit",
            "triple:  dc.l  2,1,0",
            "addr:    dc.w  2,\(port)",
            "         dc.b  127,0,0,1",
            "         dc.l  0,0",
            "msg:     dc.b  \"FROM-OS9-SOCKET\"",
            "msgl     equ   *-msg",
            "sockdev: dc.b  \"/socket\",0",
            "nildev:  dc.b  \"/nil\",0",
            "",
            "  ends",
            ""
        ]).joined(separator: "\r")
    }

    /// Opens "/socket" and asks it for a socket; the path is left in d7.
    let openSocket = [
        "  lea     sockdev(pc),a0",
        "  moveq   #3,d0",
        "  OS9     I$Open",
        "  bcs     fail",
        "  move.w  d0,d7",
        "  lea     triple(pc),a0",
        "  moveq   #12,d2",
        "  move.w  #SSResv,d1",
        "  OS9     I$SetStt",
        "  bcs     fail"
    ]
    /// Connects the socket in d7 to `addr`, writes `msg` down it and closes it.
    let connectAndSend = [
        "  move.w  d7,d0",
        "  lea     addr(pc),a0",
        "  moveq   #16,d2",
        "  move.w  #SSConn,d1",
        "  OS9     I$SetStt",
        "  bcs     fail",
        "  move.w  d7,d0",
        "  lea     msg(pc),a0",
        "  moveq   #msgl,d1",
        "  OS9     I$Write",
        "  bcs     fail",
        "  move.w  d7,d0",
        "  OS9     I$Close",
        "  moveq   #0,d1"
    ]

    /// Assembles <source> into /h5/<module>, runs it, and answers the output.
    func buildAndRun(_ module: String, _ source: String, timeout: TimeInterval = 30) -> String {
        try? source.write(toFile: scratchDisk + "/\(module).a", atomically: true, encoding: .utf8)
        let out = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                       "r68 /h5/\(module).a -o=/h5/\(module).r",
                       "l68 /h5/\(module).r -o=/h5/\(module)",
                       "/h5/\(module)",
                       "echo \(module.uppercased())-END"], timeout: timeout)
        for leftover in ["\(module).a", "\(module).r", module] { removeScratchItem(leftover) }
        return out
    }

    /// The lines of <out> worth showing when a test fails.
    func errorLines(_ out: String) -> String {
        out.replacingOccurrences(of: "\r", with: "\n").split(separator: "\n")
            .filter { $0.contains("Error") || $0.contains("END") }
            .prefix(4).joined(separator: " | ")
    }

    // A client: socket, connect, write. The host must receive what it wrote.
    let clientName = "net: a /socket client (the older socket library) connects and sends"
    if filter.isEmpty || clientName.localizedCaseInsensitiveContains(filter) {
        if containerized {
            print("SKIP: \(clientName) (the container cannot reach the host's loopback)")
        } else if let (listenFd, port) = loopbackSocket(listening: true) {
            var received = [UInt8]()
            let done = DispatchSemaphore(value: 0)
            DispatchQueue.global().async {
                let conn = accept(listenFd, nil, nil)
                if conn >= 0 {
                    var buf = [UInt8](repeating: 0, count: 256)
                    while case let got = read(conn, &buf, buf.count), got > 0 {
                        received += buf[0..<got]
                    }
                    close(conn)
                }
                done.signal()
            }
            let out = buildAndRun("ispcli", socketProgram("ispcli", port: port, openSocket + connectAndSend))
            let drained = done.wait(timeout: .now() + 10) == .success
            if !drained { shutdown(listenFd, SHUT_RDWR) }   // releases the reader's accept
            close(listenFd)
            let text = String(bytes: received, encoding: .utf8) ?? "<not UTF-8>"
            if drained && text == "FROM-OS9-SOCKET" && out.contains("ISPCLI-END") && !out.contains("Error #") {
                print("PASS: \(clientName)")
                passed += 1
            } else {
                print("FAIL: \(clientName)")
                print("      host received: \"\(text)\" (drained=\(drained))")
                print("      out: \(errorLines(out))")
                failed += 1
            }
        } else {
            print("SKIP: \(clientName) (no loopback port could be bound)")
        }
    }

    // A send parked on a full socket and cut short by a signal must not leave its
    // progress behind: the next write from the same buffer skipped that many
    // bytes and reported them sent (found by the pre-release character-I/O
    // review). The host holds off reading so the first 2 MB send parks, an
    // alarm ends it, and the second 2 MB -- all B -- must arrive whole.
    let abandonName = "net: a socket send cut short by a signal leaves nothing for the next send to skip"
    if filter.isEmpty || abandonName.localizedCaseInsensitiveContains(filter) {
        if containerized {
            print("SKIP: \(abandonName) (the container cannot reach the host's loopback)")
        } else if let (listenFd, port) = loopbackSocket(listening: true) {
            // a small receive window, so the host cannot swallow 2 MB at once
            // and the first send really has to park (macOS loopback otherwise can)
            var window: Int32 = 8192
            setsockopt(listenFd, SOL_SOCKET, SO_RCVBUF, &window, socklen_t(MemoryLayout<Int32>.size))
            var letterA = 0, letterB = 0
            let done = DispatchSemaphore(value: 0)
            DispatchQueue.global().async {
                let conn = accept(listenFd, nil, nil)
                if conn >= 0 {
                    Thread.sleep(forTimeInterval: 3.0)      // the first send parks, then is cut short
                    var buf = [UInt8](repeating: 0, count: 65536)
                    while case let got = read(conn, &buf, buf.count), got > 0 {
                        for byte in buf[0..<got] {
                            if byte == 0x41 { letterA += 1 } else if byte == 0x42 { letterB += 1 }
                        }
                    }
                    close(conn)
                }
                done.signal()
            }
            let body = [
                "F$Icpt equ $09", "F$RTE equ $1E", "F$Alarm equ $56", "F$SRqMem equ $28",
                "  lea handler(pc),a0", "  OS9 F$Icpt",
                // fill first: the send must start the moment the connection
                // exists, while the host is still holding off
                "  move.l #$200000,d0", "  OS9 F$SRqMem", "  bcs fail", "  movea.l a2,a3",
                "  movea.l a3,a1", "  move.l #$80000,d2",
                "filla:", "  move.l #$41414141,(a1)+", "  subq.l #1,d2", "  bne.s filla"] +
                openSocket + Array(connectAndSend.prefix(6)) + [
                "  moveq #0,d0", "  moveq #1,d1", "  moveq #2,d2", "  moveq #50,d3", "  OS9 F$Alarm",
                "  move.w d7,d0", "  movea.l a3,a0", "  move.l #$200000,d1", "  OS9 I$Write",
                "  movea.l a3,a1", "  move.l #$80000,d2",
                "fillb:", "  move.l #$42424242,(a1)+", "  subq.l #1,d2", "  bne.s fillb",
                "  move.w d7,d0", "  movea.l a3,a0", "  move.l #$200000,d1", "  OS9 I$Write", "  bcs fail",
                "  move.w d7,d0", "  OS9 I$Close",
                "  moveq #0,d1", "  bra fail",
                "handler:", "  OS9 F$RTE"
            ]
            let out = buildAndRun("ispabn", socketProgram("ispabn", port: port, body), timeout: 90)
            let drained = done.wait(timeout: .now() + 30) == .success
            if !drained { shutdown(listenFd, SHUT_RDWR) }
            close(listenFd)
            if drained && letterB == 0x200000 && letterA < 0x200000 && out.contains("ISPABN-END") {
                print("PASS: \(abandonName)")
                passed += 1
            } else {
                print("FAIL: \(abandonName)")
                print("      host got \(letterA) A and \(letterB) B (want every one of 2097152 B), drained=\(drained)")
                print("      out: \(errorLines(out))")
                failed += 1
            }
        } else {
            print("SKIP: \(abandonName) (no loopback port could be bound)")
        }
    }

    // Two processes writing one socket path, the peer slow to read: both
    // writes park. The resume point is one per path, so the second writer
    // wiped the first's and the first went out again from its first byte --
    // duplicated bytes, and the second write inside the first (found by the
    // networking review). The parent puts the socket on its path 1 and forks a
    // copy of itself ("C") that inherits it; each writes a megabyte. The host
    // must get exactly a megabyte of each, in two runs.
    let twoWriterName = "net: two processes writing one socket neither repeat nor split each other's writes"
    if filter.isEmpty || twoWriterName.localizedCaseInsensitiveContains(filter) {
        if containerized {
            print("SKIP: \(twoWriterName) (the container cannot reach the host's loopback)")
        } else if let (listenFd, port) = loopbackSocket(listening: true) {
            var window: Int32 = 8192
            setsockopt(listenFd, SOL_SOCKET, SO_RCVBUF, &window, socklen_t(MemoryLayout<Int32>.size))
            var letterA = 0, letterB = 0, runs = 0, last: UInt8 = 0
            let done = DispatchSemaphore(value: 0)
            DispatchQueue.global().async {
                let conn = accept(listenFd, nil, nil)
                if conn >= 0 {
                    Thread.sleep(forTimeInterval: 3.0)      // both writes park meanwhile
                    var buf = [UInt8](repeating: 0, count: 65536)
                    while case let got = read(conn, &buf, buf.count), got > 0 {
                        for byte in buf[0..<got] {
                            if byte == 0x41 { letterA += 1 } else if byte == 0x42 { letterB += 1 }
                            if byte != last { runs += 1; last = byte }
                        }
                    }
                    close(conn)
                }
                done.signal()
            }
            let megabyte = 0x100000
            let body = [
                "F$Fork equ $03", "F$Wait equ $04", "F$SRqMem equ $28", "I$Dup equ $82",
                "  tst.l d5", "  beq.s parent", "  cmpi.b #'C',(a5)", "  beq.w child",
                "parent:"] + openSocket + Array(connectAndSend.prefix(6)) + [
                "  moveq #1,d0", "  OS9 I$Close",
                "  move.w d7,d0", "  OS9 I$Dup", "  bcs fail",
                "  lea myname(pc),a0", "  lea cparm(pc),a1", "  moveq #0,d0", "  moveq #0,d1",
                "  moveq #2,d2", "  moveq #2,d3", "  moveq #0,d4", "  OS9 F$Fork", "  bcs fail",
                "  move.l #$100000,d0", "  OS9 F$SRqMem", "  bcs fail", "  movea.l a2,a3",
                "  movea.l a3,a1", "  move.l #$40000,d2",
                "filla:", "  move.l #$41414141,(a1)+", "  subq.l #1,d2", "  bne.s filla",
                "  move.w d7,d0", "  movea.l a3,a0", "  move.l #$100000,d1", "  OS9 I$Write", "  bcs fail",
                "  OS9 F$Wait",
                "  move.w d7,d0", "  OS9 I$Close",
                "  moveq #1,d0", "  OS9 I$Close",
                "  moveq #0,d1", "  bra fail",
                "child:",
                "  move.l #$100000,d0", "  OS9 F$SRqMem", "  bcs fail", "  movea.l a2,a3",
                "  movea.l a3,a1", "  move.l #$40000,d2",
                "fillb:", "  move.l #$42424242,(a1)+", "  subq.l #1,d2", "  bne.s fillb",
                "  moveq #1,d0", "  movea.l a3,a0", "  move.l #$100000,d1", "  OS9 I$Write", "  bcs fail",
                "  moveq #0,d1", "  bra fail",
                "myname: dc.b \"isp2w\",0", "cparm: dc.b \"C\",13", "  align"
            ]
            let out = buildAndRun("isp2w", socketProgram("isp2w", port: port, body), timeout: 90)
            let drained = done.wait(timeout: .now() + 30) == .success
            if !drained { shutdown(listenFd, SHUT_RDWR) }
            close(listenFd)
            let whole = letterA == megabyte && letterB == megabyte && runs == 2
            if drained && whole && out.contains("ISP2W-END") {
                print("PASS: \(twoWriterName)")
                passed += 1
            } else {
                print("FAIL: \(twoWriterName)")
                print("      host got \(letterA) A, \(letterB) B in \(runs) runs (want 1048576 each, 2 runs)")
                print("      drained=\(drained)")
                print("      out: \(errorLines(out))")
                failed += 1
            }
        } else {
            print("SKIP: \(twoWriterName) (no loopback port could be bound)")
        }
    }

    // A server: socket, bind, listen, accept. The accepted connection comes back
    // as a new path in d1; the host client must read what is written to it.
    let serverName = "net: a /socket server binds, listens and accepts, the connection a path of its own"
    if filter.isEmpty || serverName.localizedCaseInsensitiveContains(filter) {
        if containerized {
            print("SKIP: \(serverName) (the container cannot reach the host's loopback)")
        } else if let (probe, port) = loopbackSocket(listening: false) {
            close(probe)                    // a port that was free a moment ago
            var received = [UInt8]()
            var connected = false
            let done = DispatchSemaphore(value: 0)
            DispatchQueue.global().async {
                // The server is not listening until the emulator has started and
                // assembled it, so keep trying for as long as that can take.
                let deadline = Date().addingTimeInterval(25)
                while !connected && Date() < deadline {
                    let client = socket(AF_INET, streamSocketType, 0)
                    var addr = sockaddr_in()
                    addr.sin_family = sa_family_t(AF_INET)
                    addr.sin_port = port.bigEndian
                    addr.sin_addr.s_addr = INADDR_LOOPBACK.bigEndian
                    connected = withUnsafePointer(to: &addr) {
                        $0.withMemoryRebound(to: sockaddr.self, capacity: 1) {
                            connect(client, $0, socklen_t(MemoryLayout<sockaddr_in>.size)) == 0
                        }
                    }
                    if connected {
                        var buf = [UInt8](repeating: 0, count: 256)
                        while case let got = read(client, &buf, buf.count), got > 0 {
                            received += buf[0..<got]
                        }
                    } else {
                        usleep(100_000)
                    }
                    close(client)
                }
                done.signal()
            }
            let serve = [
                "  move.w  d7,d0",
                "  lea     addr(pc),a0",
                "  moveq   #16,d2",
                "  move.w  #SSBind,d1",
                "  OS9     I$SetStt",
                "  bcs     fail",
                "  move.w  d7,d0",
                "  suba.l  a0,a0",
                "  moveq   #1,d2",
                "  move.w  #SSListen,d1",
                "  OS9     I$SetStt",
                "  bcs     fail",
                "  move.w  d7,d0",
                "  suba.l  a0,a0",          // no peer address wanted
                "  suba.l  a1,a1",
                "  move.w  #SSAccept,d1",
                "  OS9     I$SetStt",
                "  bcs     fail",
                "  move.w  d1,d6",          // the connection's own path
                "  move.w  d6,d0",
                "  lea     msg(pc),a0",
                "  moveq   #msgl,d1",
                "  OS9     I$Write",
                "  bcs     fail",
                "  move.w  d6,d0",
                "  OS9     I$Close",
                "  move.w  d7,d0",
                "  OS9     I$Close",
                "  moveq   #0,d1"
            ]
            let out = buildAndRun("ispsrv", socketProgram("ispsrv", port: port, openSocket + serve))
            let drained = done.wait(timeout: .now() + 30) == .success
            let text = String(bytes: received, encoding: .utf8) ?? "<not UTF-8>"
            if drained && text == "FROM-OS9-SOCKET" && out.contains("ISPSRV-END") && !out.contains("Error #") {
                print("PASS: \(serverName)")
                passed += 1
            } else {
                print("FAIL: \(serverName)")
                print("      host received: \"\(text)\" (connected=\(connected) drained=\(drained))")
                print("      out: \(errorLines(out))")
                failed += 1
            }
        } else {
            print("SKIP: \(serverName) (no loopback port could be bound)")
        }
    }

    // A refused connection is reported by the socket error a BSD caller prints
    // (ECONNREFUSED, 007:026), not a generic device error. The port is found
    // free and closed again, so nothing answers there; inside a container that
    // is the container's own loopback, which refuses just the same.
    let refusedName = "net: a refused /socket connect reports ECONNREFUSED"
    if filter.isEmpty || refusedName.localizedCaseInsensitiveContains(filter) {
        if let (probe, port) = loopbackSocket(listening: false) {
            close(probe)
            let out = buildAndRun("ispref", socketProgram("ispref", port: port, openSocket + connectAndSend))
            if out.contains("Error #007:026") {
                print("PASS: \(refusedName)")
                passed += 1
            } else {
                print("FAIL: \(refusedName)")
                print("      out: \(errorLines(out))")
                failed += 1
            }
        } else {
            print("SKIP: \(refusedName) (no loopback port could be bound)")
        }
    }

    // A four-byte IP_MULTICAST_TTL (level 0, option 10) is the guest's
    // big-endian int. It went to the host as raw bytes -- 1 read as $01000000
    // on a little-endian host, which refused it -- so the option never took.
    let ttlName = "net: a /socket multicast TTL given as an int reaches the host as its value"
    if filter.isEmpty || ttlName.localizedCaseInsensitiveContains(filter) {
        let udpTTL = [
            "  lea     sockdev(pc),a0", "  moveq   #3,d0", "  OS9     I$Open", "  bcs     fail",
            "  move.w  d0,d7",
            "  lea     udp(pc),a0", "  moveq   #12,d2", "  move.w  #SSResv,d1", "  OS9     I$SetStt",
            "  bcs     fail",
            "  move.w  d7,d0", "  lea     ttl(pc),a0", "  moveq   #10,d2", "  moveq   #0,d3", "  moveq   #4,d4",
            "  move.w  #$74,d1", "  OS9     I$SetStt", "  bcs     fail",
            "  move.w  d7,d0", "  OS9     I$Close", "  moveq   #0,d1", "  bra     fail",
            "udp:     dc.l  2,2,0", "ttl:     dc.l  1"
        ]
        let out = buildAndRun("ispttl", socketProgram("ispttl", port: 1, udpTTL))
        if out.contains("ISPTTL-END") && !out.contains("Error #") {
            print("PASS: \(ttlName)")
            passed += 1
        } else {
            print("FAIL: \(ttlName)")
            print("      out: \(errorLines(out))")
            failed += 1
        }
    }

    // SS_Resv on a path that is no socket: E$UnkSvc (208), where it used to
    // answer success -- telling a caller it had a socket when nothing was made.
    let resvName = "setstat: SS_Resv on a path that is not a socket answers E$UnkSvc"
    if filter.isEmpty || resvName.localizedCaseInsensitiveContains(filter) {
        let onNil = [
            "  lea     nildev(pc),a0",
            "  moveq   #3,d0",
            "  OS9     I$Open",
            "  bcs     fail",
            "  lea     triple(pc),a0",
            "  moveq   #12,d2",
            "  move.w  #SSResv,d1",
            "  OS9     I$SetStt",
            "  bcs     fail",
            "  moveq   #1,d1"               // success here is the defect
        ]
        let out = buildAndRun("ispnil", socketProgram("ispnil", port: 1, onNil))
        if out.contains("Error #000:208") {
            print("PASS: \(resvName)")
            passed += 1
        } else {
            print("FAIL: \(resvName)")
            print("      out: \(errorLines(out))")
            failed += 1
        }
    }
}

// ── F$Alarm: a fired alarm interrupts an INDEFINITE F$Sleep(0) ─────────────────
// Same bug, the other sleep variant: F$Sleep(0) (wakes only on signal, no
// natural timeout at all) was likewise never interrupted by a due alarm
// before the fix -- doc note in the syscall reference explicitly said this
// combination was "deliberately never tested live... nothing in a scripted
// harness can safely signal it" until the alarm itself became a safe,
// self-contained signal source for exactly this.
do {
    let alAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "",
        "F$Exit   equ  $06",
        "F$Alarm  equ  $56",
        "F$Sleep  equ  $0A",
        "I$WritLn equ  $8C",
        "",
        "  psect alfire3,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,512,start",
        "",
        "start:",
        "  clr.l   d0",             // aId must be 0 on input (A_Make's own check)
        "  move.w  #1,d1",          // A$Set (one-shot)
        "  move.w  #7,d2",          // sig=7
        "  move.l  #100,d3",        // interval=100 ticks = 1 real second
        "  OS9     F$Alarm",
        "  bcs     setfail",
        "  clr.l   d0",             // F$Sleep(0): indefinite, wakes only on signal
        "  OS9     F$Sleep",
        "  lea     nofiremsg(pc),a0",
        "  moveq   #nofiremsgl,d1",
        "  moveq   #1,d0",
        "  OS9     I$WritLn",
        "  bra     done",
        "setfail:",
        "  lea     setfailmsg(pc),a0",
        "  moveq   #setfailmsgl,d1",
        "  moveq   #1,d0",
        "  OS9     I$WritLn",
        "done:",
        "  moveq   #0,d1",
        "  OS9     F$Exit",
        "nofiremsg:   dc.b  \"ALARM DID NOT KILL SLEEPING PROCESS\",$0D",
        "nofiremsgl   equ   *-nofiremsg",
        "setfailmsg:  dc.b  \"A$SET FAILED\",$0D",
        "setfailmsgl  equ   *-setfailmsg",
        "",
        "  ends",
        ""
    ].joined(separator: "\r")

    let asmPath = scratchDisk + "/alfire3.a"
    try? alAsm.write(toFile: asmPath, atomically: true, encoding: .utf8)

    let name = "f$alarm: a fired alarm interrupts an indefinite F$Sleep(0)"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let out = os9([
            "load /dd/CMDS/r68 /dd/CMDS/l68",
            "r68 /h5/alfire3.a -o=/h5/alfire3.r",
            "l68 /h5/alfire3.r -o=/h5/alfire3",
            "/h5/alfire3"
        ], timeout: 15)
        if !out.contains("ALARM DID NOT KILL SLEEPING PROCESS") && !out.contains("A$SET FAILED") && out != "(timeout)" {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            print("      [an alarm must interrupt an indefinite sleep, which by design never wakes on its own]")
            let preview = out.split(separator: "\n")
                .filter { !$0.hasPrefix("#") && $0 != "$" && !$0.isEmpty }
                .prefix(8).joined(separator: " | ")
            print("      output: \(preview)")
            failed += 1
        }
    }

    for leftover in ["alfire3.a", "alfire3.r", "alfire3"] {
        try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
    }
}

// ── F$Icpt: an installed intercept handler actually runs, and the process
// survives the signal instead of being killed ─────────────────────────────────
// ROADMAP.md carried this as a documented non-functional feature ("F$Icpt
// accepts an install but never delivers a signal to the handler"), based on a
// 2026-07-20 dogfood pass (dogfood-report-syscalls-batch3-2026-07-20.md) that
// only ever installed the handler and sent S_Wake (signal code 1) -- S_Wake is
// explicitly special-cased in send_signal() (procstuff.c) and skips the whole
// intercept-dispatch branch, so that pass could never have exercised delivery
// regardless of the gap it was checking for.
//
// Reading procstuff.c's send_signal() shows a complete dispatch path already
// exists for a real (non-S_Wake) signal when a handler is installed: it saves
// the interrupted registers into rteregs/rtevector/rtefunc, points pc at
// pd._sigvec with a[6]=icpta6 and d1.w=signal, and F$RTE (OS9_F_RTE, fcalls.c)
// restores the saved state afterward. Confirmed live BEFORE writing this test:
// an alarm-delivered signal (sig=7, not S_Wake) to a process that installed an
// F$Icpt handler runs the handler and the process resumes and exits cleanly --
// this is a live re-characterization, not a fix; no production code changed.
// Verified non-vacuous: forcing procstuff.c's `sigp->pd._sigvec!=0 && ptocOK`
// check false in a scratch build makes both tests below fail red (the process
// is killed with the signal as its abort code instead of printing HANDLER
// RAN/SURVIVED) -- see docs/ for the session's investigation notes.
do {
    let icAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "",
        "F$Exit   equ  $06",
        "F$Icpt   equ  $09",
        "F$RTE    equ  $1E",
        "F$Alarm  equ  $56",
        "F$Sleep  equ  $0A",
        "I$WritLn equ  $8C",
        "",
        "  psect icptalm,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,512,start",
        "",
        "start:",
        "  lea     handler(pc),a0",
        "  movea.l a7,a6",
        "  OS9     F$Icpt",
        "  bcs     icptfail",
        "  clr.l   d0",
        "  move.w  #1,d1",            // A$Set
        "  move.w  #7,d2",            // sig=7, ordinary interceptable
        "  move.l  #100,d3",          // interval=100 ticks = 1 real second
        "  OS9     F$Alarm",
        "  bcs     setfail",
        "  clr.l   d0",               // F$Sleep(0): indefinite, wakes only on signal
        "  OS9     F$Sleep",
        "  lea     survivedmsg(pc),a0",
        "  moveq   #survivedmsgl,d1",
        "  moveq   #1,d0",
        "  OS9     I$WritLn",
        "  bra     done",
        "icptfail:",
        "  lea     icptfailmsg(pc),a0",
        "  moveq   #icptfailmsgl,d1",
        "  moveq   #1,d0",
        "  OS9     I$WritLn",
        "  bra     done",
        "setfail:",
        "  lea     setfailmsg(pc),a0",
        "  moveq   #setfailmsgl,d1",
        "  moveq   #1,d0",
        "  OS9     I$WritLn",
        "done:",
        "  moveq   #0,d1",
        "  OS9     F$Exit",
        "handler:",
        "  lea     handlermsg(pc),a0",
        "  moveq   #handlermsgl,d1",
        "  moveq   #1,d0",
        "  OS9     I$WritLn",
        "  OS9     F$RTE",
        "survivedmsg:  dc.b  \"SURVIVED\",$0D",
        "survivedmsgl  equ   *-survivedmsg",
        "icptfailmsg:  dc.b  \"F$ICPT FAILED\",$0D",
        "icptfailmsgl  equ   *-icptfailmsg",
        "setfailmsg:   dc.b  \"A$SET FAILED\",$0D",
        "setfailmsgl   equ   *-setfailmsg",
        "handlermsg:   dc.b  \"HANDLER RAN\",$0D",
        "handlermsgl   equ   *-handlermsg",
        "",
        "  ends",
        ""
    ].joined(separator: "\r")

    let asmPath = scratchDisk + "/icptalm.a"
    try? icAsm.write(toFile: asmPath, atomically: true, encoding: .utf8)

    let name = "f$icpt: an alarm-delivered signal runs the installed handler, process survives"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let out = os9([
            "load /dd/CMDS/r68 /dd/CMDS/l68",
            "r68 /h5/icptalm.a -o=/h5/icptalm.r",
            "l68 /h5/icptalm.r -o=/h5/icptalm",
            "/h5/icptalm"
        ], timeout: 15)
        if out.contains("HANDLER RAN") && out.contains("SURVIVED") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            print("      [installed handler must run and the process must survive the signal]")
            let preview = out.split(separator: "\n")
                .filter { !$0.hasPrefix("#") && $0 != "$" && !$0.isEmpty }
                .prefix(8).joined(separator: " | ")
            print("      output: \(preview)")
            failed += 1
        }
    }

    for leftover in ["icptalm.a", "icptalm.r", "icptalm"] {
        try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
    }
}

// ── F$Icpt: same thing via a self-directed F$Send while ACTIVE (not asleep) ────
// Distinct code path from the alarm test above: this signal is queued and
// drained via sig_mask()'s async-pending check right after the F$Send syscall
// itself returns (see os9exec_nt.c's main loop), rather than via CheckAlarms()
// inside DoWait(). Exercising both confirms the intercept mechanism doesn't
// depend on the process being asleep when the signal arrives.
do {
    let icAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "",
        "F$Exit   equ  $06",
        "F$Icpt   equ  $09",
        "F$RTE    equ  $1E",
        "F$Send   equ  $08",
        "F$ID     equ  $0C",
        "I$WritLn equ  $8C",
        "",
        "  psect icptsnd,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,512,start",
        "",
        "start:",
        "  lea     handler(pc),a0",
        "  movea.l a7,a6",
        "  OS9     F$Icpt",
        "  bcs     icptfail",
        "  OS9     F$ID",
        "  move.l  d0,d6",
        "  clr.l   d0",
        "  move.w  d6,d0",
        "  clr.l   d1",
        "  move.w  #7,d1",            // sig=7, ordinary interceptable
        "  OS9     F$Send",
        "  bcs     sendfail",
        "  lea     survivedmsg(pc),a0",
        "  moveq   #survivedmsgl,d1",
        "  moveq   #1,d0",
        "  OS9     I$WritLn",
        "  bra     done",
        "icptfail:",
        "  lea     icptfailmsg(pc),a0",
        "  moveq   #icptfailmsgl,d1",
        "  moveq   #1,d0",
        "  OS9     I$WritLn",
        "  bra     done",
        "sendfail:",
        "  lea     sendfailmsg(pc),a0",
        "  moveq   #sendfailmsgl,d1",
        "  moveq   #1,d0",
        "  OS9     I$WritLn",
        "done:",
        "  moveq   #0,d1",
        "  OS9     F$Exit",
        "handler:",
        "  lea     handlermsg(pc),a0",
        "  moveq   #handlermsgl,d1",
        "  moveq   #1,d0",
        "  OS9     I$WritLn",
        "  OS9     F$RTE",
        "survivedmsg:  dc.b  \"SURVIVED\",$0D",
        "survivedmsgl  equ   *-survivedmsg",
        "icptfailmsg:  dc.b  \"F$ICPT FAILED\",$0D",
        "icptfailmsgl  equ   *-icptfailmsg",
        "sendfailmsg:  dc.b  \"F$SEND FAILED\",$0D",
        "sendfailmsgl  equ   *-sendfailmsg",
        "handlermsg:   dc.b  \"HANDLER RAN\",$0D",
        "handlermsgl   equ   *-handlermsg",
        "",
        "  ends",
        ""
    ].joined(separator: "\r")

    let asmPath = scratchDisk + "/icptsnd.a"
    try? icAsm.write(toFile: asmPath, atomically: true, encoding: .utf8)

    let name = "f$icpt: a self-directed F$Send while active runs the installed handler, process survives"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let out = os9([
            "load /dd/CMDS/r68 /dd/CMDS/l68",
            "r68 /h5/icptsnd.a -o=/h5/icptsnd.r",
            "l68 /h5/icptsnd.r -o=/h5/icptsnd",
            "/h5/icptsnd"
        ], timeout: 15)
        if out.contains("HANDLER RAN") && out.contains("SURVIVED") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            print("      [installed handler must run and the process must survive the signal]")
            let preview = out.split(separator: "\n")
                .filter { !$0.hasPrefix("#") && $0 != "$" && !$0.isEmpty }
                .prefix(8).joined(separator: " | ")
            print("      output: \(preview)")
            failed += 1
        }
    }

    for leftover in ["icptsnd.a", "icptsnd.r", "icptsnd"] {
        try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
    }
}

// ── F$Send: PID 0 broadcasts to the sender's own forked children, sender
// survives ──────────────────────────────────────────────────────────────────
// Same stale-claim shape as the F$Icpt retraction above. ROADMAP.md and the
// os9-dev skill's syscall reference both carried "F$Send doesn't implement
// PID-0 broadcast" -- based on OS9_F_Send's own comment ("0 is NOT all
// here!") and a 2026-07-20 test that only ever checked F$Send(pid=0,...)
// returned success, never whether anyone else actually received it. Reading
// send_signal() (procstuff.c) shows a complete broadcast loop already exists,
// gated only on the SENDER's own pid not being 0:
//   if (currentpid!=0 && spid==0) { for k in 1..<MAXPROCESSES:
//       if same group && same user && k!=currentpid: send_signal(k,signal) }
// Confirmed live: a process forks two children (which just sleep forever),
// sends signal 0 (Kill) to pid 0, then confirms both children are gone (a
// harmless post-kill signal to each now errors) and that it -- the sender --
// is still alive (a self-directed signal still succeeds, and it reaches the
// PASS line at all). Verified non-vacuous: forcing procstuff.c's broadcast
// condition false in a scratch build (never ./os9exec) makes the run hang
// (the forked children never die, so the harness's shutdown wedges on them)
// -- same failure shape the harness already treats as red via its
// `out != "(timeout)"` guard elsewhere in this file. No production code
// changed this session.
do {
    let kslpAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "",
        "F$Exit   equ  $06",
        "F$Sleep  equ  $0A",
        "",
        "  psect kslp,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,400,start",
        "",
        "start:",
        "  clr.l   d0",
        "  OS9     F$Sleep",
        "  moveq   #99,d1",
        "  OS9     F$Exit",
        "",
        "  ends",
        ""
    ].joined(separator: "\r")

    let kslpPath = scratchDisk + "/kslp.a"
    try? kslpAsm.write(toFile: kslpPath, atomically: true, encoding: .utf8)

    let k0Asm = [
        "  use /dd/DEFS/oskdefs.d",
        "",
        "F$Exit   equ  $06",
        "F$Fork   equ  $03",
        "F$Send   equ  $08",
        "F$ID     equ  $0C",
        "I$WritLn equ  $8C",
        "",
        "  psect kill0test,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,800,start",
        "",
        "start:",
        "  lea     childname(pc),a0",
        "  clr.l   d0",
        "  clr.l   d1",
        "  clr.l   d2",
        "  clr.l   d3",
        "  moveq   #128,d4",
        "  movea.l a0,a1",
        "  OS9     F$Fork",
        "  bcs     forkAfail",
        "  move.l  d0,d6",
        "  lea     childname(pc),a0",
        "  clr.l   d0",
        "  clr.l   d1",
        "  clr.l   d2",
        "  clr.l   d3",
        "  moveq   #128,d4",
        "  movea.l a0,a1",
        "  OS9     F$Fork",
        "  bcs     forkBfail",
        "  move.l  d0,d7",
        "  clr.l   d0",
        "  clr.l   d1",
        "  OS9     F$Send",
        "  bcs     killfail",
        "  OS9     F$ID",
        "  move.l  d0,d5",
        "  clr.l   d0",
        "  move.w  d5,d0",
        "  clr.l   d1",
        "  moveq   #1,d1",
        "  OS9     F$Send",
        "  bcs     selfsendfail",
        "  clr.l   d0",
        "  move.w  d6,d0",
        "  clr.l   d1",
        "  moveq   #1,d1",
        "  OS9     F$Send",
        "  bcc     achildalive",
        "  clr.l   d0",
        "  move.w  d7,d0",
        "  clr.l   d1",
        "  moveq   #1,d1",
        "  OS9     F$Send",
        "  bcc     bchildalive",
        "  lea     passmsg(pc),a0",
        "  moveq   #passmsgl,d1",
        "  moveq   #1,d0",
        "  OS9     I$WritLn",
        "  bra     done",
        "forkAfail:",
        "  lea     forkAfailmsg(pc),a0",
        "  moveq   #forkAfailmsgl,d1",
        "  moveq   #1,d0",
        "  OS9     I$WritLn",
        "  bra     done",
        "forkBfail:",
        "  lea     forkBfailmsg(pc),a0",
        "  moveq   #forkBfailmsgl,d1",
        "  moveq   #1,d0",
        "  OS9     I$WritLn",
        "  bra     done",
        "killfail:",
        "  lea     killfailmsg(pc),a0",
        "  moveq   #killfailmsgl,d1",
        "  moveq   #1,d0",
        "  OS9     I$WritLn",
        "  bra     done",
        "selfsendfail:",
        "  lea     selfsendfailmsg(pc),a0",
        "  moveq   #selfsendfailmsgl,d1",
        "  moveq   #1,d0",
        "  OS9     I$WritLn",
        "  bra     done",
        "achildalive:",
        "  lea     achildalivemsg(pc),a0",
        "  moveq   #achildalivemsgl,d1",
        "  moveq   #1,d0",
        "  OS9     I$WritLn",
        "  bra     done",
        "bchildalive:",
        "  lea     bchildalivemsg(pc),a0",
        "  moveq   #bchildalivemsgl,d1",
        "  moveq   #1,d0",
        "  OS9     I$WritLn",
        "done:",
        "  moveq   #0,d1",
        "  OS9     F$Exit",
        "childname:       dc.b  \"/h5/kslp\",0",
        "passmsg:         dc.b  \"PASS BROADCAST\",$0D",
        "passmsgl         equ   *-passmsg",
        "forkAfailmsg:    dc.b  \"FORK A FAILED\",$0D",
        "forkAfailmsgl    equ   *-forkAfailmsg",
        "forkBfailmsg:    dc.b  \"FORK B FAILED\",$0D",
        "forkBfailmsgl    equ   *-forkBfailmsg",
        "killfailmsg:     dc.b  \"F$SEND KILL0 FAILED\",$0D",
        "killfailmsgl     equ   *-killfailmsg",
        "selfsendfailmsg: dc.b  \"SENDER DID NOT SURVIVE\",$0D",
        "selfsendfailmsgl equ   *-selfsendfailmsg",
        "achildalivemsg:  dc.b  \"CHILD A STILL ALIVE\",$0D",
        "achildalivemsgl  equ   *-achildalivemsg",
        "bchildalivemsg:  dc.b  \"CHILD B STILL ALIVE\",$0D",
        "bchildalivemsgl  equ   *-bchildalivemsg",
        "",
        "  ends",
        ""
    ].joined(separator: "\r")

    let k0Path = scratchDisk + "/kill0.a"
    try? k0Asm.write(toFile: k0Path, atomically: true, encoding: .utf8)

    let name = "f$send: PID 0 broadcasts to the sender's own children, sender survives"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let out = os9([
            "load /dd/CMDS/r68 /dd/CMDS/l68",
            "r68 /h5/kslp.a -o=/h5/kslp.r",
            "l68 /h5/kslp.r -o=/h5/kslp",
            "r68 /h5/kill0.a -o=/h5/kill0.r",
            "l68 /h5/kill0.r -o=/h5/kill0",
            "/h5/kill0"
        ], timeout: 15)
        if out.contains("PASS BROADCAST") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            print("      [F$Send(pid=0,...) must kill every other process sharing the sender's user/group, but not the sender]")
            let preview = out.split(separator: "\n")
                .filter { !$0.hasPrefix("#") && $0 != "$" && !$0.isEmpty }
                .prefix(8).joined(separator: " | ")
            print("      output: \(preview)")
            failed += 1
        }
    }

    for leftover in ["kslp.a", "kslp.r", "kslp", "kill0.a", "kill0.r", "kill0"] {
        try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
    }
}

// ── F$CpyMem: a user process may write memory it owns, not memory it doesn't ────
// OS-9 lets a user-state F$CpyMem READ any address but only WRITE where the
// caller has permission (F$ChkMem). os9exec used to skip that check entirely, so
// any process could clobber any arena address. The check now allows the caller's
// own data/blocks AND any loaded RAM module (shared data modules must stay
// writable -- owner's call), and refuses a foreign system address. Both halves
// are asserted: dropping either token is a regression -- and the pre-fix binary
// dropped the "FOREIGN BLOCKED" token (the copy was allowed), so this fails red
// against it.
do {
    let cmAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "",
        "F$Exit   equ  $06",
        "F$CpyMem equ  $1B",
        "F$ID     equ  $0C",
        "I$WritLn equ  $8C",
        "",
        "  psect cpytst,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,512,start",
        "",
        "start:",
        "  OS9     F$ID",              // d0.w = own PID (F$CpyMem's cosmetic owner arg)
        "  move.w  d0,d2",
        "* stage 1: copy into the module's own buffer (dst is PC-relative) -- allowed",
        "  lea     src(pc),a0",
        "  lea     dst(pc),a1",
        "  moveq   #8,d1",
        "  move.w  d2,d0",
        "  OS9     F$CpyMem",
        "  bcs     s2",                // errored: skip the OK token
        "  lea     mown(pc),a0",
        "  moveq   #mownl,d1",
        "  moveq   #1,d0",
        "  OS9     I$WritLn",
        "s2:",
        "* stage 2: copy into a foreign in-arena address ($1000) -- must be refused",
        "  lea     src(pc),a0",
        "  move.l  #$1000,a1",
        "  moveq   #8,d1",
        "  move.w  d2,d0",
        "  OS9     F$CpyMem",
        "  bcc     done",             // carry clear = write allowed = gate failed
        "  lea     mfor(pc),a0",
        "  moveq   #mforl,d1",
        "  moveq   #1,d0",
        "  OS9     I$WritLn",
        "done:",
        "  moveq   #0,d1",
        "  OS9     F$Exit",
        "mown:  dc.b  \"CPYMEM OWN OK\",$0D",
        "mownl  equ   *-mown",
        "mfor:  dc.b  \"CPYMEM FOREIGN BLOCKED\",$0D",
        "mforl  equ   *-mfor",
        "src:   dc.b  \"ABCDEFGH\"",
        "dst:   dc.b  0,0,0,0,0,0,0,0",
        "",
        "  ends",
        ""
    ].joined(separator: "\r")

    let asmPath = scratchDisk + "/cpytst.a"
    try? cmAsm.write(toFile: asmPath, atomically: true, encoding: .utf8)

    let name = "f$cpymem: writes its own memory, refuses a foreign address"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let out = os9([
            "load /dd/CMDS/r68 /dd/CMDS/l68",
            "r68 /h5/cpytst.a -o=/h5/cpytst.r",
            "l68 /h5/cpytst.r -o=/h5/cpytst",
            "/h5/cpytst"
        ], timeout: 20)
        if out.contains("CPYMEM OWN OK") && out.contains("CPYMEM FOREIGN BLOCKED") {
            print("PASS: \(name)")
            passed += 1
        } else {
            print("FAIL: \(name)")
            print("      [own-memory write must succeed AND a foreign-address write must be refused]")
            let preview = out.split(separator: "\n")
                .filter { !$0.hasPrefix("#") && $0 != "$" && !$0.isEmpty }
                .prefix(8).joined(separator: " | ")
            print("      output: \(preview)")
            failed += 1
        }
    }

    for leftover in ["cpytst.a", "cpytst.r", "cpytst"] {
        try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
    }
}

// ── F$Load error reporting: a damaged module must say HOW it is damaged ──────
// A load is asked about a file NAME, so "this isn't a module" and "this module
// is broken" used to collapse into one answer, E_FNA (214). Once the MODSYNC
// word matches, the file IS a module and the specific check that failed is
// known -- and 214 sends the reader to the file's attributes and owner for a
// fault that has nothing to do with either. The v2.4 TRM gives E$BMCRC/E$BMHP
// for F$VModul, which performs exactly this check, and says F$Load errors on
// "a module with a bad parity or CRC".
//
// Fixtures are built here from a real module so the corruption is the ONLY
// difference: one flipped bit in the body (CRC alone) and one in the header
// (parity). The unmodified copy is the control -- without it a "wrong error
// code" test would pass just as well on a module that never loads at all, and
// it is also what keeps this honest in a container, where a macOS bind mount
// can ignore the execute bit the fixtures are given (project memory
// docker-macos-bindmount-ignores-permissions): if that ever bites, every case
// collapses to E_FNA and the control fails first. Measured, not assumed --
// `make test-linux` runs all four green.
if let goodModule = FileManager.default.contents(atPath: diskPath + "/CMDS/list") {
    func plant(_ name: String, _ bytes: [UInt8]) {
        let path = scratchDisk + "/" + name
        // host-native devices carry the real execute bit, and load opens with
        // read+exec (mode 0x05) -- without 0o755 every case below fails E_FNA
        // for want of permission and the whole block passes for the wrong reason
        FileManager.default.createFile(atPath: path, contents: Data(bytes),
                                       attributes: [.posixPermissions: 0o755])
    }
    var body   = [UInt8](goodModule)
    var header = [UInt8](goodModule)
    body[200]  ^= 0x01   // past the 24-byte header: breaks the CRC only
    header[10] ^= 0x01   // inside the header: breaks header parity
    plant("m_good",   [UInt8](goodModule))
    plant("m_badcrc", body)
    plant("m_badpar", header)
    plant("m_notmod", [UInt8]("this is plainly not a module\r".utf8))

    run("modload: an untouched module still loads (control)",
        expectation: "the fixtures differ from this ONLY by the corrupted bit",
        commands: ["load \(scratch)/m_good"]) { !$0.contains("Error #") }

    check("modload: a bad module CRC reports E_BMCRC, not E_FNA",
        contains: "E_BMCRC", "load \(scratch)/m_badcrc")

    check("modload: bad module header parity reports E_BMHP, not E_FNA",
        contains: "E_BMHP", "load \(scratch)/m_badpar")

    // The other half of the same rule: a file that was never a module keeps the
    // old answer. On this emulator a host directory routinely holds .c/.bas/.txt
    // beside real modules, and reporting a CRC error for those would be worse
    // than uninformative -- E_FNA is the honest "you cannot execute this".
    check("modload: a file that is not a module at all still reports E_FNA",
        contains: "E_FNA", "load \(scratch)/m_notmod")

    for leftover in ["m_good", "m_badcrc", "m_badpar", "m_notmod"] {
        try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
    }
}

// ── F$ID packs group in the HIGH word, not the high byte ─────────────────────
// The TRM: d1.l is the "current process group/user number ... all word values",
// and F$SUser, prepFork, the module header's M$Owner and `ident` all use that
// 16/16 form. F$ID alone used the 6809-ish group<<8|user, so F$ID -> F$SUser
// did not round-trip and anything storing the result structurally got garbage.
//
// Asserted through the damage it actually did rather than by reading a register:
// `l68` stamps M$Owner from F$ID, so a module linked by claude (1.7) came out
// owned by "0.259" ($0103 pushed into the user half). `ident` is Microware's own
// decoder, which makes it a fair judge here. It must ALSO be a non-0.0 user --
// as 0.0 both packings give 0 and the test would be vacuous, which is exactly
// why the existing corpus never caught this.
if !containerized {
    let idSrc = ["Prgrm set 1", "Objct set 1", "ReEnt set $80",
                 " psect idtst,(Prgrm<<8)+Objct,(ReEnt<<8)+1,0,200,start",
                 "start", " moveq #0,d1", " trap #0", " dc.w $06", " ends"]
        .joined(separator: "\r") + "\r"          // OS-9 lines end in CR
    try? idSrc.write(toFile: scratchDisk + "/idtst.a", atomically: true, encoding: .utf8)

    run("f$id: a module linked by claude is stamped 1.7, not 0.259",
        expectation: "ident reports the builder's real group.user in M$Owner",
        commands: ["login claude", "chx /dd/CMDS",
                   "r68 \(scratch)/idtst.a -o=\(scratch)/idtst.r",
                   "l68 \(scratch)/idtst.r -o=\(scratch)/idtst",
                   "ident \(scratch)/idtst", "logout"]) {
            $0.contains("Owner:") && $0.contains("1.7") && !$0.contains("0.259")
        }

    for leftover in ["idtst.a", "idtst.r", "idtst"] {
        try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
    }
}

// ── F$SUser enforces the TRM's three cases ───────────────────────────────────
// v2.4 TRM, F$SUser: "User number 0.0 may change their ID to anything without
// restriction. A primary module owned by user 0.0 may change its ID to anything
// without restriction. Any primary module may change its user ID to match the
// module's owner. All other attempts ... return an E$Permit error."
//
// Until this was enforced, F$SUser assigned from d1 and returned 0, so any
// guest program could become 0.0 at will -- and since is_super() (group 0) is
// the codebase's only privilege test, that bypassed the entire permission model
// from inside. Demonstrated live before the fix; see the roadmap entry it closed.
//
// Both cases below run as claude (1.7) executing a module claude linked, so
// `l68` stamps M$Owner 1.7 -- the SAME program and the SAME user, differing
// only in the identity requested. That is what makes the pair meaningful: one
// asserts the gate refuses, the other that it does not simply refuse everything.
// Running as 0.0 would make both vacuous via rule 1, the same trap that let the
// original bug sit undetected.
if !containerized {
    func suserSrc(_ wanted: String) -> String {
        ["Prgrm set 1", "Objct set 1", "ReEnt set $80",
         " psect sutst,(Prgrm<<8)+Objct,(ReEnt<<8)+1,0,200,start",
         "start",
         " move.l #\(wanted),d1",
         " trap #0", " dc.w $1C",          // F$SUser
         " bcs.s denied",
         " lea okmsg(pc),a0", " move.l #oklen,d1", " bra.s emit",
         "denied",
         " lea nomsg(pc),a0", " move.l #nolen,d1",
         "emit",
         " move.w #1,d0", " trap #0", " dc.w $8A",   // I$Write to stdout
         " moveq #0,d1", " trap #0", " dc.w $06",    // F$Exit
         "okmsg dc.b \"SUSER-ALLOWED\",13,10", "oklen equ *-okmsg",
         "nomsg dc.b \"SUSER-DENIED\",13,10", "nolen equ *-nomsg",
         " ends"].joined(separator: "\r") + "\r"     // OS-9 lines end in CR
    }

    func buildAndRun(_ tag: String, _ wanted: String) -> [String] {
        try? suserSrc(wanted).write(toFile: scratchDisk + "/\(tag).a",
                                    atomically: true, encoding: .utf8)
        return ["login claude", "chx /dd/CMDS",
                "r68 \(scratch)/\(tag).a -o=\(scratch)/\(tag).r",
                "l68 \(scratch)/\(tag).r -o=\(scratch)/\(tag)",
                "\(scratch)/\(tag)", "logout"]
    }

    // Rule 1 fails (1.7 is not 0.0), rule 2 fails (module owner is 1.7, not
    // 0.0), rule 3 fails (0.0 != the module's 1.7 owner) -> E$Permit.
    run("f$suser: an ordinary user cannot become 0.0 just by asking",
        expectation: "E$Permit -- none of the TRM's three cases apply",
        commands: buildAndRun("sudeny", "$00000000")) {
            $0.contains("SUSER-DENIED") && !$0.contains("SUSER-ALLOWED")
        }

    // Rule 3: the requested ID equals the primary module's own M$Owner (1.7).
    run("f$suser: a primary module may take on its own module's owner",
        expectation: "allowed -- TRM case 3, the ID matches M$Owner",
        commands: buildAndRun("suallow", "$00010007")) {
            $0.contains("SUSER-ALLOWED") && !$0.contains("SUSER-DENIED")
        }

    // Rule 2 is what keeps `login` working from an already-logged-in ordinary
    // user: login's own module is owned by 0.0, so it may set any identity.
    // Nothing else in the suite covers this -- a plain `login` from the stock
    // top-level shell is already 0.0 and so passes under rule 1 instead.
    run("f$suser: login still works from a non-0.0 shell (module owned by 0.0)",
        expectation: "nested login succeeds; rule 2 applies to login itself",
        commands: ["login claude", "login dog", "logout", "logout"]) {
            $0.contains("dog: ")
        }

    for leftover in ["sudeny.a", "sudeny.r", "sudeny",
                     "suallow.a", "suallow.r", "suallow"] {
        try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
    }
}

// ── RBF EOF lock: a WRITE-only producer holds the end of the file ────────────
// v2.4 Technical Manual, ch.7 "End of File Lock": an EOF lock occurs when the
// user reads or writes data at the end of file, is kept "until a read or write
// is performed that is not at the end of the file", and "is the only time that
// a write call automatically causes lock out of any part of the file". The
// manual's own example is a spooler listing a file the assembler is still
// writing -- and an assembler redirecting output opened that file for
// SEQUENTIAL OUTPUT, not for update. So the lock cannot be gated on update
// mode, which is what os9exec used to do (it asked "is any update-mode path
// open for writing?" instead of "does anyone hold the end?").
//
// The shell's `>` is a write-only open, so this is the manual's example almost
// literally: a producer writes one line, waits, writes a second, closes; a
// read-only `list` starts in between. Passing means the reader waited at the
// edge rather than calling the gap end-of-file. Deliberately on a `mount -k`
// RBF image -- this lock lives in file_rbf.c and a host directory never
// reaches it.
if !containerized {
    let prod = ["echo EOFLK-one", "sleep 4", "echo EOFLK-two"]
        .joined(separator: "\r") + "\r"          // OS-9 lines end in CR
    try? prod.write(toFile: scratchDisk + "/prod", atomically: true, encoding: .utf8)

    run("rbf eof lock: a read-only reader follows a write-only producer",
        expectation: "list waits at end of file and returns both lines",
        commands: ["mount -k=360k h7",
                   "shell <\(scratch)/prod >/h7/spool &",
                   "sleep 1",
                   "list /h7/spool",
                   "sleep 3"],
        timeout: 60) {
            $0.contains("EOFLK-one") && $0.contains("EOFLK-two")
        }

    try? FileManager.default.removeItem(atPath: scratchDisk + "/prod")
}

// -- host-backed terminals -------------------------------------------------
// Every block below that calls makePTY() is skipped under DOCKER_IMAGE /
// CONTAINER_IMAGE, the same way several earlier blocks opt out. The reason is
// not shyness about containers: makePTY() calls openpty() on the HOST, so the
// name it hands to OS9T1 is a host device -- and the emulator is on the other
// side of a kernel boundary. `make test-linux` said so in the emulator's own
// words before these guards existed:
//
//     # OS9T1: cannot open '/dev/ttys012'
//
// A macOS pty name, offered to a Linux kernel. Ten tests failed that way on
// every Linux run, which is worse than not running them: a permanently red
// leg is one nobody reads. Tests that make the EMULATOR allocate the pty
// (OS9T1=pty) are NOT skipped -- those work in a container and are left to
// run, which is how the Linux leg still covers this feature at all.
// An unconfigured /tN is not a device. It used to silently alias the main
// console, so `echo` to it appeared to work while interleaving its bytes into
// the shell's own prompt -- and `tsmon /t1` failed with a misleading E_NOTRDY
// much later instead of an honest "no such unit" at open time.
check("hostterm: unconfigured /t1 is E_UNIT",
      contains: "Error #000:240 (E_UNIT)",
      "echo hello >/t1")

// The plan's own Step 1 test for this task ("checkEnv contains: 'opened'"
// against a real pty slave) turned out unable to fail either as written or
// with the redirect it was missing -- investigated live, not assumed:
//   1. Task 1's gate in pCopen only checks hostterm_configured (is OS9T1
//      SET?), never hostterm_open. With OS9T1 pointed at a real pty slave,
//      that gate already lets the open through today, straight to the
//      pre-existing /t1 fallback path -- so "does /t1 open without error"
//      already passes BEFORE this task's code exists, for any *configured*
//      OS9T1, valid or not. hostterm_open is not reachable from pCopen
//      until this task's Step 4 wires the call in.
//   2. Separately, the OS-9 shell echoes every input line onto its own
//      console before executing it (confirmed live: an unknown command's
//      literal text appears verbatim in the captured output even though it
//      never ran), so a "contains" check whose pattern is a substring of
//      the command text itself -- "opened" in "echo opened" -- is satisfied
//      by the echoed input alone and can never fail regardless of what /t1
//      does.
// The one behaviour this task actually introduces that a pre-Task-4 gate
// cannot already produce is REFUSAL of a host path that does not work --
// hostterm_open is the first code that ever tries the host open() and can
// say no. A nonexistent path is that discriminating case: today it
// "succeeds" (any configured value passes the old gate); after this task
// hostterm_open's open() genuinely fails and pCopen reports E_DEVBSY.
//
// The successful-open case (a real pty slave) is intentionally not
// duplicated here as an automated check: with output/input not wired until
// Tasks 3/4, nothing observes hostterm_open's success yet, so any such
// check is provably unable to fail at this task's boundary -- confirmed by
// testing it directly against the untouched stub. Task 3's own test already
// asserts a genuine byte-level success signal (output reaching the pty
// master), so that is where a real positive check belongs.
checkEnv("hostterm: /t1 refuses a host path that does not exist",
         contains: "Error #000:216 (E_PNNF)",
         env: ["OS9T1": "/hostterm-definitely-does-not-exist"],
         "echo x >/t1")

// Creates a pty pair. Returns (masterFD, slaveFD, slaveDeviceName). The TEST
// owns both ends, so it can drive /tN from outside the emulator with no
// parsing of emulator output. A pty slave is an ordinary tty device, so this
// exercises exactly the code path a real /dev/cu.usbserial-* will take.
//
// <slave> is deliberately returned OPEN, not closed here, and must stay open
// (close it only once the caller is done reading). Confirmed live, isolated
// from hostterm entirely with a bare pty and no os9exec involved: on macOS,
// once the LAST open reference to a pty's SLAVE closes, any output not yet
// read by the master is discarded -- even a reader already BLOCKED in read()
// before the write+close is woken with zero bytes, not the data. This is
// deterministic, not a scheduling race a fast enough reader could win. The
// emulator opens the slave BY NAME for the lifetime of one redirected
// command (e.g. `echo x >/t1` opens, writes and closes the path within that
// one command) and then closes ITS OWN reference -- if the test had already
// closed its own copy (as a first version of this helper did), that emulator
// close would be the LAST reference, and the discard would fire before the
// test ever got to read(). Holding a second reference open here keeps the
// refcount above zero for the whole test, so the emulator's own open/close
// cycle never triggers the discard -- exactly how a real attached `screen`
// session (which never closes its end) already avoids this in practice.
// Deliberately does NOT put the pty into raw mode itself. A pty's termios
// state is one struct shared by both ends -- tcsetattr on the master and on
// the slave act on the SAME state -- so if this helper called cfmakeraw()
// here too, that call would already have put the pty in raw mode before the
// emulator's own hostterm_raw() (which runs on the slave, later) ever got a
// chance to matter, and the 8-bit-transparency check below could never fail
// no matter what hostterm_raw() does. Confirmed live: with hostterm_raw()'s
// own flag-clearing temporarily disabled, the check still passed as long as
// this function set raw mode too. Leaving the pty in its default (cooked)
// state here makes hostterm_raw() the ONLY thing that can put it in raw
// mode, so the check actually exercises it.
func makePTY() -> (master: Int32, slave: Int32, name: String)? {
    var master: Int32 = 0
    var slaveFD: Int32 = 0
    guard openpty(&master, &slaveFD, nil, nil, nil) == 0 else {
        // Every caller skips its whole test on nil and prints nothing, so a
        // test that never ran would vanish from the count: say so, and count it.
        print("FAIL: a pseudo-terminal could not be opened (errno \(errno)); the test asking for it did not run")
        failed += 1
        return nil
    }
    let name = String(cString: ttyname(slaveFD))
    _ = fcntl(master, F_SETFL, fcntl(master, F_GETFL, 0) | O_NONBLOCK)
    return (master, slaveFD, name)
}

// Reads everything currently available on <fd> without blocking.
func drainNonBlocking(_ fd: Int32) -> [UInt8] {
    var out = [UInt8]()
    var buf = [UInt8](repeating: 0, count: 4096)
    while true {
        let n = read(fd, &buf, buf.count)
        if n <= 0 { break }
        out.append(contentsOf: buf[0..<n])
    }
    return out
}

// Output path: bytes OS-9 writes to /t1 must reach the host endpoint, not the
// emulator's own stdout. Names checked against `filter` by hand -- this block
// doesn't go through run()/check(), so it has to opt itself out the same way
// they do, rather than paying for an emulator run on every unrelated filter.
let hostOutputName  = "hostterm: output reaches the host endpoint"
let hostRawModeName = "hostterm: raw mode passes control bytes through unmangled"
let runHostOutput   = filter.isEmpty || hostOutputName.localizedCaseInsensitiveContains(filter)
let runHostRawMode  = filter.isEmpty || hostRawModeName.localizedCaseInsensitiveContains(filter)

if (runHostOutput || runHostRawMode) && !containerized {
    if let (master, slave, slaveName) = makePTY() {
        _ = os9(["echo host-terminal-works >/t1"], env: ["OS9T1": slaveName])
        usleep(200_000)
        let text = String(decoding: drainNonBlocking(master), as: UTF8.self)

        if runHostOutput {
            if text.contains("host-terminal-works") {
                print("PASS: \(hostOutputName)"); passed += 1
            } else {
                print("FAIL: \(hostOutputName)")
                print("      [pty master should have received the echoed text]")
                print("      got: \(text.debugDescription.prefix(200))")
                failed += 1
            }
        }

        // 0x11/0x13 are XON/XOFF, 0x7f is DEL, and 0x0a is a bare LF with no
        // preceding CR of its own. This is the assertion that would catch a
        // missing raw-mode setup in hostterm_raw -- but XON/XOFF/DEL turned
        // out NOT to discriminate for this OUTPUT direction: a pty isn't
        // real hardware, so the input-side flags (IXON, ISTRIP, ICANON) that
        // would eat/rewrite them on a real serial line are simply irrelevant
        // to bytes a process WRITES to its slave -- confirmed live, this
        // check still passed with hostterm_raw()'s own flag-clearing
        // disabled. The one OUTPUT-direction flag in the raw-mode recipe is
        // OPOST (c_oflag), which on a cooked pty rewrites a bare LF to CRLF
        // -- also confirmed live, isolated from hostterm, against a bare
        // pty with no termios changes on either end. So the bare LF is what
        // actually exercises hostterm_raw() here; the check asserts the
        // whole 4-byte sequence arrives EXACTLY as sent (contiguous, in
        // order), which a spurious inserted CR would break.
        //
        // NOT sent as literal bytes in the command text (as first tried):
        // that hung the whole run. KeyToBuffer() (utilstuff.c) applies
        // PD_XON/PD_XOFF flow control to the MAIN console's own command-line
        // input -- typing OS9T1's XOFF (0x13, the same default this device
        // also uses) sets mco->holdScreen and the console's input pump stops
        // consuming stdin entirely, with no later XON in the stream to clear
        // it. That is a property of console 0 reading its own command line,
        // unrelated to hostterm -- confirmed by reproducing the same hang
        // against a plain shell with no /t1 involved at all. Routing the
        // bytes through a file and `tee` avoids the console's keystroke path
        // completely: `tee` reads them with F$Read, not KeyToBuffer.
        let rawPath = scratchDisk + "/hostbin"
        let expectedRaw: [UInt8] = [0x11, 0x13, 0x0a, 0x7f]
        try? Data(expectedRaw).write(to: URL(fileURLWithPath: rawPath))

        _ = os9(["tee /t1 <\(scratch)/hostbin"], env: ["OS9T1": slaveName])
        usleep(200_000)
        let bytes = drainNonBlocking(master)
        try? FileManager.default.removeItem(atPath: rawPath)
        close(master)
        close(slave)

        if runHostRawMode {
            if Data(bytes).range(of: Data(expectedRaw)) != nil {
                print("PASS: \(hostRawModeName)"); passed += 1
            } else {
                print("FAIL: \(hostRawModeName)")
                print("      [XON/XOFF/LF/DEL should survive a raw-mode round trip intact]")
                print("      got: \(bytes.map { String(format: "%02x", $0) }.joined(separator: " "))")
                failed += 1
            }
        }
    } else {
        print("FAIL: hostterm: could not create a pty pair")
        failed += 1
    }
}

// Input path: bytes written into the host end of a /tN pty must reach OS-9
// reads on that device.
let hostInputName = "hostterm: input arrives from the host endpoint"
let runHostInput   = filter.isEmpty || hostInputName.localizedCaseInsensitiveContains(filter)

if runHostInput && !containerized {
    if let (master, slave, slaveName) = makePTY() {
        // Feed a whole COMMAND LINE into the pty before the emulator reads, so
        // the bytes are already waiting -- no race with the guest's scheduler.
        //
        // `shell </t1` makes an OS-9 shell take its input from the host
        // endpoint. Whatever we write is read, echoed and executed by that
        // shell, and its output goes to the console, which the harness
        // captures. So the assertion string is one only a byte that travelled
        // host -> pty -> OS-9 can produce: it appears NOWHERE in the command
        // text we send on stdin, which is the trap that made the original
        // Task 2 test vacuous (see Global Constraints).
        //
        // Trailing ESC is deliberate and load-bearing. 0x1B is PD_EOF's
        // default in the console option table (init_consoleopts, utilstuff.c),
        // so it makes the inner shell's read return E_EOF and the shell exit
        // cleanly. Without it that shell reads a pty that never reaches EOF
        // and the test can only end by timing out.
        //
        // makePTY() deliberately leaves the pty in COOKED mode (see its own
        // comment) so Task 3's raw-mode check can prove hostterm_raw() is
        // what flips it -- but that makes writing test input to master BEFORE
        // the emulator ever opens the slave actively wrong here: a pty's
        // termios is one struct shared by both ends, and while it is still
        // cooked the HOST KERNEL's own line discipline processes our write
        // immediately (ICRNL rewrites our CR to LF, ECHOCTL renders the ESC
        // as the two visible characters "^["), before hostterm_raw() ever
        // gets a chance to run on the OS-9 side -- so OS-9 ends up reading
        // already-corrupted bytes no matter what hostterm.c does. Confirmed
        // live: without this, the shell reads a line that never matches its
        // CR terminator (mangled to LF), runs on into the still-intact ESC,
        // and aborts with E_EOF before ever executing anything. Task 3
        // already proves hostterm_raw() itself works (raw mode governs
        // OUTPUT too, same shared termios), so setting raw mode here first
        // does not weaken this test's own job, which is the input plumbing.
        var raw = termios()
        tcgetattr(master, &raw)
        cfmakeraw(&raw)
        tcsetattr(master, TCSANOW, &raw)

        let line = "echo GOT-IT-FROM-HOST\r\u{1B}\r"
        _ = line.withCString { write(master, $0, strlen($0)) }

        let out = os9(["shell </t1"], timeout: 30, env: ["OS9T1": slaveName])
        close(master)
        close(slave)

        if out.contains("GOT-IT-FROM-HOST") {
            print("PASS: \(hostInputName)"); passed += 1
        } else {
            print("FAIL: \(hostInputName)")
            print("      [a command written into the pty should have run inside OS-9]")
            print("      got: \(out.suffix(200).debugDescription)")
            failed += 1
        }
    } else {
        print("FAIL: hostterm: could not create a pty pair for input test")
        failed += 1
    }
}

// -- Backpressure: a full host endpoint must never lose bytes ---------------
// ConsPutc calls hostterm_put() and used to ignore its return value: on a
// full endpoint the write stalled up to ~100ms per byte and the byte was
// then quietly dropped (consio.c's old unpaced branch). The fix parks the
// writing process in pWaitWrite -- mirroring the paced FIFO branch three
// lines above it in ConsoleOut -- instead of discarding, and a pWaitWrite
// process is rescheduled periodically (procstuff.c) until the far end
// drains.
//
// Measured, not guessed (2026-07-29): the plan this test comes from assumed
// an ~8KB pty output queue. The real number on macOS is 1024 bytes (write()
// to the slave starts returning EAGAIN there with nothing draining the
// master) -- so `dir /dd/CMDS` is already comfortably over it: measured at
// 3226 bytes against a continuously-drained pty, no bigger producer needed.
//
// The master is deliberately left UNDRAINED for a full 2 seconds after the
// command starts -- long enough for the queue to genuinely fill, not
// simulated -- then drained continuously from a second thread for the rest
// of the run, so a correct (parking, not dropping) implementation has every
// chance to deliver every byte once room frees up. Measured against this
// exact scenario, three runs each: the pre-fix build lost a stable 15 bytes
// every time (3211/3226); the post-fix build recovered the full 3226 every
// time, including with the undrained window stretched to 5 seconds. The
// threshold below sits clear of both, on the fixed-build side.
// Small thread-safe box for the drain thread below: a plain `var` captured
// and mutated by a background Thread closure, then read from the main
// thread after joining, trips the Swift 6 sendable-closure checker even
// though the DispatchSemaphore join makes it safe. Locking inside a
// dedicated type says so explicitly instead of just silencing the warning.
final class BackpressureCollector: @unchecked Sendable {
    private let lock = NSLock()
    private var bytes: [UInt8] = []
    private var stopRequested  = false

    func append(_ chunk: ArraySlice<UInt8>) {
        lock.lock(); bytes.append(contentsOf: chunk); lock.unlock()
    }
    func requestStop() { lock.lock(); stopRequested = true; lock.unlock() }
    func shouldStop() -> Bool { lock.lock(); defer { lock.unlock() }; return stopRequested }
    func total() -> Int { lock.lock(); defer { lock.unlock() }; return bytes.count }
    func snapshot() -> [UInt8] { lock.lock(); defer { lock.unlock() }; return bytes }
}

// Drains <master> into <collector> until requestStop() is called, exactly
// like the dedicated thread inside the backpressure test above -- pulled out
// here because the destination-crossover test below needs two of them
// running concurrently.
func startDrainThread(_ master: Int32, _ collector: BackpressureCollector,
                       _ stopped: DispatchSemaphore) -> Thread {
    let thread = Thread {
        var buf = [UInt8](repeating: 0, count: 4096)
        while true {
            let shouldStop = collector.shouldStop()
            let n = read(master, &buf, buf.count)
            if n > 0 {
                collector.append(buf[0..<n])
            } else if shouldStop {
                break
            } else {
                usleep(20_000)
            }
        }
        stopped.signal()
    }
    thread.start()
    return thread
}

let hostBackpressureName = "hostterm: a full endpoint blocks the writer, losing nothing"
let runHostBackpressure   = filter.isEmpty || hostBackpressureName.localizedCaseInsensitiveContains(filter)

if runHostBackpressure && !containerized {
    if let (master, slave, slaveName) = makePTY() {
        let collector    = BackpressureCollector()
        let drainStopped = DispatchSemaphore(value: 0)

        // Runs concurrently with the os9() call below, on its own thread --
        // os9() blocks the calling thread until the command finishes (or
        // times out), so this is the only way to drain WHILE it runs rather
        // than only after, which the pty's tiny queue makes mandatory: the
        // full listing physically cannot fit in 1024 bytes of kernel buffer,
        // so nothing drained DURING the run could never observe more than
        // that no matter which side of this fix is under test.
        let drainThread = Thread {
            usleep(2_000_000) // deliberately undrained -- forces the queue to fill
            var buf = [UInt8](repeating: 0, count: 4096)
            while true {
                let shouldStop = collector.shouldStop()
                let n = read(master, &buf, buf.count)
                if n > 0 {
                    collector.append(buf[0..<n])
                } else if shouldStop {
                    break
                } else {
                    usleep(20_000)
                }
            }
            drainStopped.signal()
        }
        drainThread.start()

        // 90s budget: generous enough that this test can still observe (and
        // report) the OLD code's behaviour -- its retry-then-drop loop cost
        // up to ~100ms per byte once the queue was full -- without the run
        // itself timing out before the assertion below ever sees the loss.
        _ = os9(["dir /dd/CMDS >/t1"], timeout: 90, env: ["OS9T1": slaveName])

        collector.requestStop()
        drainStopped.wait() // the drain thread does its own final read before exiting
        close(master); close(slave)

        let total = collector.total()

        // 3220 sits clear of both measured outcomes above (3211 buggy / 3226
        // fixed) without pinning the exact byte count of a CMDS listing that
        // could grow as the SDK disk does.
        if total > 3220 {
            print("PASS: \(hostBackpressureName)"); passed += 1
        } else {
            print("FAIL: \(hostBackpressureName)")
            print("      [expected the full listing to survive; only \(total) bytes did]")
            failed += 1
        }
    } else {
        print("FAIL: hostterm: could not create a pty pair for the backpressure test")
        failed += 1
    }
}

// The same stalled reader with PACING ON, the configuration a user actually runs.
// The test above uses -r, which writes straight to the endpoint and parks on a
// full one; paced output instead queues in the baud FIFO and reaches /t1 from the
// scheduler's drain -- which popped each byte and handed it to hostterm_put
// without looking at the answer. "Would block" discarded it. Measured on the
// build before this test existed: exactly 1024 bytes arrived (one pty buffer) and
// the rest of the ~3.2KB listing was gone, every run, with nothing reporting it.
let hostPacedBackpressureName = "hostterm: a full endpoint blocks a PACED writer, losing nothing"
let runHostPacedBackpressure  = filter.isEmpty || hostPacedBackpressureName.localizedCaseInsensitiveContains(filter)

if runHostPacedBackpressure && !containerized {
    if let (controller, device, deviceName) = makePTY() {
        let collector    = BackpressureCollector()
        let drainStopped = DispatchSemaphore(value: 0)

        let drainThread = Thread {
            usleep(2_000_000) // deliberately undrained, exactly as above
            var buffer = [UInt8](repeating: 0, count: 4096)
            while true {
                let shouldStop = collector.shouldStop()
                let bytesRead  = read(controller, &buffer, buffer.count)
                if bytesRead > 0 {
                    collector.append(buffer[0..<bytesRead])
                } else if shouldStop {
                    break
                } else {
                    usleep(20_000)
                }
            }
            drainStopped.signal()
        }
        drainThread.start()

        _ = os9(["dir /dd/CMDS >/t1"], timeout: 90, paced: true, env: ["OS9T1": deviceName])

        collector.requestStop()
        drainStopped.wait()
        close(controller); close(device)

        let total = collector.total()
        if total > 3220 {
            print("PASS: \(hostPacedBackpressureName)"); passed += 1
        } else {
            print("FAIL: \(hostPacedBackpressureName)")
            print("      [expected the full listing to survive pacing; only \(total) bytes did]")
            failed += 1
        }
    } else {
        print("FAIL: hostterm: could not create a pty pair for the paced backpressure test")
        failed += 1
    }
}

// -- OS9Tn=pty: self-allocated pty, name discoverable via idevs -------------
// A named endpoint (OS9T1=/dev/ttysNNN) requires the pty to already exist,
// which is fine for a test that creates the pair itself, but useless for the
// interactive case this endpoint exists for: you cannot name a pty that has
// not been allocated yet. `pty` makes hostterm allocate one itself, and
// `idevs` reports which host device it landed on.
let hostPtyNameName  = "hostterm: idevs reports a bound /tN and its host endpoint"
let hostPtyCarryName = "hostterm: OS9T1=pty carries output off the console"
let runHostPtyName   = filter.isEmpty || hostPtyNameName.localizedCaseInsensitiveContains(filter)
let runHostPtyCarry  = filter.isEmpty || hostPtyCarryName.localizedCaseInsensitiveContains(filter)

if runHostPtyName || runHostPtyCarry {
    // NOTE: do NOT "strengthen" assertion 1 by stat()ing the reported path.
    // On macOS /dev/ttysNNN are STATIC device nodes that exist whether or not
    // anything allocated them, so a stat() check would pass unconditionally --
    // vacuous. Liveness is proved by assertion 2 and by interactive
    // verification (screen + tsmon), not by stat().
    //
    // `idevs` is a SECOND command, not an addition to the first: the redirect
    // in `dir /dd >/t1` is what assertion 2 measures, so it must stay exactly
    // as it is. idevs' own output goes to the console, which is where
    // assertion 1 reads it from.
    let ptyOut = os9(["dir /dd >/t1", "idevs"], env: ["OS9T1": "pty"])

    if runHostPtyName {
        // The emulator no longer announces the slave name at allocation (it
        // used to, on the guest's own stderr path, which put emulator
        // narration inside guest program output). `idevs` is now the only
        // source of the name, so this asserts on the LISTING ROW rather than
        // on stray output: "t1  hostterm  scf ... /dev/ttysNNN".
        //
        // Matching the row and the device together is what keeps this honest.
        // A bare search for "/dev/..." anywhere in the output would be far
        // weaker now that idevs prints a whole device table -- and it would
        // still pass if the t1 row reported no endpoint at all.
        //
        // Both spellings of a pty slave: /dev/ttysNNN (Darwin) and /dev/pts/N
        // (Linux). An earlier pattern required the letters "tty" and so could
        // only ever pass on macOS -- it failed every containerised run against
        // an emulator that was handling /dev/pts/0 perfectly well.
        let t1Row = ptyOut.replacingOccurrences(of: "\r", with: "\n")
                          .split(separator: "\n")
                          .first { $0.hasPrefix("t1 ") && $0.contains("hostterm") }
        let hasDev = t1Row?.range(of: "/dev/(pts/[0-9]+|[a-z]*tty[a-zA-Z0-9/]+)",
                                  options: .regularExpression) != nil

        if hasDev {
            print("PASS: \(hostPtyNameName)"); passed += 1
        } else {
            print("FAIL: \(hostPtyNameName)")
            print("      [expected an idevs row \"t1 hostterm scf ... /dev/ttysNNN\"]")
            print("      row: \(t1Row.map(String.init) ?? "none")")
            print("      got: \(ptyOut.debugDescription.prefix(200))")
            failed += 1
        }
    }

    // "DEFS" is a directory on the system disk, so it appears in a `dir /dd`
    // listing -- and it appears in NO command this harness sends (the setup
    // lines are `chx <sdkCmds>` and `load math cio`). The shell echoes every
    // command it runs, so a check on the command text alone could never fail
    // (see Global Constraints); DEFS only ever appears via the listing itself.
    // Before Task 5, `pty` is refused, the redirection never takes effect, and
    // the listing lands on the console -- so this assertion fails honestly.
    if runHostPtyCarry {
        if !ptyOut.contains("DEFS") {
            print("PASS: \(hostPtyCarryName)"); passed += 1
        } else {
            print("FAIL: \(hostPtyCarryName)")
            print("      [listing reached the console, so /t1 was not the pty]")
            failed += 1
        }
    }
}

// The endpoint alone says WHERE the terminal went, not WHAT TO TYPE. The
// removed open-time announcement carried both; `devs` now prints the attach
// command as a footer under the table. Asserting on it here because the
// instruction is the half you need when you have done this once and come back
// to it months later -- exactly the value rdoggett flagged when he noticed it
// had gone missing.
let hostAttachHintName = "devs: prints how to attach to a bound /tN"
if filter.isEmpty || hostAttachHintName.localizedCaseInsensitiveContains(filter) {
    let out = os9(["echo x >/t1", "devs"], env: ["OS9T1": "pty"])
    // The hint must name the device AND carry a real host path -- "attach /t1
    // with:" alone would pass on a footer that printed an empty endpoint.
    let hint = out.replacingOccurrences(of: "\r", with: "\n")
                  .split(separator: "\n")
                  .first { $0.contains("attach /t1 with:") }
    let hasDev = hint?.range(of: "screen +/dev/(pts/[0-9]+|[a-z]*tty[a-zA-Z0-9/]+)",
                             options: .regularExpression) != nil

    if hasDev {
        print("PASS: \(hostAttachHintName)"); passed += 1
    } else {
        print("FAIL: \(hostAttachHintName)")
        print("      [expected a footer line \"attach /t1 with:  screen /dev/...\"]")
        print("      hint: \(hint.map(String.init) ?? "none")")
        failed += 1
    }
}

// NOTE: there was a separate "idevs reports a bound /tN" test here. It pulled
// the device path out of the allocation ANNOUNCEMENT and demanded a matching
// idevs row. With the announcement removed it had no left-hand side left, and
// what remained of it was word-for-word the assertion above -- two tests that
// looked independent and were not. Folded into the OS9T1=pty block, which
// already runs the same emulator invocation.

// Two commands, each opening and closing /t1, with `idevs` after each. If the
// binding is torn down when the first command's path closes, hostterm_endpoint()
// goes empty and the listing SKIPS the device entirely -- so the first idevs
// shows no "t1 hostterm" row at all. Asking twice therefore measures survival
// directly. The old form inferred it by counting allocation announcements,
// which no longer exist: they printed to the guest's own stderr path, putting
// emulator narration inside guest program output.
// (Do not assert on distinct name strings: posix_openpt/ptsname deterministically
// hand back the same lowest-free slot, so a torn-down-and-reallocated pty
// reappears under the IDENTICAL name -- proven live, so that check is vacuous.
// Requiring the two endpoints to be EQUAL is safe for exactly that reason, and
// is not what distinguishes the two outcomes: the row's presence is.)
let hostSurvivesCloseName = "hostterm: a pty binding survives the path that opened it"
let runHostSurvivesClose  = filter.isEmpty || hostSurvivesCloseName.localizedCaseInsensitiveContains(filter)

if runHostSurvivesClose {
    let twiceOut = os9(["echo one >/t1", "idevs", "echo two >/t1", "idevs"],
                       env: ["OS9T1": "pty"])
    let endpoints = twiceOut.replacingOccurrences(of: "\r", with: "\n")
                            .split(separator: "\n")
                            .filter { $0.hasPrefix("t1 ") && $0.contains("hostterm") }
                            .compactMap { row in
        row.range(of: "/dev/(pts/[0-9]+|[a-z]*tty[a-zA-Z0-9/]+)",
                  options: .regularExpression).map { String(row[$0]) }
    }

    if endpoints.count == 2 && endpoints[0] == endpoints[1] {
        print("PASS: \(hostSurvivesCloseName)"); passed += 1
    } else {
        print("FAIL: \(hostSurvivesCloseName)")
        print("      [expected a t1 hostterm row in BOTH idevs listings, same endpoint]")
        print("      endpoints: \(endpoints)")
        failed += 1
    }
}

// -- Serial speed: a bound /tN follows the path's PD_BAU --------------------
// A pty ignores speed for timing but STORES it, and its termios state is
// shared between both ends -- so we can read back exactly what the emulator
// set. Default PD_BAU is 0x0F = 19200 (init_consoleopts, utilstuff.c).
// Measured live on this machine: a fresh, untouched pty defaults to B9600,
// not B19200, so this assertion is real -- it cannot pass by accident.
let hostSpeedDefaultName = "hostterm: host port speed follows the path's PD_BAU"
let runHostSpeedDefault  = filter.isEmpty || hostSpeedDefaultName.localizedCaseInsensitiveContains(filter)

if runHostSpeedDefault && !containerized {
    if let (master, slave, slaveName) = makePTY() {
        _ = os9(["echo x >/t1"], env: ["OS9T1": slaveName])

        var t = termios()
        tcgetattr( master, &t )
        let got = cfgetospeed( &t )
        close( master ); close( slave )

        if got == speed_t(B19200) {
            print("PASS: \(hostSpeedDefaultName)"); passed += 1
        } else {
            print("FAIL: \(hostSpeedDefaultName)")
            print("      [expected B19200 (\(speed_t(B19200))), got \(got)]")
            failed += 1
        }
    } else {
        print("FAIL: hostterm: could not create a pty pair for the speed-default test")
        failed += 1
    }
}

// `tmode` issues I$SetStt SS_Opt on its stdin path, so redirecting stdin
// from /t1 retunes THAT device. 2400 is deliberately not the default -- this
// is the test that proves the SS_Opt hook in pCsetopt, independent of
// whether open-time defaulting (above) happens to already match.
let hostSpeedTmodeName = "hostterm: tmode baud= retunes a live host port"
let runHostSpeedTmode  = filter.isEmpty || hostSpeedTmodeName.localizedCaseInsensitiveContains(filter)

if runHostSpeedTmode && !containerized {
    if let (master, slave, slaveName) = makePTY() {
        _ = os9(["tmode </t1 baud=2400"], env: ["OS9T1": slaveName])

        var t = termios()
        tcgetattr( master, &t )
        let got = cfgetospeed( &t )
        close( master ); close( slave )

        if got == speed_t(B2400) {
            print("PASS: \(hostSpeedTmodeName)"); passed += 1
        } else {
            print("FAIL: \(hostSpeedTmodeName)")
            print("      [expected B2400 (\(speed_t(B2400))), got \(got)]")
            failed += 1
        }
    } else {
        print("FAIL: hostterm: could not create a pty pair for the tmode-speed test")
        failed += 1
    }
}

// -- Serial format: a bound /tN follows the path's PD_PAR --------------------
// Parity, bits per character and stop bits, laid out in PD_PAR (Technical I/O
// Manual, SCF, page 3-9), were never applied to the host port: only the speed
// was. A pty stores them as it stores the speed, so they read back through the
// master. Two runs: the default (8 bits, no parity, one stop bit -- the pty is
// first set to something else, so the check cannot pass by leaving it alone)
// and `tmode par=even cs=7 stop=2`, which exercises every field at once.
let hostFormatName = "hostterm: host port parity, bits and stop bits follow PD_PAR"
let runHostFormat  = filter.isEmpty || hostFormatName.localizedCaseInsensitiveContains(filter)

if runHostFormat && !containerized {
    func formatAfter(_ commands: [String]) -> tcflag_t? {
        guard let (master, slave, slaveName) = makePTY() else { return nil }
        var t = termios()
        tcgetattr( slave, &t )
        t.c_cflag = (t.c_cflag & ~tcflag_t(CSIZE)) | tcflag_t(CS5 | PARENB | PARODD | CSTOPB)
        tcsetattr( slave, TCSANOW, &t )
        _ = os9(commands, env: ["OS9T1": slaveName])
        tcgetattr( master, &t )
        close( master ); close( slave )
        return t.c_cflag & tcflag_t(CSIZE | PARENB | PARODD | CSTOPB)
    }
    let want8N1 = tcflag_t(CS8)
    let want7E2 = tcflag_t(CS7 | PARENB | CSTOPB)
    if let plain = formatAfter(["echo x >/t1"]),
       let tuned = formatAfter(["tmode </t1 par=even cs=7 stop=2"]) {
        if plain == want8N1 && tuned == want7E2 {
            print("PASS: \(hostFormatName)"); passed += 1
        } else {
            print("FAIL: \(hostFormatName)")
            print("      [default: want \(String(want8N1, radix: 16)), got \(String(plain, radix: 16));" +
                  " 7E2: want \(String(want7E2, radix: 16)), got \(String(tuned, radix: 16))]")
            failed += 1
        }
    } else {
        print("FAIL: hostterm: could not create a pty pair for the format test")
        failed += 1
    }
}

// -- the retired OS9T wildcard, and the refusal it was bolted onto -----------
// A bare "OS9T" once meant "any /tN not named individually", auto-allocating a
// pty on first open. It was retired on 2026-09-20 (rdoggett) once `iterm`
// could make a terminal from inside a running system, which is the case it
// existed for: it CREATED a resource rather than discovering one, so it could
// never fail and could never tell you that ">/t5" was a typo for ">/t4".
// The first test below guards the retirement -- the variable must now do
// nothing -- and the second guards the refusal that was always the default.
// /t5 is unconfigured by every other test in this file.
let hostWildcardName       = "hostterm: the retired OS9T wildcard no longer serves a /tN"
let hostWildcardStrictName = "hostterm: an unconfigured /tN refuses with E$Unit"
let runHostWildcard        = filter.isEmpty || hostWildcardName.localizedCaseInsensitiveContains(filter)
let runHostWildcardStrict  = filter.isEmpty || hostWildcardStrictName.localizedCaseInsensitiveContains(filter)

if runHostWildcard {
    // Setting it must change nothing: /t5 stays E$Unit (#000:240) and no
    // hostterm row appears for it. `idevs` is how a binding would show,
    // the open-time announcement having been removed long since.
    let wild = os9(["echo x >/t5", "idevs"], env: ["OS9T": "pty"])
    let row  = wild.replacingOccurrences(of: "\r", with: "\n")
                   .split(separator: "\n")
                   .first { $0.hasPrefix("t5 ") && $0.contains("hostterm") }

    if row == nil && wild.contains("Error #000:240") {
        print("PASS: \(hostWildcardName)"); passed += 1
    } else {
        print("FAIL: \(hostWildcardName)")
        print("      [OS9T must no longer bind anything: expected E$Unit and no t5 row]")
        print("      row: \(row.map(String.init) ?? "none")")
        print("      got: \(wild.debugDescription.prefix(200))")
        failed += 1
    }
}

if runHostWildcardStrict {
    // Guards the DECISION, not the code: a terminal nobody named and nobody
    // declared does not exist, and saying so is the faithful answer -- real
    // OS-9 has no device without a descriptor. A later change that made
    // allocation implicit again would break this test, which is the point.
    let strict = os9(["echo x >/t5"])

    if strict.contains("Error #000:240 (E_UNIT)") {
        print("PASS: \(hostWildcardStrictName)"); passed += 1
    } else {
        print("FAIL: \(hostWildcardStrictName)")
        print("      [expected Error #000:240 (E_UNIT)]")
        print("      got: \(strict.debugDescription.prefix(200))")
        failed += 1
    }
}

// -- baud_drain_due destination crossover ------------------------------------
// baud_drain_due (consio.c) drains every paced device's FIFO from the
// scheduler, not from an fmgr entry point -- there is no ambient
// gConsoleID for it to inherit the way pConsIn/pConsInLn/ConsoleOut/pCready/
// pCclose do. Two devices with live backlogs at once
// is exactly the shape that could leak one device's bytes onto the other's
// pty if the drain used ConsPutc's ambient gConsoleID instead of naming its
// destination explicitly.
//
// Markers: "bootptest" (unique to /dd/CMDS -- confirmed absent from the
// /dd/DEFS listing) and "flexdef.h" (unique to /dd/DEFS -- confirmed absent
// from the /dd/CMDS listing), checked live against the actual h0 disk this
// suite runs against, 2026-07-29. Neither string appears anywhere in the
// command text sent below, so a match cannot come from the shell's own
// command echo.
let dualDeviceName = "hostterm: paced output from two devices does not cross over"
let runDualDevice   = filter.isEmpty || dualDeviceName.localizedCaseInsensitiveContains(filter)

if runDualDevice && !containerized {
    if let (master1, slave1, slave1Name) = makePTY(),
       let (master2, slave2, slave2Name) = makePTY() {
        let collector1 = BackpressureCollector()
        let collector2 = BackpressureCollector()
        let stopped1   = DispatchSemaphore(value: 0)
        let stopped2   = DispatchSemaphore(value: 0)

        // Both threads must be draining BEFORE the shell command starts:
        // pacing keeps both backlogs alive for ~1.7s (dir /dd/CMDS is ~3226
        // bytes at the default 19200), well past the 1024-byte pty queue, so
        // an undrained window here would deadlock the writer rather than
        // exercise the drain's device attribution.
        _ = startDrainThread(master1, collector1, stopped1)
        _ = startDrainThread(master2, collector2, stopped2)

        // Two devices, two concurrent writers, distinct content, PACED (no
        // -r) so both FIFOs are still draining across many baud_drain_due
        // calls at once.
        _ = os9(["dir /dd/CMDS >/t1 &", "dir /dd/DEFS >/t2"],
                timeout: 120, paced: true,
                env: ["OS9T1": slave1Name, "OS9T2": slave2Name])

        // The backgrounded /t1 job can still be draining its FIFO after the
        // foreground /t2 command (and the shell that spawned both) has
        // exited -- give it a moment before stopping the readers.
        usleep(500_000)
        collector1.requestStop(); collector2.requestStop()
        stopped1.wait(); stopped2.wait()
        close(master1); close(slave1)
        close(master2); close(slave2)

        let text1 = String(decoding: collector1.snapshot(), as: UTF8.self)
        let text2 = String(decoding: collector2.snapshot(), as: UTF8.self)

        let noCrossover = text1.contains("bootptest") && !text1.contains("flexdef.h")
                        && text2.contains("flexdef.h") && !text2.contains("bootptest")

        if noCrossover {
            print("PASS: \(dualDeviceName)"); passed += 1
        } else {
            print("FAIL: \(dualDeviceName)")
            print("      [expected /t1 to carry only the CMDS listing (bootptest) and")
            print("       /t2 only the DEFS listing (flexdef.h), with no crossover]")
            print("      /t1 has bootptest: \(text1.contains("bootptest")), " +
                  "/t1 has flexdef.h: \(text1.contains("flexdef.h"))")
            print("      /t2 has flexdef.h: \(text2.contains("flexdef.h")), " +
                  "/t2 has bootptest: \(text2.contains("bootptest"))")
            failed += 1
        }
    } else {
        print("FAIL: hostterm: could not create two pty pairs for the crossover test")
        failed += 1
    }
}

// -- an abort key typed on /tN interrupts THAT terminal's writer --------------
// KeyToBuffer takes its signal target from the device's own syspath
// (`lastwritten_pid`), and only lw_pid() sets it -- which ConsPutcTo reached on
// the main-console arm alone, because the hostterm_bound() branch returns first.
// So Ctrl-E typed on a bound /t1 used to flush that terminal's paced backlog
// (silently discarding queued output) while signalling nobody, and the process
// it was aimed at ran to completion. Measured, not reasoned: 3226 bytes with no
// abort, ~2984 with one -- ~240 bytes gone, listing still complete.
//
// The abort char goes to the pty MASTER, i.e. in on /t1's own input, which is
// the whole point: this is not the console's abort key. holdOpen keeps the shell
// alive past the injection, so the writer is genuinely running when it lands --
// without it the shell exits first and the FIFO flush truncates the output no
// matter what the emulator does, which passes for the wrong reason.
// Confirmed 3/3 FAIL before the fix, 0/3 after.
let tnAbortName = "hostterm: an abort key on /tN interrupts that terminal's writer"
let runTNAbort  = filter.isEmpty || tnAbortName.localizedCaseInsensitiveContains(filter)

if runTNAbort && !containerized {
    if let (master, slave, slaveName) = makePTY() {
        let collector = BackpressureCollector()
        let stopped   = DispatchSemaphore(value: 0)
        _ = startDrainThread(master, collector, stopped)

        // Ctrl-E (the default PD_QUT) once the listing has demonstrably STARTED,
        // but long before the ~3226-byte listing could finish on its own.
        //
        // Waits for the condition rather than for a fixed 0.6s. That delay
        // assumed the writer had produced output by then, which is true on an
        // idle machine and false on a loaded one: with several container builds
        // running this failed 3 runs in 5, always the same way -- 61 bytes
        // collected, the abort landing before "BOOTOBJS" was ever emitted, so
        // the test reported "started: false" and blamed the emulator for the
        // machine being busy. Polling for the first entry makes the injection
        // point depend on the writer, not on the load average.
        DispatchQueue.global().async {
            let deadline = Date().addingTimeInterval(3.0)
            while Date() < deadline {
                if String(decoding: collector.snapshot(), as: UTF8.self)
                    .contains("BOOTOBJS") { break }
                Thread.sleep(forTimeInterval: 0.05)
            }
            var abortChar: UInt8 = 0x05
            _ = write(master, &abortChar, 1)
        }

        // holdOpen covers the poll window above plus the run that follows it;
        // it must outlast the worst case, or the shell exits first and the FIFO
        // flush truncates the listing whatever the emulator did.
        _ = os9(["dir /dd/CMDS >/t1 &", "free /dd"],
                timeout: 120, paced: true,
                env: ["OS9T1": slaveName], holdOpen: 6.0)

        usleep(500_000)
        collector.requestStop(); stopped.wait()
        close(master); close(slave)

        let text = String(decoding: collector.snapshot(), as: UTF8.self)
        // Started (first name present) but was cut off (last name absent).
        // Both halves matter: without the first, "aborted" is indistinguishable
        // from "never ran".
        let started  = text.contains("BOOTOBJS")
        let finished = text.contains("xmode")

        if started && !finished {
            print("PASS: \(tnAbortName)"); passed += 1
        } else {
            print("FAIL: \(tnAbortName)")
            print("      [expected the listing to start (BOOTOBJS) and be cut off")
            print("       before its last entry (xmode)]")
            print("      started: \(started), ran to completion: \(finished), " +
                  "bytes: \(collector.snapshot().count)")
            failed += 1
        }
    } else {
        print("FAIL: hostterm: could not create a pty for the /tN abort test")
        failed += 1
    }
}

// -- XOFF halts one terminal's output, and only that terminal ----------------
// "Output from a SCF device is halted immediately when PD_XOFF is received and
// will not be resumed until PD_XON is received" (Technical I/O Manual V2.4,
// PD_XOFF). os9exec set holdScreen from the key path and then never looked at
// it on any write path a modern build reaches -- the two `while (holdScreen)
// CheckInputBuffers()` loops live in console.stubs.c (behind USE_CLASSIC) and
// serialaccess.c (not in the makefile at all). So XOFF on /tN was a no-op for
// output, and the pause users DID see on the main console came from the HOST
// tty's own IXON eating ^S -- see the console test below.
//
// Two assertions from one run, because they are two different claims about the
// same 4-second window and a second paced run would double the cost:
//
//  * /t1's output stops. Sampled at two points three seconds apart; equal
//    means halted. The "sampled while still mid-listing" check is what keeps
//    that from passing on a listing that had simply finished -- without it the
//    equality is vacuous.
//  * the CONSOLE listing, on a different device, runs to completion anyway.
//    That is the bug behind the bug: the obvious way to honour an XOFF is to
//    spin inside the write syscall, and under a cooperative scheduler that
//    stalls every other process and every due F$Alarm, not just the writer.
//    ConsoleOut parks the writer (pWaitWrite) instead. Verified able to fail by
//    temporarily restoring the spin: the console listing is then truncated.
//
// The XOFF goes to the pty MASTER -- in on /t1's own input, the terminal
// asking its own output to stop. holdOpen keeps the shell alive across the
// whole hold; without it the shell exits, baud_drain_all_pending flushes
// everything, and both assertions pass for the wrong reason.
let tnXoffHaltName  = "hostterm: XOFF on /tN halts that terminal's output until XON"
let tnXoffAliveName = "hostterm: an XOFF hold does not stall the rest of the system"
let runTNXoffHalt   = filter.isEmpty || tnXoffHaltName.localizedCaseInsensitiveContains(filter)
let runTNXoffAlive  = filter.isEmpty || tnXoffAliveName.localizedCaseInsensitiveContains(filter)

if (runTNXoffHalt || runTNXoffAlive) && !containerized {
    if let (master, slave, slaveName) = makePTY() {
        let collector = BackpressureCollector()
        let stopped   = DispatchSemaphore(value: 0)
        _ = startDrainThread(master, collector, stopped)

        let heldLock  = NSLock()
        let sampled   = DispatchSemaphore(value: 0)
        var earlySample = -1     // bytes on /t1 shortly after the XOFF
        var lateSample  = -1     // bytes on /t1 three seconds later

        DispatchQueue.global().async {
            Thread.sleep(forTimeInterval: 0.6)
            var xoff: UInt8 = 0x13
            _ = write(master, &xoff, 1)

            // Each sample is published the moment it is taken, never both at
            // the end: a run that ends early would otherwise leave both unset
            // and the failure would say nothing about which half went wrong.
            Thread.sleep(forTimeInterval: 0.6)
            heldLock.lock(); earlySample = collector.total(); heldLock.unlock()
            Thread.sleep(forTimeInterval: 3.0)
            heldLock.lock(); lateSample  = collector.total(); heldLock.unlock()

            var xon: UInt8 = 0x11
            _ = write(master, &xon, 1)
            sampled.signal()
        }

        // Both listings paced, so both are still streaming when the XOFF lands
        // -- the console one finishes DURING the hold, which is the point.
        let consoleOut = os9(["dir /dd/CMDS >/t1 &", "dir /dd/CMDS"],
                             timeout: 180, paced: true,
                             env: ["OS9T1": slaveName], holdOpen: 9.0)

        // Both samples first, THEN stop draining. Without this the collector
        // can be shut down before the second sample is due whenever the run
        // ends early -- which is exactly what a broken build does -- leaving
        // the failure report with nothing to say about the half that matters.
        _ = sampled.wait(timeout: .now() + 20)
        usleep(500_000)
        collector.requestStop(); stopped.wait()
        close(master); close(slave)

        heldLock.lock()
        let early = earlySample, late = lateSample
        heldLock.unlock()
        let total = collector.total()

        if runTNXoffHalt {
            // early == late: nothing left the device while held.
            // early < total: it was genuinely mid-listing, not already done.
            // total > early: XON released the rest, so nothing was discarded.
            if early >= 0 && early == late && early < total {
                print("PASS: \(tnXoffHaltName)"); passed += 1
            } else {
                print("FAIL: \(tnXoffHaltName)")
                print("      [expected /t1 to be mid-listing and frozen across the hold]")
                print("      bytes at XOFF+0.6s: \(early), +3.6s: \(late), final: \(total)")
                failed += 1
            }
        }

        if runTNXoffAlive {
            // "xmode" is the last entry of a /dd/CMDS listing and appears in no
            // command this harness sends, so the shell's own command echo cannot
            // supply it (see Global Constraints).
            if consoleOut.contains("xmode") {
                print("PASS: \(tnXoffAliveName)"); passed += 1
            } else {
                print("FAIL: \(tnXoffAliveName)")
                print("      [the console listing did not finish while /t1 was held]")
                print("      console bytes: \(consoleOut.count)")
                failed += 1
            }
        }
    } else {
        print("FAIL: hostterm: could not create a pty for the /tN XOFF test")
        failed += 1
    }
}

// -- shutdown must survive a process that wrote to a /tN ---------------------
// `kill_process` (procstuff.c) dereferenced `cp->last_mco->spP` unconditionally.
// A /tN keeps its ttydev_typ while `hostterm_close()` drops the syspath and
// leaves `dev.spP` NULL, and cleanup() runs close_syspaths BEFORE
// kill_processes -- so ANY process still holding a last_mco for a /tN crashed
// on the way out. `hostterm_poll` already carried this exact guard; this was
// the other unguarded dereference.
//
// It presented as an unkillable 100%-CPU hang, not a crash, because
// setup_exception left segv_handler armed after the emulation loop: the fault
// siglongjmp'd back into a loop whose world had already been torn down, faulted
// again, and span forever with the PC in unmapped memory. Both halves are
// fixed; this test covers the pair, since either one alone brings the hang or
// the crash back.
//
// No holdOpen: the terminator goes out with the body, so the shell exits while
// the backgrounded writer is still running -- that is the whole setup. Paced
// and drained, both load-bearing: unpaced-and-undrained instead parks the
// writer on a genuinely full pty, which is correct blocked-writer behaviour
// (idle, and it completes in full the moment a reader appears -- measured) and
// would make this test flaky for a reason that is not a bug.
let tnShutdownName = "hostterm: cleanup survives a process that wrote to /tN"
let runTNShutdown  = filter.isEmpty || tnShutdownName.localizedCaseInsensitiveContains(filter)

if runTNShutdown && !containerized {
    if let (master, slave, slaveName) = makePTY() {
        let collector = BackpressureCollector()
        let stopped   = DispatchSemaphore(value: 0)
        _ = startDrainThread(master, collector, stopped)

        let consoleOut = os9(["dir /dd/CMDS >/t1 &"], timeout: 120, paced: true,
                             env: ["OS9T1": slaveName])

        usleep(500_000)
        collector.requestStop(); stopped.wait()
        close(master); close(slave)

        // Assert on the BUS ERROR, not on the delivered bytes. The listing is
        // fully out before teardown even starts, so a "did the data survive"
        // check passes with the defect present -- measured, it did. The host
        // NULL deref surfaces two ways depending on where kill_process was
        // called from: inside the emulation loop it is caught and reported as a
        // fabricated OS-9 `E_BUSERR` against an innocent program, and during
        // cleanup it is a plain SIGSEGV (or, before the handler was disarmed,
        // the 100% spin, which fails this test by timing out instead). "xmode"
        // stays in as the data-loss half of the claim.
        let text  = String(decoding: collector.snapshot(), as: UTF8.self)
        let clean = !consoleOut.contains("E_BUSERR")
        if clean && text.contains("xmode") {
            print("PASS: \(tnShutdownName)"); passed += 1
        } else {
            print("FAIL: \(tnShutdownName)")
            print("      [kill_process dereferenced a /tN's dropped syspath: reported as a")
            print("       bus error, a SIGSEGV in cleanup, or a 100%-CPU spin (timeout)]")
            print("      bus error reported: \(!clean), listing tail present: \(text.contains("xmode"))")
            print("      bytes off /t1: \(collector.snapshot().count)")
            failed += 1
        }
    } else {
        print("FAIL: hostterm: could not create a pty for the /tN shutdown test")
        failed += 1
    }
}

// -- F$PErr with a TERMINAL as its error path --------------------------------
// F$PErr searches the path it is given for the error's text. Handed a terminal
// -- which the clean-room `load` does, calling prerr(2, errno) -- that search
// read the terminal: with nothing typed the read PARKED the process and came
// back empty, so the built-in message printed and the call returned while the
// process was still parked. The dispatcher resumes a parked process by
// re-running its call, so the message printed again, forever: about 850 times
// in 20 seconds on a pty, and the keystrokes meant for the shell were eaten.
// Found by the osk-freeware session, 2026-09-19. Needs a real pty: with output
// piped the console read reports EOF instead of parking, and nothing loops.
do {
    let perrName = "f$perr: an error path that is a terminal prints once, and does not park"
    if (filter.isEmpty || perrName.localizedCaseInsensitiveContains(filter)) && !containerized {
        let perrAsm = [
            "  use /dd/DEFS/oskdefs.d",
            "",
            "F$Exit   equ  $06",
            "F$PErr   equ  $0F",
            "I$WritLn equ  $8C",
            "",
            "  psect perrtst,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,512,start",
            "",
            "start:",
            "  moveq   #2,d0",            // the error path: standard error, a terminal here
            "  move.w  #221,d1",          // E$MNF, as load reports
            "  OS9     F$PErr",
            "  lea     done(pc),a0",
            "  moveq   #donel,d1",
            "  moveq   #1,d0",
            "  OS9     I$WritLn",
            "  moveq   #0,d1",
            "  OS9     F$Exit",
            "done:  dc.b \"PERRDONE\",$0D",
            "donel  equ  *-done",
            "",
            "  ends",
            ""
        ].joined(separator: "\r")
        try? perrAsm.write(toFile: scratchDisk + "/perrtst.a", atomically: true, encoding: .utf8)
        _ = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
                 "r68 /h5/perrtst.a -o=/h5/perrtst.r",
                 "l68 /h5/perrtst.r -o=/h5/perrtst"], timeout: 30)

        var text = ""
        if let (master, slave, _) = makePTY() {
            let process = Process()
            process.executableURL     = execURL
            process.arguments         = [shellArg]
            process.environment       = ["OS9DISK": diskPath,
                                         "OS9H\(scratchDev.dropFirst())": scratchDisk].merging(inheritedByChildren) { mine, _ in mine }
            let slaveHandle = FileHandle(fileDescriptor: slave, closeOnDealloc: false)
            process.standardInput  = slaveHandle
            process.standardOutput = slaveHandle
            process.standardError  = slaveHandle
            var collected = [UInt8]()
            if (try? process.run()) != nil {
                usleep(1_500_000)
                collected += drainNonBlocking(master)
                var cmd = Array("/\(scratchDev)/perrtst\r".utf8)
                _ = write(master, &cmd, cmd.count)
                let deadline = Date().addingTimeInterval(20)
                while Date() < deadline {
                    collected += drainNonBlocking(master)
                    if String(decoding: collected, as: UTF8.self).contains("PERRDONE") { break }
                    usleep(100_000)
                }
                var quit = Array("\u{1B}\n\u{04}\n".utf8)
                _ = write(master, &quit, quit.count)
                usleep(300_000)
                collected += drainNonBlocking(master)
                if process.isRunning { process.terminate() }
                process.waitUntilExit()
            }
            close(master); close(slave)
            text = String(decoding: collected, as: UTF8.self)
        }
        let errors = text.components(separatedBy: "000:221").count - 1
        if text.contains("PERRDONE") && errors == 1 {
            print("PASS: \(perrName)"); passed += 1
        } else {
            print("FAIL: \(perrName)")
            print("      [the message must print once and the program carry on; printed \(errors) times, finished=\(text.contains("PERRDONE"))]")
            failed += 1
        }
        removeScratchItem("perrtst.a"); removeScratchItem("perrtst.r"); removeScratchItem("perrtst")
    }
}

// -- tracing must not write into the traced program's own output -----------
// -d output used to go through upe_printf, i.e. to the GUEST's stderr PATH, so
// it followed wherever the guest had redirected its errors. `echo hi >>file`
// under -d1 put 6,672 bytes of emulator trace INSIDE the guest's file, and a
// program that dups a pipe onto its stderr and reads that pipe back never saw
// EOF because the emulator kept feeding it trace -- an hour of a peer
// session's time, looking like I$Dup hanging. An instrument may not change
// what it measures. The operator's copy of the trace is checked too: a fix
// that simply silenced tracing would pass the first half of this.
do {
    let name = "debug: -d tracing goes to the operator, not into the guest's file"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let witness = scratchDisk + "/dtrace"
        try? FileManager.default.removeItem(atPath: witness)

        // `>>` redirects the guest's STDERR, which is where the trace used to go.
        let out  = os9(["echo hi >>\(scratch)/dtrace"], flags: ["-d1", "0x60A"])
        let leak = (try? String(contentsOfFile: witness, encoding: .utf8)) ?? ""
        let sawTrace = out.contains("OS9 F$") || out.contains("OS9 I$")

        if leak.isEmpty && sawTrace {
            print("PASS: \(name)"); passed += 1
        } else if !sawTrace {
            print("FAIL: \(name)")
            print("      [the operator got no trace at all -- -d is supposed to still work]")
            failed += 1
        } else {
            print("FAIL: \(name)")
            print("      [\(leak.count) bytes of emulator trace landed in the guest's own file]")
            print("      got: \(leak.prefix(120).debugDescription)")
            failed += 1
        }
    }
}

// The debugger is the same question as the trace above, and it answered it
// itself: it READS from the host's stdin, so with its output on the guest's
// stderr path the two halves of one conversation pointed at different places.
// Entering it while the guest had redirected stderr put the banner into the
// guest's FILE and left the operator typing blind. `idbg`'s command-line USAGE
// text is deliberately not covered here -- that is a command's own output and
// should follow a redirect like any other.
do {
    let name = "debug: the debugger talks to the operator, not into the guest's file"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let witness = scratchDisk + "/idbgbanner"
        try? FileManager.default.removeItem(atPath: witness)

        // Enter the debugger with stderr redirected, then [G]o straight out.
        let out  = os9(["idbg >>\(scratch)/idbgbanner", "g"])
        let leak = (try? String(contentsOfFile: witness, encoding: .utf8)) ?? ""
        let sawBanner = out.contains("type ?<Enter>") || out.contains("dbgmsk=")

        if leak.isEmpty && sawBanner {
            print("PASS: \(name)"); passed += 1
        } else if !sawBanner {
            print("FAIL: \(name)")
            print("      [the operator never saw the debugger's banner]")
            failed += 1
        } else {
            print("FAIL: \(name)")
            print("      [\(leak.count) bytes of debugger output went into the guest's file]")
            failed += 1
        }
    }
}

// -- pwd and cd: the names from the other half of the world ------------------
// rdoggett, 2026-09-20: "I'd be grateful to have pd/pwd programs and cd/chd
// because I'm always typing the wrong one, but I know the cd/chd are not
// possible". `cd` IS possible, but only because os9exec is the kernel: an
// internal command is forked like any utility, so it moves its PARENT's data
// directory, which no guest program could do. The claim is therefore about
// what survives the command -- the shell must still be there AFTER the
// process that moved it has exited, which the second `pwd` is asked from a
// later fork entirely.
do {
    let name = "cd: moves the shell's data directory, and pwd reports it afterwards"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let out  = os9(["pwd", "cd CMDS", "pwd", "cd ..", "pwd"])
        let said = out.replacingOccurrences(of: "\r", with: "\n")
                      .split(separator: "\n").map(String.init)
                      .filter { $0.hasPrefix("/") && !$0.contains(" ") }

        // Written against the SHAPE rather than the disk's name, so the test
        // says the same thing on whatever device the suite is pointed at.
        let ok = said.count == 3 && said[1] == said[0] + "/CMDS" && said[2] == said[0]

        if ok {
            print("PASS: \(name)"); passed += 1
        } else {
            print("FAIL: \(name)")
            print("      [expected <dir>, <dir>/CMDS, <dir> from three separate forks]")
            print("      got: \(said)")
            failed += 1
        }
    }
}

// pwd must print the OS-9 pathlist, not the host path it is backed by. That is
// the whole difference between a useful answer and a misleading one: the real
// Microware `pd` prints "/dd/SYS", and a `pwd` that answered
// "/Users/.../oskBoot/SYS" would be a different question's answer. /h5 is the
// suite's own scratch device, so its OS-9 name is known here exactly.
// -- systime, the emulator's own timing report --------------------------------
// About two hundred lines of funcdispatch.c -- int_systime, show_timing,
// show_os9timers, show_syscalltimers, show_line, time_disp -- and a coverage
// run put every one of them at 0%. Nothing had ever asked the emulator how
// long it was spending in which system call, so the answer could have become
// an empty table, or a table of the wrong calls, without anything noticing.
//
// The counts are what is checked, not the times: a run this small spends
// under a tick almost everywhere, so the time columns are legitimately blank
// and asserting on them would be asserting on the speed of the host.
do {
    let name = "systime: the timing report names the calls that were made"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        // -r arms the counters, the shell work makes calls, -f and -i ask for
        // the two lists back. F$Fork and I$WritLn are unavoidable: the shell
        // forks `echo`, and `echo` writes a line.
        let out = os9(["systime -r", "echo hi", "systime -f", "systime -i"])
        var wrong = [String]()
        if !out.contains("F$XXX")    { wrong.append("no F$ table")   }
        if !out.contains("I$XXX")    { wrong.append("no I$ table")   }
        if !out.contains("F$Fork")   { wrong.append("F$Fork uncounted")  }
        if !out.contains("I$WritLn") { wrong.append("I$WritLn uncounted") }

        if wrong.isEmpty {
            print("PASS: \(name)"); passed += 1
        } else {
            print("FAIL: \(name)")
            print("      [\(wrong.joined(separator: ", "))]")
            print("      [`systime -r` then -f/-i must report the calls a forked echo makes]")
            failed += 1
        }
    }
}

do {
    let name = "systime: measurement can be turned off and on again"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let out = os9(["systime -d", "systime -e", "systime -?"])
        let ok  = out.contains("Disabled timing measurement")
               && out.contains("Re-enabled timing measurement")
               && out.contains("Usage:")
        if ok {
            print("PASS: \(name)"); passed += 1
        } else {
            print("FAIL: \(name)")
            print("      [-d, -e and -? must each answer; got: " +
                  "\(out.split(whereSeparator: \.isNewline).filter { $0.contains("timing") || $0.contains("Usage") }.prefix(3).joined(separator: " | "))]")
            failed += 1
        }
    }
}

// -- what a -d trace actually SAYS --------------------------------------------
// Two tests already prove -d output goes to the operator rather than into the
// guest's file. Neither looks at what it says, and the formatters are the
// bulk of debug.c: a coverage run put get_stat_name at 11% and debug_help at
// 0%. A trace that printed `$0000` where it used to print `SS_Opt`, or a flag
// list that stopped naming the flags, would still pass every routing test --
// and -d is the tool anyone reaches for first when the emulator misbehaves,
// so it failing quietly is expensive exactly when it is needed.
do {
    let name = "debug: a -d trace names the status call, not just its number"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        // dbgSysCall (0x0002). Even `echo` makes the shell ask its terminal
        // for options, so this needs no particular utility to be installed.
        let trace = os9(["echo hi"], flags: ["-d", "0x0002"])
        if trace.contains("SS_Opt") && trace.contains("I$GetStt") {
            print("PASS: \(name)"); passed += 1
        } else {
            print("FAIL: \(name)")
            print("      [expected the trace to name I$GetStt and SS_Opt; a number in")
            print("       their place means the name tables stopped being consulted]")
            print("      saw: \(trace.split(whereSeparator: \.isNewline).filter { $0.contains("GetStt") }.prefix(2).joined(separator: " | "))")
            failed += 1
        }
    }
}

do {
    let name = "debug: dhelp lists the -d flags by name and by mask"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        // The only place the -d vocabulary is written down for a user. Both
        // halves matter: the name is what a person reads, the mask is what
        // they have to type.
        let help = os9(["dhelp"])
        let missing = [("dbgSysCall", "0x0002"), ("dbgModules", "0x0020")]
            .filter { !(help.contains($0.0) && help.contains($0.1)) }
            .map { $0.0 }
        if missing.isEmpty {
            print("PASS: \(name)"); passed += 1
        } else {
            print("FAIL: \(name)")
            print("      [dhelp no longer documents: \(missing.joined(separator: ", "))]")
            failed += 1
        }
    }
}

// -- the internal status commands ---------------------------------------------
// Every one of these was never executed by any test until now: `ihelp`,
// `iprocs`, `imdir`, `ipaths`, `imem`, `ihit` and `iunused` between them are
// ~150 lines that a coverage run (tools/coverage.sh) showed at 0%. They are
// the operator's whole view INTO a running emulator -- what is running, what
// is loaded, which paths are open, where the memory went -- so one that
// silently stopped reporting would be invisible, and the loss would only show
// the day somebody needed it to debug something else.
//
// What is asserted is that each one produces its own report, identified by a
// column heading no other command prints. Deliberately NOT the layout: column
// widths and ordering are free to change, and a test that pinned them would
// fail for reasons nobody cares about. `ihelp` is checked for a command that
// is really in the table, because the thing worth catching there is an entry
// quietly disappearing -- which has happened twice, to `pd` and to the bare
// `OS9T` wildcard.
do {
    let name = "internal commands: every status report still reports"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        // command -> a string only THAT command's report contains
        let reports = [("ihelp",   "internal commands:"),
                       ("ihelp",   "iprocs"),
                       ("iprocs",  "Last Syscall"),
                       ("imdir",   "stacksiz"),
                       ("ipaths",  "parID/refNum"),
                       ("imem",    "End (+1)"),
                       ("ihit",    "hash field hit rate"),
                       ("iunused", "Block")]
        var silent = [String]()
        for (cmd, marker) in reports where !os9([cmd]).contains(marker) {
            silent.append("\(cmd) (no \"\(marker)\")")
        }
        if silent.isEmpty {
            print("PASS: \(name)"); passed += 1
        } else {
            print("FAIL: \(name)")
            print("      [these printed no report: \(silent.joined(separator: ", "))]")
            failed += 1
        }
    }
}

// -- an internal command given no arguments -----------------------------------
// The usage text is the only thing standing between a typo and silence. Each
// of these helpers was also at 0%: nothing had ever run one of these commands
// wrong. A command that answered nothing at all would look exactly like one
// that had worked.
do {
    let name = "internal commands: a missing argument earns a usage message"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        var quiet = [String]()
        for cmd in ["icopy", "imakdir"] where !os9([cmd]).contains("Syntax:") {
            quiet.append(cmd)
        }
        if quiet.isEmpty {
            print("PASS: \(name)"); passed += 1
        } else {
            print("FAIL: \(name)")
            print("      [no \"Syntax:\" line from: \(quiet.joined(separator: ", "))]")
            failed += 1
        }
    }
}

do {
    let name = "pwd: names the device, not the host directory behind it"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let out = os9(["cd /h5", "pwd"])
        let ok  = out.replacingOccurrences(of: "\r", with: "\n")
                     .split(separator: "\n").map(String.init)
                     .contains { $0 == "/h5" }

        if ok {
            print("PASS: \(name)"); passed += 1
        } else {
            print("FAIL: \(name)")
            print("      [expected a line \"/h5\", the OS-9 name of the scratch device]")
            print("      got: \(out.debugDescription.prefix(200))")
            failed += 1
        }
    }
}

// `pd` is deliberately NOT an internal command: the system disk carries the
// real Microware one, and an internal command of that name hides it, because
// prepFork prefers a resident module and a disk utility is not resident until
// something loads it. Measured when this was first written -- `pd` ran the
// internal code and printed a host path. Whatever answers `pd`, it must never
// be that: either Microware's utility runs, or nothing does.
do {
    let name = "pd: the disk's own pd is what runs, never an internal one"
    if filter.isEmpty || name.localizedCaseInsensitiveContains(filter) {
        let out = os9(["cd /h5", "pd"])
        let ok  = !out.contains(scratchDisk) && !out.contains("/Users/")

        if ok {
            print("PASS: \(name)"); passed += 1
        } else {
            print("FAIL: \(name)")
            print("      [a host path in pd's output means an internal pd shadowed the disk's]")
            print("      got: \(out.debugDescription.prefix(200))")
            failed += 1
        }
    }
}

// -- iterm: make a /tN from inside the running system ------------------------
// On real OS-9 you load a device descriptor and the device is there. os9exec
// has no descriptor machinery, but `mount` already makes an /hX at runtime and
// `iterm` is the terminal equivalent (rdoggett, 2026-09-12). The device must be
// usable at once, not merely listed: the guest writes to it and the bytes come
// out of the host endpoint. Local only -- the endpoint is opened from the host
// side, which is not the machine the emulator runs on under a container.
do {
    let name = "iterm: a /tN declared at runtime carries the guest's bytes to its endpoint"
    if (filter.isEmpty || name.localizedCaseInsensitiveContains(filter)) && !containerized {
        let process = Process()
        let toEmu = Pipe(), fromEmu = Pipe()
        process.executableURL  = execURL
        process.arguments      = ["-r", shellArg]
        process.environment    = ["OS9DISK": diskPath].merging(inheritedByChildren) { mine, _ in mine }
        process.standardInput  = toEmu
        process.standardOutput = fromEmu
        process.standardError  = fromEmu
        var said = "", endpoint = "", heard = ""
        if (try? process.run()) != nil {
            let out = fromEmu.fileHandleForReading
            _ = fcntl(out.fileDescriptor, F_SETFL, fcntl(out.fileDescriptor, F_GETFL, 0) | O_NONBLOCK)
            toEmu.fileHandleForWriting.write("iterm t4\n".data(using: .utf8)!)
            // the endpoint it allocated, from iterm's own report
            let deadline = Date().addingTimeInterval(15)
            while Date() < deadline && endpoint.isEmpty {
                var buf = [UInt8](repeating: 0, count: 4096)
                let n = read(out.fileDescriptor, &buf, buf.count)
                if n > 0 { said += String(decoding: buf[0..<n], as: UTF8.self) }
                if let r = said.range(of: "/dev/tty[a-z0-9]+", options: .regularExpression) {
                    endpoint = String(said[r])
                }
                if endpoint.isEmpty { usleep(100_000) }
            }
            if !endpoint.isEmpty {
                let fd = open(endpoint, O_RDWR | O_NOCTTY | O_NONBLOCK)
                toEmu.fileHandleForWriting.write("echo ITERMWORKS >/t4\n".data(using: .utf8)!)
                if fd >= 0 {
                    let stop = Date().addingTimeInterval(15)
                    while Date() < stop && !heard.contains("ITERMWORKS") {
                        var buf = [UInt8](repeating: 0, count: 4096)
                        let n = read(fd, &buf, buf.count)
                        if n > 0 { heard += String(decoding: buf[0..<n], as: UTF8.self) }
                        else { usleep(100_000) }
                    }
                    close(fd)
                }
            }
            toEmu.fileHandleForWriting.write("\u{1B}\n\u{04}\n".data(using: .utf8)!)
            let quit = Date().addingTimeInterval(10)
            while process.isRunning && Date() < quit { usleep(100_000) }
            if process.isRunning { process.terminate() }
            process.waitUntilExit()
        }
        if !endpoint.isEmpty && heard.contains("ITERMWORKS") {
            print("PASS: \(name)"); passed += 1
        } else {
            print("FAIL: \(name)")
            print("      [iterm must name the endpoint it made and the device must carry bytes to it]")
            print("      endpoint: \(endpoint.isEmpty ? "(none reported)" : endpoint), heard: \(heard.isEmpty ? "(nothing)" : heard.trimmingCharacters(in: .whitespacesAndNewlines))")
            failed += 1
        }
    }
}

// -- XOFF halts output; input keeps being taken ------------------------------
// ReadCharsFromTerminal used to return "not ready" whenever holdScreen was set,
// so a terminal paused with ^S also stopped accepting typing: keystrokes piled
// up in inBuf and every one of them ran at once on ^Q. The Technical I/O Manual
// V2.4 (PD_XOFF) halts OUTPUT only, and SS_Ready never had the test either
// (DevReadyTerminal), so the device reported characters available while the
// read refused to hand them over.
//
// Proof is a side effect that does NOT touch the held screen: a command typed
// during the hold writes a file, and the file must appear BEFORE the XON. That
// ordering is the whole assertion -- with the defect present the file appears
// too, just late, so a bare "does it exist at the end" check passes either way.
//
// Driven over a real pty rather than through os9(): os9() writes the whole
// command body in one go, so the XOFF byte is drained into inBuf at an
// unpredictable point -- possibly before the shell has even printed the prompt
// it then parks on -- and the run's outcome stops depending on the thing under
// test. Real timing is the point here, as it is for the raw-mode test below.
// -- an XOFF held BEFORE a built-in runs must not eat its output ------------
// An INTERNAL COMMAND is host C running straight through: no emulated PC to
// rewind, so ConsoleOut's normal backpressure (park the writer in pWaitWrite)
// has nobody to suspend and the rest of its output went nowhere. Measured
// before the fix: `dhelp` with ^S typed at the prompt first produced 11 bytes
// of 1184, and the missing 1173 never arrived even after XON.
//
// Typing ^S DURING the output does not show this -- the command never yields
// to the input pump, so the XOFF is not seen until it has already finished.
// The hold has to be in place BEFORE the command starts, which is why earlier
// hunts using `mount -?` mid-output came back clean.
//
// Both halves are asserted, because a "fix" that simply ignored the hold would
// pass the second alone: almost nothing may arrive WHILE held (XOFF halts
// output -- Technical I/O Manual V2.4, PD_XOFF), and everything must arrive
// after XON. Paced on purpose: -r has no FIFO and cannot show it.
let xoffIntUtilName = "console: an XOFF held before a built-in does not eat its output"
let runXoffIntUtil  = filter.isEmpty || xoffIntUtilName.localizedCaseInsensitiveContains(filter)

if runXoffIntUtil && !containerized {
    if let (master, slave, _) = makePTY() {
        let process = Process()
        process.executableURL       = execURL
        process.arguments           = [shellArg]        // NO -r: pacing is the point
        process.currentDirectoryURL = URL(fileURLWithPath: scratchDisk)
        process.environment         = ["OS9DISK": diskPath, "OS9STOP": "1"].merging(inheritedByChildren) { mine, _ in mine }
        let slaveHandle = FileHandle(fileDescriptor: slave, closeOnDealloc: false)
        process.standardInput  = slaveHandle
        process.standardOutput = slaveHandle
        process.standardError  = slaveHandle

        var duringHold = -1
        var afterXon   = -1

        if (try? process.run()) != nil {
            func send(_ s: String) { var b = Array(s.utf8); _ = write(master, &b, b.count) }
            func drain(_ seconds: Double, into total: inout Int) {
                let end = Date().addingTimeInterval(seconds)
                var buf = [UInt8](repeating: 0, count: 65536)
                while Date() < end {
                    var fds = pollfd(fd: master, events: Int16(POLLIN), revents: 0)
                    if poll(&fds, 1, 200) > 0 {
                        let n = read(master, &buf, buf.count)
                        if n <= 0 { return }
                        total += n
                    }
                }
            }
            var discard = 0
            drain(2.0, into: &discard)          // settle, then ignore the banner
            send("\u{13}")                      // XOFF *before* the command
            usleep(400_000)
            send("dhelp\n")
            duringHold = 0
            drain(5.0, into: &duringHold)       // must stay ~0: the hold is real
            send("\u{11}")                      // XON
            afterXon = duringHold
            drain(4.0, into: &afterXon)         // the whole listing must land here
            send("\u{1B}\n\u{04}\n")
            usleep(500_000)
            if process.isRunning { process.terminate() }
            process.waitUntilExit()
        }
        close(master); close(slave)

        // dhelp is ~1184 bytes; the echo of the command line is the only thing
        // allowed through while held (echo is best-effort and unparkable --
        // DECISIONS-68k.md), so allow a few bytes but not the listing.
        if duringHold >= 0 && duringHold < 60 && afterXon > 900 {
            print("PASS: \(xoffIntUtilName)"); passed += 1
        } else {
            print("FAIL: \(xoffIntUtilName)")
            print("      [held: <60 bytes during, >900 after XON]")
            print("      during hold: \(duringHold)   after XON: \(afterXon)")
            failed += 1
        }
    }
}

// -- a hold nobody lifts stops a built-in once, not once per character --------
// A built-in cannot park, so it waits in place for a hold to lift -- and while
// it waits, every process on every terminal is stopped. That wait was two
// minutes, and it was taken again before every character: ^S with nobody left
// to type ^Q froze the whole emulator for hours behind a single `dhelp` (found
// by the pre-release review). Now the wait is BUILTIN_HOLD_MS (10s), once per
// hold. Both halves: the hold is honoured at first, and the listing then
// arrives whole although XON never comes -- and in order: written around the
// still-held queue, its newer bytes went out ahead of the older ones.
let holdOnceName = "console: a built-in waits out a hold nobody lifts once, then writes"
if (filter.isEmpty || holdOnceName.localizedCaseInsensitiveContains(filter)) && !containerized {
    if let (ptyMain, ptyTerminal, _) = makePTY() {
        let process = Process()
        process.executableURL       = execURL
        process.arguments           = [shellArg]        // NO -r: pacing is the point
        process.currentDirectoryURL = URL(fileURLWithPath: scratchDisk)
        process.environment         = ["OS9DISK": diskPath, "OS9STOP": "1"]
                                      .merging(inheritedByChildren) { mine, _ in mine }
        let terminalHandle = FileHandle(fileDescriptor: ptyTerminal, closeOnDealloc: false)
        process.standardInput  = terminalHandle
        process.standardOutput = terminalHandle
        process.standardError  = terminalHandle

        var early = -1
        var later = -1
        var text  = Data()

        if (try? process.run()) != nil {
            func send(_ keys: String) { var bytes = Array(keys.utf8); _ = write(ptyMain, &bytes, bytes.count) }
            func drain(_ seconds: Double, into total: inout Int) {
                let end = Date().addingTimeInterval(seconds)
                var buf = [UInt8](repeating: 0, count: 65536)
                while Date() < end {
                    var fds = pollfd(fd: ptyMain, events: Int16(POLLIN), revents: 0)
                    if poll(&fds, 1, 200) > 0 {
                        let count = read(ptyMain, &buf, buf.count)
                        if count <= 0 { return }
                        total += count
                        text.append(contentsOf: buf[0..<count])
                    }
                }
            }
            var discard = 0
            drain(2.0, into: &discard)          // settle, then ignore the banner
            text = Data()
            send("\u{13}")                      // XOFF, and never an XON
            usleep(400_000)
            send("dhelp\n")
            early = 0
            drain(5.0, into: &early)            // inside the wait: held
            later = early
            drain(14.0, into: &later)           // past it: the whole listing
            send("\u{11}\u{1B}\n\u{04}\n")
            usleep(500_000)
            if process.isRunning { process.terminate() }
            process.waitUntilExit()
        }
        close(ptyMain); close(ptyTerminal)

        // dhelp is ~1184 bytes; the command line's echo may pass while held
        let head = text.range(of: Data("Debug and Stop masks".utf8))?.lowerBound
        let tail = text.range(of: Data("insider information".utf8))?.lowerBound
        var inOrder = false
        if let head, let tail { inOrder = head < tail }
        if early >= 0 && early < 60 && later > 900 && inOrder {
            print("PASS: \(holdOnceName)"); passed += 1
        } else {
            print("FAIL: \(holdOnceName)")
            print("      [held <60 bytes for 5s, then >900 by 19s with no XON, first line first]")
            print("      first 5s: \(early)   by 19s: \(later)   in order: \(inOrder)")
            failed += 1
        }
    }
}

// -- ^C behind a full type-ahead buffer still aborts ---------------------------
// The console readers stopped reading the host once the 256-byte input buffer
// was full, and KeyToBuffer refused a full buffer before it looked at the
// special keys: with 300 characters typed ahead of a listing, ^C was never even
// read and the listing ran to its end. Keys past a full buffer now wait in a
// type-ahead queue, and the special ones act the moment they arrive (found by
// the pre-release character-I/O review).
let ctrlCAheadName = "console: ^C typed behind 300 characters of type-ahead still stops a listing"
if (filter.isEmpty || ctrlCAheadName.localizedCaseInsensitiveContains(filter)) && !containerized {
    if let (controller, device, _) = makePTY() {
        let process = Process()
        process.executableURL       = execURL
        process.arguments           = [shellArg]        // paced: the listing takes seconds
        process.currentDirectoryURL = URL(fileURLWithPath: scratchDisk)
        process.environment         = ["OS9DISK": diskPath].merging(inheritedByChildren) { mine, _ in mine }
        let deviceHandle = FileHandle(fileDescriptor: device, closeOnDealloc: false)
        process.standardInput  = deviceHandle
        process.standardOutput = deviceHandle
        process.standardError  = deviceHandle

        var afterAbort = -1
        if (try? process.run()) != nil {
            func send(_ text: String) { var bytes = Array(text.utf8); _ = write(controller, &bytes, bytes.count) }
            func drain(_ seconds: Double, into total: inout Int) {
                let end = Date().addingTimeInterval(seconds)
                var buf = [UInt8](repeating: 0, count: 65536)
                while Date() < end {
                    var fds = pollfd(fd: controller, events: Int16(POLLIN), revents: 0)
                    if poll(&fds, 1, 200) > 0 {
                        let count = read(controller, &buf, buf.count)
                        if count <= 0 { return }
                        total += count
                    }
                }
            }
            var discard = 0
            drain(2.0, into: &discard)
            send("list /dd/SYS/errmsg\n")
            drain(1.0, into: &discard)
            send(String(repeating: "x", count: 300))   // type-ahead the listing never reads
            drain(0.5, into: &discard)
            send("\u{03}")                              // ^C
            afterAbort = 0
            drain(6.0, into: &afterAbort)
            send("\u{1B}\n\u{04}\n")
            usleep(500_000)
            if process.isRunning { process.terminate() }
            process.waitUntilExit()
        }
        close(controller); close(device)

        // errmsg is about 13 KB; stopped, only the FIFO's tail and a prompt remain
        if afterAbort >= 0 && afterAbort < 2000 {
            print("PASS: \(ctrlCAheadName)"); passed += 1
        } else {
            print("FAIL: \(ctrlCAheadName)")
            print("      bytes in the 6 s after ^C: \(afterAbort) (the listing should have stopped)")
            failed += 1
        }
    }
}

// -- an echo waiting behind ^S does not spin, and ^Q releases it --------------
// A reader's echo goes through the terminal's paced queue. Held by ^S with that
// queue full, the echo waited for room in a loop that never slept, because a
// held device sets no deadline: a whole core until ^Q (found by the pre-release
// character-I/O review).
let echoHoldName = "console: an echo waiting behind ^S costs almost no CPU, and ^Q lets it through"
if (filter.isEmpty || echoHoldName.localizedCaseInsensitiveContains(filter)) && !containerized {
    if let (controller, device, _) = makePTY() {
        let process = Process()
        process.executableURL       = execURL
        process.arguments           = [shellArg]
        process.currentDirectoryURL = URL(fileURLWithPath: scratchDisk)
        process.environment         = ["OS9DISK": diskPath].merging(inheritedByChildren) { mine, _ in mine }
        let deviceHandle = FileHandle(fileDescriptor: device, closeOnDealloc: false)
        process.standardInput  = deviceHandle
        process.standardOutput = deviceHandle
        process.standardError  = deviceHandle

        func cpuSeconds(_ pid: Int32) -> Double {
            let lister = Process()
            lister.executableURL = URL(fileURLWithPath: "/bin/ps")
            lister.arguments = ["-o", "time=", "-p", String(pid)]
            let pipe = Pipe()
            lister.standardOutput = pipe
            guard (try? lister.run()) != nil else { return -1 }
            lister.waitUntilExit()
            let text = String(bytes: pipe.fileHandleForReading.readDataToEndOfFile(), encoding: .utf8) ?? ""
            let parts = text.trimmingCharacters(in: .whitespacesAndNewlines).split(separator: ":")
            let seconds = parts.reduce(0.0) { $0 * 60 + (Double($1) ?? 0) }
            return parts.isEmpty ? -1 : seconds
        }

        var spent = -1.0
        var afterXon = -1
        if (try? process.run()) != nil {
            func send(_ text: String) { var bytes = Array(text.utf8); _ = write(controller, &bytes, bytes.count) }
            func drain(_ seconds: Double, into total: inout Int) {
                let end = Date().addingTimeInterval(seconds)
                var buf = [UInt8](repeating: 0, count: 65536)
                while Date() < end {
                    var fds = pollfd(fd: controller, events: Int16(POLLIN), revents: 0)
                    if poll(&fds, 1, 200) > 0 {
                        let count = read(controller, &buf, buf.count)
                        if count <= 0 { return }
                        total += count
                    }
                }
            }
            var discard = 0
            drain(2.0, into: &discard)
            send("list /dd/SYS/errmsg &\n")
            drain(0.5, into: &discard)
            send("\u{13}")                              // ^S: the queue fills and stays full
            drain(1.0, into: &discard)
            send(String(repeating: "a", count: 200))     // echoes that find no room
            drain(0.5, into: &discard)
            let before = cpuSeconds(process.processIdentifier)
            drain(3.0, into: &discard)
            let after = cpuSeconds(process.processIdentifier)
            if before >= 0 && after >= 0 { spent = after - before }
            send("\u{11}")                              // ^Q
            afterXon = 0
            drain(4.0, into: &afterXon)
            send("\u{03}\n\u{1B}\n\u{04}\n")
            usleep(500_000)
            if process.isRunning { process.terminate() }
            process.waitUntilExit()
        }
        close(controller); close(device)

        if spent >= 0 && spent < 1.0 && afterXon > 500 {
            print("PASS: \(echoHoldName)"); passed += 1
        } else {
            print("FAIL: \(echoHoldName)")
            print("      CPU while held: \(spent) s of 3 (want < 1), bytes after ^Q: \(afterXon) (want > 500)")
            failed += 1
        }
    }
}

// -- page pause stops output and the key that resumes it is not typed --------
// "Page pause (tmode pause): output halts after each full screen until a key is
// pressed" (the os9-dev skill, after the v2.4 manuals). A full page only ended
// the write early, so output never stopped; one line count served every
// terminal; and the next key typed was swallowed wherever it went -- `echo abc`
// then ran as `cho abc` (found by the pre-release character-I/O review). Paced,
// because the first fix held the queue as well as the writer, and the page's
// last lines then stayed hidden while the pause asked for a key.
let pagePauseName = "console: tmode pause stops a listing at each page, and the resuming key is not typed"
if (filter.isEmpty || pagePauseName.localizedCaseInsensitiveContains(filter)) && !containerized {
    let pageFile = scratchDisk + "/pagefile"
    let lines = (1...20).map { String(format: "LINE%02d", $0) }.joined(separator: "\r") + "\r"
    try? lines.write(toFile: pageFile, atomically: true, encoding: .utf8)
    if let (controller, device, _) = makePTY() {
        let process = Process()
        process.executableURL       = execURL
        process.arguments           = [shellArg]   // paced: the page's own lines must still drain
        process.currentDirectoryURL = URL(fileURLWithPath: scratchDisk)
        let deviceEnv = ["OS9DISK": diskPath, "OS9H\(scratchDev.dropFirst())": scratchDisk]
        process.environment         = deviceEnv.merging(inheritedByChildren) { mine, _ in mine }
        let deviceHandle = FileHandle(fileDescriptor: device, closeOnDealloc: false)
        process.standardInput  = deviceHandle
        process.standardOutput = deviceHandle
        process.standardError  = deviceHandle

        var firstPage = ""
        var secondPage = ""
        var ending = ""
        if (try? process.run()) != nil {
            func send(_ text: String) { var bytes = Array(text.utf8); _ = write(controller, &bytes, bytes.count) }
            func collect(_ seconds: Double) -> String {
                var got = [UInt8]()
                let end = Date().addingTimeInterval(seconds)
                var buf = [UInt8](repeating: 0, count: 65536)
                while Date() < end {
                    var fds = pollfd(fd: controller, events: Int16(POLLIN), revents: 0)
                    if poll(&fds, 1, 200) > 0 {
                        let count = read(controller, &buf, buf.count)
                        if count <= 0 { break }
                        got += buf[0..<count]
                    }
                }
                return String(bytes: got, encoding: .isoLatin1) ?? ""
            }
            _ = collect(2.0)
            send("tmode pause pag=5\n")
            _ = collect(1.0)
            send("list /\(scratchDev)/pagefile\n")
            firstPage = collect(1.5)
            send(" ")
            secondPage = collect(1.5)
            for _ in 0..<3 {                    // one key per page: lines 11-15, 16-20, the prompt
                send(" ")
                _ = collect(1.0)
            }
            send("tmode nopause\n")
            _ = collect(1.0)
            send("echo abc\n")
            ending = collect(1.5)
            send("\u{1B}\n\u{04}\n")
            usleep(500_000)
            if process.isRunning { process.terminate() }
            process.waitUntilExit()
        }
        close(controller); close(device)

        let stopped = firstPage.contains("LINE05") && !firstPage.contains("LINE07")
        let resumed = secondPage.contains("LINE08") && !secondPage.contains("LINE13")
        // `echo abc` prints a line of its own; run as `cho abc` it is error 216
        let printed = ending.components(separatedBy: .newlines)
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
        let typed = printed.contains("abc") && !ending.contains("216")
        if stopped && resumed && typed {
            print("PASS: \(pagePauseName)"); passed += 1
        } else {
            print("FAIL: \(pagePauseName)")
            print("      stopped at page 1: \(stopped), next page on a key: \(resumed), echo abc intact: \(typed)")
            failed += 1
        }
    }
    try? FileManager.default.removeItem(atPath: pageFile)
}

// -- a /tN that takes part of a line ending gets the rest once, not again ----
// A line ending (CR, auto-LF, PD_NUL pad bytes) goes to a bound /tN as one
// unit. When the pty took only part of it, the writer parked and on resume
// sent the WHOLE unit again, duplicating its CR, LF or pad bytes (found by the
// pre-release character-I/O review). Here the reader stays away until the pty
// buffer is full, so partial writes are certain, then drains everything. Each
// I$WritLn is handed more than its record, too: a write resumed after a partial
// line ending carried on past the record into those bytes (a later review).
let tnUnitName = "hostterm: a line ending the /tN takes only part of is finished, not sent twice"
if (filter.isEmpty || tnUnitName.localizedCaseInsensitiveContains(filter)) && !containerized {
    let unitAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit equ $06", "I$Open equ $84", "I$GetStt equ $8D", "I$SetStt equ $8E",
        "I$WritLn equ $8C", "I$Close equ $8F",
        "  psect mtnul,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "  vsect", "opt: ds.b 128", "  ends",
        "start:",
        "  lea term(pc),a0", "  moveq #2,d0", "  OS9 I$Open", "  bcs.s fail", "  move.w d0,d7",
        "  moveq #0,d1", "  lea opt(a6),a0", "  OS9 I$GetStt", "  bcs.s fail",
        "  move.b #100,opt+6(a6)", "  move.b #1,opt+5(a6)",          // PD_NUL 100, PD_ALF on
        "  move.w d7,d0", "  moveq #0,d1", "  lea opt(a6),a0", "  OS9 I$SetStt", "  bcs.s fail",
        "  moveq #39,d6",
        "more:", "  move.w d7,d0", "  lea line(pc),a0", "  moveq #40,d1", "  OS9 I$WritLn", "  bcs.s fail",
        "  dbra d6,more",
        "  move.w d7,d0", "  OS9 I$Close",
        "  moveq #0,d1",
        "fail:", "  OS9 F$Exit",
        "term: dc.b \"/t1\",0",
        // a record, and after its CR bytes that are not part of it
        "line: dc.b \"LINE-AB\",13,\"XXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX\"",
        "  ends", ""
    ].joined(separator: "\r")
    try? unitAsm.write(toFile: scratchDisk + "/mtnul.a", atomically: true, encoding: .utf8)
    _ = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
             "r68 /h5/mtnul.a -o=/h5/mtnul.r", "l68 /h5/mtnul.r -o=/h5/mtnul"], timeout: 60)

    if let (controller, device, deviceName) = makePTY() {
        let received = NSMutableData()
        let readerDone = DispatchSemaphore(value: 0)
        DispatchQueue.global().async {
            Thread.sleep(forTimeInterval: 2.0)          // let the pty fill: partial writes follow
            var buf = [UInt8](repeating: 0, count: 65536)
            var quiet = 0
            while quiet < 15 {                          // until 3 s pass with nothing new
                var fds = pollfd(fd: controller, events: Int16(POLLIN), revents: 0)
                if poll(&fds, 1, 200) > 0 {
                    let count = read(controller, &buf, buf.count)
                    if count <= 0 { break }
                    received.append(buf, length: count)
                    quiet = 0
                } else { quiet += 1 }
            }
            readerDone.signal()
        }
        _ = os9(["/h5/mtnul"], timeout: 60, env: ["OS9T1": deviceName], holdOpen: 4.0)
        _ = readerDone.wait(timeout: .now() + 30)
        close(controller); close(device)

        let bytes = [UInt8](received as Data)
        let returns = bytes.filter { $0 == 13 }.count
        let pads = bytes.filter { $0 == 0 }.count
        let beyond = bytes.filter { $0 == 0x58 }.count   // 'X': past the record's end
        if returns == 40 && pads == 4000 && beyond == 0 {
            print("PASS: \(tnUnitName)"); passed += 1
        } else {
            print("FAIL: \(tnUnitName)")
            print("      CRs: \(returns) (want 40), NULs: \(pads) (want 4000), past the record: \(beyond) (want 0)")
            failed += 1
        }
    }
    for leftover in ["mtnul.a", "mtnul.r", "mtnul"] {
        try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
    }
}

// -- a write to a /tN whose far end has gone fails, it does not park forever --
// A write the host refused outright (EIO on a hung-up pty) was treated like
// one that would block: parked and retried for ever, the writer stuck and the
// terminal held against every other program. It now ends with E$Write
// (found by the pre-release review of the console model).
let tnGoneName = "hostterm: a write to a /tN whose far end has gone ends E$Write, not a park for ever"
if (filter.isEmpty || tnGoneName.localizedCaseInsensitiveContains(filter)) && !containerized {
    let goneAsm = [
        "  use /dd/DEFS/oskdefs.d",
        "F$Exit equ $06", "F$Sleep equ $0A", "I$Open equ $84", "I$WritLn equ $8C",
        "  psect mtgone,(Prgrm<<8)+Objct,(ReEnt<<8)+0,1,1024,start",
        "start:",
        "  lea term(pc),a0", "  moveq #2,d0", "  OS9 I$Open", "  bcs.s fail", "  move.w d0,d7",
        "  move.l #200,d0", "  OS9 F$Sleep",                     // the host closes its end meanwhile
        "  move.w d7,d0", "  lea line(pc),a0", "  moveq #6,d1", "  OS9 I$WritLn",
        "  bcc.s wrote", "  cmpi.w #245,d1", "  bne.s other",
        "  lea gonem(pc),a0", "  bra.s tell",
        "wrote:", "  lea wrotem(pc),a0", "  bra.s tell",
        "other:", "  lea otherm(pc),a0",
        "tell:", "  moveq #2,d0", "  moveq #40,d1", "  OS9 I$WritLn",
        "  moveq #0,d1",
        "fail:", "  OS9 F$Exit",
        "term: dc.b \"/t1\",0", "line: dc.b \"HELLO\",13",
        "gonem: dc.b \"WRITE ENDED E$WRITE\",13", "wrotem: dc.b \"WRITE SAID IT WROTE\",13",
        "otherm: dc.b \"WRITE ENDED ANOTHER ERROR\",13",
        "  ends", ""
    ].joined(separator: "\r")
    try? goneAsm.write(toFile: scratchDisk + "/mtgone.a", atomically: true, encoding: .utf8)
    _ = os9(["load /dd/CMDS/r68 /dd/CMDS/l68",
             "r68 /h5/mtgone.a -o=/h5/mtgone.r", "l68 /h5/mtgone.r -o=/h5/mtgone"], timeout: 60)
    if let (controller, device, deviceName) = makePTY() {
        DispatchQueue.global().asyncAfter(deadline: .now() + 0.8) { close(controller) }
        let out = os9(["/h5/mtgone"], timeout: 30, env: ["OS9T1": deviceName])
        close(device)
        if out.contains("WRITE ENDED E$WRITE") {
            print("PASS: \(tnGoneName)"); passed += 1
        } else {
            print("FAIL: \(tnGoneName)")
            let seen = out.split(whereSeparator: \.isNewline)
                .filter { $0.contains("WRITE") || $0.contains("timed out") }
            print("      saw: \(seen)")
            failed += 1
        }
    }
    for leftover in ["mtgone.a", "mtgone.r", "mtgone"] {
        try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
    }
}

// -- a built-in's output to a slow /tN arrives whole ---------------------------
// A built-in cannot park, and its output to a bound /tN went through a path
// that dropped every byte the pty would not take at once: with the reader a
// moment late, `dhelp >/t1` arrived with holes. It now waits (bounded) for the
// pty to take each unit (found by the pre-release review of the console model).
let tnBuiltinName = "hostterm: a built-in's output to a /tN whose reader is late arrives whole"
if (filter.isEmpty || tnBuiltinName.localizedCaseInsensitiveContains(filter)) && !containerized {
    func dhelpBytes(readerDelay: Double) -> Int {
        guard let (controller, device, deviceName) = makePTY() else { return -1 }
        var total = 0
        let done = DispatchSemaphore(value: 0)
        DispatchQueue.global().async {
            Thread.sleep(forTimeInterval: readerDelay)
            var buf = [UInt8](repeating: 0, count: 65536)
            var quiet = 0
            while quiet < 15 {
                var fds = pollfd(fd: controller, events: Int16(POLLIN), revents: 0)
                if poll(&fds, 1, 200) > 0 {
                    let count = read(controller, &buf, buf.count)
                    if count <= 0 { break }
                    total += count
                    quiet = 0
                } else { quiet += 1 }
            }
            done.signal()
        }
        _ = os9(["dhelp >/t1"], timeout: 30, env: ["OS9T1": deviceName], holdOpen: 3.0)
        _ = done.wait(timeout: .now() + 20)
        close(controller); close(device)
        return total
    }
    let prompt = dhelpBytes(readerDelay: 0)
    let late = dhelpBytes(readerDelay: 1.5)
    if prompt > 900 && late == prompt {
        print("PASS: \(tnBuiltinName)"); passed += 1
    } else {
        print("FAIL: \(tnBuiltinName)")
        print("      bytes with a prompt reader: \(prompt), with a late one: \(late) (want equal, > 900)")
        failed += 1
    }
}

let xoffInputName = "console: XOFF halts output but input is still taken"
let runXoffInput  = filter.isEmpty || xoffInputName.localizedCaseInsensitiveContains(filter)

if runXoffInput && !containerized {
    if let (master, slave, _) = makePTY() {
        let witness = scratchDisk + "/xoffinput"
        try? FileManager.default.removeItem(atPath: witness)

        let collector = BackpressureCollector()
        let stopped   = DispatchSemaphore(value: 0)
        _ = startDrainThread(master, collector, stopped)

        let process = Process()
        process.executableURL       = execURL
        process.arguments           = ["-r", shellArg]
        process.currentDirectoryURL = URL(fileURLWithPath: scratchDisk)
        process.environment         = ["OS9DISK": diskPath,
                                       "OS9H\(scratchDev.dropFirst())": scratchDisk].merging(inheritedByChildren) { mine, _ in mine }
        let slaveHandle = FileHandle(fileDescriptor: slave, closeOnDealloc: false)
        process.standardInput  = slaveHandle
        process.standardOutput = slaveHandle
        process.standardError  = slaveHandle

        var ranDuringHold = false
        var sizeAtXon     = -1

        if (try? process.run()) != nil {
            func send(_ s: String) {
                var b = Array(s.utf8); _ = write(master, &b, b.count)
            }
            // Settle, then force a fresh prompt so the shell is sitting in a
            // READ when the XOFF lands -- not parked mid-prompt, which would
            // stall it for a reason that has nothing to do with the read gate.
            send("chx \(sdkCmds)\nload math cio\n")
            usleep(2_000_000)
            send("\n")
            usleep(1_000_000)

            send("\u{13}")                            // XOFF: screen held from here
            usleep(300_000)
            send("dump /dd/CMDS/cc >\(scratch)/xoffinput\n")

            // Poll for the side effect while the screen is still held.
            for _ in 0..<80 {
                if let a = try? FileManager.default.attributesOfItem(atPath: witness),
                   let sz = a[.size] as? Int, sz > 0 { ranDuringHold = true; break }
                usleep(100_000)
            }
            sizeAtXon = (try? FileManager.default.attributesOfItem(atPath: witness))
                        .flatMap { $0[.size] as? Int } ?? -1

            send("\u{11}")                            // XON: release
            usleep(500_000)
            send("\u{1B}\n\u{04}\n")
            usleep(1_000_000)
            if process.isRunning { process.terminate() }
            process.waitUntilExit()
        }

        collector.requestStop(); stopped.wait()
        close(master); close(slave)
        try? FileManager.default.removeItem(atPath: witness)

        if ranDuringHold {
            print("PASS: \(xoffInputName)"); passed += 1
        } else {
            print("FAIL: \(xoffInputName)")
            print("      [a command typed during the hold did not run until XON --")
            print("       the read path is gating on holdScreen again]")
            print("      witness size when XON was sent: \(sizeAtXon)")
            failed += 1
        }
    } else {
        print("FAIL: console: could not create a pty for the XOFF input test")
        failed += 1
    }
}

// -- an abort key reaches a shell whose child computes without system calls --
// A key's signal is sent outside any system call, so it waits in the signal
// queue, and that queue was flushed only after the CURRENT process made a
// call. A child computing with no calls never makes one, so Ctrl-E and Ctrl-C
// went nowhere: the shell (the terminal's last writer, whom the key signals)
// was never woken, and the machine could not be stopped from the keyboard --
// measured on macOS with the tick on, on this build and the release before.
// The tick now flushes the queue when it ends a slice. What each key then does
// is the shell's business, as the manual describes: Ctrl-E kills the child,
// Ctrl-C moves one that has written nothing to the background. Either way the
// shell takes the next command, which is what is checked -- a witness file
// written by a command typed after the key. The child loops forever, so a
// build that drops the key fails outright rather than by timing. Needs the
// tick: with it off nothing takes the CPU from the child at all.
func abortReachesShellOfComputingChild(key: UInt8, witnessName: String) -> Bool? {
    guard let (master, slave, _) = makePTY() else { return nil }
    let spinAsm = ["  psect kspin,$0101,$8001,0,512,start", "start:", "  bra.s start", "  ends", ""]
        .joined(separator: "\r")
    let witness = scratchDisk + "/" + witnessName
    try? spinAsm.write(toFile: scratchDisk + "/kspin.a", atomically: true, encoding: .utf8)
    for stale in [witnessName, "kbuilt", "kready"] {
        try? FileManager.default.removeItem(atPath: scratchDisk + "/" + stale)
    }

    let collector = BackpressureCollector()
    let stopped   = DispatchSemaphore(value: 0)
    _ = startDrainThread(master, collector, stopped)

    let process = Process()
    process.executableURL       = execURL
    process.arguments           = ["-r", shellArg]
    process.currentDirectoryURL = URL(fileURLWithPath: scratchDisk)
    process.environment         = ["OS9DISK": diskPath,
                                   "OS9H\(scratchDev.dropFirst())": scratchDisk].merging(inheritedByChildren) { mine, _ in mine }
    let slaveHandle = FileHandle(fileDescriptor: slave, closeOnDealloc: false)
    process.standardInput  = slaveHandle
    process.standardOutput = slaveHandle
    process.standardError  = slaveHandle

    var reached = false
    if (try? process.run()) != nil {
        func send(_ s: String) { var b = Array(s.utf8); _ = write(master, &b, b.count) }
        // Each step is known finished by a marker the shell writes after it:
        // a module file exists before its linker is done, and a key typed while
        // l68 still runs kills l68 instead (it writes, so it is the last writer)
        // -- which made the first draft of this test pass on a broken build.
        func waitFor(_ marker: String) {
            for _ in 0..<150 where !FileManager.default.fileExists(atPath: scratchDisk + "/" + marker) {
                usleep(100_000)
            }
        }
        // Nothing is typed before the first prompt: setting the terminal up
        // flushes pending input (TCSAFLUSH), so earlier keystrokes are lost.
        for _ in 0..<100 where !String(decoding: collector.snapshot(), as: UTF8.self).contains("$ ") {
            usleep(100_000)
        }
        send("chx \(sdkCmds)\nload \(sdkCmds)/r68 \(sdkCmds)/l68\n")
        send("r68 \(scratch)/kspin.a -o=\(scratch)/kspin.r\nl68 \(scratch)/kspin.r -o=\(scratch)/kspin\n")
        send("echo built >\(scratch)/kbuilt\n")
        waitFor("kbuilt")
        send("echo ready >\(scratch)/kready; \(scratch)/kspin\n")
        waitFor("kready")
        usleep(1_000_000)
        var k = key; _ = write(master, &k, 1)
        usleep(500_000)
        send("echo reached >\(scratch)/\(witnessName)\n")
        for _ in 0..<50 where !reached {
            if let a = try? FileManager.default.attributesOfItem(atPath: witness),
               let sz = a[.size] as? Int, sz > 0 { reached = true }
            else { usleep(100_000) }
        }
        send("\u{05}")                                // a backgrounded child is still spinning
        process.terminate()
        process.waitUntilExit()
    }
    collector.requestStop(); stopped.wait()
    close(master); close(slave)
    for leftover in ["kspin.a", "kspin.r", "kspin", "kbuilt", "kready", witnessName] {
        try? FileManager.default.removeItem(atPath: scratchDisk + "/" + leftover)
    }
    return reached
}

for (keyName, key) in [("Ctrl-E", UInt8(0x05)), ("Ctrl-C", UInt8(0x03))] {
    let name = "console: \(keyName) reaches the shell while its child computes without calls"
    guard filter.isEmpty || name.localizedCaseInsensitiveContains(filter) else { continue }
    if containerized {
        print("SKIP: \(name) (needs a pty on the host)")
    } else if (ProcessInfo.processInfo.environment["OS9_FLAGS"] ?? "").contains("-q") {
        print("SKIP: \(name) (the system tick is off, so nothing takes the CPU from the child)")
    } else if let reached = abortReachesShellOfComputingChild(key: key, witnessName: "abortwit") {
        if reached {
            print("PASS: \(name)"); passed += 1
        } else {
            print("FAIL: \(name)")
            print("      [a command typed after the key never ran: the shell was not woken]")
            failed += 1
        }
    } else {
        print("FAIL: console: could not create a pty for the \(keyName) test")
        failed += 1
    }
}

// -- the console's own ^S/^Q belong to OS-9, not to the host tty -------------
// setup_term() turned off ICANON, ECHO, ISIG and OPOST but left IXON on, so the
// HOST tty consumed ^S before os9exec ever read it and stopped accepting output.
// The emulator then blocked inside write(2) -- with the whole 68k machine on one
// thread, that froze every OS-9 process, the system tick and every pending
// alarm until ^Q, which is what "^S stops everything" meant. Measured on a live
// session: 0.65s of CPU per 5s free-running, 0.02s per 5s during the ^S.
//
// Asserted on the tty's own flags rather than by driving a paused session,
// because the fix IS the flag: with IXON clear the byte reaches KeyToBuffer and
// the /tN tests above cover what OS-9 then does with it. The rest of the recipe
// is checked at the same time so a future edit cannot quietly drop one.
//
// This needs a real tty on fd 0 -- os9(), which pipes stdin, skips setup_term()
// entirely (isatty(0) is false), so no test using it could ever see this.
let consoleRawName = "console: the host tty hands ^S/^Q to OS-9 instead of eating them"
let runConsoleRaw  = filter.isEmpty || consoleRawName.localizedCaseInsensitiveContains(filter)

if runConsoleRaw && !containerized {
    if let (master, slave, _) = makePTY() {
        var before = termios()
        _ = tcgetattr(slave, &before)

        let process = Process()
        process.executableURL     = execURL
        process.arguments         = ["-r", shellArg]
        process.environment       = ["OS9DISK": diskPath].merging(inheritedByChildren) { mine, _ in mine }
        process.currentDirectoryURL = URL(fileURLWithPath: scratchDisk)
        let slaveHandle = FileHandle(fileDescriptor: slave, closeOnDealloc: false)
        process.standardInput  = slaveHandle
        process.standardOutput = slaveHandle
        process.standardError  = slaveHandle

        var sawRaw = false
        if (try? process.run()) != nil {
            // Poll rather than sleep a fixed interval: setup_term() runs early,
            // but "early" is not a guarantee worth hard-coding. Drain the master
            // while polling: the banner comes first, and a pty holds only about
            // 1 KB on macOS, so anything that lengthens it (a sanitizer build's
            // own warnings did) blocks os9exec in write() before it ever
            // reaches setup_term(), and the test would blame the tty setup.
            let flags = fcntl(master, F_GETFL)
            _ = fcntl(master, F_SETFL, flags | O_NONBLOCK)
            var drain = [UInt8](repeating: 0, count: 4096)
            for _ in 0..<100 {
                while read(master, &drain, drain.count) > 0 {}
                var now = termios()
                if tcgetattr(slave, &now) == 0, (now.c_iflag & tcflag_t(IXON)) == 0 {
                    sawRaw = true
                    break
                }
                usleep(50_000)
            }
            var quit = Array("\u{1B}\n\u{04}\n".utf8)
            _ = write(master, &quit, quit.count)
            usleep(500_000)
            if process.isRunning { process.terminate() }
            process.waitUntilExit()
        }

        // The pty is ours; put it back the way we found it for anything later.
        _ = tcsetattr(slave, TCSANOW, &before)
        close(master); close(slave)

        // Guard against the flag having been clear before os9exec touched it:
        // openpty() hands back a cooked tty with IXON ON, so "it was already
        // off" would make the assertion vacuous.
        let startedCooked = (before.c_iflag & tcflag_t(IXON)) != 0

        if sawRaw && startedCooked {
            print("PASS: \(consoleRawName)"); passed += 1
        } else if !startedCooked {
            print("FAIL: \(consoleRawName)")
            print("      [the pty already had IXON off, so this proves nothing]")
            failed += 1
        } else {
            print("FAIL: \(consoleRawName)")
            print("      [IXON still set on the console tty: ^S never reaches OS-9,")
            print("       it stops the host's output and blocks the whole emulator]")
            failed += 1
        }
    } else {
        print("FAIL: console: could not create a pty for the raw-mode test")
        failed += 1
    }
}

// -- -d 0x0002 return lines name the call that was entered --------------------
// funcdispatch.c used to re-derive a return line's name from cp->func at exit
// time. That field is a single slot per process, overloaded three ways
// (function code, exception vector offset, and 0 for "fatal, no handler"), so
// by the time a return printed it could hold something else entirely -- and
// because F$Link IS function code $00, the 0 sentinel printed a whole
// fabricated `<<< F$Link returns:` line, padded with the 0xAAAAAAAx register
// fill pattern as though those values meant something. That is not cosmetic:
// it sent a 2026-07-29 investigation chasing an E_NOTRDY attributed to the
// wrong call. debug_comein now snapshots what it announced.
//
// The BACKGROUNDED job is load-bearing, not decoration. exec_syscall skips its
// own debug_return whenever arbitration is due and re-enters the main loop
// instead, whose top prints a return for whatever cp->func now holds -- so the
// defect needs a second runnable process for arbitration to fall due while an
// internal utility (`procs` here) is mid-run. `&` guarantees that structurally.
//
// Measured against the pre-fix binary, because two tidier-looking versions of
// this test were VACUOUS: bare `procs` passed, and so did bare `free /dd`, even
// though `free /dd` does reproduce when piped in outside this harness. Timing
// alone is not a reliable trigger. This shape failed 3/3 before the fix and
// passes 3/3 after. Do not simplify the command list without re-checking that
// it can still fail.
let tracePairingName = "debug: -d syscall trace pairs every return with its entry"
let runTracePairing  = filter.isEmpty || tracePairingName.localizedCaseInsensitiveContains(filter)

if runTracePairing {
    let trace = os9(["dir /dd/DEFS &", "procs"], flags: ["-d", "0x0002"])

    // ">>>" / "<<<" then one mask char, then "Pid=NN: OS9 <name>". START and
    // INTERCEPT are legitimately unpaired: neither has an entry line of its own.
    var pending: [String: [String]] = [:]
    var unpaired: [(String, String)] = []
    var mismatched: [(String, String, String)] = []

    for line in trace.split(whereSeparator: \.isNewline) {
        for match in line.ranges(of: try! Regex("(>>>|<<<).Pid=([0-9]+): OS9 ([^ ]+)")) {
            let field = String(line[match])
            let isEntry = field.hasPrefix(">>>")
            // "…Pid=NN: OS9 name" -- split off the pid and the name positionally.
            guard let pidPart  = field.split(separator: "=").last?.split(separator: ":").first,
                  let namePart = field.split(separator: " ").last else { continue }
            let pid  = String(pidPart)
            let name = String(namePart)
            if name == "START" || name == "INTERCEPT" { continue }

            if isEntry {
                pending[pid, default: []].append(name)
            } else if let expected = pending[pid]?.popLast() {
                if expected != name { mismatched.append((pid, expected, name)) }
            } else {
                unpaired.append((pid, name))
            }
        }
    }

    // F$Exit never returns, so it is expected to stay open; nothing else should.
    let strayOpen = pending.flatMap { pid, names in
        names.filter { $0 != "F$Exit" }.map { (pid, $0) }
    }

    if trace.contains("Pid=") && unpaired.isEmpty && mismatched.isEmpty && strayOpen.isEmpty {
        print("PASS: \(tracePairingName)"); passed += 1
    } else {
        print("FAIL: \(tracePairingName)")
        if !trace.contains("Pid=") {
            print("      [no trace output at all -- did -d 0x0002 reach the emulator?]")
        }
        for u in unpaired    { print("      return printed with no entry: pid=\(u.0) \(u.1)") }
        for m in mismatched  { print("      pid=\(m.0) entered \(m.1) but return printed as \(m.2)") }
        for s in strayOpen   { print("      entry never returned: pid=\(s.0) \(s.1)") }
        failed += 1
    }
}

// ── An internal command's output survives baud pacing ────────────────────────
// Paced output goes through a 256-byte FIFO. A real OS-9 process that fills it
// is parked in pWaitWrite and resumed, losing nothing; an INTERNAL command is
// host C running straight through and cannot be parked, so everything past the
// full FIFO used to be dropped silently. `mount -?` prints 678 bytes and about
// 262 arrived -- cut mid-word, no newline, the next prompt on the same line,
// and the -k/-v lines missing entirely. That is what put a wrong "mount -? does
// not document -k" entry on the roadmap, and it survived a later check that
// used -r, which turns pacing off and hides the whole thing.
//
// Compared paced against unpaced rather than against a fixed byte count, so the
// test keeps working when the usage text changes. `paced: true` is the point --
// running this with the suite's default -r would assert nothing at all.
let pacedUsageName = "console: an internal command's usage survives baud pacing"
if filter.isEmpty || pacedUsageName.localizedCaseInsensitiveContains(filter) {
    let unpaced = os9(["mount -?"])
    let paced   = os9(["mount -?"], timeout: containerized ? 120 : 60, paced: true)

    func usageLines(_ s: String) -> [String] {
        s.split(whereSeparator: \.isNewline)
         .map { $0.trimmingCharacters(in: .whitespaces) }
         .filter { $0.hasPrefix("-") }
    }
    let u = usageLines(unpaced), p = usageLines(paced)

    // The precondition guards against a vacuous pass: if the usage text ever
    // shrinks below one FIFO, this test stops exercising the overflow at all.
    let bigEnough = unpaced.utf8.count > 256
    if bigEnough && p == u && u.contains(where: { $0.hasPrefix("-k=") }) {
        print("PASS: \(pacedUsageName)")
        passed += 1
    } else {
        print("FAIL: \(pacedUsageName)")
        if !bigEnough { print("      usage text is now under 256 bytes -- this no longer tests the FIFO") }
        else { print("      unpaced \(u.count) option lines, paced \(p.count); paced output is being dropped") }
        failed += 1
    }
}

// ── a module's own offsets are not trusted ───────────────────────────────────
// os9exec patches four modules as they load (init, le0, inetdb, L2) to hand
// the guest the host's network settings. inetdb's adaption reads the position
// of the "hosts" field FROM THE MODULE, at a fixed offset, and used to trust
// whatever it found there.
//
// This disk carries a module that fails that trust: /dd/CMDS/BOOTOBJS/SPF/
// inetdb (SPF, edition 9) is 2008 bytes and declares a hosts offset of
// 16777229 with an end of 116. The size is computed as end-minus-start into a
// uint32_t, so the negative difference becomes ~4.2 billion, and memcpy walks
// off the end of the arena -- a bus error every time, on the plain `load` of a
// module that ships on the system disk. Guest data driving an unchecked
// pointer, which is the worst shape a defect can have here.
//
// The fix bounds-checks every offset the module supplies (and the hardcoded
// ones le0 and L2 write at, which had the same hole in the WRITE direction),
// and leaves a module that is not the expected shape alone -- adapting it is a
// convenience, not a precondition for loading it.
//
// ONE check, asserting both halves. A separate "the module still loads" check
// was written first and then deleted: it passes on master, because the module
// reaches the module directory even though the adaption bus-errors on the way
// -- so it could never fail and proved nothing. The mdir half survives here as
// the vacuity guard it always was, and no bus error alone would pass if the
// load had failed for some unrelated reason.
// Verified to fail against master: `Error #000:102 (E_BUSERR)`.
run("modules: a bad inetdb offset does not bus-error the loader",
    expectation: "no E_BUSERR from load",
    commands: ["load /dd/CMDS/BOOTOBJS/SPF/inetdb", "mdir"]) {
    $0.contains("inetdb") && !$0.contains("BUSERR")
}

// ── SCF honours PD_EOR, the path's end-of-record character ───────────────────
// PD_EOR is a path option ($8B in the SCF option section), settable with
// `tmode eor=<h>` and with I$SetStt SS_Opt, and it is what ends a record --
// not a hardcoded carriage return. The console read paths used to disagree
// with each other about that: the echo already read PD_EOR while the
// terminator test was a literal CR, so moving PD_EOR left lines ending on a
// character SCF no longer considered a terminator.
//
// This is not a theoretical option nobody moves. Instrumented run against the
// v2.4 system disk, 2026-08-21: tsmon sets PD_EOR=$00 (with PD_EOF and PD_EKO)
// on /term at boot and then does a one-byte I$Read; pdksh and umacs both zero
// PD_EKO and PD_EOF on entry and deliberately LEAVE PD_EOR at $0D, which is
// the contract that makes their raw reads return on Enter at all.
//
// $5F is chosen as the stand-in terminator because it is not a shell
// metacharacter and cannot be produced by the harness's own line endings: the
// obvious $0A can never reach an OS-9 program on a Unix host at all, since
// ConsGetc swaps LF and CR unconditionally (consio.c).
//
// `noecho` is load-bearing, not tidiness: with echo on, the captured stream
// carries the typed characters as well as the program's output, and the two
// run together on one line precisely because the EOR character correctly gets
// no auto-LF -- which makes a substring assertion match in both directions.

// Claim: v2.4 Technical I/O Manual, SCF chapter -- I$ReadLn terminates when
// "an end-of-record character is detected (PD_EOR)". Two commands are sent as
// ONE line with no CR between them, so only a build that terminates on $5F
// can run them as two. Verified to fail against the pre-change binary: the
// whole text ran as a single command, echoing "EORONE_echo EORTWO_".
//
// The trailing `tmode eor=0D_` is load-bearing, and its absence is a real
// finding rather than a nuisance: once PD_EOF ends a read only on an empty
// buffer, the harness's own ESC terminator no longer works while PD_EOR is
// moved. The joiner's newline arrives first, is ordinary data under eor=5F,
// and the ESC behind it is then data too -- so the session waits for a `_`
// that never comes. Restoring PD_EOR before the terminator is what a real
// user would have to do, and what real OS-9 would require.
run("console: I$ReadLn ends the line at PD_EOR, not at CR",
    expectation: "one line ending in EORONE and another ending in EORTWO",
    commands: ["tmode noecho eor=5F",
               "echo EORONE_echo EORTWO_tmode eor=0D_"]) { out in
    let lines = out.split(whereSeparator: \.isNewline)
                   .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
    return lines.contains { $0.hasSuffix("EORONE") }
        && lines.contains { $0.hasSuffix("EORTWO") }
}

// Claim: same chapter, PD_ALF -- "If PD_ALF is not zero, carriage returns are
// automatically followed by line-feeds." The auto-LF follows the CARRIAGE
// RETURN; ending the record is PD_EOR's separate job. This build used to key
// the LF on PD_EOR, so with PD_EOR moved every written line lost its LF and
// the next one was printed over it.
//
// The line still has to be delivered through the $5F terminator to get here,
// so this rides on the ReadLn fix above rather than failing on its own -- the
// two ship together. Asserted on bytes, not on Characters: Swift folds CR LF
// into a single grapheme, which would make a String search read the same
// whether or not the LF is there.
run("console: PD_ALF adds the LF after CR, not after PD_EOR",
    expectation: "an output line still ends CR LF when PD_EOR is not CR",
    commands: ["tmode noecho eor=5F", "echo ALFMARK_tmode eor=0D_"]) { out in
    Data(out.utf8).range(of: Data("ALFMARK\r\n".utf8)) != nil
}

// SCF's echo of a line being read goes out BEHIND the output already queued
// for the terminal, never ahead of it. Under baud pacing (the default) a
// command's output waits in the pacing queue after the command has exited, and
// the echo used to go straight to the screen, so with commands piped in the
// shell's echo of its next line was printed inside the previous command's
// output: "$ Oecho ORDERTWO" followed by "RDERONE". Paced on purpose -- the
// harness's usual -r bypasses the queue and cannot show it.
if filter.isEmpty || "console: a read's echo waits behind output already queued".localizedCaseInsensitiveContains(filter) {
    let name = "console: a read's echo waits behind output already queued"
    let out = os9(["echo ORDERONE", "echo ORDERTWO"], paced: true)
    let lines = out.split(whereSeparator: \.isNewline)
                   .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
    if lines.contains("ORDERONE") && lines.contains("$ echo ORDERTWO") && lines.contains("ORDERTWO") {
        print("PASS: \(name)"); passed += 1
    } else {
        print("FAIL: \(name)")
        print("      [each command's output is whole, and the next echo follows it]")
        print("      output: \(lines.filter { $0.contains("ORDER") }.joined(separator: " | "))")
        failed += 1
    }
}

// Claim: same chapter -- "If I$ReadLn has satisfied its input byte count, SCF
// ignores any further input characters until an end-of-record character
// (PD_EOR) is received. It echoes the PD_OVF character for each byte ignored."
// An over-long line is TRUNCATED, not split: the tail is thrown away, never
// handed to a second read.
//
// The shell asks for $200 = 512 bytes (measured from a `-d 2` syscall trace),
// which is also SCF's own editing-buffer size, so 700 X's overflow it by a
// wide margin. Verified to fail against the pre-change binary: the tail came
// back as a second command and the run printed
// `shell: can't execute "XXXX...ZZTAILZZ"`.
//
// The run-length bounds are the vacuity guard. Too short and the line never
// reached the shell at all; a run of the full 700 would mean the count no
// longer truncates anything and the absence of the tail marker proves nothing.
let eorPad = String(repeating: "X", count: 700)
run("console: I$ReadLn discards the excess past its byte count",
    expectation: "the tail never runs as a command, and the line was truncated",
    commands: ["echo \(eorPad)ZZTAILZZ"]) { out in
    var longest = 0, current = 0
    for ch in out {
        if ch == "X" { current += 1; if current > longest { longest = current } }
        else { current = 0 }
    }
    return !out.contains("ZZTAILZZ") && longest > 100 && longest < 700
}

// Claim: SCF allocates a per-path buffer for input line editing, and that
// buffer is the ceiling on a line however much the caller asks for. `Guru`
// (Galactic Industrial, "The OS-9 Guru -- The Facts"), stated three times and
// consistently: "SCF allocates a buffer of 512 bytes (256 bytes prior to OS-9
// version 2.3) for input line editing"; "the buffer is 512 bytes, so this is
// the maximum length of a line typed in, including the [CR]".
//
// NOT Microware's word -- no line-length limit appears in the v2.4 Technical
// I/O Manual or the Technical Reference, where every "input buffer" is the
// DRIVER's, in the flow-control sections. Two pieces of circumstantial
// support from Microware's own binaries, `-d 2` traces on a v2.4 disk: the
// shell asks for exactly $200 (512) on a console I$ReadLn and BASIC09 for
// $1FF (511), which with its terminator is 512 exactly.
//
// Nothing on that disk asks for MORE than 512, which is why this went four
// major versions without mattering and why the test needs an instrument of
// its own: test/68k-console/rdlnecho reads one line with a 1024-byte count
// and writes back exactly the bytes I$ReadLn returned. Its SRC/ carries the
// 68000 source; it links against no C library and needs no SDK to run.
//
// `tmode noecho` is the vacuity guard, not tidiness: with echo on, the
// console's own echo of the typed line is ALSO 512 X's, so a broken run
// where the module never executed would still show a 512-run and pass.
// With echo off the only X's in the stream are ones the module wrote, so
// "module did not run" scores zero and fails. Verified to fail against the
// pre-clamp binary: 600 X's came back, and no bells.
let scfBufName = "console: SCF's 512-byte line buffer caps what I$ReadLn returns"
if !containerized {   // the instrument lives in the repo, not in the image
    let consoleTools = repoRoot.appendingPathComponent("test/68k-console").path
    run(scfBufName,
        expectation: "a 600-character line returns 511 data bytes plus its terminator",
        commands: ["tmode noecho", "/h6/CMDS/rdlnecho", String(repeating: "X", count: 600)],
        env: ["OS9H6": consoleTools]) { out in
        var longest = 0, current = 0
        for ch in out {
            if ch == "X" { current += 1; if current > longest { longest = current } }
            else { current = 0 }
        }
        // 511, not 512: the buffer is 512 "including the [CR]", so data fills
        // 511 slots and the terminator takes the last one -- the returned
        // record is still 512 bytes. 89 = 600 typed - 511 kept, each ignored
        // byte answered with PD_OVF. Measured across the boundary: 511 typed
        // gives 511 data and no bell, 512 typed gives 511 data and exactly one.
        return longest == 511 && out.filter { $0 == "\u{07}" }.count == 89
    }
}

// Claim: v2.4 Technical I/O Manual, SCF chapter -- I$Read's count is a
// MAXIMUM. The read also ends when "an end-of-record character is detected
// (PD_EOR)", and de-selecting PD_EOR is named there as the supported way to
// ask for the count instead. A literal 0 was passed, so every console
// I$Read behaved as though PD_EOR were disabled.
//
// This needs an instrument (test/68k-console/rdecho: one raw I$Read with a
// 1024-byte count, then write back exactly what it returned), because the
// difference only shows when a SECOND record is already buffered behind the
// first -- which is precisely what the harness's pipe provides, all of the
// input being written before the emulator starts.
//
// Verified against master, and it is worth knowing how it fails: the raw
// read swallows BOTH records and then the session's own ESC as well, so the
// module exits on E$EOF having written nothing, and the shell -- whose EOF
// character has just been eaten by someone else -- waits for input that can
// never arrive. The run dies on the harness timeout. An earlier note here
// claimed no check could discriminate, on the reasoning that ConsRead
// always returns short once input runs dry; that was wrong. It parks in
// pWaitRead and is rescheduled, indefinitely.
//
// Two assertions, because either alone is weaker: AAAA proves the read
// returned at the record boundary, and the shell's complaint about BBBB
// proves the rest was LEFT for the next reader rather than consumed.
let rawReadName = "console: I$Read stops at PD_EOR and leaves the next record"
if !containerized {   // the instrument lives in the repo, not in the image
    let consoleTools = repoRoot.appendingPathComponent("test/68k-console").path
    run(rawReadName,
        expectation: "the raw read returns AAAA and leaves BBBB for the shell",
        commands: ["tmode noecho", "/h6/CMDS/rdecho", "AAAA", "BBBB"],
        env: ["OS9H6": consoleTools]) { out in
        out.contains("AAAA") && out.contains("BBBB")
    }
}

// ── -M actually resizes the 68k arena ────────────────────────────────────────
// -M was documented as "Set 68k arena size" and did nothing of the kind, for two
// compounding reasons: the option switch lowercases its letter, so `case 'M'`
// was unreachable and -M silently became -m (the first process's extra static
// storage); and the option loop runs after os9exec_globinit(), which had already
// allocated the arena. Together those made -M look like it could only SHRINK the
// arena -- "-M 8M" appeared to work while "-M 32M", the default value itself,
// died with "No more memory !!!" because 32 MB of extra process storage does not
// fit in a 32 MB arena.
//
// Asserting on a RAM disk rather than on any printed size, because a RAM disk is
// carved from the arena in one contiguous piece and so can only succeed if the
// arena is genuinely bigger. The pair is the point: the refusal proves the test
// is not vacuous (this size really is beyond a default arena), and the success
// proves -M moved the ceiling. Verified to fail against the pre-fix binary.
let arenaName = "memory: -M grows the 68k arena, not the first process's storage"
if filter.isEmpty || arenaName.localizedCaseInsensitiveContains(filter) {
    let tooBig  = os9(["mount -r=65536", "free /r0"])
    let withBig = os9(["mount -r=65536", "free /r0"], flags: ["-M", "128M"])

    let refused  = tooBig.contains("needs 65536 kB")
    let accepted = withBig.contains("262144 sectors")

    if refused && accepted {
        print("PASS: \(arenaName)")
        passed += 1
    } else {
        print("FAIL: \(arenaName)")
        if !refused  { print("      a 64MB RAM disk was NOT refused by a default 32MB arena -- test is vacuous") }
        if !accepted { print("      -M 128M did not make room for it; -M is inert again") }
        failed += 1
    }
}

// ── Results ───────────────────────────────────────────────────────────────────

try? FileManager.default.removeItem(atPath: scratchDisk) // the run owns it; take it with us
// The canary outlives its own tests: container mode mounts it into EVERY
// invocation, so removing it when the fs block finished would leave every later
// test asking docker to mount a path that no longer exists.
try? FileManager.default.removeItem(atPath: canaryHost)

print("\nResults: \(passed) passed, \(failed) failed")
exit(failed > 0 ? 1 : 0)
